import { Invoice, Party, Product, SpecialRate, User } from '../types';
import { supabase } from './supabase';

export const Cloud = {
  // Flag to indicate we are using Supabase (replaces getScriptUrl check)
  getScriptUrl: () => 'SUPABASE_ENABLED', 
  setScriptUrl: (url: string) => {}, // No-op

  // --- SYNC METHODS (UPSERT) ---

  syncInvoice: async (invoice: Invoice) => {
    const { error } = await supabase
      .from('invoices')
      .upsert({
        id: invoice.id,
        invoiceNumber: invoice.invoiceNumber,
        partyId: invoice.partyId,
        partyName: invoice.partyName,
        date: invoice.date,
        items: invoice.items, // JSONB column
        subTotal: invoice.subTotal,
        taxAmount: invoice.taxAmount,
        globalDiscount: invoice.globalDiscount,
        grandTotal: invoice.grandTotal,
        vehicleNumber: invoice.vehicleNumber,
        poNumber: invoice.poNumber,
        partyAddress: invoice.partyAddress,
        partyGst: invoice.partyGst,
        partyPan: invoice.partyPan,
        partyAadhar: invoice.partyAadhar,
        partyPhone: invoice.partyPhone
      });

    if (error) {
      console.error('Error syncing invoice:', error);
      return { success: false, error: error.message };
    }
    return { success: true };
  },

  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
    // 1. Sync Parties
    if (parties.length > 0) {
      const { error } = await supabase.from('parties').upsert(parties);
      if (error) console.error('Error syncing parties:', error);
    }

    // 2. Sync Products
    if (products.length > 0) {
      const { error } = await supabase.from('products').upsert(products);
      if (error) console.error('Error syncing products:', error);
    }

    // 3. Sync Users
    if (users.length > 0) {
      const { error } = await supabase.from('app_users').upsert(users);
      if (error) console.error('Error syncing users:', error);
    }

    // 4. Sync Rates (Delete old for party and insert new, or upsert if ID managed)
    // For simplicity with the RateManager logic, we'll try to upsert.
    // However, the app generates rates dynamically.
    // Strategy: We will delete existing rates for the involved parties and re-insert.
    // But to be safe and simple: standard upsert might duplicate if IDs aren't tracked.
    // The App RateManager doesn't track ID for SpecialRate. 
    // We will clear the table and re-insert ALL rates to ensure consistency (simplest for small datasets).
    // Optimization: Only if rates exist.
    if (rates.length > 0) {
      // For a robust system, we should diff, but for now we'll upsert based on composite key logic if possible
      // or just insert. Since we don't have unique IDs in frontend SpecialRate type, 
      // we should modify the type or just clear/insert.
      // Let's assume we replace all rates for simplicity to match "Sheet" behavior.

      const { error: delError } = await supabase.from('special_rates').delete().neq('id', 0); // Delete all
      if (!delError) {
         // Transform to match DB columns if needed, but names match types.ts
         const { error } = await supabase.from('special_rates').insert(rates);
         if (error) console.error('Error syncing rates:', error);
      }
    }
  },

  // --- FETCH METHODS ---

  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES' | 'INVOICES' | 'USERS'): Promise<any> => {
    if (type === 'PARTIES') {
      const { data, error } = await supabase.from('parties').select('*');
      if (error) throw error;
      return data;
    }
    if (type === 'PRODUCTS') {
      const { data, error } = await supabase.from('products').select('*');
      if (error) throw error;
      return data;
    }
    if (type === 'RATES') {
      const { data, error } = await supabase.from('special_rates').select('*');
      if (error) throw error;
      return data;
    }
    return [];
  },

  fetchUsers: async (): Promise<User[]> => {
    const { data, error } = await supabase.from('app_users').select('*');
    if (error) {
      console.warn("Could not fetch users", error);
      return [];
    }
    return data as User[];
  },

  fetchInvoices: async (): Promise<Invoice[]> => {
    const { data, error } = await supabase.from('invoices').select('*').order('created_at', { ascending: false });
    if (error) {
      console.error("Error fetching invoices", error);
      return [];
    }
    // Supabase returns exact shape needed usually, but we ensure types
    return data.map((inv: any) => ({
      ...inv,
      items: typeof inv.items === 'string' ? JSON.parse(inv.items) : inv.items // Handle JSONB
    })) as Invoice[];
  },

  testConnection: async () => {
    const { error } = await supabase.from('parties').select('count', { count: 'exact', head: true });
    if (error) throw error;
    return true;
  }
};

import React, { useState, useEffect } from 'react';
import { Party, Product, SpecialRate } from '../types';
import { Users, Search, Check, Save, CloudLightning, X, Grid, LayoutList } from 'lucide-react';

interface Props {
  parties: Party[];
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (r: SpecialRate[]) => void;
}

export const RateManager: React.FC<Props> = ({ parties, products, specialRates, setSpecialRates }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string | null>(null);
  const [filterText, setFilterText] = useState('');
  const [partySearch, setPartySearch] = useState('');

  // Local temporary state for inputs to allow smooth typing
  const [draftRates, setDraftRates] = useState<Record<string, number>>({});
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'pending'>('saved');

  // Load rates into draft state when party changes
  useEffect(() => {
    if (selectedPartyId) {
      const partyRates = specialRates.filter(r => r.partyId === selectedPartyId);
      const rateMap: Record<string, number> = {};
      partyRates.forEach(r => {
        rateMap[r.productId] = r.rate;
      });
      setDraftRates(rateMap);
      setSaveStatus('saved');
    } else {
      setDraftRates({});
    }
  }, [selectedPartyId, specialRates]);

  // Debounce logic for Auto-Saving
  useEffect(() => {
    if (!selectedPartyId || saveStatus !== 'pending') return;

    const timer = setTimeout(() => {
        setSaveStatus('saving');

        const otherRates = specialRates.filter(r => r.partyId !== selectedPartyId);
        const newPartyRates = Object.entries(draftRates).map(([prodId, rate]) => ({
            partyId: selectedPartyId,
            productId: prodId,
            rate: rate
        }));

        setSpecialRates([...otherRates, ...newPartyRates]);
        setSaveStatus('saved');

    }, 800);

    return () => clearTimeout(timer);
  }, [draftRates, selectedPartyId, saveStatus, specialRates, setSpecialRates]);

  const handleRateChange = (productId: string, newValue: string) => {
    if (!selectedPartyId) return;
    setSaveStatus('pending');

    const numValue = parseFloat(newValue);
    const newDraft = { ...draftRates };

    if (!isNaN(numValue) && newValue !== '') {
      newDraft[productId] = numValue;
    } else {
      delete newDraft[productId];
    }
    setDraftRates(newDraft);
  };

  const selectedParty = parties.find(p => p.id === selectedPartyId);

  const filteredProducts = products.filter(p => 
    (p.name && p.name.toLowerCase().includes(filterText.toLowerCase())) || 
    (p.code && p.code.toLowerCase().includes(filterText.toLowerCase()))
  );

  const filteredParties = parties.filter(p => {
    const term = partySearch.toLowerCase();
    return (
      p.name.toLowerCase().includes(term) ||
      (p.phone && String(p.phone).toLowerCase().includes(term))
    );
  });

  return (
    <div className="flex h-[calc(100vh-64px)] overflow-hidden bg-slate-50">
      {/* Sidebar: Party Selection */}
      <div className="w-80 border-r border-slate-200 bg-white flex flex-col shadow-sm z-10">
        <div className="p-4 border-b border-slate-100 bg-slate-50/80 backdrop-blur-sm">
          <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2 mb-3">
            <Users size={18} className="text-sky-600" /> Parties
          </h2>

          <div className="relative">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
             <input 
               type="text" 
               placeholder="Search..." 
               value={partySearch}
               onChange={(e) => setPartySearch(e.target.value)}
               className="w-full pl-9 pr-3 py-2 text-sm border border-slate-200 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none bg-white text-slate-800"
             />
          </div>
        </div>

        <div className="overflow-y-auto flex-1">
          {filteredParties.map(party => {
            const isActive = selectedPartyId === party.id;
            const hasRates = specialRates.some(r => r.partyId === party.id);

            return (
              <button
                key={party.id}
                onClick={() => setSelectedPartyId(party.id)}
                className={`w-full text-left px-4 py-3 border-b border-slate-50 flex justify-between items-center transition-all hover:bg-slate-50 ${
                  isActive ? 'bg-sky-50 border-sky-100' : ''
                }`}
              >
                <div>
                  <div className={`font-semibold text-sm ${isActive ? 'text-sky-900' : 'text-slate-700'}`}>
                    {party.name}
                  </div>
                  {hasRates && (
                    <div className="text-[10px] text-sky-600 font-medium mt-0.5 flex items-center gap-1">
                       <Grid size={10} /> Custom Sheet
                    </div>
                  )}
                </div>
                {isActive && <div className="w-1.5 h-1.5 rounded-full bg-sky-500"></div>}
              </button>
            );
          })}
        </div>
      </div>

      {/* Main Content: Spreadsheet Area */}
      <div className="flex-1 flex flex-col relative bg-white">
        {selectedParty ? (
          <>
            <div className="px-6 py-3 border-b border-slate-200 bg-white flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <div className="h-10 w-10 bg-emerald-100 rounded-lg flex items-center justify-center text-emerald-600 font-bold text-xl shadow-sm">
                        {selectedParty.name.charAt(0)}
                    </div>
                    <div>
                        <h1 className="text-lg font-bold text-slate-900 leading-tight">{selectedParty.name}</h1>
                        <p className="text-xs text-slate-500">Rate Sheet Editor</p>
                    </div>
                </div>

                <div className="flex items-center gap-4">
                     <div className="relative w-64">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                        <input 
                        type="text" 
                        placeholder="Find product..."
                        value={filterText}
                        onChange={(e) => setFilterText(e.target.value)}
                        className="pl-9 pr-4 py-1.5 border border-slate-300 rounded-md text-sm w-full focus:ring-2 focus:ring-emerald-500 outline-none"
                        />
                     </div>
                     <div className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold uppercase tracking-wider transition-all ${
                        saveStatus === 'saved' ? 'text-slate-400 bg-slate-100' : 
                        saveStatus === 'saving' ? 'text-emerald-600 bg-emerald-50' :
                        'text-orange-500 bg-orange-50'
                     }`}>
                        {saveStatus === 'saved' ? <Check size={14}/> : <CloudLightning size={14} className={saveStatus === 'saving' ? 'animate-pulse' : ''} />}
                        {saveStatus === 'saved' ? 'Saved' : 'Saving...'}
                     </div>
                </div>
            </div>

            {/* The "Sheet" */}
            <div className="flex-1 overflow-y-auto">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
                  <tr>
                    <th className="px-6 py-3 border-b border-slate-200 text-[11px] font-bold text-slate-500 uppercase tracking-wider w-[10%]">Code</th>
                    <th className="px-6 py-3 border-b border-slate-200 text-[11px] font-bold text-slate-500 uppercase tracking-wider w-[50%]">Product Name</th>
                    <th className="px-0 py-3 border-b border-slate-200 text-[11px] font-bold text-slate-500 uppercase tracking-wider text-right w-[20%]">Standard Rate</th>
                    <th className="px-6 py-3 border-b border-slate-200 text-[11px] font-bold text-emerald-700 uppercase tracking-wider w-[20%] bg-emerald-50/50 text-center">
                        Special Rate
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {filteredProducts.map((product, idx) => {
                      const currentVal = draftRates[product.id];
                      const isCustom = currentVal !== undefined;

                      return (
                        <tr key={product.id} className="hover:bg-slate-50 transition-colors group">
                          <td className="px-6 py-2 text-xs font-mono text-slate-400 group-hover:text-slate-600 border-r border-transparent group-hover:border-slate-100">
                             {product.code || '-'}
                          </td>
                          <td className="px-6 py-2 text-sm font-medium text-slate-700 border-r border-transparent group-hover:border-slate-100">
                             {product.name}
                          </td>
                          <td className="px-0 py-2 text-sm text-slate-400 font-mono text-right border-r border-transparent group-hover:border-slate-100 pr-6">
                             {product.standardRate}
                          </td>
                          <td className={`px-2 py-1 text-center border-l ${isCustom ? 'bg-emerald-50/30' : 'bg-slate-50/30'}`}>
                             <input 
                                type="number"
                                className={`w-full text-center py-1.5 rounded-md text-sm font-bold font-mono focus:ring-2 focus:ring-emerald-500 outline-none transition-all ${
                                    isCustom ? 'text-emerald-700 bg-white shadow-sm border border-emerald-200' : 'text-slate-800 bg-transparent hover:bg-white focus:bg-white'
                                }`}
                                placeholder="-"
                                value={currentVal ?? ''}
                                onChange={(e) => handleRateChange(product.id, e.target.value)}
                             />
                          </td>
                        </tr>
                      );
                    })}
                </tbody>
              </table>
              {filteredProducts.length === 0 && (
                  <div className="flex flex-col items-center justify-center h-64 text-slate-400">
                      <Search size={32} className="mb-2 opacity-20"/>
                      <p>No products found.</p>
                  </div>
              )}
            </div>
          </>
        ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-slate-400 bg-slate-50/50">
                <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center shadow-sm mb-4">
                    <LayoutList size={32} className="text-slate-300" />
                </div>
                <h3 className="text-lg font-bold text-slate-600 mb-1">No Party Selected</h3>
                <p className="text-sm">Choose a customer from the left to edit their rate sheet.</p>
            </div>
        )}
      </div>
    </div>
  );
};

