                    <CheckCircle className="text-emerald-600" size={24} />
                    <div>
                    <h4 className="font-bold text-emerald-900">Connected to Supabase</h4>
                    <p className="text-xs text-emerald-700">Database is active and reachable.</p>
                    </div>
                </div>
             )}

             {connectionStatus === 'error' && (
                <div className="flex items-center gap-4 bg-red-50 p-4 rounded-lg border border-red-200">
                    <XCircle className="text-red-600" size={24} />
                    <div>
                    <h4 className="font-bold text-red-900">Connection Failed</h4>
                    <p className="text-xs text-red-700 mb-1">Could not reach the database.</p>
                    <p className="text-[10px] font-mono bg-red-100/50 p-1 rounded text-red-800">{connectionError}</p>
                    </div>
                </div>
             )}
          </div>
      </div>

      {/* Manual Push Area */}
