             }`}>
                {saveStatus === 'saved' ? <Check size={14}/> : <CloudLightning size={14} className={saveStatus === 'saving' ? 'animate-pulse' : ''} />}
                {saveStatus === 'saved' ? 'All Changes Saved' : saveStatus === 'saving' ? 'Syncing...' : 'Unsaved Changes'}
             </div>
         </div>

         <div className="flex items-center gap-3">
             {viewMode === 'detail' ? (
                 <div className="relative w-64">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                    <input 
                      type="text" 
                      placeholder="Search items..." 
                      value={filterText}
                      onChange={(e) => setFilterText(e.target.value)}
                      className="w-full pl-9 pr-3 py-1.5 text-sm border border-slate-300 rounded-md focus:ring-2 focus:ring-sky-500 outline-none"
                    />
                 </div>
             ) : (
                 <div className="text-xs text-slate-400 font-medium italic">
                    Grid View: {parties.length} Parties x {products.length} Products
                 </div>
             )}
         </div>
      </div>

      {/* CONTENT AREA */}
      <div className="flex-1 overflow-hidden relative">

         {/* --- DETAIL VIEW (Original) --- */}
         {viewMode === 'detail' && (
            <div className="flex h-full">
                {/* Sidebar */}
                <div className="w-72 border-r border-slate-200 bg-white flex flex-col h-full overflow-hidden">
                   <div className="p-3 border-b border-slate-100 bg-slate-50">
                       <input 
                         type="text" 
                         placeholder="Search Party..." 
                         value={partySearch}
                         onChange={e => setPartySearch(e.target.value)}
                         className="w-full px-3 py-2 text-sm border border-slate-200 rounded-md outline-none focus:border-sky-400"
                       />
                   </div>
                   <div className="overflow-y-auto flex-1">
                      {filteredParties.map(p => {
                         const isActive = selectedPartyId === p.id;
                         return (
                            <button 
                              key={p.id}
                              onClick={() => setSelectedPartyId(p.id)}
                              className={`w-full text-left px-4 py-3 border-b border-slate-50 text-sm font-medium transition-colors ${isActive ? 'bg-sky-50 text-sky-700 border-sky-200' : 'text-slate-600 hover:bg-slate-50'}`}
                            >
                                {p.name}
                            </button>
                         )
                      })}
                   </div>
                </div>

                {/* Main */}
                <div className="flex-1 overflow-y-auto bg-slate-50/30 p-0">
                    {selectedPartyId ? (
                        <div className="bg-white min-h-full">
                           <table className="w-full text-left">
                              <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm text-xs uppercase font-bold text-slate-500">
                                 <tr>
                                    <th className="px-6 py-3 w-1/4">Product</th>
                                    <th className="px-6 py-3 w-1/4 text-right">Std Rate</th>
                                    <th className="px-6 py-3 w-1/4 text-center">Your Rate</th>
                                 </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-100">
                                 {filteredProducts.map(prod => {
                                     const key = `${selectedPartyId}_${prod.id}`;
                                     const rate = matrixMap[key];
                                     const isCustom = rate !== undefined;
                                     return (
                                        <tr key={prod.id} className="hover:bg-slate-50">
                                           <td className="px-6 py-2">
                                              <div className="font-medium text-slate-800 text-sm">{prod.name}</div>
                                              <div className="text-[10px] text-slate-400">{prod.code}</div>
                                           </td>
                                           <td className="px-6 py-2 text-right font-mono text-sm text-slate-400">
                                               {prod.standardRate}
                                           </td>
                                           <td className="px-6 py-2 text-center">
                                              <input 
                                                type="number"
                                                className={`w-24 text-center py-1.5 rounded border text-sm font-bold outline-none focus:ring-2 focus:ring-sky-500 ${isCustom ? 'bg-sky-50 border-sky-300 text-sky-700' : 'bg-white border-slate-200 text-slate-800'}`}
                                                value={rate ?? ''}
                                                placeholder="-"
                                                onChange={(e) => handleRateChange(selectedPartyId, prod.id, e.target.value)}
                                              />
                                           </td>
                                        </tr>
                                     );
                                 })}
                              </tbody>
                           </table>
                        </div>
                    ) : (
                        <div className="flex flex-col items-center justify-center h-full text-slate-400">
                            <ArrowLeft size={24} className="mb-2" />
                            <p>Select a party to edit rates</p>
                        </div>
                    )}
                </div>
            </div>
         )}

         {/* --- MATRIX VIEW (New) --- */}
         {viewMode === 'matrix' && (
             <div className="overflow-auto h-full w-full bg-white">
                <table className="w-max border-collapse">
                   <thead className="bg-slate-100 sticky top-0 z-10 shadow-sm">
                      <tr>
                         <th className="sticky left-0 z-20 bg-slate-100 border-b border-r border-slate-300 px-4 py-3 text-xs font-bold text-slate-700 uppercase tracking-wider min-w-[200px] text-left shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]">
                             Party Name
                         </th>
                         {products.map(prod => (
                             <th key={prod.id} className="px-2 py-3 border-b border-slate-300 text-[10px] font-bold text-slate-500 uppercase min-w-[100px] text-center">
                                 <div className="truncate w-24 mx-auto" title={prod.name}>{prod.name}</div>
                                 <div className="text-[9px] text-slate-400">Std: {prod.standardRate}</div>
                             </th>
                         ))}
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100">
                      {parties.map(party => (
                         <tr key={party.id} className="hover:bg-slate-50 transition-colors group">
                            <td className="sticky left-0 z-10 bg-white group-hover:bg-slate-50 border-r border-slate-200 px-4 py-2 text-xs font-bold text-slate-800 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]">
                                {party.name}
                            </td>
                            {products.map(prod => {
                                const key = `${party.id}_${prod.id}`;
                                const rate = matrixMap[key];
                                const isCustom = rate !== undefined;
                                return (
                                    <td key={prod.id} className={`p-1 border-r border-slate-100 text-center ${isCustom ? 'bg-sky-50/30' : ''}`}>
                                        <input 
                                          type="number"
                                          className={`w-full text-center py-1.5 rounded text-xs font-medium outline-none focus:ring-2 focus:ring-sky-500 transition-all ${
                                            isCustom ? 'text-sky-700 font-bold bg-white border border-sky-200 shadow-sm' : 'text-slate-400 bg-transparent hover:bg-white border border-transparent hover:border-slate-200'
                                          }`}
                                          value={rate ?? ''}
                                          placeholder="-"
                                          onChange={(e) => handleRateChange(party.id, prod.id, e.target.value)}
                                        />
                                    </td>
                                );
                            })}
                         </tr>
                      ))}
                   </tbody>
                </table>
             </div>
         )}

      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Party, Product, SpecialRate, Invoice, InvoiceItem } from '../types';
import { ShoppingCart, User, Plus, Trash2, Save, Scan, Zap, FileText, CloudLightning, Loader2, Printer, X, CreditCard, Box, MapPin, Phone, Calculator, ChevronDown, ChevronUp, Edit3, Copy, Download, FileSpreadsheet, Search, Tag, Sparkles, Info } from 'lucide-react';
import { Store } from '../services/store';
import { Cloud } from '../services/cloud';
import { InvoiceTemplate } from './InvoiceTemplate';
import { exportInvoicesToCSV } from '../services/csv';

interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
  products: Product[];
  specialRates: SpecialRate[];
  onInvoiceSaved: () => void;
  initialData?: Invoice | null; 
}

// Defined Vehicle Options
const VEHICLE_OPTIONS = [
  "WB894170", 
  "WB25K1322", 
  "WB25K2982", 
  "WB25L6365", 
  "WB25K1326", 
  "WB25K1341", 
  "WB47J7275", 
  "WB35H3960"
];

const getTodayString = () => {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

export const Billing: React.FC<Props> = ({ parties, setParties, products, specialRates, onInvoiceSaved, initialData }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string>('');
  const [items, setItems] = useState<InvoiceItem[]>([]);

  const [invoiceDate, setInvoiceDate] = useState(getTodayString());

  const [customInvoiceNo, setCustomInvoiceNo] = useState('');

  const [refNo, setRefNo] = useState(''); 

  const [globalDiscount, setGlobalDiscount] = useState<number>(0);

  const [isSaving, setIsSaving] = useState(false);
  const [hasCloudConfig, setHasCloudConfig] = useState(false);

  const [isPartyModalOpen, setIsPartyModalOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);

  const [lastInvoice, setLastInvoice] = useState<Invoice | null>(null);

  const [newPartyName, setNewPartyName] = useState('');
  const [newPartyPhone, setNewPartyPhone] = useState(''); 

  useEffect(() => {
    if (isPreviewOpen && lastInvoice) {
      const timer = setTimeout(() => {
        window.print();
      }, 1500); 
      return () => clearTimeout(timer);
    }
  }, [isPreviewOpen, lastInvoice]);

  useEffect(() => {
    setHasCloudConfig(!!Cloud.getScriptUrl());
  }, []);

  const [partySearch, setPartySearch] = useState('');
  const [showPartySuggestions, setShowPartySuggestions] = useState(false);
  const [partyHighlightIndex, setPartyHighlightIndex] = useState(0);

  useEffect(() => {
    if (initialData) {
      setSelectedPartyId(initialData.partyId);

      const p = parties.find(party => party.id === initialData.partyId);
      if(p) setPartySearch(p.name);
      else setPartySearch(initialData.partyName);

      const cleanItems = initialData.items.map(item => {
        let pId = item.productId;
        if (!pId && products.length > 0) {
            const found = products.find(p => p.name.trim().toLowerCase() === item.productName.trim().toLowerCase());
            if (found) pId = found.id;
        }

        return {
          ...item,
          productId: pId || '',
          quantity: isNaN(item.quantity) ? 0 : item.quantity,
          rate: isNaN(item.rate) ? 0 : item.rate,
          total: isNaN(item.total) ? 0 : item.total,
          gstPercent: isNaN(item.gstPercent || 0) ? 0 : item.gstPercent
        };
      });

      setItems(cleanItems);
      setInvoiceDate(initialData.date);
      setCustomInvoiceNo(initialData.invoiceNumber);
      setVehicleNo(initialData.vehicleNumber || '');
      setRefNo(initialData.poNumber || '');
      setGlobalDiscount(initialData.globalDiscount || 0);
    } else {
      setSelectedPartyId('');
      setPartySearch('');
      setItems([]);
      setInvoiceDate(getTodayString());
      setCustomInvoiceNo('');
      setVehicleNo('');
      setRefNo('');
      setGlobalDiscount(0);

      setTimeout(() => partyInputRef.current?.focus(), 100);
    }
  }, [initialData, products]);

  useEffect(() => {
    const totalQty = items.reduce((sum, item) => sum + item.quantity, 0);
    if (totalQty > 0) {
      setRefNo(totalQty.toString());
    } else {
      setRefNo('');
    }
  }, [items]);

  const [vehicleNo, setVehicleNo] = useState('');
  const [showVehicleSuggestions, setShowVehicleSuggestions] = useState(false);
  const [vehicleHighlightIndex, setVehicleHighlightIndex] = useState(0);

  const [currentProductId, setCurrentProductId] = useState('');
  const [productSearch, setProductSearch] = useState(''); 
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const [productHighlightIndex, setProductHighlightIndex] = useState(0);

  const [currentQty, setCurrentQty] = useState(0);
  const [currentRate, setCurrentRate] = useState(0); 

  const [stdRate, setStdRate] = useState(0);

  const [rateType, setRateType] = useState<'standard' | 'special' | 'manual'>('standard');

  const partyInputRef = useRef<HTMLInputElement>(null);
  const invoiceNoInputRef = useRef<HTMLInputElement>(null);
  const vehicleInputRef = useRef<HTMLInputElement>(null);
  const productInputRef = useRef<HTMLInputElement>(null);
  const qtyInputRef = useRef<HTMLInputElement>(null);
  const addBtnRef = useRef<HTMLButtonElement>(null);

  const filteredParties = parties.filter(p => p.name.toLowerCase().includes(partySearch.toLowerCase()));

  const filteredVehicles = VEHICLE_OPTIONS.filter(v => 
    v.toLowerCase().includes(vehicleNo.toLowerCase())
  );

  const filteredProducts = products.filter(p => {
    const terms = productSearch.toLowerCase().split(' ').filter(t => t);
    const pName = p.name.toLowerCase();
    return terms.every(term => pName.includes(term));
  });

  // --- ROBUST PRICING ENGINE ---
  useEffect(() => {
    if (!currentProductId) {
        setStdRate(0);
        setCurrentRate(0);
        return;
    }

    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    // 1. Get Standard Rate
    const standard = product.standardRate;
    setStdRate(standard);

    // 2. Check for Special Rate
    let finalRate = standard;
    let type: 'standard' | 'special' = 'standard';

    if (selectedPartyId) {
        const special = specialRates.find(r => r.partyId === selectedPartyId && r.productId === currentProductId);
        if (special) {
            finalRate = special.rate;
            type = 'special';
        }
    }

    // 3. Apply
    setCurrentRate(finalRate);
    setRateType(type);

  }, [currentProductId, selectedPartyId, products, specialRates]);

  // --- KEYBOARD HANDLERS ---
  useEffect(() => {
    const handleGlobalKeys = (e: KeyboardEvent) => {
      if (e.key === 'Insert') {
        e.preventDefault();
        if (isPreviewOpen) {
          handlePrint();
        } else {
          handleSaveInvoice();
        }
      }
      if (isPreviewOpen && (e.ctrlKey || e.metaKey) && e.key === 'p') {
        e.preventDefault();
        window.print();
      }
    };
    window.addEventListener('keydown', handleGlobalKeys);
    return () => window.removeEventListener('keydown', handleGlobalKeys);
  }, [isPreviewOpen, items, selectedPartyId]); 

  const handleGenericKeyDown = (e: React.KeyboardEvent, nextRef: React.RefObject<HTMLElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      nextRef.current?.focus();
    }
  };

  const handlePartyKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
        e.preventDefault();
        setPartyHighlightIndex(prev => Math.min(prev + 1, filteredParties.length - 1));
        setShowPartySuggestions(true);
    } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        setPartyHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
        e.preventDefault();
        if (showPartySuggestions && filteredParties.length > 0) {
            selectParty(filteredParties[partyHighlightIndex]);
        } else {
            const exactMatch = filteredParties.find(p => p.name.toLowerCase() === partySearch.toLowerCase());
            if (exactMatch) selectParty(exactMatch);
            else invoiceNoInputRef.current?.focus(); 
        }
    } else if (e.key === 'Escape') {
        setShowPartySuggestions(false);
    }
  };

  const handleVehicleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setVehicleHighlightIndex(prev => Math.min(prev + 1, filteredVehicles.length - 1));
      setShowVehicleSuggestions(true);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setVehicleHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (showVehicleSuggestions && filteredVehicles.length > 0) {
        setVehicleNo(filteredVehicles[vehicleHighlightIndex]);
      }
      setShowVehicleSuggestions(false);
      productInputRef.current?.focus();
    } else if (e.key === 'Escape') {
      setShowVehicleSuggestions(false);
    }
  };

  const handleProductKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setProductHighlightIndex(prev => Math.min(prev + 1, filteredProducts.length - 1));
      setShowProductSuggestions(true);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setProductHighlightIndex(prev => Math.max(prev - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (showProductSuggestions && filteredProducts.length > 0) {
        selectProduct(filteredProducts[productHighlightIndex]);
      } else {
         if (currentProductId) qtyInputRef.current?.focus();
      }
    } else if (e.key === 'Escape') {
      setShowProductSuggestions(false);
    }
  };

  const handleQtyKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
       e.preventDefault();
       addItem(e); 
    }
  };

  const selectParty = (p: Party) => {
      setSelectedPartyId(p.id);
      setPartySearch(p.name);
      setShowPartySuggestions(false);
      invoiceNoInputRef.current?.focus();
  };

  const selectProduct = (p: Product) => {
    setProductSearch(p.name);
    setCurrentProductId(p.id);
    setShowProductSuggestions(false);
    setTimeout(() => qtyInputRef.current?.focus(), 50);
  };

  const handleProductSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setProductSearch(e.target.value);
    setCurrentProductId(''); 
    setProductHighlightIndex(0);
    setShowProductSuggestions(true);
  };

  const handleCreateParty = (e: React.FormEvent) => {
    e.preventDefault();
    if(!newPartyName.trim()) return;
    const newParty: Party = {
      id: crypto.randomUUID(),
      name: newPartyName.trim(),
      phone: newPartyPhone.trim(), 
      address: '', city: '', gstNumber: '', aadharNumber: '', panNumber: ''
    };
    setParties([...parties, newParty]); 
    setSelectedPartyId(newParty.id); 
    setPartySearch(newParty.name);

    setNewPartyName('');
    setNewPartyPhone('');
    setIsPartyModalOpen(false);
    invoiceNoInputRef.current?.focus();
  };

  const addItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentProductId || currentQty <= 0) return;
    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    const gstPercent = product.gstPercent || 0;
    const inclusiveRate = currentRate;
    const baseRate = inclusiveRate / (1 + (gstPercent / 100));
    const grossTotal = currentQty * inclusiveRate; 

    const newItem: InvoiceItem = {
      id: crypto.randomUUID(),
      productId: product.id,
      productName: product.name,
      quantity: currentQty,
      rate: inclusiveRate,
      baseRate: baseRate,  
      total: grossTotal,   
      hsn: product.hsn,
      gstPercent: gstPercent
    };

    setItems([...items, newItem]);

    setProductSearch('');
    setCurrentProductId('');
    setCurrentQty(0); 
    setCurrentRate(0);
    setRateType('standard');
    productInputRef.current?.focus();
  };

  const removeItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const handleSaveInvoice = async () => {
    if (!selectedPartyId || items.length === 0) return;

    setIsSaving(true);

    const party = parties.find(p => p.id === selectedPartyId);

    const subTotal = items.reduce((sum, item) => sum + item.total, 0);

    const taxAmount = items.reduce((sum, item) => {
       const taxable = item.total / (1 + (item.gstPercent || 0)/100);
       return sum + (item.total - taxable);
    }, 0);

    const grandTotal = Math.round(subTotal - globalDiscount);

    const savedPhone = (party && party.phone) ? party.phone : (initialData?.partyPhone || '');

    const newInvoice: Invoice = {
      id: initialData ? initialData.id : crypto.randomUUID(), 
      invoiceNumber: customInvoiceNo,
      partyId: selectedPartyId,
      partyName: party?.name || 'Unknown Party',
      date: invoiceDate,
      items: items,
      subTotal: subTotal,
      taxPercent: 0,
      taxAmount: taxAmount,
      globalDiscount: globalDiscount,
      grandTotal: grandTotal,
      vehicleNumber: vehicleNo,
      poNumber: refNo,
      partyAddress: party ? [party.address, party.city].filter(Boolean).join(', ') : '',
      partyGst: party?.gstNumber || '',
      partyPan: party?.panNumber || '',
      partyAadhar: party?.aadharNumber || '',
      partyPhone: savedPhone
    };

    try {
        if (initialData) {
            Store.updateInvoice(newInvoice);
        } else {
            Store.saveInvoice(newInvoice);
        }

        setLastInvoice(newInvoice);
        setIsPreviewOpen(true); 
        onInvoiceSaved(); 

        setItems([]);
        setSelectedPartyId('');
        setPartySearch('');
        setCustomInvoiceNo('');
        setVehicleNo('');
        setRefNo('');
        setGlobalDiscount(0);
        setTimeout(() => partyInputRef.current?.focus(), 100);

        if (hasCloudConfig) {
             Cloud.syncInvoice(newInvoice).catch(err => {
                 console.error("Background sync error:", err);
             });
        }

    } catch (error) {
        console.error("Save failed", error);
        alert("Error saving locally.");
    } finally {
        setIsSaving(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="flex h-full flex-col md:flex-row bg-slate-50">

      {/* LEFT: Billing Form */}
      <div className="flex-1 flex flex-col h-full overflow-hidden border-r border-slate-200">
        {/* Header */}
        <div className="px-6 py-4 bg-white border-b border-slate-200 flex justify-between items-center shadow-sm">
           <div>
             <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
               {initialData ? <Edit3 size={20} className="text-orange-500"/> : <FileText size={20} className="text-sky-600" />} 
               {initialData ? 'Edit Invoice' : 'New Invoice'}
             </h2>
             <div className="text-xs text-slate-400 font-mono mt-0.5">{invoiceDate} • {customInvoiceNo}</div>
           </div>

           <div className="flex items-center gap-2">
              <div className="text-right mr-2 hidden md:block">
                  <div className="text-[10px] text-slate-400 uppercase font-bold">Total Amount</div>
                  <div className="text-xl font-black text-slate-800">
                    ₹{Math.round(items.reduce((sum, item) => sum + item.total, 0) - globalDiscount).toLocaleString('en-IN')}
                  </div>
              </div>
              <button 
                onClick={handleSaveInvoice}
                disabled={isSaving || !selectedPartyId || items.length === 0}
                className="bg-slate-900 hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-slate-200 transition-all active:scale-95"
              >
                {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
                <span>{initialData ? 'Update' : 'Save'}</span>
              </button>
           </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-4 md:space-y-6">

           {/* Section 1: Party Selection */}
           <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200">
              <div className="flex justify-between items-center mb-2">
                 <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">BILL TO</label>
                 <button onClick={() => setIsPartyModalOpen(true)} className="text-[10px] font-bold text-sky-600 hover:underline flex items-center gap-1">
                   <Plus size={10} /> New Party
                 </button>
              </div>

              <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                  <input 
                    ref={partyInputRef}
                    type="text" 
                    value={partySearch}
                    onChange={(e) => {
                        setPartySearch(e.target.value);
                        setSelectedPartyId(''); // Reset selection if typing
                        setPartyHighlightIndex(0);
                        setShowPartySuggestions(true);
                    }}
                    onFocus={() => setShowPartySuggestions(true)}
                    onBlur={() => setTimeout(() => setShowPartySuggestions(false), 200)}
                    onKeyDown={handlePartyKeyDown}
                    placeholder="Type party name..."
