                   </div>

                   {/* Rate */}
                   <div className="w-32 relative">
                      <div className="text-[10px] font-bold text-slate-400 mb-1 ml-1 text-center">Rate</div>

                      {/* Rate Type Badge */}
                      <div className="absolute top-[-24px] left-0 w-full text-center">
