                                         )}
                                     </div>
                                  </div>
                                </div>
                                );
                              })}
                            </div>
                          )}
                      </div>
                   </div>

                   {/* Qty */}
                   <div className="w-20">
                      <div className="text-[10px] font-bold text-slate-400 mb-1 ml-1 text-center">Qty</div>
                      <input 
