// Helper to escape CSV fields
const safe = (str: string | number | undefined) => {
  if (str === undefined || str === null) return '';
  const s = String(str);
  if (s.includes(',') || s.includes('"') || s.includes('\n')) {
    return `"${s.replace(/"/g, '""')}"`;
  }
  return s;
};

// --- PARSER ---
export const parseCSV = (text: string): string[][] => {
  const result: string[][] = [];
  let row: string[] = [];
  let inQuote = false;
  let currentToken = '';

  for(let i = 0; i < text.length; i++) {
    const char = text[i];
    const nextChar = text[i+1];

    if (char === '"') {
      if (inQuote && nextChar === '"') {
        currentToken += '"';
        i++; 
      } else {
        inQuote = !inQuote;
      }
    } else if (char === ',' && !inQuote) {
      row.push(currentToken.trim());
      currentToken = '';
    } else if ((char === '\n' || char === '\r') && !inQuote) {
      if (currentToken || row.length > 0) row.push(currentToken.trim());
      if (row.length > 0) result.push(row);
      row = [];
      currentToken = '';
      if (char === '\r' && nextChar === '\n') i++;
    } else {
      currentToken += char;
    }
  }
  if (currentToken || row.length > 0) {
    row.push(currentToken.trim());
    result.push(row);
  }
  return result;
};

// --- EXPORTERS ---

export const exportPartiesToCSV = (parties: Party[]) => {
  let csv = "ID,Code,Name,Address,City,Phone,GST,Aadhar,PAN\n";
  parties.forEach(p => {
    csv += `${safe(p.id)},${safe(p.code)},${safe(p.name)},${safe(p.address)},${safe(p.city)},${safe(p.phone)},${safe(p.gstNumber)},${safe(p.aadharNumber)},${safe(p.panNumber)}\n`;
  });
  return csv;
};

export const exportProductsToCSV = (products: Product[]) => {
  let csv = "ID,Name,Code,Standard Rate,Unit\n";
  products.forEach(p => {
    csv += `${safe(p.id)},${safe(p.name)},${safe(p.code)},${p.standardRate},${safe(p.unit)}\n`;
  });
  return csv;
};

// The Matrix Export: Rows=Products, Cols=Parties
export const exportRatesMatrixToCSV = (parties: Party[], products: Product[], rates: SpecialRate[]) => {
  // Header: Product Info, then each Party Name
  let csv = "Product ID,Product Name,Standard Rate";
  parties.forEach(p => {
    csv += `,${safe(p.name)}`; // Use Name for readability in Sheets
  });
  csv += "\n";

  // Rows
  products.forEach(prod => {
    csv += `${safe(prod.id)},${safe(prod.name)},${prod.standardRate}`;
    parties.forEach(party => {
      const rateObj = rates.find(r => r.partyId === party.id && r.productId === prod.id);
      const val = rateObj ? rateObj.rate : ''; 
      csv += `,${val}`;
    });
    csv += "\n";
  });

  return csv;
};

export const exportInvoicesToCSV = (invoices: Invoice[]) => {
  // Flat format for DB analysis: Invoice Header repeated for each Item
  let csv = "Invoice ID,Invoice Number,Date,Party Name,Tax Amount,Grand Total,Product Name,Quantity,Rate,Line Total\n";

  invoices.forEach(inv => {
    inv.items.forEach(item => {
      csv += `${safe(inv.id)},${safe(inv.invoiceNumber)},${inv.date},${safe(inv.partyName)},${inv.taxAmount},${inv.grandTotal},${safe(item.productName)},${item.quantity},${item.rate},${item.total}\n`;
    });
  });
  return csv;
};

// --- IMPORTERS ---

export const parsePartiesFromCSV = (csvText: string): Party[] => {
  const rows = parseCSV(csvText);
  if (rows.length < 2) return [];
  // Old Format: A=ID, B=Name, C=Address, D=City, E=Phone, F=GST, G=Aadhar, H=PAN
  // New Format: A=ID, B=Code, C=Name, D=Address, E=City, F=Phone, G=GST, H=Aadhar, I=PAN

  // Detect format by header check
  const header = rows[0];
  const hasCode = header[1].toLowerCase() === 'code';

  if (hasCode) {
    return rows.slice(1).map(r => ({
        id: r[0] || crypto.randomUUID(), 
        code: r[1] || '',
        name: r[2],
        address: r[3] || '',
        city: r[4] || '',
        phone: r[5] || '',
        gstNumber: r[6] || '',
        aadharNumber: r[7] || '',
        panNumber: r[8] || ''
    })).filter(p => p.name);
  } else {
    // Fallback for old CSVs
    return rows.slice(1).map(r => ({
        id: r[0] || crypto.randomUUID(), 
        name: r[1],
        address: r[2] || '',
        city: r[3] || '',
        phone: r[4] || '',
        gstNumber: r[5] || '',
        aadharNumber: r[6] || '',
        panNumber: r[7] || ''
    })).filter(p => p.name);
  }
};

export const parseProductsFromCSV = (csvText: string): Product[] => {
  const rows = parseCSV(csvText);
  if (rows.length < 2) return [];
  return rows.slice(1).map(r => ({
    id: r[0] || crypto.randomUUID(),
    name: r[1],
    code: r[2] || '',
    standardRate: parseFloat(r[3]) || 0,
    unit: r[4] || 'pcs'
  })).filter(p => p.name);
};

export const parseRatesMatrixFromCSV = (csvText: string, parties: Party[], products: Product[]): SpecialRate[] => {
  const rows = parseCSV(csvText);
  if (rows.length < 2) return [];

  const header = rows[0]; // Product ID, Product Name, Std Rate, Party1, Party2...

  // Map column index to Party ID
  const partyColMap: Record<number, string> = {};

  // Start from col 3 (0=ID, 1=Name, 2=Rate)
  for (let i = 3; i < header.length; i++) {
    const partyName = header[i];
    const party = parties.find(p => p.name.trim().toLowerCase() === partyName.trim().toLowerCase());
    if (party) {
      partyColMap[i] = party.id;
    }
  }

  const newRates: SpecialRate[] = [];

  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    const productName = row[1];
    const productIdRaw = row[0];

    let product = products.find(p => p.id === productIdRaw);
    if (!product) product = products.find(p => p.name === productName);

    if (product) {
      Object.entries(partyColMap).forEach(([colIdx, partyId]) => {
        const rateVal = parseFloat(row[Number(colIdx)]);
        if (!isNaN(rateVal) && rateVal > 0) {
          newRates.push({
            partyId: partyId,
            productId: product!.id,
            rate: rateVal
          });
        }
      });
    }
  }

  return newRates;
};

import React, { useState } from 'react';
import { Party } from '../types';
import { Plus, Trash2, Edit2, User, MapPin, Phone, CreditCard, FileText, Search, X, Hash, RefreshCw } from 'lucide-react';

interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
}

export const PartyManager: React.FC<Props> = ({ parties, setParties }) => {
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<Party>>({});
  const [searchTerm, setSearchTerm] = useState('');

  // --- NEW LOGIC: First Letter + Last Letter + Number (RZ01, RZ02...) ---
  const generateSmartCode = (name: string, excludeId?: string) => {
    if (!name || name.trim().length === 0) return '';

    const cleanName = name.trim().toUpperCase();
    const firstChar = cleanName.charAt(0);
    // If name is 1 char, last char is same as first
    const lastChar = cleanName.charAt(cleanName.length - 1);

    // Only use letters/numbers for prefix to be safe
    const prefix = `${firstChar}${lastChar}`.replace(/[^A-Z0-9]/g, 'X'); 

    // Find all existing codes that start with this prefix (RZ...)
    // Exclude the current party if we are editing (though usually we don't regen on edit)
    const existingCodes = parties
        .filter(p => p.id !== excludeId && p.code && p.code.startsWith(prefix))
        .map(p => p.code!);

    let maxNum = 0;
    existingCodes.forEach(code => {
        // Extract the part after the prefix (RZ01 -> 01)
        const numPartStr = code.substring(prefix.length);
        const numPart = parseInt(numPartStr);
        if (!isNaN(numPart) && numPart > maxNum) {
            maxNum = numPart;
        }
    });

    const nextNum = maxNum + 1;
    // Pad with zero (1 -> 01, 10 -> 10)
    return `${prefix}${String(nextNum).padStart(2, '0')}`;
  };

  const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const newName = e.target.value;

      // If we are ADDING a new party (not editing), auto-generate the code
      if (!editingId) {
          const autoCode = generateSmartCode(newName);
          setFormData(prev => ({ ...prev, name: newName, code: autoCode }));
      } else {
          // If editing, just update name, don't change code automatically
          setFormData(prev => ({ ...prev, name: newName }));
      }
  };

  // Bulk Regenerate Button Logic
  const handleRegenAllCodes = () => {
    if(!confirm("This will regenerate codes for ALL parties (RZ01 format). Proceed?")) return;

    // We must process them one by one to handle duplicates correctly
    // Sort roughly by name so RZ01 goes to the "first" Riyaz
    const sortedParties = [...parties].sort((a, b) => a.name.localeCompare(b.name));
    const newPartiesList: Party[] = [];

    // We need a temporary lookup of generated codes to ensure uniqueness during this batch process
    // However, the helper function relies on 'parties' state which isn't updated yet.
    // So we implement a local tracker.

    const usedPrefixCounts: Record<string, number> = {};

    sortedParties.forEach(p => {
        const cleanName = p.name.trim().toUpperCase();
        const prefix = (cleanName.length > 0) 
            ? `${cleanName.charAt(0)}${cleanName.charAt(cleanName.length - 1)}`.replace(/[^A-Z0-9]/g, 'X') 
            : 'XX';

        if (!usedPrefixCounts[prefix]) usedPrefixCounts[prefix] = 0;
        usedPrefixCounts[prefix]++;

        const num = usedPrefixCounts[prefix];
        const newCode = `${prefix}${String(num).padStart(2, '0')}`;

        newPartiesList.push({ ...p, code: newCode });
    });

    setParties(newPartiesList);
    alert("Codes regenerated successfully!");
  };

  const handleAddNew = () => {
      setFormData({});
      setEditingId(null);
      setIsFormOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    // Final safety check: if code is empty for some reason, gen it now
    let finalCode = formData.code;
    if (!finalCode) {
        finalCode = generateSmartCode(formData.name, editingId || undefined);
    }

    if (editingId) {
      setParties(parties.map(p => p.id === editingId ? { ...p, ...formData, code: finalCode } as Party : p));
    } else {
      const newParty: Party = {
        id: crypto.randomUUID(),
        name: formData.name!,
        code: finalCode!,
        phone: formData.phone || '',
        address: formData.address || '',
        city: formData.city || '',
        gstNumber: formData.gstNumber || '',
        aadharNumber: formData.aadharNumber || '',
        panNumber: formData.panNumber || '',
        email: formData.email || '',
      };
      setParties([...parties, newParty]);
    }
    closeForm();
  };

  const deleteParty = (id: string) => {
    if (confirm('Are you sure? This will delete the party and their special rates.')) {
      setParties(parties.filter(p => p.id !== id));
    }
  };

  const openEdit = (party: Party) => {
    setFormData(party);
    setEditingId(party.id);
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setFormData({});
    setEditingId(null);
    setIsFormOpen(false);
  };

  // Filter Logic
  const filteredParties = parties.filter(p => {
    const term = searchTerm.toLowerCase();
    return (
      (p.name && p.name.toLowerCase().includes(term)) ||
      (p.code && p.code.toLowerCase().includes(term)) ||
      (p.phone && String(p.phone).toLowerCase().includes(term)) ||
      (p.city && p.city.toLowerCase().includes(term)) ||
      (p.gstNumber && p.gstNumber.toLowerCase().includes(term))
    );
  });

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Parties List</h2>
          <p className="text-slate-500">Manage customer details (GST, PAN, Aadhar).</p>
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          {/* Search Bar */}
          <div className="relative flex-1 md:w-64">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
             <input 
               type="text" 
               placeholder="Search parties..." 
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
               className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none bg-white text-slate-900 shadow-sm"
             />
             {searchTerm && (
               <button 
                onClick={() => setSearchTerm('')}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
               >
                 <X size={14} />
               </button>
             )}
          </div>

          <button 
             onClick={handleRegenAllCodes}
             className="bg-white border border-slate-200 text-slate-600 hover:bg-slate-50 px-3 py-2 rounded-lg flex items-center gap-2 transition-colors shadow-sm font-medium whitespace-nowrap text-xs"
             title="Regenerate all party codes to RZ01 format"
          >
             <RefreshCw size={16} /> Regen Codes
          </button>

          <button 
            onClick={handleAddNew}
            className="bg-sky-600 hover:bg-sky-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition-colors shadow-sm font-medium whitespace-nowrap"
          >
            <Plus size={18} /> Add Party
          </button>
        </div>
      </div>

      {isFormOpen && (
