import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Users, Package, DollarSign, FileText, History, Menu, X, Database, CheckCircle, RefreshCw, Loader2, LayoutDashboard, Printer, LogOut, User as UserIcon, Edit3, Download, MoreHorizontal, FileDown, Search, Trophy, ClipboardList } from 'lucide-react';
