function parseSeedData() {
  const rows = RAW_CSV.trim().split('\n').map(r => r.split(',')); 
  const header = rows[0];

  const parties: Party[] = [];
  const products: Product[] = [];
  const rates: SpecialRate[] = [];

  // 1. Parse Parties from Header (Index 3 to end)
  const partyNames = header.slice(3);
  const partyMap: Record<number, string> = {}; // colIndex -> partyId
  const nameToIdMap: Record<string, string> = {}; // Name -> ID map to handle duplicates in header

  partyNames.forEach((name, idx) => {
    if(!name || !name.trim()) return;
    const cleanName = name.trim().toUpperCase();

    // DUPLICATE CHECK: If we already have a party with this name, reuse its ID.
    // This effectively merges "SOURAV GHOSH" appearing twice into one party record.
    if (nameToIdMap[cleanName]) {
        partyMap[idx + 3] = nameToIdMap[cleanName];
    } else {
        const id = crypto.randomUUID();
        parties.push({
            id,
            name: cleanName,
            address: '',
            city: '',
            phone: '',
            gstNumber: '',
            panNumber: '',
            aadharNumber: '',
            code: '' // App will auto-generate
        });
        partyMap[idx + 3] = id;
        nameToIdMap[cleanName] = id;
    }
  });

  // 2. Parse Products and Rates from Rows (Index 1 to end)
  for(let i=1; i<rows.length; i++) {
    const row = rows[i];
    if(row.length < 3) continue;

    const pId = row[0].trim();
    const pName = row[1].trim();
    const pRate = parseFloat(row[2]);

    if(!pName) continue;

    // Create Product
    const product: Product = {
      id: pId || crypto.randomUUID(),
      name: pName,
      code: pId, // Use p1 as SKU/Code
      standardRate: isNaN(pRate) ? 0 : pRate,
      unit: 'pcs'
    };
    products.push(product);

    // 3. Parse Rates
    for(let col=3; col < row.length; col++) {
       const cellVal = row[col] ? row[col].trim() : '';
       if(cellVal) {
          const rateVal = parseFloat(cellVal);
          const partyId = partyMap[col];

          if(partyId && !isNaN(rateVal)) {
             // We might encounter multiple columns for the same merged party.
             // We'll upsert (overwrite) if a rate already exists for this party/product combo.
             const existingRateIndex = rates.findIndex(r => r.partyId === partyId && r.productId === product.id);
             if (existingRateIndex >= 0) {
                 rates[existingRateIndex].rate = rateVal;
             } else {
                 rates.push({
                    partyId,
                    productId: product.id,
                    rate: rateVal
                 });
             }
          }
       }
    }
  }

  return { parties, products, rates };
}

