  onUrlChange?: (url: string) => void;
  onForcePush?: () => void;
}

export const DataManager: React.FC<Props> = ({ parties, products, onForcePush }) => {
  const [statusMsg, setStatusMsg] = useState<{msg: string, type: 'success' | 'error'} | null>(null);

  // Connection State
  const [connectionStatus, setConnectionStatus] = useState<'checking' | 'connected' | 'error'>('checking');
  const [connectionError, setConnectionError] = useState('');

  useEffect(() => {
    checkSupabaseConnection();
  }, []);

  const checkSupabaseConnection = async () => {
    setConnectionStatus('checking');
    const result = await Cloud.testConnection();
    if (result.success) {
      setConnectionStatus('connected');
    } else {
      setConnectionStatus('error');
      setConnectionError(result.error || 'Unknown Error');
    }
  };

  const handleFactoryReset = () => {
      if (confirm("Are you sure? This will wipe LOCAL changes to Parties and Products and restore the original list. Invoices will be kept.")) {
          Store.resetToSeedData();
      }
  };

  return (
    <div className="p-6 max-w-4xl mx-auto pb-20">
      <div className="mb-8 border-b border-slate-200 pb-6">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <Database className="text-sky-600" /> Data Management
        </h2>
        <p className="text-slate-500">
          Sync status and manual backups.
        </p>
      </div>

      {statusMsg && (
        <div className={`fixed top-4 right-4 z-50 px-6 py-4 rounded-xl shadow-xl flex items-center gap-3 animate-in slide-in-from-top-5 duration-300 ${statusMsg.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-500 text-white'}`}>
          {statusMsg.type === 'success' ? <CheckCircle /> : <AlertTriangle />}
          <span className="font-bold">{statusMsg.msg}</span>
        </div>
      )}

      {/* CLOUD CONFIG */}
      <div className="bg-white border border-slate-200 shadow-xl shadow-slate-200/50 rounded-xl p-6 mb-8">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <CloudLightning className="text-sky-500" /> Database Connection
            </h3>
            <button 
                onClick={checkSupabaseConnection} 
                className="text-xs font-bold text-sky-600 hover:text-sky-800 flex items-center gap-1 bg-sky-50 px-3 py-1.5 rounded-lg transition-colors"
            >
                <RefreshCw size={12} className={connectionStatus === 'checking' ? 'animate-spin' : ''} />
                Test Connection
            </button>
          </div>

          <div className="space-y-6">
             {connectionStatus === 'checking' && (
                <div className="flex items-center gap-4 bg-slate-50 p-4 rounded-lg border border-slate-200 animate-pulse">
                    <RefreshCw className="text-slate-400 animate-spin" size={24} />
                    <div>
                    <h4 className="font-bold text-slate-700">Connecting...</h4>
                    <p className="text-xs text-slate-500">Verifying credentials with Supabase.</p>
                    </div>
                </div>
             )}

             {connectionStatus === 'connected' && (
                <div className="flex items-center gap-4 bg-emerald-50 p-4 rounded-lg border border-emerald-200">
                    <CheckCircle className="text-emerald-600" size={24} />
                    <div>
                    <h4 className="font-bold text-emerald-900">Connected to Supabase</h4>
                    <p className="text-xs text-emerald-700">Database is active and reachable.</p>
                    </div>
                </div>
             )}

             {connectionStatus === 'error' && (
                <div className="flex items-center gap-4 bg-red-50 p-4 rounded-lg border border-red-200">
                    <XCircle className="text-red-600" size={24} />
                    <div>
                    <h4 className="font-bold text-red-900">Connection Failed</h4>
                    <p className="text-xs text-red-700 mb-1">Could not reach the database.</p>
                    <p className="text-[10px] font-mono bg-red-100/50 p-1 rounded text-red-800">{connectionError}</p>
                    </div>
                </div>
             )}
          </div>
      </div>

      {/* Manual Push Area */}
      {onForcePush && (
        <div className="mt-8 border-t border-slate-200 pt-6">
           <h3 className="text-sm font-bold text-slate-600 mb-3">Troubleshooting</h3>
           <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               <button 
                 onClick={onForcePush} 
                 disabled={connectionStatus !== 'connected'}
                 className="w-full py-4 bg-slate-800 hover:bg-slate-900 disabled:bg-slate-300 disabled:cursor-not-allowed text-white font-bold rounded-xl shadow-md transition-all flex justify-center items-center gap-2"
               >
                   <ArrowUpCircle size={20} />
                   Force Upload Data to Cloud
               </button>

               <button 
                 onClick={handleFactoryReset}
                 className="w-full py-4 bg-red-50 hover:bg-red-100 border border-red-200 text-red-700 font-bold rounded-xl shadow-sm transition-all flex justify-center items-center gap-2"
               >
                   <RotateCcw size={20} />
                   Reset to Factory Data
               </button>
           </div>
           <p className="text-center text-xs text-slate-400 mt-2">
             Use "Reset" if you see empty lists. Use "Force Upload" if cloud is empty.
           </p>
        </div>
      )}
    </div>
  );
};

