import { Party, Product, SpecialRate, Invoice, User } from '../types';

const KEYS = {
  PARTIES: 'greemzar_parties',
  PRODUCTS: 'greemzar_products',
  RATES: 'greemzar_rates',
  INVOICES: 'greemzar_invoices',
  USERS: 'greemzar_users',
  VERSION: 'greemzar_db_version'
};

// Increment this version to FORCE overwrite local data with empty lists
// v3.0: Clean Start - No Hardcoded Data
const CURRENT_DB_VERSION = 'v3.0-empty-force-fix';

const SEED_USERS: User[] = [{ username: 'riyaz', password: '6211', role: 'admin' }];

// --- MIGRATION / INITIALIZATION ---
try {
  const currentVersion = localStorage.getItem(KEYS.VERSION);
  if (currentVersion !== CURRENT_DB_VERSION) {
    console.log(`Migrating Data from ${currentVersion} to ${CURRENT_DB_VERSION}`);

    // FORCE WIPE LOCAL DATA to satisfy "REMOVE ALL DETAILS" request
    localStorage.setItem(KEYS.PARTIES, JSON.stringify([]));
    localStorage.setItem(KEYS.PRODUCTS, JSON.stringify([]));
    localStorage.setItem(KEYS.RATES, JSON.stringify([]));
    // We keep invoices usually, but since "EVERY THING" was requested, we wipe them if it's a hard reset.
    // However, users often want to keep history. We will sanitize history instead of deleting it, 
    // unless it's null/undefined.
    if (!localStorage.getItem(KEYS.INVOICES)) {
        localStorage.setItem(KEYS.INVOICES, JSON.stringify([]));
    }

    localStorage.setItem(KEYS.VERSION, CURRENT_DB_VERSION);
  }
} catch (e) {
  console.error("Migration failed", e);
}

export const Store = {
  resetToSeedData: () => {
    // RESETS TO EMPTY LISTS
    localStorage.setItem(KEYS.PARTIES, JSON.stringify([]));
    localStorage.setItem(KEYS.PRODUCTS, JSON.stringify([]));
    localStorage.setItem(KEYS.RATES, JSON.stringify([]));
    localStorage.setItem(KEYS.INVOICES, JSON.stringify([]));
    localStorage.setItem(KEYS.VERSION, CURRENT_DB_VERSION);
    window.location.reload();
  },

  getParties: (): Party[] => {
    const data = localStorage.getItem(KEYS.PARTIES);
    if (!data || data === 'null') return []; 
    try { return JSON.parse(data); } catch { return []; }
  },
  saveParties: (parties: Party[]) => localStorage.setItem(KEYS.PARTIES, JSON.stringify(parties)),

  getProducts: (): Product[] => {
    const data = localStorage.getItem(KEYS.PRODUCTS);
    if (!data || data === 'null') return [];
    try { return JSON.parse(data); } catch { return []; }
  },
  saveProducts: (products: Product[]) => localStorage.setItem(KEYS.PRODUCTS, JSON.stringify(products)),

  getRates: (): SpecialRate[] => {
    const data = localStorage.getItem(KEYS.RATES);
    if (!data || data === 'null') return [];
    try { return JSON.parse(data); } catch { return []; }
  },
  saveRates: (rates: SpecialRate[]) => localStorage.setItem(KEYS.RATES, JSON.stringify(rates)),

  getInvoices: (): Invoice[] => {
    const data = localStorage.getItem(KEYS.INVOICES);
    if (!data || data === 'null') return [];
    try {
        const parsed = JSON.parse(data);
        if (!Array.isArray(parsed)) return [];

        // CRITICAL: Sanitize data to prevent White Screen of Death
        return parsed.map((inv: any) => ({
            id: inv.id || crypto.randomUUID(),
            invoiceNumber: inv.invoiceNumber || 'Unknown',
            partyId: inv.partyId || '',
            partyName: inv.partyName || 'Unknown Party',
            date: inv.date || new Date().toISOString().split('T')[0],
            items: Array.isArray(inv.items) ? inv.items : [],
            subTotal: Number(inv.subTotal) || 0,
            taxPercent: Number(inv.taxPercent) || 0,
            taxAmount: Number(inv.taxAmount) || 0,
            globalDiscount: Number(inv.globalDiscount) || 0,
            grandTotal: Number(inv.grandTotal) || 0,
            vehicleNumber: inv.vehicleNumber || '',
            poNumber: inv.poNumber || '',
            partyAddress: inv.partyAddress || '',
            partyGst: inv.partyGst || '',
            partyPan: inv.partyPan || '',
            partyAadhar: inv.partyAadhar || '',
            partyPhone: inv.partyPhone || ''
        }));
    } catch (e) {
        console.error("Corrupt Invoice Data Found. Resetting to empty to fix crash.", e);
        return [];
    }
  },
  saveInvoice: (invoice: Invoice) => {
    const invoices = Store.getInvoices();
    invoices.unshift(invoice); // Add to top
    localStorage.setItem(KEYS.INVOICES, JSON.stringify(invoices));
  },
  updateInvoice: (updatedInvoice: Invoice) => {
    const invoices = Store.getInvoices();
    const index = invoices.findIndex(inv => inv.id === updatedInvoice.id);
    if (index !== -1) {
      invoices[index] = updatedInvoice;
      localStorage.setItem(KEYS.INVOICES, JSON.stringify(invoices));
    }
  },
  saveInvoices: (invoices: Invoice[]) => {
    localStorage.setItem(KEYS.INVOICES, JSON.stringify(invoices));
  },

  getUsers: (): User[] => {
    const data = localStorage.getItem(KEYS.USERS);
    try { return data ? JSON.parse(data) : SEED_USERS; } catch { return SEED_USERS; }
  },
  saveUsers: (users: User[]) => localStorage.setItem(KEYS.USERS, JSON.stringify(users)),
};

import { Invoice, Party, Product, SpecialRate, User } from '../types';
import { supabase } from './supabase';

export const Cloud = {
  // Flag to indicate we are using Supabase (replaces getScriptUrl check)
  getScriptUrl: () => 'SUPABASE_ENABLED', 
  setScriptUrl: (url: string) => {}, // No-op

  // --- ONE-TIME WIPE ---
  clearAllData: async () => {
    console.warn("WIPING ALL SERVER DATA...");
    // We assume ID is not 0 (UUIDs or text IDs)
    await supabase.from('special_rates').delete().neq('id', 0);
    await supabase.from('parties').delete().neq('id', '0'); 
    await supabase.from('products').delete().neq('id', '0');
    // Note: We are keeping invoices and users for now unless requested.
    return true;
  },

  // --- SYNC METHODS (UPSERT) ---

  syncInvoice: async (invoice: Invoice) => {
    const { error } = await supabase
      .from('invoices')
      .upsert({
        id: invoice.id,
        invoiceNumber: invoice.invoiceNumber,
        partyId: invoice.partyId,
        partyName: invoice.partyName,
        date: invoice.date,
        items: invoice.items, // JSONB column
        subTotal: invoice.subTotal,
        taxAmount: invoice.taxAmount,
        globalDiscount: invoice.globalDiscount,
        grandTotal: invoice.grandTotal,
        vehicleNumber: invoice.vehicleNumber,
        poNumber: invoice.poNumber,
        partyAddress: invoice.partyAddress,
        partyGst: invoice.partyGst,
        partyPan: invoice.partyPan,
        partyAadhar: invoice.partyAadhar,
        partyPhone: invoice.partyPhone
      });

    if (error) {
      console.error('Error syncing invoice:', error);
      return { success: false, error: error.message };
    }
    return { success: true };
  },

  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
    // 1. Sync Parties
    if (parties.length > 0) {
      const { error } = await supabase.from('parties').upsert(parties);
      if (error) console.error('Error syncing parties:', error);
    }

    // 2. Sync Products
    if (products.length > 0) {
      const { error } = await supabase.from('products').upsert(products);
      if (error) console.error('Error syncing products:', error);
    }

    // 3. Sync Users
    if (users.length > 0) {
      const { error } = await supabase.from('app_users').upsert(users);
      if (error) console.error('Error syncing users:', error);
    }

    // 4. Sync Rates (Delete old for party and insert new, or upsert if ID managed)
    const { error: delError } = await supabase.from('special_rates').delete().neq('id', 0); // Delete all
    if (!delError && rates.length > 0) {
         const { error } = await supabase.from('special_rates').insert(rates);
         if (error) console.error('Error syncing rates:', error);
    }
  },

  // --- FETCH METHODS ---

  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES' | 'INVOICES' | 'USERS'): Promise<any> => {
    if (type === 'PARTIES') {
      const { data, error } = await supabase.from('parties').select('*').order('name', { ascending: true });
      if (error) throw error;
      return data;
    }
    if (type === 'PRODUCTS') {
      const { data, error } = await supabase.from('products').select('*').order('name', { ascending: true });
      if (error) throw error;
      return data;
    }
    if (type === 'RATES') {
      const { data, error } = await supabase.from('special_rates').select('*').order('id', { ascending: true });
      if (error) throw error;
      return data;
    }
    return [];
  },

  fetchUsers: async (): Promise<User[]> => {
    const { data, error } = await supabase.from('app_users').select('*');
    if (error) {
      console.warn("Could not fetch users", error);
      throw error;
    }
    return data as User[];
  },

  fetchInvoices: async (): Promise<Invoice[]> => {
    const { data, error } = await supabase.from('invoices').select('*').order('created_at', { ascending: false });
    if (error) {
      console.error("Error fetching invoices", error);
      throw error;
    }

    // Safety mapping to ensure no null values crash the frontend
    return data.map((inv: any) => ({
      ...inv,
      invoiceNumber: inv.invoiceNumber || '',
      partyName: inv.partyName || 'Unknown Party',
      items: typeof inv.items === 'string' ? JSON.parse(inv.items) : (inv.items || []), // Handle JSONB or null
      // CRITICAL: Convert nulls to 0 to prevent toFixed() crashes
      subTotal: Number(inv.subTotal) || 0,
      taxAmount: Number(inv.taxAmount) || 0,
      globalDiscount: Number(inv.globalDiscount) || 0,
      grandTotal: Number(inv.grandTotal) || 0,
      taxPercent: Number(inv.taxPercent) || 0,
    })) as Invoice[];
  },

  testConnection: async () => {
    try {
      // Simple lightweight query to check connection
      const { error } = await supabase.from('parties').select('id').limit(1);
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (e: any) {
      return { success: false, error: e.message || "Unknown Connection Error" };
    }
  }
};

