import { Invoice, Party, Product, SpecialRate, User } from '../types';
import { supabase } from './supabase';

export const Cloud = {
  // Flag to indicate we are using Supabase (replaces getScriptUrl check)
  getScriptUrl: () => 'SUPABASE_ENABLED', 
  setScriptUrl: (url: string) => {}, // No-op

  // --- ONE-TIME WIPE ---
  clearAllData: async () => {
    // SECURITY: This function is disabled to prevent accidental data loss.
    // To re-enable, uncomment the lines below, but use with extreme caution.
    console.warn("Wipe command blocked by security policy.");

    /* 
    console.warn("WIPING ALL SERVER DATA...");
    // We assume ID is not 0 (UUIDs or text IDs)
    await supabase.from('special_rates').delete().neq('id', 0);
    await supabase.from('parties').delete().neq('id', '0'); 
    await supabase.from('products').delete().neq('id', '0');
    */

    // Note: We are keeping invoices and users for now unless requested.
    return true;
  },

  // --- SYNC METHODS (UPSERT) ---

  syncInvoice: async (invoice: Invoice) => {
    const { error } = await supabase
      .from('invoices')
      .upsert({
        id: invoice.id,
        invoiceNumber: invoice.invoiceNumber,
        partyId: invoice.partyId,
        partyName: invoice.partyName,
        date: invoice.date,
        items: invoice.items, // JSONB column
        subTotal: invoice.subTotal,
        taxAmount: invoice.taxAmount,
        globalDiscount: invoice.globalDiscount,
        grandTotal: invoice.grandTotal,
        vehicleNumber: invoice.vehicleNumber,
        poNumber: invoice.poNumber,
        partyAddress: invoice.partyAddress,
        partyGst: invoice.partyGst,
        partyPan: invoice.partyPan,
        partyAadhar: invoice.partyAadhar,
        partyPhone: invoice.partyPhone
      });

    if (error) {
      console.error('Error syncing invoice:', error);
      return { success: false, error: error.message };
    }
    return { success: true };
  },

  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
    // 1. Sync Parties
    if (parties.length > 0) {
      const { error } = await supabase.from('parties').upsert(parties);
      if (error) console.error('Error syncing parties:', error);
    }

    // 2. Sync Products
    if (products.length > 0) {
      const { error } = await supabase.from('products').upsert(products);
      if (error) console.error('Error syncing products:', error);
    }

    // 3. Sync Users
    if (users.length > 0) {
      const { error } = await supabase.from('app_users').upsert(users);
      if (error) console.error('Error syncing users:', error);
    }

    // 4. Sync Rates (Delete old for party and insert new, or upsert if ID managed)
    const { error: delError } = await supabase.from('special_rates').delete().neq('id', 0); // Delete all
    if (!delError && rates.length > 0) {
         const { error } = await supabase.from('special_rates').insert(rates);
         if (error) console.error('Error syncing rates:', error);
    }
  },

  // --- FETCH METHODS ---

  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES' | 'INVOICES' | 'USERS'): Promise<any> => {
    if (type === 'PARTIES') {
      const { data, error } = await supabase.from('parties').select('*').order('name', { ascending: true });
      if (error) throw error;
      return data;
    }
    if (type === 'PRODUCTS') {
      const { data, error } = await supabase.from('products').select('*').order('name', { ascending: true });
      if (error) throw error;
      return data;
    }
    if (type === 'RATES') {
      const { data, error } = await supabase.from('special_rates').select('*').order('id', { ascending: true });
      if (error) throw error;
      return data;
    }
    return [];
  },

  fetchUsers: async (): Promise<User[]> => {
    const { data, error } = await supabase.from('app_users').select('*');
    if (error) {
      console.warn("Could not fetch users", error);
      throw error;
    }
    return data as User[];
  },

  fetchInvoices: async (): Promise<Invoice[]> => {
    const { data, error } = await supabase.from('invoices').select('*').order('created_at', { ascending: false });
    if (error) {
      console.error("Error fetching invoices", error);
      throw error;
    }

    // Safety mapping to ensure no null values crash the frontend
    return data.map((inv: any) => ({
      ...inv,
      invoiceNumber: inv.invoiceNumber || '',
      partyName: inv.partyName || 'Unknown Party',
      items: typeof inv.items === 'string' ? JSON.parse(inv.items) : (inv.items || []), // Handle JSONB or null
      // CRITICAL: Convert nulls to 0 to prevent toFixed() crashes
      subTotal: Number(inv.subTotal) || 0,
      taxAmount: Number(inv.taxAmount) || 0,
      globalDiscount: Number(inv.globalDiscount) || 0,
      grandTotal: Number(inv.grandTotal) || 0,
      taxPercent: Number(inv.taxPercent) || 0,
    })) as Invoice[];
  },

  testConnection: async () => {
    try {
      // Simple lightweight query to check connection
      const { error } = await supabase.from('parties').select('id').limit(1);
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (e: any) {
      return { success: false, error: e.message || "Unknown Connection Error" };
    }
  }
};

export interface Party {
  id: string;        // A: Serial No (Internal UUID)
  name: string;      // B: Name
  code?: string;     // New: Auto-generated Serial/Short Code (e.g. C-001)
  address: string;   // C: Address
  city: string;      // D: City (New)
  phone: string;     // E: Phone
  gstNumber: string; // F: GST (New)
  aadharNumber: string;// G: Aadhar (New)
  panNumber: string; // H: PAN (New)
  email?: string;    // kept as optional internal field
}

export interface Product {
  id: string;
  name: string;
  code: string;
  standardRate: number;
  unit: string;
  hsn?: string;
  gstPercent?: number;
  qtyPerCase?: number;
}

// The core mapping: Party + Product = Specific Rate
export interface SpecialRate {
  partyId: string;
  productId: string;
  rate: number;
}

export interface InvoiceItem {
  id: string;
  productId: string;
  productName: string;
  quantity: number;
  rate: number; // This is now the GROSS (Inclusive) Rate
  baseRate: number; // New: Rate before Tax
  total: number; // Total Inclusive Amount (Qty * Rate)
  hsn?: string;
  gstPercent?: number;
}

export interface Invoice {
  id: string;
  invoiceNumber: string;
  partyId: string;
  partyName: string; 
  date: string;
  items: InvoiceItem[];
  subTotal: number;
  taxPercent: number;
  taxAmount: number;
  globalDiscount: number; // New: Discount on total invoice
  grandTotal: number;
  // New fields for the PDF format
  vehicleNumber?: string;
  poNumber?: string; // Reference No
  // Snapshot fields for Sheet Export "A to Z"
  partyAddress?: string;
  partyGst?: string;
  partyPan?: string;    // New Snapshot
  partyAadhar?: string; // New Snapshot
  partyPhone?: string;  // New Snapshot
}

export interface User {
