                         </td>
                       </tr>
                     );
                  })}
                  {statementData.length === 0 && (
                    <tr>
                       <td colSpan={4} className="px-6 py-12 text-center text-slate-400">
                          No invoices found for this party in the selected date range.
                       </td>
