    const pName = inv.partyName ? inv.partyName.toLowerCase() : '';
    const vNo = inv.vehicleNumber ? inv.vehicleNumber.toLowerCase() : '';

    return (
      invNo.includes(term) ||
      pName.includes(term) ||
      vNo.includes(term)
    );
  });

  if (!isAuthenticated) {
