export const Store = {
  getParties: (): Party[] => {
    const data = localStorage.getItem(KEYS.PARTIES);
    try { return data ? JSON.parse(data) : []; } catch { return []; }
  },
  saveParties: (parties: Party[]) => localStorage.setItem(KEYS.PARTIES, JSON.stringify(parties)),

  getProducts: (): Product[] => {
    const data = localStorage.getItem(KEYS.PRODUCTS);
    try { return data ? JSON.parse(data) : []; } catch { return []; }
  },
  saveProducts: (products: Product[]) => localStorage.setItem(KEYS.PRODUCTS, JSON.stringify(products)),

  getRates: (): SpecialRate[] => {
    const data = localStorage.getItem(KEYS.RATES);
    try { return data ? JSON.parse(data) : []; } catch { return []; }
  },
  saveRates: (rates: SpecialRate[]) => localStorage.setItem(KEYS.RATES, JSON.stringify(rates)),

  getInvoices: (): Invoice[] => {
    const data = localStorage.getItem(KEYS.INVOICES);
    try {
        const parsed = JSON.parse(data || '[]');
        return Array.isArray(parsed) ? parsed : [];
    } catch { return []; }
  },
  saveInvoice: (invoice: Invoice) => {
    const invoices = Store.getInvoices();
    invoices.unshift(invoice);
    localStorage.setItem(KEYS.INVOICES, JSON.stringify(invoices));
  },
  updateInvoice: (updatedInvoice: Invoice) => {
    const invoices = Store.getInvoices();
    const index = invoices.findIndex(inv => inv.id === updatedInvoice.id);
    if (index !== -1) {
      invoices[index] = updatedInvoice;
      localStorage.setItem(KEYS.INVOICES, JSON.stringify(invoices));
    }
  },
  saveInvoices: (invoices: Invoice[]) => localStorage.setItem(KEYS.INVOICES, JSON.stringify(invoices)),

  getUsers: (): User[] => {
    const data = localStorage.getItem(KEYS.USERS);
    try { return data ? JSON.parse(data) : SEED_USERS; } catch { return SEED_USERS; }
  },
  saveUsers: (users: User[]) => localStorage.setItem(KEYS.USERS, JSON.stringify(users)),
};

import { Invoice, Party, Product, SpecialRate, User } from '../types';
import { supabase } from './supabase';

export const Cloud = {
  getScriptUrl: () => 'SUPABASE_ENABLED', 

  clearAllData: async () => {
    console.warn("Wipe command blocked by security policy. Contact admin for manual DB resets.");
    return true;
  },

  syncInvoice: async (invoice: Invoice) => {
    const { error } = await supabase
      .from('invoices')
      .upsert({
        id: invoice.id,
        invoiceNumber: invoice.invoiceNumber,
        partyId: invoice.partyId,
        partyName: invoice.partyName,
        date: invoice.date,
        items: invoice.items,
        subTotal: invoice.subTotal,
        taxAmount: invoice.taxAmount,
        globalDiscount: invoice.globalDiscount,
        grandTotal: invoice.grandTotal,
        vehicleNumber: invoice.vehicleNumber,
        poNumber: invoice.poNumber,
        partyAddress: invoice.partyAddress,
        partyGst: invoice.partyGst,
        partyPan: invoice.partyPan,
        partyAadhar: invoice.partyAadhar,
        partyPhone: invoice.partyPhone
      });

    if (error) {
      console.error('Error syncing invoice:', error);
      return { success: false, error: error.message };
    }
    return { success: true };
  },

  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
    if (parties.length > 0) await supabase.from('parties').upsert(parties);
    if (products.length > 0) await supabase.from('products').upsert(products);
    if (users.length > 0) await supabase.from('app_users').upsert(users);

    await supabase.from('special_rates').delete().neq('id', 0);
    if (rates.length > 0) {
         await supabase.from('special_rates').insert(rates);
    }
  },

  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES'): Promise<any> => {
    if (type === 'PARTIES') {
      const { data, error } = await supabase.from('parties').select('*').order('name', { ascending: true });
      if (error) throw error;
      return data;
    }
    if (type === 'PRODUCTS') {
      const { data, error } = await supabase.from('products').select('*').order('name', { ascending: true });
      if (error) throw error;
      return data;
    }
    if (type === 'RATES') {
      const { data, error } = await supabase.from('special_rates').select('*');
      if (error) throw error;
      return data.map((r: any) => ({ partyId: r.partyId, productId: r.productId, rate: r.rate }));
    }
    return [];
  },

  fetchUsers: async (): Promise<User[]> => {
    const { data, error } = await supabase.from('app_users').select('*');
    if (error) throw error;
    return data as User[];
  },

  fetchInvoices: async (): Promise<Invoice[]> => {
    const { data, error } = await supabase.from('invoices').select('*').order('created_at', { ascending: false });
    if (error) throw error;

    return data.map((inv: any) => ({
      ...inv,
      items: typeof inv.items === 'string' ? JSON.parse(inv.items) : (inv.items || []),
      subTotal: Number(inv.subTotal) || 0,
      taxAmount: Number(inv.taxAmount) || 0,
      globalDiscount: Number(inv.globalDiscount) || 0,
      grandTotal: Number(inv.grandTotal) || 0,
      taxPercent: Number(inv.taxPercent) || 0,
    })) as Invoice[];
  },

  testConnection: async () => {
    try {
      const { error } = await supabase.from('parties').select('id').limit(1);
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (e: any) {
      return { success: false, error: e.message || "Unknown Connection Error" };
    }
  }
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Users, Package, DollarSign, FileText, History, Menu, X, Database, CheckCircle, RefreshCw, Loader2, LayoutDashboard, Printer, LogOut, User as UserIcon, Edit3, Download, MoreHorizontal, FileDown, Search, Trophy, ClipboardList, ScrollText } from 'lucide-react';
import { PartyManager } from './components/PartyManager';
import { ProductManager } from './components/ProductManager';
import { RateManager } from './components/RateManager';
import { Billing } from './components/Billing';
import { DataManager } from './components/DataManager';
import { UserManager } from './components/UserManager';
import { MoreMenu } from './components/MoreMenu';
import { InvoiceLogs } from './components/InvoiceLogs';
import { Ranking } from './components/Ranking';
import { PartyStatement } from './components/PartyStatement';
import { Login } from './components/Login';
import { Store } from './services/store';
import { Cloud } from './services/cloud';
import { Party, Product, SpecialRate, Invoice, ViewState, User } from './types';
import { InvoiceTemplate } from './components/InvoiceTemplate';
import { exportInvoicesToCSV } from './services/csv';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  const [validUsers, setValidUsers] = useState<User[]>(() => Store.getUsers());
  const [parties, setParties] = useState<Party[]>(() => Store.getParties());
  const [products, setProducts] = useState<Product[]>(() => Store.getProducts());
  const [specialRates, setSpecialRates] = useState<SpecialRate[]>(() => Store.getRates());
  const [invoices, setInvoices] = useState<Invoice[]>(() => Store.getInvoices());

  const [currentView, setCurrentView] = useState<ViewState>('billing');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [viewInvoice, setViewInvoice] = useState<Invoice | null>(null);
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);
  const [invoiceSearch, setInvoiceSearch] = useState('');
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);

  const [contextMenu, setContextMenu] = useState<{ visible: boolean; x: number; y: number; invoice: Invoice | null }>({
    visible: false,
    x: 0,
    y: 0,
    invoice: null,
  });

  const [pdfInvoice, setPdfInvoice] = useState<Invoice | null>(null);
  const pdfContainerRef = useRef<HTMLDivElement>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'pulling'>('idle');
  const cloudUrl = 'SUPABASE_ENABLED';

  const isFirstLoad = useRef(true);
  const hasPendingChanges = useRef(false);
  const isRemoteUpdate = useRef(false);
  const lastPushTime = useRef(0);

  const loadLocalData = () => {
    setParties(Store.getParties());
    setProducts(Store.getProducts());
    setSpecialRates(Store.getRates());
    setInvoices(Store.getInvoices());
    setValidUsers(Store.getUsers());
  };

  useEffect(() => {
    const handleClick = () => setContextMenu(prev => ({ ...prev, visible: false }));
    window.addEventListener('click', handleClick);
    return () => window.removeEventListener('click', handleClick);
  }, []);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('gfb_user');
    if (sessionUser) setIsAuthenticated(true);
    handleCloudPull();
  }, []);

  // --- AUTO-PUSH ---
  useEffect(() => {
    Store.saveParties(parties);
    Store.saveProducts(products);
    Store.saveRates(specialRates);
    Store.saveUsers(validUsers);

    if (isFirstLoad.current) {
      isFirstLoad.current = false;
      return;
    }

    if (isRemoteUpdate.current) {
       isRemoteUpdate.current = false; 
       return; 
    }

    hasPendingChanges.current = true;
    setSyncStatus('syncing');

    const handler = setTimeout(async () => {
       try {
         await Cloud.syncMasterData(parties, products, specialRates, validUsers);
         lastPushTime.current = Date.now();
         setSyncStatus('synced');
         hasPendingChanges.current = false;
         setTimeout(() => setSyncStatus('idle'), 2000);
       } catch (e) {
         console.error("Auto-sync failed", e);
         setSyncStatus('idle');
         hasPendingChanges.current = false; 
       }
    }, 2000); 

    return () => clearTimeout(handler);
  }, [parties, products, specialRates, validUsers]);

  const handleCloudPull = useCallback(async () => {
      if (syncStatus === 'syncing' || syncStatus === 'pulling' || hasPendingChanges.current) return;
      if (Date.now() - lastPushTime.current < 4000) return; 

      try {
        setSyncStatus('pulling');
        const [cloudParties, cloudProducts, cloudRates, cloudInvoices, cloudUsers] = await Promise.all([
           Cloud.fetchData('PARTIES'),
           Cloud.fetchData('PRODUCTS'),
           Cloud.fetchData('RATES'),
           Cloud.fetchInvoices(),
           Cloud.fetchUsers()
        ]);

        if (hasPendingChanges.current) {
           setSyncStatus('idle');
           return;
        }

        let updateData = false;
        if (JSON.stringify(cloudParties) !== JSON.stringify(parties)) { setParties(cloudParties); updateData = true; }
        if (JSON.stringify(cloudProducts) !== JSON.stringify(products)) { setProducts(cloudProducts); updateData = true; }
        if (JSON.stringify(cloudRates) !== JSON.stringify(specialRates)) { setSpecialRates(cloudRates); updateData = true; }

        if (cloudInvoices.length !== invoices.length) {
             setInvoices(cloudInvoices);
             Store.saveInvoices(cloudInvoices);
        }

        if (cloudUsers.length > 0 && JSON.stringify(cloudUsers) !== JSON.stringify(validUsers)) {
            setValidUsers(cloudUsers);
            Store.saveUsers(cloudUsers);
        }

        if (updateData) isRemoteUpdate.current = true;
        setSyncStatus('idle');
      } catch (e) {
        console.error("Supabase Pull Error", e);
        setSyncStatus('idle');
      }
  }, [parties, products, specialRates, invoices, validUsers, syncStatus]);

  // SETTING THE 5 SECOND INTERVAL AS REQUESTED
  useEffect(() => {
    const interval = setInterval(handleCloudPull, 5000); 
    return () => clearInterval(interval);
  }, [handleCloudPull]);

  const handleEditInvoice = (invoice: Invoice) => {
    setEditingInvoice(invoice);
    setCurrentView('billing');
  };

  const handlePrintOptions = (e: React.MouseEvent, invoice: Invoice) => {
    e.preventDefault();
    e.stopPropagation();
    setContextMenu({ visible: true, x: e.pageX - 120, y: e.pageY, invoice: invoice });
  };

  const handleMenuAction = (action: 'print' | 'download') => {
    const inv = contextMenu.invoice;
    setContextMenu(prev => ({ ...prev, visible: false }));
    if (inv) {
      if (action === 'print') setViewInvoice(inv);
      else if (action === 'download') setPdfInvoice(inv);
    }
  };

  if (!isAuthenticated) return <Login onLogin={(u) => { setIsAuthenticated(true); sessionStorage.setItem('gfb_user', JSON.stringify(u)); }} validUsers={validUsers} />;

  const NavItem = ({ view, icon: Icon, label }: { view: ViewState; icon: any; label: string }) => (
    <button
      onClick={() => { setCurrentView(view); setEditingInvoice(null); setIsMobileMenuOpen(false); }}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium mb-1 ${currentView === view ? 'bg-sky-100 text-sky-800 shadow-sm ring-1 ring-sky-200' : 'text-slate-500 hover:bg-slate-50 hover:text-sky-600'}`}
    >
      <Icon size={18} />
      <span>{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900">
      {/* Sync Status Widget */}
      <div className="fixed bottom-6 right-6 z-50">
        <div className="bg-white rounded-xl shadow-lg border border-slate-100 p-3 pr-4 flex items-center gap-3 min-w-[180px]">
          {syncStatus === 'syncing' || syncStatus === 'pulling' ? <RefreshCw className="text-orange-500 animate-spin" size={20} /> : <CheckCircle className="text-emerald-500" size={20} />}
          <div className="flex-1">
            <div className="font-bold text-xs text-slate-700">
              {syncStatus === 'syncing' ? 'Syncing...' : syncStatus === 'pulling' ? 'Updating...' : 'Connected'}
            </div>
          </div>
          <button onClick={handleCloudPull} className="p-1.5 hover:bg-slate-50 rounded-full text-slate-400"><RefreshCw size={14} /></button>
        </div>
      </div>

      {/* Sidebar */}
      <div className={`fixed md:static inset-y-0 left-0 w-64 bg-white border-r border-slate-200 transform transition-transform duration-300 z-[60] ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0 flex flex-col`}>
        <div className="p-6"><h1 className="text-xl font-bold text-slate-800">GREENZAR</h1></div>
        <nav className="px-4 py-2 flex-1 overflow-y-auto">
          <NavItem view="billing" icon={FileText} label="Create Invoice" />
          <NavItem view="history" icon={History} label="History" />
          <NavItem view="logs" icon={ClipboardList} label="All Logs" />
          <NavItem view="statement" icon={ScrollText} label="Statement" />
          <NavItem view="ranking" icon={Trophy} label="Ranking" />
          <div className="h-px bg-slate-100 my-4" />
          <NavItem view="parties" icon={Users} label="Parties" />
          <NavItem view="products" icon={Package} label="Products" />
          <NavItem view="rates" icon={DollarSign} label="Special Rates" />
          <NavItem view="users" icon={UserIcon} label="Users" />
          <NavItem view="data" icon={Database} label="Data Sync" />
        </nav>
      </div>

      {/* Main */}
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        {currentView === 'billing' && <Billing parties={parties} setParties={setParties} products={products} specialRates={specialRates} setSpecialRates={setSpecialRates} onInvoiceSaved={() => setInvoices(Store.getInvoices())} initialData={editingInvoice} />}
        {currentView === 'history' && (
          <div className="p-6 overflow-y-auto">
             <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold">Invoice History</h2>
                <input type="text" placeholder="Search..." value={invoiceSearch} onChange={e => setInvoiceSearch(e.target.value)} className="border px-4 py-2 rounded-lg outline-none" />
             </div>
             <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 border-b">
                      <tr><th className="px-6 py-4">#</th><th className="px-6 py-4">Party</th><th className="px-6 py-4 text-right">Total</th><th className="px-6 py-4 text-right">Actions</th></tr>
                   </thead>
                   <tbody>
                      {invoices.filter(i => i.partyName.toLowerCase().includes(invoiceSearch.toLowerCase())).map(inv => (
                        <tr key={inv.id} className="border-b hover:bg-slate-50">
                           <td className="px-6 py-4 font-mono">{inv.invoiceNumber}</td>
                           <td className="px-6 py-4 font-medium">{inv.partyName}</td>
                           <td className="px-6 py-4 text-right font-bold">₹{inv.grandTotal}</td>
                           <td className="px-6 py-4 text-right">
                              <button onClick={() => handleEditInvoice(inv)} className="p-2 text-slate-400 hover:text-orange-500"><Edit3 size={16}/></button>
                              <button onClick={(e) => handlePrintOptions(e, inv)} className="p-2 text-slate-400 hover:text-sky-500"><Printer size={16}/></button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        )}
        {currentView === 'parties' && <div className="h-full overflow-y-auto"><PartyManager parties={parties} setParties={setParties} /></div>}
        {currentView === 'products' && <div className="h-full overflow-y-auto"><ProductManager products={products} setProducts={setProducts} /></div>}
        {currentView === 'rates' && <RateManager parties={parties} products={products} specialRates={specialRates} setSpecialRates={setSpecialRates} />}
        {currentView === 'users' && <div className="h-full overflow-y-auto"><UserManager users={validUsers} setUsers={setValidUsers} /></div>}
        {currentView === 'data' && <div className="h-full overflow-y-auto"><DataManager parties={parties} products={products} specialRates={specialRates} invoices={invoices} refreshData={loadLocalData} onForcePush={async () => { setSyncStatus('syncing'); await Cloud.syncMasterData(parties, products, specialRates, validUsers); setSyncStatus('synced'); setTimeout(() => setSyncStatus('idle'), 2000); alert("Data Uploaded."); }} /></div>}
        {currentView === 'logs' && <div className="h-full overflow-y-auto"><InvoiceLogs invoices={invoices} /></div>}
        {currentView === 'ranking' && <div className="h-full overflow-y-auto"><Ranking invoices={invoices} parties={parties} /></div>}
        {currentView === 'statement' && <div className="h-full overflow-y-auto"><PartyStatement invoices={invoices} parties={parties} /></div>}
      </div>

      {/* Hidden PDF/Print views */}
