import React, { useState, useEffect, useRef } from 'react';
import { Party, Product, SpecialRate, Invoice, InvoiceItem } from '../types';
import { ShoppingCart, User, Plus, Trash2, Save, FileText, Loader2, Printer, X, CreditCard, Box, MapPin, Phone, Search, Tag, Sparkles, ArrowUpCircle } from 'lucide-react';
import { Store } from '../services/store';
import { Cloud } from '../services/cloud';
import { InvoiceTemplate } from './InvoiceTemplate';

interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (rates: SpecialRate[]) => void; 
  onInvoiceSaved: () => void;
  initialData?: Invoice | null; 
}

export const Billing: React.FC<Props> = ({ parties, setParties, products, specialRates, setSpecialRates, onInvoiceSaved, initialData }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string>('');
  const [partySearch, setPartySearch] = useState('');
  const [showPartySuggestions, setShowPartySuggestions] = useState(false);
  const [items, setItems] = useState<InvoiceItem[]>([]);
  const [invoiceDate, setInvoiceDate] = useState(new Date().toISOString().split('T')[0]);
  const [customInvoiceNo, setCustomInvoiceNo] = useState('');
  const [vehicleNo, setVehicleNo] = useState('');
  const [globalDiscount, setGlobalDiscount] = useState(0);
  const [isSaving, setIsSaving] = useState(false);

  const [productSearch, setProductSearch] = useState('');
  const [currentProductId, setCurrentProductId] = useState('');
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const [currentQty, setCurrentQty] = useState(0);
  const [currentRate, setCurrentRate] = useState(0);
  const [rateType, setRateType] = useState<'standard' | 'special' | 'manual'>('standard');

  useEffect(() => {
    if (initialData) {
      setSelectedPartyId(initialData.partyId);
      setPartySearch(initialData.partyName);
      setItems(initialData.items);
      setInvoiceDate(initialData.date);
      setCustomInvoiceNo(initialData.invoiceNumber);
      setVehicleNo(initialData.vehicleNumber || '');
      setGlobalDiscount(initialData.globalDiscount || 0);
    }
  }, [initialData]);

  // Rate lookup engine
  useEffect(() => {
    if (!currentProductId) return;
    const prod = products.find(p => p.id === currentProductId);
    if (!prod) return;

    const special = specialRates.find(r => r.partyId === selectedPartyId && r.productId === currentProductId);
    if (special) {
      setCurrentRate(special.rate);
      setRateType('special');
    } else {
      setCurrentRate(prod.standardRate);
      setRateType('standard');
    }
  }, [currentProductId, selectedPartyId, products, specialRates]);

  const addItem = () => {
    const prod = products.find(p => p.id === currentProductId);
    if (!prod || currentQty <= 0) return;

    const newItem: InvoiceItem = {
      id: crypto.randomUUID(),
      productId: prod.id,
      productName: prod.name,
      quantity: currentQty,
      rate: currentRate,
      baseRate: currentRate / (1 + (prod.gstPercent || 0)/100),
      total: currentQty * currentRate,
      gstPercent: prod.gstPercent
    };
    setItems([...items, newItem]);
    setProductSearch('');
    setCurrentProductId('');
    setCurrentQty(0);
  };

  const handleSave = async () => {
    if (!selectedPartyId || items.length === 0) return;
    setIsSaving(true);

    const subTotal = items.reduce((s, i) => s + i.total, 0);
    const newInvoice: Invoice = {
      id: initialData?.id || crypto.randomUUID(),
      invoiceNumber: customInvoiceNo || 'INV-' + Date.now(),
      partyId: selectedPartyId,
      partyName: partySearch,
      date: invoiceDate,
      items,
      subTotal,
      taxPercent: 0,
      taxAmount: items.reduce((s, i) => s + (i.total - i.baseRate * i.quantity), 0),
      globalDiscount,
      grandTotal: Math.round(subTotal - globalDiscount),
      vehicleNumber: vehicleNo
    };

    if (initialData) Store.updateInvoice(newInvoice);
    else Store.saveInvoice(newInvoice);

    await Cloud.syncInvoice(newInvoice);
    onInvoiceSaved();
    setIsSaving(false);
    alert("Invoice Saved Successfully!");
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 p-6 overflow-hidden">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
         {/* Customer Selection */}
         <div className="bg-white p-5 rounded-xl border relative shadow-sm">
            <label className="text-xs font-bold text-slate-400 uppercase block mb-2">Customer</label>
            <input type="text" value={partySearch} onChange={e => { setPartySearch(e.target.value); setShowPartySuggestions(true); }} placeholder="Search Party..." className="w-full border p-2 rounded-lg" />
            {showPartySuggestions && partySearch && (
              <div className="absolute left-5 right-5 z-20 bg-white border shadow-xl rounded-lg mt-1 max-h-40 overflow-y-auto">
                {parties.filter(p => p.name.toLowerCase().includes(partySearch.toLowerCase())).map(p => (
                  <div key={p.id} onClick={() => { setSelectedPartyId(p.id); setPartySearch(p.name); setShowPartySuggestions(false); }} className="p-3 hover:bg-sky-50 cursor-pointer border-b">
                    <div className="font-bold">{p.name}</div>
                    <div className="text-xs text-slate-400">{p.city}</div>
                  </div>
                ))}
              </div>
            )}
         </div>

         {/* Meta Details */}
         <div className="bg-white p-5 rounded-xl border shadow-sm grid grid-cols-2 gap-4">
            <div><label className="text-[10px] font-bold text-slate-400">Invoice No</label><input value={customInvoiceNo} onChange={e => setCustomInvoiceNo(e.target.value)} className="w-full border p-2 rounded-lg" /></div>
            <div><label className="text-[10px] font-bold text-slate-400">Vehicle</label><input value={vehicleNo} onChange={e => setVehicleNo(e.target.value)} className="w-full border p-2 rounded-lg" /></div>
         </div>
      </div>

      {/* Item Entry */}
      <div className="bg-sky-50 p-5 rounded-xl border border-sky-100 mb-6 flex gap-4 items-end relative">
         <div className="flex-1 relative">
            <label className="text-[10px] font-bold text-sky-700">Product</label>
            <input value={productSearch} onChange={e => { setProductSearch(e.target.value); setShowProductSuggestions(true); }} className="w-full border p-2 rounded-lg" />
            {showProductSuggestions && productSearch && (
               <div className="absolute left-0 right-0 z-20 bg-white border shadow-xl rounded-lg mt-1 max-h-40 overflow-y-auto">
                  {products.filter(p => p.name.toLowerCase().includes(productSearch.toLowerCase())).map(p => (
                    <div key={p.id} onClick={() => { setCurrentProductId(p.id); setProductSearch(p.name); setShowProductSuggestions(false); }} className="p-2 hover:bg-sky-50 cursor-pointer border-b">
                       <div className="font-bold">{p.name}</div>
                       <div className="text-xs text-slate-400">Std: ₹{p.standardRate}</div>
                    </div>
                  ))}
               </div>
            )}
         </div>
         <div className="w-24">
            <label className="text-[10px] font-bold text-sky-700">Qty</label>
            <input type="number" value={currentQty} onChange={e => setCurrentQty(parseFloat(e.target.value))} className="w-full border p-2 rounded-lg text-center" />
         </div>
         <div className="w-32">
            <label className="text-[10px] font-bold text-sky-700">Rate ({rateType})</label>
            <input type="number" value={currentRate} onChange={e => { setCurrentRate(parseFloat(e.target.value)); setRateType('manual'); }} className="w-full border p-2 rounded-lg text-right" />
         </div>
         <button onClick={addItem} className="bg-sky-600 text-white p-2.5 rounded-lg mb-[1px]"><Plus/></button>
      </div>

      {/* Table & Footer */}
      <div className="flex-1 bg-white border rounded-xl shadow-sm overflow-hidden flex flex-col">
         <div className="flex-1 overflow-y-auto">
            <table className="w-full text-left">
               <thead className="bg-slate-50 border-b">
                  <tr className="text-xs font-bold text-slate-500 uppercase">
                    <th className="p-4">Item</th><th className="p-4 text-center">Qty</th><th className="p-4 text-right">Rate</th><th className="p-4 text-right">Total</th><th className="p-4"></th>
                  </tr>
               </thead>
               <tbody>
                  {items.map(item => (
                    <tr key={item.id} className="border-b">
                       <td className="p-4 font-bold">{item.productName}</td>
                       <td className="p-4 text-center">{item.quantity}</td>
                       <td className="p-4 text-right">₹{item.rate}</td>
                       <td className="p-4 text-right font-black">₹{item.total}</td>
                       <td className="p-4 text-center"><button onClick={() => setItems(items.filter(i => i.id !== item.id))} className="text-red-400"><Trash2 size={16}/></button></td>
                    </tr>
                  ))}
               </tbody>
            </table>
         </div>
