import React, { useState, useEffect } from 'react';
import { Party, Product, SpecialRate, Invoice, User } from '../types';
import { Database, AlertTriangle, CheckCircle, CloudLightning, ArrowUpCircle, RefreshCw, XCircle, FileCode, Download, FileSpreadsheet, Share } from 'lucide-react';
import { Cloud } from '../services/cloud';
import { exportSupabasePartiesCSV, exportSupabaseProductsCSV, exportSupabaseRatesCSV, exportSupabaseInvoicesCSV, exportSupabaseUsersCSV } from '../services/csv';

interface Props {
  parties: Party[];
  products: Product[];
  specialRates: SpecialRate[];
  invoices: Invoice[];
  refreshData: () => void;
  onUrlChange?: (url: string) => void;
  onForcePush?: () => void;
}

export const DataManager: React.FC<Props> = ({ parties, products, specialRates, invoices, onForcePush }) => {
  const [statusMsg, setStatusMsg] = useState<{msg: string, type: 'success' | 'error'} | null>(null);
  const [connectionStatus, setConnectionStatus] = useState<'checking' | 'connected' | 'error'>('checking');
  const [connectionError, setConnectionError] = useState('');

  useEffect(() => {
    checkSupabaseConnection();
  }, []);

  const checkSupabaseConnection = async () => {
    setConnectionStatus('checking');
    const result = await Cloud.testConnection();
    if (result.success) {
      setConnectionStatus('connected');
    } else {
      setConnectionStatus('error');
      setConnectionError(result.error || 'Unknown Error');
    }
  };

  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    setStatusMsg({ msg: `${filename} Downloaded`, type: 'success' });
    setTimeout(() => setStatusMsg(null), 3000);
  };

  const generateSqlBackup = () => {
    let sql = `-- GREENZAR FULL DATABASE BACKUP\n-- Generated on: ${new Date().toLocaleString()}\n\n`;

    // 1. Parties
    sql += `-- PARTIES DATA\n`;
    parties.forEach(p => {
      sql += `INSERT INTO parties (id, name, code, address, city, phone, "gstNumber", "aadharNumber", "panNumber", email) VALUES ('${p.id}', '${p.name.replace(/'/g, "''")}', '${p.code || ''}', '${(p.address || '').replace(/'/g, "''")}', '${(p.city || '').replace(/'/g, "''")}', '${p.phone || ''}', '${p.gstNumber || ''}', '${p.aadharNumber || ''}', '${p.panNumber || ''}', '${p.email || ''}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, code = EXCLUDED.code;\n`;
    });

    // 2. Products
    sql += `\n-- PRODUCTS DATA\n`;
    products.forEach(p => {
      sql += `INSERT INTO products (id, name, code, "standardRate", unit, hsn, "gstPercent", "qtyPerCase") VALUES ('${p.id}', '${p.name.replace(/'/g, "''")}', '${p.code || ''}', ${p.standardRate}, '${p.unit}', '${p.hsn || ''}', ${p.gstPercent || 0}, ${p.qtyPerCase || 1}) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, "standardRate" = EXCLUDED."standardRate";\n`;
    });

    // 3. Special Rates
    sql += `\n-- SPECIAL RATES DATA\n`;
    specialRates.forEach(r => {
      if (r.id) {
        sql += `INSERT INTO special_rates (id, "partyId", "productId", rate) VALUES (${r.id}, '${r.partyId}', '${r.productId}', ${r.rate}) ON CONFLICT (id) DO UPDATE SET rate = EXCLUDED.rate;\n`;
      } else {
        sql += `INSERT INTO special_rates ("partyId", "productId", rate) VALUES ('${r.partyId}', '${r.productId}', ${r.rate});\n`;
      }
    });

    // 4. Invoices
    sql += `\n-- INVOICES DATA\n`;
    invoices.forEach(inv => {
      const itemsJson = JSON.stringify(inv.items).replace(/'/g, "''");
      sql += `INSERT INTO invoices (id, "invoiceNumber", "partyId", "partyName", date, items, "subTotal", "taxAmount", "globalDiscount", "grandTotal", "vehicleNumber", "poNumber", "partyAddress", "partyGst", "partyPan", "partyAadhar", "partyPhone") VALUES ('${inv.id}', '${inv.invoiceNumber}', '${inv.partyId}', '${(inv.partyName || '').replace(/'/g, "''")}', '${inv.date}', '${itemsJson}', ${inv.subTotal}, ${inv.taxAmount}, ${inv.globalDiscount}, ${inv.grandTotal}, '${inv.vehicleNumber || ''}', '${inv.poNumber || ''}', '${(inv.partyAddress || '').replace(/'/g, "''")}', '${inv.partyGst || ''}', '${inv.partyPan || ''}', '${inv.partyAadhar || ''}', '${inv.partyPhone || ''}') ON CONFLICT (id) DO NOTHING;\n`;
    });

    downloadFile(sql, `greenzar_full_backup_${new Date().toISOString().split('T')[0]}.sql`, 'text/sql');
  };

  const handleCsvExport = (table: 'parties' | 'products' | 'rates' | 'invoices' | 'users') => {
    let content = "";
    let filename = "";

    switch(table) {
        case 'parties':
            content = exportSupabasePartiesCSV(parties);
            filename = "supabase_parties_migration.csv";
            break;
        case 'products':
            content = exportSupabaseProductsCSV(products);
            filename = "supabase_products_migration.csv";
            break;
        case 'rates':
            content = exportSupabaseRatesCSV(specialRates);
            filename = "supabase_special_rates_migration.csv";
            break;
        case 'invoices':
            content = exportSupabaseInvoicesCSV(invoices);
            filename = "supabase_invoices_migration.csv";
            break;
        case 'users':
            const u = JSON.parse(localStorage.getItem('greemzar_users') || '[]');
            content = exportSupabaseUsersCSV(u);
            filename = "supabase_users_migration.csv";
            break;
    }

    downloadFile(content, filename, 'text/csv');
  };

  return (
    <div className="p-6 max-w-5xl mx-auto pb-20">
      <div className="mb-8 border-b border-slate-200 pb-6">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <Database className="text-sky-600" /> Data Management
        </h2>
        <p className="text-slate-500">
          Cloud sync control, SQL backups, and Supabase CSV migration tools.
        </p>
      </div>

      {statusMsg && (
        <div className={`fixed top-4 right-4 z-[200] px-6 py-4 rounded-xl shadow-xl flex items-center gap-3 animate-in slide-in-from-top-5 duration-300 ${statusMsg.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-500 text-white'}`}>
          {statusMsg.type === 'success' ? <CheckCircle /> : <AlertTriangle />}
          <span className="font-bold">{statusMsg.msg}</span>
        </div>
      )}

      {/* Connection Card */}
      <div className="bg-white border border-slate-200 shadow-xl shadow-slate-200/50 rounded-2xl p-6 mb-8">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-black text-slate-800 flex items-center gap-2 uppercase tracking-tight">
                <CloudLightning className="text-sky-500" /> Supabase Status
            </h3>
            <button 
                onClick={checkSupabaseConnection} 
                className="text-xs font-bold text-sky-600 hover:text-sky-800 flex items-center gap-1 bg-sky-50 px-3 py-1.5 rounded-lg transition-colors border border-sky-100"
            >
                <RefreshCw size={12} className={connectionStatus === 'checking' ? 'animate-spin' : ''} />
                Refresh
            </button>
          </div>

          <div className="space-y-4">
             {connectionStatus === 'connected' ? (
                <div className="flex items-center gap-4 bg-emerald-50 p-4 rounded-xl border border-emerald-200">
                    <div className="p-3 bg-white rounded-full text-emerald-600 shadow-sm"><CheckCircle size={24} /></div>
                    <div>
                        <h4 className="font-black text-emerald-900 uppercase text-xs tracking-wider">Live & Connected</h4>
                        <p className="text-xs text-emerald-700 font-medium">Automatic sync is active (every 5 seconds).</p>
                    </div>
                </div>
             ) : connectionStatus === 'error' ? (
                <div className="flex items-center gap-4 bg-red-50 p-4 rounded-xl border border-red-200">
