        </h2>
        <p className="text-slate-500">
          Cloud sync control, SQL backups, and Supabase CSV migration tools.
        </p>
      </div>

      {statusMsg && (
        <div className={`fixed top-4 right-4 z-[200] px-6 py-4 rounded-xl shadow-xl flex items-center gap-3 animate-in slide-in-from-top-5 duration-300 ${statusMsg.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-500 text-white'}`}>
          {statusMsg.type === 'success' ? <CheckCircle /> : <AlertTriangle />}
          <span className="font-bold">{statusMsg.msg}</span>
        </div>
      )}

      {/* Connection Card */}
      <div className="bg-white border border-slate-200 shadow-xl shadow-slate-200/50 rounded-2xl p-6 mb-8">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-black text-slate-800 flex items-center gap-2 uppercase tracking-tight">
                <CloudLightning className="text-sky-500" /> Supabase Status
            </h3>
            <button 
                onClick={checkSupabaseConnection} 
                className="text-xs font-bold text-sky-600 hover:text-sky-800 flex items-center gap-1 bg-sky-50 px-3 py-1.5 rounded-lg transition-colors border border-sky-100"
            >
                <RefreshCw size={12} className={connectionStatus === 'checking' ? 'animate-spin' : ''} />
                Refresh
            </button>
          </div>

          <div className="space-y-4">
             {connectionStatus === 'connected' ? (
                <div className="flex items-center gap-4 bg-emerald-50 p-4 rounded-xl border border-emerald-200">
                    <div className="p-3 bg-white rounded-full text-emerald-600 shadow-sm"><CheckCircle size={24} /></div>
                    <div>
                        <h4 className="font-black text-emerald-900 uppercase text-xs tracking-wider">Live & Connected</h4>
                        <p className="text-xs text-emerald-700 font-medium">Automatic sync is active (every 5 seconds).</p>
                    </div>
                </div>
             ) : connectionStatus === 'error' ? (
                <div className="flex items-center gap-4 bg-red-50 p-4 rounded-xl border border-red-200">
                    <div className="p-3 bg-white rounded-full text-red-600 shadow-sm"><XCircle size={24} /></div>
