import { Party, Product, SpecialRate, Invoice, User } from '../types';

// Helper to escape CSV fields
const safe = (str: string | number | undefined) => {
  if (str === undefined || str === null) return '';
  const s = String(str);
  if (s.includes(',') || s.includes('"') || s.includes('\n')) {
    return `"${s.replace(/"/g, '""')}"`;
  }
  return s;
};

// --- EXPORTERS FOR SUPABASE MIGRATION ---

export const exportSupabasePartiesCSV = (parties: Party[]) => {
  let csv = "id,name,code,address,city,phone,gstNumber,aadharNumber,panNumber,email\n";
  parties.forEach(p => {
    csv += `${safe(p.id)},${safe(p.name)},${safe(p.code)},${safe(p.address)},${safe(p.city)},${safe(p.phone)},${safe(p.gstNumber)},${safe(p.aadharNumber)},${safe(p.panNumber)},${safe(p.email)}\n`;
  });
  return csv;
};

export const exportSupabaseProductsCSV = (products: Product[]) => {
  let csv = "id,name,code,standardRate,unit,hsn,gstPercent,qtyPerCase\n";
  products.forEach(p => {
    csv += `${safe(p.id)},${safe(p.name)},${safe(p.code)},${p.standardRate},${safe(p.unit)},${safe(p.hsn)},${p.gstPercent || 0},${p.qtyPerCase || 1}\n`;
  });
  return csv;
};

// EXCLUDING ID for Rates to prevent the Supabase identity error during CSV import
export const exportSupabaseRatesCSV = (rates: SpecialRate[]) => {
  let csv = "partyId,productId,rate\n";
  rates.forEach(r => {
    csv += `${safe(r.partyId)},${safe(r.productId)},${r.rate}\n`;
  });
  return csv;
};

export const exportSupabaseInvoicesCSV = (invoices: Invoice[]) => {
  let csv = "id,invoiceNumber,partyId,partyName,date,items,subTotal,taxAmount,globalDiscount,grandTotal,vehicleNumber,poNumber,partyAddress,partyGst,partyPan,partyAadhar,partyPhone\n";
  invoices.forEach(inv => {
    const itemsJson = JSON.stringify(inv.items).replace(/"/g, '""');
    csv += `${safe(inv.id)},${safe(inv.invoiceNumber)},${safe(inv.partyId)},${safe(inv.partyName)},${safe(inv.date)},"${itemsJson}",${inv.subTotal},${inv.taxAmount},${inv.globalDiscount},${inv.grandTotal},${safe(inv.vehicleNumber)},${safe(inv.poNumber)},${safe(inv.partyAddress)},${safe(inv.partyGst)},${safe(inv.partyPan)},${safe(inv.partyAadhar)},${safe(inv.partyPhone)}\n`;
  });
  return csv;
};

export const exportSupabaseUsersCSV = (users: User[]) => {
