    invoices.forEach(inv => {
      const itemsJson = JSON.stringify(inv.items).replace(/'/g, "''");
      sql += `INSERT INTO invoices (id, "invoiceNumber", "partyId", "partyName", date, items, "subTotal", "taxAmount", "globalDiscount", "grandTotal", "vehicleNumber", "poNumber", "partyAddress", "partyGst", "partyPan", "partyAadhar", "partyPhone") VALUES ('${inv.id}', '${inv.invoiceNumber}', '${inv.partyId}', '${(inv.partyName || '').replace(/'/g, "''")}', '${inv.date}', '${itemsJson}', ${inv.subTotal}, ${inv.taxAmount}, ${inv.globalDiscount}, ${inv.grandTotal}, '${inv.vehicleNumber || ''}', '${inv.poNumber || ''}', '${(inv.partyAddress || '').replace(/'/g, "''")}', '${inv.partyGst || ''}', '${inv.partyPan || ''}', '${inv.partyAadhar || ''}', '${inv.partyPhone || ''}') ON CONFLICT (id) DO NOTHING;\n`;
    });

    downloadFile(sql, `greenzar_backup_${new Date().toISOString().split('T')[0]}.sql`, 'text/sql');
  };

  const handleCsvExport = (table: 'parties' | 'products' | 'rates' | 'invoices' | 'users') => {
    let content = "";
    let filename = "";
    switch(table) {
        case 'parties': content = exportSupabasePartiesCSV(parties); filename = "parties_migration.csv"; break;
        case 'products': content = exportSupabaseProductsCSV(products); filename = "products_migration.csv"; break;
        case 'rates': content = exportSupabaseRatesCSV(specialRates); filename = "special_rates_migration.csv"; break;
        case 'invoices': content = exportSupabaseInvoicesCSV(invoices); filename = "invoices_migration.csv"; break;
        case 'users':
            const u = JSON.parse(localStorage.getItem('greemzar_users') || '[]');
            content = exportSupabaseUsersCSV(u);
            filename = "users_migration.csv";
            break;
    }
    downloadFile(content, filename, 'text/csv');
  };

  return (
    <div className="p-6 max-w-5xl mx-auto pb-20">
      <div className="mb-8 border-b border-slate-200 pb-6">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <Database className="text-sky-600" /> Data Management
        </h2>
        <p className="text-slate-500">
          Sync control, SQL backups, and specialized Supabase migration tools.
        </p>
      </div>

      {statusMsg && (
        <div className={`fixed top-4 right-4 z-[200] px-6 py-4 rounded-xl shadow-xl flex items-center gap-3 animate-in slide-in-from-top-5 duration-300 ${statusMsg.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-500 text-white'}`}>
          {statusMsg.type === 'success' ? <CheckCircle /> : <AlertTriangle />}
          <span className="font-bold">{statusMsg.msg}</span>
        </div>
      )}

      {/* ERROR TROUBLESHOOTING BOX */}
      <div className="bg-red-50 border border-red-200 rounded-2xl p-6 mb-8 flex flex-col md:flex-row gap-6 items-center">
          <div className="p-4 bg-white rounded-full text-red-500 shadow-sm shrink-0">
              <AlertTriangle size={32} />
          </div>
          <div className="flex-1">
              <h3 className="font-black text-red-900 uppercase text-xs tracking-wider mb-1">Fix Error 23503 (Foreign Key)</h3>
              <p className="text-sm text-red-800 leading-relaxed">
                  If you see "violates foreign key constraint", it means you are importing Special Rates before the Parties. 
                  <b> You MUST import Parties FIRST, then Products, and Special Rates LAST.</b>
              </p>
          </div>
      </div>

      {/* SQL FIX INSTRUCTION */}
      <div className="bg-orange-50 border border-orange-200 rounded-2xl p-6 mb-8 flex flex-col md:flex-row gap-6 items-center">
          <div className="p-4 bg-white rounded-full text-orange-500 shadow-sm shrink-0">
              <Info size={32} />
          </div>
          <div className="flex-1">
              <h3 className="font-black text-orange-900 uppercase text-xs tracking-wider mb-1">Fix "GENERATED ALWAYS" Error</h3>
              <p className="text-sm text-orange-800 leading-relaxed mb-4">
                  If Supabase blocks your import with "GENERATED ALWAYS", run this command in the SQL Editor.
              </p>
              <div className="flex flex-wrap gap-2">
                  <button onClick={copyFixSql} className="flex items-center gap-2 bg-white border border-orange-200 text-orange-700 px-4 py-2 rounded-lg text-xs font-bold hover:bg-orange-100 transition-colors">
                      <Copy size={14} /> Copy SQL Fix Command
                  </button>
                  <button onClick={() => setShowFixSql(!showFixSql)} className="flex items-center gap-2 bg-orange-600 text-white px-4 py-2 rounded-lg text-xs font-bold hover:bg-orange-700 transition-colors">
                      <Info size={14} /> {showFixSql ? 'Hide' : 'Show'} Command
                  </button>
              </div>
              {showFixSql && (
                  <pre className="mt-4 bg-slate-900 text-sky-400 p-4 rounded-xl text-xs font-mono overflow-x-auto border border-slate-800">
                      ALTER TABLE special_rates ALTER COLUMN id SET GENERATED BY DEFAULT;
                  </pre>
              )}
          </div>
      </div>

      {/* CSV MIGRATION - WITH ENFORCED ORDER */}
      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm p-8 mb-8">
          <div className="mb-6">
              <h3 className="text-lg font-black text-slate-800 flex items-center gap-2 uppercase tracking-tight">
                  <ListChecks className="text-emerald-500" /> 1. Required Import Order (CSV)
              </h3>
              <p className="text-sm text-slate-500 mt-1">Download and import these files into Supabase <b>in this specific order</b> to avoid errors.</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
             {/* Step 1: Parties */}
             <div className="bg-slate-50 rounded-xl p-5 border-2 border-dashed border-slate-200 flex flex-col items-center text-center">
                 <div className="w-10 h-10 bg-sky-600 text-white rounded-full flex items-center justify-center font-black mb-4 shadow-lg">1</div>
                 <h4 className="font-bold text-slate-800 text-sm mb-1">Parties Table</h4>
                 <p className="text-[10px] text-slate-500 mb-4">Must be imported first. Contains customer IDs.</p>
                 <button onClick={() => handleCsvExport('parties')} className="w-full bg-white border border-slate-200 py-2 rounded-lg text-xs font-bold flex items-center justify-center gap-2 hover:bg-slate-100 transition-all">
                     <Download size={14} /> Download Parties
                 </button>
             </div>

             {/* Step 2: Products */}
             <div className="bg-slate-50 rounded-xl p-5 border-2 border-dashed border-slate-200 flex flex-col items-center text-center">
                 <div className="w-10 h-10 bg-sky-600 text-white rounded-full flex items-center justify-center font-black mb-4 shadow-lg">2</div>
                 <h4 className="font-bold text-slate-800 text-sm mb-1">Products Table</h4>
                 <p className="text-[10px] text-slate-500 mb-4">Import after Parties. Contains Item IDs.</p>
                 <button onClick={() => handleCsvExport('products')} className="w-full bg-white border border-slate-200 py-2 rounded-lg text-xs font-bold flex items-center justify-center gap-2 hover:bg-slate-100 transition-all">
                     <Download size={14} /> Download Products
                 </button>
             </div>

             {/* Step 3: Special Rates */}
             <div className="bg-emerald-50 rounded-xl p-5 border-2 border-emerald-200 flex flex-col items-center text-center">
                 <div className="w-10 h-10 bg-emerald-600 text-white rounded-full flex items-center justify-center font-black mb-4 shadow-lg shadow-emerald-100">3</div>
                 <h4 className="font-bold text-emerald-900 text-sm mb-1">Special Rates</h4>
                 <p className="text-[10px] text-emerald-700 mb-4">Import LAST. Links Parties to Products.</p>
                 <button onClick={() => handleCsvExport('rates')} className="w-full bg-emerald-600 text-white py-2 rounded-lg text-xs font-bold flex items-center justify-center gap-2 hover:bg-emerald-700 transition-all">
                     <Download size={14} /> Download Rates
                 </button>
             </div>
          </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
          <div className="bg-slate-900 text-white p-8 rounded-2xl shadow-xl flex flex-col justify-between items-start gap-4">
              <div>
                  <div className="p-3 bg-white/10 text-white rounded-xl w-fit mb-4 backdrop-blur-md">
                      <FileCode size={32} />
                  </div>
                  <h4 className="text-xl font-black uppercase tracking-tight mb-2">Full SQL Backup</h4>
                  <p className="text-sm text-slate-400 leading-relaxed">Download a complete script to rebuild your database. Optimized for Supabase compatibility.</p>
              </div>
              <button onClick={generateSqlBackup} className="mt-4 w-full flex items-center justify-center gap-3 bg-white text-slate-900 hover:bg-slate-100 font-black py-4 rounded-xl transition-all shadow-lg">
                  <Download size={20} /> Export SQL Script
              </button>
          </div>

          <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between items-start gap-4">
              <div>
                  <div className="p-3 bg-orange-100 text-orange-600 rounded-xl w-fit mb-4">
                      <ArrowUpCircle size={32} />
                  </div>
                  <h4 className="text-xl font-black text-slate-800 uppercase tracking-tight mb-2">Supabase Status</h4>
                  <div className="mt-2">
                    {connectionStatus === 'connected' ? (
                        <span className="text-emerald-600 font-bold text-sm flex items-center gap-1"><CheckCircle size={14} /> Live & Connected</span>
                    ) : (
                        <span className="text-red-500 font-bold text-sm flex items-center gap-1"><XCircle size={14} /> Disconnected</span>
                    )}
                  </div>
              </div>
              <button onClick={onForcePush} disabled={connectionStatus !== 'connected'} className="mt-4 w-full flex items-center justify-center gap-3 bg-orange-600 hover:bg-orange-700 disabled:bg-slate-200 disabled:text-slate-400 text-white font-black py-4 rounded-xl transition-all shadow-lg">
                  <RefreshCw size={20} className={connectionStatus === 'checking' ? 'animate-spin' : ''} /> Force Cloud Push
              </button>
          </div>
      </div>

      {/* OTHER CSVS */}
      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm p-8">
          <div className="mb-6">
              <h3 className="text-lg font-black text-slate-800 flex items-center gap-2 uppercase tracking-tight">
                  <FileSpreadsheet className="text-emerald-500" /> 2. Additional Tables
              </h3>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
             <button onClick={() => handleCsvExport('invoices')} className="flex items-center justify-between p-4 bg-slate-50 border border-slate-200 rounded-xl hover:bg-slate-100 transition-all group">
                 <div className="text-left text-xs font-bold text-slate-500">Invoices.csv</div>
                 <Download size={18} className="text-slate-300 group-hover:text-slate-500" />
             </button>

             <button onClick={() => handleCsvExport('users')} className="flex items-center justify-between p-4 bg-slate-50 border border-slate-200 rounded-xl hover:bg-slate-100 transition-all group">
                 <div className="text-left text-xs font-bold text-slate-500">Users.csv</div>
                 <Download size={18} className="text-slate-300 group-hover:text-slate-500" />
             </button>
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Party, Product, SpecialRate, Invoice, User } from '../types';
import { Database, AlertTriangle, CheckCircle, CloudLightning, ArrowUpCircle, RefreshCw, XCircle, FileCode, Download, FileSpreadsheet, Share, Copy, Info, ListChecks, Zap } from 'lucide-react';
import { Cloud } from '../services/cloud';
import { exportSupabasePartiesCSV, exportSupabaseProductsCSV, exportSupabaseRatesCSV, exportSupabaseInvoicesCSV, exportSupabaseUsersCSV } from '../services/csv';

interface Props {
  parties: Party[];
  products: Product[];
  specialRates: SpecialRate[];
  invoices: Invoice[];
  refreshData: () => void;
  onUrlChange?: (url: string) => void;
  onForcePush?: () => void;
}

export const DataManager: React.FC<Props> = ({ parties, products, specialRates, invoices, onForcePush }) => {
  const [statusMsg, setStatusMsg] = useState<{msg: string, type: 'success' | 'error'} | null>(null);
  const [connectionStatus, setConnectionStatus] = useState<'checking' | 'connected' | 'error'>('checking');
  const [connectionError, setConnectionError] = useState('');
  const [showFixSql, setShowFixSql] = useState(false);

  useEffect(() => {
    checkSupabaseConnection();
  }, []);

  const checkSupabaseConnection = async () => {
    setConnectionStatus('checking');
    const result = await Cloud.testConnection();
    if (result.success) {
      setConnectionStatus('connected');
    } else {
      setConnectionStatus('error');
      setConnectionError(result.error || 'Unknown Error');
    }
  };

  const copyMasterFixSql = () => {
    const sql = `-- 1. CLEAR EXISTING DATA (To avoid conflicts)
TRUNCATE TABLE special_rates, invoices, parties, products CASCADE;

-- 2. ALLOW MANUAL IDs (Fixes "GENERATED ALWAYS" Error)
ALTER TABLE parties ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE products ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE special_rates ALTER COLUMN id SET GENERATED BY DEFAULT;`;
    navigator.clipboard.writeText(sql);
    setStatusMsg({ msg: "Master Fix SQL Copied!", type: 'success' });
    setTimeout(() => setStatusMsg(null), 3000);
  };

  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    setStatusMsg({ msg: `${filename} Downloaded`, type: 'success' });
    setTimeout(() => setStatusMsg(null), 3000);
  };

  const generateSqlBackup = () => {
    let sql = `-- GREENZAR FULL DATABASE BACKUP\n-- Generated on: ${new Date().toLocaleString()}\n\n`;

    sql += `-- 1. PARTIES\n`;
    parties.forEach(p => {
      sql += `INSERT INTO parties (id, name, code, address, city, phone, "gstNumber", "aadharNumber", "panNumber", email) VALUES ('${p.id}', '${p.name.replace(/'/g, "''")}', '${p.code || ''}', '${(p.address || '').replace(/'/g, "''")}', '${(p.city || '').replace(/'/g, "''")}', '${p.phone || ''}', '${p.gstNumber || ''}', '${p.aadharNumber || ''}', '${p.panNumber || ''}', '${p.email || ''}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name;\n`;
    });

    sql += `\n-- 2. PRODUCTS\n`;
    products.forEach(p => {
      sql += `INSERT INTO products (id, name, code, "standardRate", unit, hsn, "gstPercent", "qtyPerCase") VALUES ('${p.id}', '${p.name.replace(/'/g, "''")}', '${p.code || ''}', ${p.standardRate}, '${p.unit}', '${p.hsn || ''}', ${p.gstPercent || 0}, ${p.qtyPerCase || 1}) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name;\n`;
    });

    sql += `\n-- 3. SPECIAL RATES\n`;
    specialRates.forEach(r => {
      sql += `INSERT INTO special_rates ("partyId", "productId", rate) VALUES ('${r.partyId}', '${r.productId}', ${r.rate}) ON CONFLICT ("partyId", "productId") DO UPDATE SET rate = EXCLUDED.rate;\n`;
    });

    sql += `\n-- 4. INVOICES\n`;
    invoices.forEach(inv => {
      const itemsJson = JSON.stringify(inv.items).replace(/'/g, "''");
      sql += `INSERT INTO invoices (id, "invoiceNumber", "partyId", "partyName", date, items, "subTotal", "taxAmount", "globalDiscount", "grandTotal", "vehicleNumber", "poNumber", "partyAddress", "partyGst", "partyPan", "partyAadhar", "partyPhone") VALUES ('${inv.id}', '${inv.invoiceNumber}', '${inv.partyId}', '${(inv.partyName || '').replace(/'/g, "''")}', '${inv.date}', '${itemsJson}', ${inv.subTotal}, ${inv.taxAmount}, ${inv.globalDiscount}, ${inv.grandTotal}, '${inv.vehicleNumber || ''}', '${inv.poNumber || ''}', '${(inv.partyAddress || '').replace(/'/g, "''")}', '${inv.partyGst || ''}', '${inv.partyPan || ''}', '${inv.partyAadhar || ''}', '${inv.partyPhone || ''}') ON CONFLICT (id) DO NOTHING;\n`;
    });

    downloadFile(sql, `greenzar_backup_${new Date().toISOString().split('T')[0]}.sql`, 'text/sql');
  };

  const handleCsvExport = (table: 'parties' | 'products' | 'rates' | 'invoices' | 'users') => {
    let content = "";
    let filename = "";
    switch(table) {
        case 'parties': content = exportSupabasePartiesCSV(parties); filename = "parties_migration.csv"; break;
        case 'products': content = exportSupabaseProductsCSV(products); filename = "products_migration.csv"; break;
        case 'rates': content = exportSupabaseRatesCSV(specialRates); filename = "special_rates_migration.csv"; break;
        case 'invoices': content = exportSupabaseInvoicesCSV(invoices); filename = "invoices_migration.csv"; break;
        case 'users':
            const u = JSON.parse(localStorage.getItem('greemzar_users') || '[]');
            content = exportSupabaseUsersCSV(u);
            filename = "users_migration.csv";
            break;
    }
    downloadFile(content, filename, 'text/csv');
  };

  return (
    <div className="p-6 max-w-5xl mx-auto pb-20">
      <div className="mb-8 border-b border-slate-200 pb-6">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <Database className="text-sky-600" /> Data Management
        </h2>
        <p className="text-slate-500">
          Sync control, SQL backups, and specialized Supabase migration tools.
        </p>
      </div>

      {statusMsg && (
        <div className={`fixed top-4 right-4 z-[200] px-6 py-4 rounded-xl shadow-xl flex items-center gap-3 animate-in slide-in-from-top-5 duration-300 ${statusMsg.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-500 text-white'}`}>
          {statusMsg.type === 'success' ? <CheckCircle /> : <AlertTriangle />}
          <span className="font-bold">{statusMsg.msg}</span>
        </div>
      )}

      {/* MASTER DATABASE FIX BOX */}
      <div className="bg-sky-900 text-white rounded-2xl p-8 mb-8 shadow-2xl relative overflow-hidden">
          <div className="absolute top-0 right-0 p-4 opacity-10">
              <Zap size={120} />
          </div>
          <div className="relative z-10">
              <h3 className="text-xl font-black uppercase tracking-widest mb-2 flex items-center gap-2">
                <Zap className="text-yellow-400" fill="currentColor" /> Master Fix Script
              </h3>
              <p className="text-sky-100 text-sm mb-6 max-w-2xl leading-relaxed">
                  To fix <b>Error 23503 (Foreign Key)</b> and <b>GENERATED ALWAYS</b> errors, run this script in the 
                  <span className="font-bold text-white underline mx-1">Supabase SQL Editor</span> before importing your CSVs.
              </p>
              <div className="flex flex-wrap gap-4">
                  <button 
                    onClick={copyMasterFixSql} 
                    className="bg-yellow-400 hover:bg-yellow-300 text-sky-950 px-6 py-3 rounded-xl font-black text-sm transition-all flex items-center gap-2 shadow-lg active:scale-95"
                  >
                      <Copy size={18} /> Copy Master Fix SQL
                  </button>
                  <button 
                    onClick={() => setShowFixSql(!showFixSql)} 
                    className="bg-white/10 hover:bg-white/20 text-white px-6 py-3 rounded-xl font-bold text-sm transition-all flex items-center gap-2"
                  >
                      <Info size={18} /> {showFixSql ? 'Hide Script' : 'View Script'}
                  </button>
              </div>
              {showFixSql && (
                  <pre className="mt-6 bg-black/40 text-sky-300 p-6 rounded-xl text-xs font-mono overflow-x-auto border border-white/10 backdrop-blur-sm">
{`-- Run this to reset tables and allow manual ID insertion
TRUNCATE TABLE special_rates, invoices, parties, products CASCADE;

ALTER TABLE parties ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE products ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE special_rates ALTER COLUMN id SET GENERATED BY DEFAULT;`}
                  </pre>
              )}
          </div>
      </div>

      {/* CSV MIGRATION - STEP BY STEP GUIDE */}
      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm p-8 mb-8">
          <div className="mb-8 flex justify-between items-start">
              <div>
                <h3 className="text-lg font-black text-slate-800 flex items-center gap-2 uppercase tracking-tight">
                    <ListChecks className="text-emerald-500" /> Required Import Order
                </h3>
                <p className="text-sm text-slate-500 mt-1">Download and import these files <b>AFTER</b> running the Fix Script above.</p>
              </div>
              <div className="bg-red-50 text-red-600 px-4 py-2 rounded-lg text-xs font-bold border border-red-100 flex items-center gap-2">
                 <AlertTriangle size={14} /> Never import Rates before Parties!
              </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
             {/* Step 1: Parties */}
             <div className="bg-slate-50 rounded-xl p-6 border-2 border-dashed border-slate-200 flex flex-col items-center text-center group hover:border-sky-300 transition-all">
                 <div className="w-12 h-12 bg-sky-600 text-white rounded-full flex items-center justify-center font-black mb-4 shadow-lg ring-4 ring-sky-100 group-hover:scale-110 transition-transform">1</div>
                 <h4 className="font-bold text-slate-800 text-sm mb-1 uppercase tracking-tighter">Parties Table</h4>
                 <p className="text-[10px] text-slate-500 mb-6 leading-relaxed">Import this FIRST. It creates the Customer IDs that Rates depend on.</p>
                 <button onClick={() => handleCsvExport('parties')} className="w-full bg-white border border-slate-200 py-3 rounded-xl text-xs font-bold flex items-center justify-center gap-2 hover:bg-slate-100 transition-all shadow-sm">
                     <Download size={14} /> Download Parties
                 </button>
             </div>

             {/* Step 2: Products */}
             <div className="bg-slate-50 rounded-xl p-6 border-2 border-dashed border-slate-200 flex flex-col items-center text-center group hover:border-sky-300 transition-all">
                 <div className="w-12 h-12 bg-sky-600 text-white rounded-full flex items-center justify-center font-black mb-4 shadow-lg ring-4 ring-sky-100 group-hover:scale-110 transition-transform">2</div>
                 <h4 className="font-bold text-slate-800 text-sm mb-1 uppercase tracking-tighter">Products Table</h4>
                 <p className="text-[10px] text-slate-500 mb-6 leading-relaxed">Import this SECOND. It creates the Product IDs used in Rates.</p>
                 <button onClick={() => handleCsvExport('products')} className="w-full bg-white border border-slate-200 py-3 rounded-xl text-xs font-bold flex items-center justify-center gap-2 hover:bg-slate-100 transition-all shadow-sm">
                     <Download size={14} /> Download Products
                 </button>
             </div>

             {/* Step 3: Special Rates */}
             <div className="bg-emerald-50 rounded-xl p-6 border-2 border-emerald-200 flex flex-col items-center text-center group hover:border-emerald-300 transition-all">
                 <div className="w-12 h-12 bg-emerald-600 text-white rounded-full flex items-center justify-center font-black mb-4 shadow-lg ring-4 ring-emerald-100 group-hover:scale-110 transition-transform">3</div>
                 <h4 className="font-bold text-emerald-900 text-sm mb-1 uppercase tracking-tighter">Special Rates</h4>
                 <p className="text-[10px] text-emerald-700 mb-6 leading-relaxed">Import this LAST. This is the file causing Error 23503 if Steps 1 & 2 are missed.</p>
                 <button onClick={() => handleCsvExport('rates')} className="w-full bg-emerald-600 text-white py-3 rounded-xl text-xs font-bold flex items-center justify-center gap-2 hover:bg-emerald-700 transition-all shadow-lg">
                     <Download size={14} /> Download Rates
                 </button>
             </div>
          </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
          <div className="bg-slate-900 text-white p-8 rounded-2xl shadow-xl flex flex-col justify-between items-start gap-4">
              <div>
                  <div className="p-3 bg-white/10 text-white rounded-xl w-fit mb-4 backdrop-blur-md">
                      <FileCode size={32} />
                  </div>
                  <h4 className="text-xl font-black uppercase tracking-tight mb-2">Full SQL Backup</h4>
                  <p className="text-sm text-slate-400 leading-relaxed">A complete script to rebuild your database. Best for advanced users.</p>
              </div>
              <button onClick={generateSqlBackup} className="mt-4 w-full flex items-center justify-center gap-3 bg-white text-slate-900 hover:bg-slate-100 font-black py-4 rounded-xl transition-all shadow-lg">
                  <Download size={20} /> Export SQL Script
              </button>
