import React, { useState, useEffect } from 'react';
import { Party, Product, SpecialRate, Invoice, User } from '../types';
import { Database, AlertTriangle, CheckCircle, CloudLightning, ArrowUpCircle, RefreshCw, XCircle, FileCode, Download, FileSpreadsheet, Share, Copy, Info, ListChecks, Zap, Terminal } from 'lucide-react';
import { Cloud } from '../services/cloud';
import { exportSupabasePartiesCSV, exportSupabaseProductsCSV, exportSupabaseRatesCSV, exportSupabaseInvoicesCSV, exportSupabaseUsersCSV } from '../services/csv';

interface Props {
  parties: Party[];
  products: Product[];
  specialRates: SpecialRate[];
  invoices: Invoice[];
  refreshData: () => void;
  onUrlChange?: (url: string) => void;
  onForcePush?: () => void;
}

export const DataManager: React.FC<Props> = ({ parties, products, specialRates, invoices, onForcePush }) => {
  const [activeTab, setActiveTab] = useState<'sync' | 'setup' | 'backup'>('sync');
  const [statusMsg, setStatusMsg] = useState<{msg: string, type: 'success' | 'error'} | null>(null);
  const [connectionStatus, setConnectionStatus] = useState<'checking' | 'connected' | 'error'>('checking');
  const [connectionError, setConnectionError] = useState('');
  const [showFixSql, setShowFixSql] = useState(false);

  useEffect(() => {
    checkSupabaseConnection();
  }, []);

  const checkSupabaseConnection = async () => {
    setConnectionStatus('checking');
    const result = await Cloud.testConnection();
    if (result.success) {
      setConnectionStatus('connected');
    } else {
      setConnectionStatus('error');
      setConnectionError(result.error || 'Unknown Error');
    }
  };

  const schemaSql = `-- 1. PARTIES
CREATE TABLE IF NOT EXISTS parties (id TEXT PRIMARY KEY, name TEXT NOT NULL, code TEXT, address TEXT, city TEXT, phone TEXT, "gstNumber" TEXT, "aadharNumber" TEXT, "panNumber" TEXT, email TEXT);

-- 2. PRODUCTS
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, name TEXT NOT NULL, code TEXT, "standardRate" NUMERIC, unit TEXT, hsn TEXT, "gstPercent" NUMERIC, "qtyPerCase" NUMERIC);

-- 3. SPECIAL RATES
CREATE TABLE IF NOT EXISTS special_rates (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "partyId" TEXT REFERENCES parties(id), "productId" TEXT REFERENCES products(id), rate NUMERIC, UNIQUE("partyId", "productId"));

-- 4. INVOICES
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, "invoiceNumber" TEXT, "partyId" TEXT, "partyName" TEXT, date DATE, items JSONB, "subTotal" NUMERIC, "taxAmount" NUMERIC, "globalDiscount" NUMERIC, "grandTotal" NUMERIC, "vehicleNumber" TEXT, "poNumber" TEXT, "partyAddress" TEXT, "partyGst" TEXT, "partyPan" TEXT, "partyAadhar" TEXT, "partyPhone" TEXT);

-- 5. USERS
CREATE TABLE IF NOT EXISTS app_users (username TEXT PRIMARY KEY, password TEXT, role TEXT);

-- 6. FIX IDENTITY (CRITICAL)
ALTER TABLE special_rates ALTER COLUMN id SET GENERATED BY DEFAULT;`;

  const copyToClipboard = (text: string, msg: string) => {
    navigator.clipboard.writeText(text);
    setStatusMsg({ msg, type: 'success' });
    setTimeout(() => setStatusMsg(null), 2000);
  };

  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
