    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    setStatusMsg({ msg: `${filename} Downloaded`, type: 'success' });
    setTimeout(() => setStatusMsg(null), 3000);
  };

  const generateSqlBackup = () => {
    let sql = `-- GREENZAR FULL DATABASE BACKUP\n-- Generated on: ${new Date().toLocaleString()}\n\n`;
    sql += parties.map(p => `INSERT INTO parties (id, name, code, address, city, phone, "gstNumber", "aadharNumber", "panNumber", email) VALUES ('${p.id}', '${p.name.replace(/'/g, "''")}', '${p.code || ''}', '${(p.address || '').replace(/'/g, "''")}', '${(p.city || '').replace(/'/g, "''")}', '${p.phone || ''}', '${p.gstNumber || ''}', '${p.aadharNumber || ''}', '${p.panNumber || ''}', '${p.email || ''}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name;`).join('\n') + '\n\n';
    sql += products.map(p => `INSERT INTO products (id, name, code, "standardRate", unit, hsn, "gstPercent", "qtyPerCase") VALUES ('${p.id}', '${p.name.replace(/'/g, "''")}', '${p.code || ''}', ${p.standardRate}, '${p.unit}', '${p.hsn || ''}', ${p.gstPercent || 0}, ${p.qtyPerCase || 1}) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name;`).join('\n') + '\n\n';
    sql += specialRates.map(r => `INSERT INTO special_rates ("partyId", "productId", rate) VALUES ('${r.partyId}', '${r.productId}', ${r.rate}) ON CONFLICT ("partyId", "productId") DO UPDATE SET rate = EXCLUDED.rate;`).join('\n') + '\n\n';
    downloadFile(sql, `greenzar_data_${new Date().toISOString().split('T')[0]}.sql`, 'text/sql');
  };

  return (
    <div className="p-6 max-w-5xl mx-auto pb-20">
      <div className="mb-8 border-b border-slate-200 pb-6 flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
