          </h2>
          <p className="text-slate-500">Sync control, SQL backups, and Supabase migration tools.</p>
        </div>
        <div className="flex bg-slate-100 p-1 rounded-xl">
           <button onClick={() => setActiveTab('sync')} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === 'sync' ? 'bg-white text-sky-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Cloud Sync</button>
           <button onClick={() => setActiveTab('setup')} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${activeTab === 'setup' ? 'bg-white text-sky-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Setup SQL</button>
