        </div>
        <div className="flex bg-slate-100 p-1 rounded-2xl">
           <button onClick={() => setActiveTab('sync')} className={`px-5 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'sync' ? 'bg-white text-sky-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Fix Errors</button>
           <button onClick={() => setActiveTab('setup')} className={`px-5 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'setup' ? 'bg-white text-sky-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Tables Setup</button>
           <button onClick={() => setActiveTab('backup')} className={`px-5 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'backup' ? 'bg-white text-sky-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Full Restore</button>
        </div>
