BEGIN;

CREATE TABLE IF NOT EXISTS parties (
    id TEXT PRIMARY KEY, 
    name TEXT NOT NULL, 
    code TEXT, 
    address TEXT, 
    city TEXT, 
    phone TEXT, 
    "gstNumber" TEXT, 
    "aadharNumber" TEXT, 
    "panNumber" TEXT, 
    email TEXT
);

CREATE TABLE IF NOT EXISTS products (
    id TEXT PRIMARY KEY, 
    name TEXT NOT NULL, 
    code TEXT, 
    "standardRate" NUMERIC, 
    unit TEXT, 
    hsn TEXT, 
    "gstPercent" NUMERIC, 
    "qtyPerCase" NUMERIC
);

CREATE TABLE IF NOT EXISTS special_rates (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, 
    "partyId" TEXT REFERENCES parties(id) ON DELETE CASCADE, 
    "productId" TEXT REFERENCES products(id) ON DELETE CASCADE, 
    rate NUMERIC, 
    UNIQUE("partyId", "productId")
);

CREATE TABLE IF NOT EXISTS invoices (
    id TEXT PRIMARY KEY, 
    "invoiceNumber" TEXT, 
    "partyId" TEXT, 
    "partyName" TEXT, 
    date DATE, 
    items JSONB, 
    "subTotal" NUMERIC, 
    "taxAmount" NUMERIC, 
    "globalDiscount" NUMERIC, 
    "grandTotal" NUMERIC, 
    "vehicleNumber" TEXT, 
    "poNumber" TEXT, 
    "partyAddress" TEXT, 
    "partyGst" TEXT, 
    "partyPan" TEXT, 
    "partyAadhar" TEXT, 
    "partyPhone" TEXT
);

CREATE TABLE IF NOT EXISTS app_users (
    username TEXT PRIMARY KEY, 
    password TEXT, 
    role TEXT
);

-- FIX IDENTITY COLUMN
ALTER TABLE special_rates ALTER COLUMN id SET GENERATED BY DEFAULT;

COMMIT;`;

  const copyToClipboard = (text: string, msg: string) => {
    navigator.clipboard.writeText(text);
    setStatusMsg({ msg, type: 'success' });
    setTimeout(() => setStatusMsg(null), 2000);
