  // Helper function to download files
  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const generateSqlBackup = () => {
    let sql = `-- ==========================================\n`;
    sql += `-- GREENZAR MASTER RESTORE SCRIPT\n`;
    sql += `-- Generated on: ${new Date().toLocaleString()}\n`;
    sql += `-- ==========================================\n\n`;

    sql += `BEGIN;\n\n`;

    // Clear existing data in correct order (children first)
    sql += `-- CLEAR OLD DATA\n`;
    sql += `TRUNCATE TABLE special_rates, invoices, parties, products CASCADE;\n\n`;

    // 1. Parties (The Parent)
    sql += `-- 1. INSERT PARTIES\n`;
    sql += parties.map(p => `INSERT INTO parties (id, name, code, address, city, phone, "gstNumber", "aadharNumber", "panNumber", email) VALUES ('${p.id}', '${p.name.replace(/'/g, "''")}', '${p.code || ''}', '${(p.address || '').replace(/'/g, "''")}', '${(p.city || '').replace(/'/g, "''")}', '${p.phone || ''}', '${p.gstNumber || ''}', '${p.aadharNumber || ''}', '${p.panNumber || ''}', '${p.email || ''}');`).join('\n') + '\n\n';

    // 2. Products
    sql += `-- 2. INSERT PRODUCTS\n`;
    sql += products.map(p => `INSERT INTO products (id, name, code, "standardRate", unit, hsn, "gstPercent", "qtyPerCase") VALUES ('${p.id}', '${p.name.replace(/'/g, "''")}', '${p.code || ''}', ${p.standardRate}, '${p.unit}', '${p.hsn || ''}', ${p.gstPercent || 0}, ${p.qtyPerCase || 1});`).join('\n') + '\n\n';

    // 3. Special Rates (The Child - depends on Parties & Products)
    sql += `-- 3. INSERT SPECIAL RATES\n`;
    sql += specialRates.map(r => `INSERT INTO special_rates ("partyId", "productId", rate) VALUES ('${r.partyId}', '${r.productId}', ${r.rate});`).join('\n') + '\n\n';

    sql += `COMMIT;\n`;

    // Use the download helper
    downloadFile(sql, `greenzar_full_restore_${new Date().toISOString().split('T')[0]}.sql`, 'text/sql');
    setStatusMsg({ msg: "Full Restore SQL Downloaded", type: 'success' });
  };

  return (
