        </div>
      </div>

      {statusMsg && (
        <div className={`fixed top-6 right-6 z-[200] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-right-5 duration-300 ${statusMsg.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-500 text-white'}`}>
          <CheckCircle size={20} />
          <span className="font-black text-sm uppercase tracking-wider">{statusMsg.msg}</span>
        </div>
      )}

      {activeTab === 'sync' && (
        <div className="space-y-6 animate-in fade-in duration-300">
           {/* TROUBLESHOOTER BOX */}
           <div className="bg-red-50 border-2 border-red-200 rounded-[2rem] p-8 shadow-sm">
              <div className="flex items-start gap-6">
                 <div className="bg-red-100 text-red-600 p-4 rounded-2xl shrink-0">
                    <ShieldAlert size={40} />
                 </div>
                 <div>
                    <h3 className="text-xl font-black text-red-900 uppercase tracking-tight mb-4">Fixing ERROR 23503 (Foreign Key)</h3>
                    <p className="text-sm text-red-800 mb-6 leading-relaxed font-medium">
                       This error happens when you try to upload <b>Rates</b> before the <b>Customers (Parties)</b> are created. 
                       Supabase doesn't know who the rate belongs to.
                    </p>
                    <div className="space-y-4 mb-8">
                       <div className="flex items-center gap-3 text-red-900 font-bold text-sm">
                          <CheckCircle size={18} className="text-red-600" /> Use the "Full Restore" tab to get everything in ONE file.
                       </div>
