                  <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl border ${connectionStatus === 'connected' ? 'bg-emerald-50 border-emerald-100 text-emerald-700' : 'bg-red-50 border-red-100 text-red-700'}`}>
                      <div className={`w-3 h-3 rounded-full ${connectionStatus === 'connected' ? 'bg-emerald-500' : 'bg-red-500'} animate-pulse`}></div>
                      <span className="text-xs font-black uppercase tracking-widest">{connectionStatus === 'connected' ? 'Cloud Connected' : 'Connection Error'}</span>
                  </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'setup' && (
        <div className="space-y-6 animate-in fade-in duration-300">
