export const DataManager: React.FC<Props> = ({ parties, products, specialRates, invoices, onForcePush }) => {
  const [activeTab, setActiveTab] = useState<'sync' | 'setup' | 'backup'>('sync');
  const [statusMsg, setStatusMsg] = useState<{msg: string, type: 'success' | 'error'} | null>(null);
  const [connectionStatus, setConnectionStatus] = useState<'checking' | 'connected' | 'error'>('checking');

  useEffect(() => {
    checkSupabaseConnection();
  }, []);

  const checkSupabaseConnection = async () => {
    setConnectionStatus('checking');
    const result = await Cloud.testConnection();
    if (result.success) {
      setConnectionStatus('connected');
    } else {
      setConnectionStatus('error');
    }
  };

  const schemaSql = `-- ==========================================
-- STEP 1: CREATE TABLES (RUN THIS FIRST)
-- ==========================================

BEGIN;

CREATE TABLE IF NOT EXISTS parties (
    id TEXT PRIMARY KEY, 
    name TEXT NOT NULL, 
    code TEXT, 
    address TEXT, 
    city TEXT, 
    phone TEXT, 
    "gstNumber" TEXT, 
    "aadharNumber" TEXT, 
    "panNumber" TEXT, 
    email TEXT
);

CREATE TABLE IF NOT EXISTS products (
    id TEXT PRIMARY KEY, 
    name TEXT NOT NULL, 
    code TEXT, 
    "standardRate" NUMERIC, 
    unit TEXT, 
    hsn TEXT, 
    "gstPercent" NUMERIC, 
    "qtyPerCase" NUMERIC
);

CREATE TABLE IF NOT EXISTS special_rates (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, 
    "partyId" TEXT REFERENCES parties(id) ON DELETE CASCADE, 
    "productId" TEXT REFERENCES products(id) ON DELETE CASCADE, 
    rate NUMERIC, 
    UNIQUE("partyId", "productId")
);

CREATE TABLE IF NOT EXISTS invoices (
    id TEXT PRIMARY KEY, 
    "invoiceNumber" TEXT, 
    "partyId" TEXT, 
    "partyName" TEXT, 
    date DATE, 
    items JSONB, 
    "subTotal" NUMERIC, 
    "taxAmount" NUMERIC, 
    "globalDiscount" NUMERIC, 
    "grandTotal" NUMERIC, 
    "vehicleNumber" TEXT, 
    "poNumber" TEXT, 
    "partyAddress" TEXT, 
    "partyGst" TEXT, 
    "partyPan" TEXT, 
    "partyAadhar" TEXT, 
    "partyPhone" TEXT
);

CREATE TABLE IF NOT EXISTS app_users (
    username TEXT PRIMARY KEY, 
    password TEXT, 
    role TEXT
);

-- FIX IDENTITY COLUMN
ALTER TABLE special_rates ALTER COLUMN id SET GENERATED BY DEFAULT;

COMMIT;`;

  const copyToClipboard = (text: string, msg: string) => {
    navigator.clipboard.writeText(text);
    setStatusMsg({ msg, type: 'success' });
    setTimeout(() => setStatusMsg(null), 2000);
  };

  // Helper function to download files
  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const generateSqlBackup = () => {
    let sql = `-- ==========================================\n`;
    sql += `-- GREENZAR MASTER RESTORE SCRIPT\n`;
    sql += `-- Generated on: ${new Date().toLocaleString()}\n`;
    sql += `-- ==========================================\n\n`;

    sql += `BEGIN;\n\n`;

    // Clear existing data in correct order (children first)
    sql += `-- CLEAR OLD DATA\n`;
    sql += `TRUNCATE TABLE special_rates, invoices, parties, products CASCADE;\n\n`;

    // 1. Parties (The Parent)
    sql += `-- 1. INSERT PARTIES\n`;
    sql += parties.map(p => `INSERT INTO parties (id, name, code, address, city, phone, "gstNumber", "aadharNumber", "panNumber", email) VALUES ('${p.id}', '${p.name.replace(/'/g, "''")}', '${p.code || ''}', '${(p.address || '').replace(/'/g, "''")}', '${(p.city || '').replace(/'/g, "''")}', '${p.phone || ''}', '${p.gstNumber || ''}', '${p.aadharNumber || ''}', '${p.panNumber || ''}', '${p.email || ''}');`).join('\n') + '\n\n';

    // 2. Products
    sql += `-- 2. INSERT PRODUCTS\n`;
    sql += products.map(p => `INSERT INTO products (id, name, code, "standardRate", unit, hsn, "gstPercent", "qtyPerCase") VALUES ('${p.id}', '${p.name.replace(/'/g, "''")}', '${p.code || ''}', ${p.standardRate}, '${p.unit}', '${p.hsn || ''}', ${p.gstPercent || 0}, ${p.qtyPerCase || 1});`).join('\n') + '\n\n';

    // 3. Special Rates (The Child - depends on Parties & Products)
    sql += `-- 3. INSERT SPECIAL RATES\n`;
    sql += specialRates.map(r => `INSERT INTO special_rates ("partyId", "productId", rate) VALUES ('${r.partyId}', '${r.productId}', ${r.rate});`).join('\n') + '\n\n';

    sql += `COMMIT;\n`;

    // Use the download helper
    downloadFile(sql, `greenzar_full_restore_${new Date().toISOString().split('T')[0]}.sql`, 'text/sql');
    setStatusMsg({ msg: "Full Restore SQL Downloaded", type: 'success' });
  };

  return (
    <div className="p-6 max-w-5xl mx-auto pb-20">
      <div className="mb-8 border-b border-slate-200 pb-6 flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <Database className="text-sky-600" /> Data Management
          </h2>
          <p className="text-slate-500 text-sm">Solve SQL errors and manage your cloud data.</p>
        </div>
        <div className="flex bg-slate-100 p-1 rounded-2xl">
           <button onClick={() => setActiveTab('sync')} className={`px-5 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'sync' ? 'bg-white text-sky-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Fix Errors</button>
           <button onClick={() => setActiveTab('setup')} className={`px-5 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'setup' ? 'bg-white text-sky-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Tables Setup</button>
           <button onClick={() => setActiveTab('backup')} className={`px-5 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'backup' ? 'bg-white text-sky-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Full Restore</button>
        </div>
      </div>

      {statusMsg && (
        <div className={`fixed top-6 right-6 z-[200] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-right-5 duration-300 ${statusMsg.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-500 text-white'}`}>
          <CheckCircle size={20} />
          <span className="font-black text-sm uppercase tracking-wider">{statusMsg.msg}</span>
        </div>
      )}

      {activeTab === 'sync' && (
        <div className="space-y-6 animate-in fade-in duration-300">
           {/* TROUBLESHOOTER BOX */}
           <div className="bg-red-50 border-2 border-red-200 rounded-[2rem] p-8 shadow-sm">
              <div className="flex items-start gap-6">
                 <div className="bg-red-100 text-red-600 p-4 rounded-2xl shrink-0">
                    <ShieldAlert size={40} />
                 </div>
                 <div>
                    <h3 className="text-xl font-black text-red-900 uppercase tracking-tight mb-4">Fixing ERROR 23503 (Foreign Key)</h3>
                    <p className="text-sm text-red-800 mb-6 leading-relaxed font-medium">
                       This error happens when you try to upload <b>Rates</b> before the <b>Customers (Parties)</b> are created. 
                       Supabase doesn't know who the rate belongs to.
                    </p>
                    <div className="space-y-4 mb-8">
                       <div className="flex items-center gap-3 text-red-900 font-bold text-sm">
                          <CheckCircle size={18} className="text-red-600" /> Use the "Full Restore" tab to get everything in ONE file.
                       </div>
                       <div className="flex items-center gap-3 text-red-900 font-bold text-sm">
                          <CheckCircle size={18} className="text-red-600" /> Make sure you copy the WHOLE text, not just the bottom.
                       </div>
                    </div>
                    <button onClick={() => setActiveTab('backup')} className="bg-red-600 hover:bg-red-700 text-white px-8 py-3 rounded-xl font-black text-xs uppercase tracking-widest shadow-xl transition-all active:scale-95">
                       Go to Full Restore SQL
                    </button>
                 </div>
              </div>
           </div>

           <div className="bg-white border border-slate-200 rounded-[2rem] p-10 shadow-sm">
              <h3 className="text-lg font-black text-slate-800 uppercase tracking-widest mb-6 flex items-center gap-3">
                 <PlayCircle className="text-sky-600" /> Manual Sync Check
              </h3>
              <div className="flex flex-wrap gap-4">
                  <button onClick={onForcePush} className="bg-sky-600 hover:bg-sky-700 text-white px-8 py-4 rounded-2xl font-black text-sm flex items-center gap-3 shadow-xl transition-all uppercase tracking-widest">
                      <RefreshCw size={20} /> Push Local Data to Cloud
                  </button>
                  <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl border ${connectionStatus === 'connected' ? 'bg-emerald-50 border-emerald-100 text-emerald-700' : 'bg-red-50 border-red-100 text-red-700'}`}>
                      <div className={`w-3 h-3 rounded-full ${connectionStatus === 'connected' ? 'bg-emerald-500' : 'bg-red-500'} animate-pulse`}></div>
                      <span className="text-xs font-black uppercase tracking-widest">{connectionStatus === 'connected' ? 'Cloud Connected' : 'Connection Error'}</span>
                  </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'setup' && (
        <div className="space-y-6 animate-in fade-in duration-300">
           <div className="bg-slate-900 rounded-[2.5rem] p-10 shadow-2xl relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-8 opacity-10 text-white group-hover:rotate-12 transition-transform duration-700">
                  <Terminal size={200} />
              </div>
              <div className="relative z-10">
                 <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6">
                    <div>
                      <h3 className="text-2xl font-black text-white uppercase tracking-widest flex items-center gap-4">
                          <Terminal className="text-sky-400" /> Table Creation Script
                      </h3>
                      <p className="text-slate-400 text-sm mt-2 leading-relaxed max-w-lg">Run this script in the Supabase SQL Editor if your database tables are missing or broken.</p>
                    </div>
                    <button onClick={() => copyToClipboard(schemaSql, "Table Script Copied!")} className="bg-sky-500 hover:bg-sky-400 text-white px-10 py-5 rounded-2xl font-black text-sm flex items-center gap-3 shadow-2xl active:scale-95 transition-all uppercase tracking-widest">
                        <Copy size={24} /> Copy Code
                    </button>
                 </div>
                 <div className="bg-black/50 rounded-3xl p-8 border border-white/5 backdrop-blur-md">
                   <pre className="text-sky-300 text-xs font-mono overflow-x-auto leading-relaxed h-[400px] custom-scrollbar">
                     {schemaSql}
                   </pre>
                 </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'backup' && (
         <div className="space-y-6 animate-in fade-in duration-300">
            <div className="bg-emerald-900 text-white p-12 rounded-[3rem] shadow-2xl relative overflow-hidden group">
               <div className="absolute -bottom-20 -right-20 opacity-10 rotate-12 group-hover:scale-110 transition-transform duration-1000">
                  <FileCode size={400} />
               </div>
               <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-12">
                  <div className="max-w-xl text-center md:text-left">
                     <h3 className="text-4xl font-black uppercase tracking-widest mb-4">Full System Restore</h3>
                     <p className="text-emerald-100/70 text-base leading-relaxed mb-8">
                        This downloads <b>everything</b> (Parties, Products, and Rates) in the perfect order. 
                        Running this file in Supabase will clear old data and fix all "Foreign Key" errors (23503).
                     </p>
                     <div className="bg-black/20 p-4 rounded-xl text-xs font-bold text-emerald-200 border border-white/10 flex items-center gap-3">
                        <Info size={16} /> Order: Clear Data → Parties → Products → Special Rates
                     </div>
                  </div>
                  <button onClick={generateSqlBackup} className="bg-white text-emerald-950 px-12 py-6 rounded-2xl font-black hover:bg-emerald-50 transition-all shadow-2xl hover:shadow-white/20 active:scale-95 flex items-center gap-4 shrink-0 uppercase tracking-widest text-lg">
                      <Download size={32} /> Download All.sql
                  </button>
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
               <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 flex flex-col justify-between items-start group hover:border-sky-300 transition-all shadow-sm">
                  <div className="mb-8">
                    <div className="bg-sky-50 text-sky-600 p-4 rounded-2xl w-fit mb-6 shadow-sm"><Users size={32} /></div>
                    <h4 className="font-black text-slate-800 uppercase tracking-tight text-xl">CSV: Parties</h4>
                    <p className="text-slate-500 text-sm mt-2 leading-relaxed">Download just your customer list for manual editing in Excel.</p>
                  </div>
                  <button onClick={() => downloadFile(exportSupabasePartiesCSV(parties), "parties_only.csv", "text/csv")} className="w-full flex items-center justify-center gap-3 bg-slate-100 hover:bg-slate-200 text-slate-700 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all">
                    <Download size={20} /> Download CSV
                  </button>
               </div>
               <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 flex flex-col justify-between items-start group hover:border-sky-300 transition-all shadow-sm">
                  <div className="mb-8">
                    <div className="bg-purple-50 text-purple-600 p-4 rounded-2xl w-fit mb-6 shadow-sm"><Package size={32} /></div>
                    <h4 className="font-black text-slate-800 uppercase tracking-tight text-xl">CSV: Products</h4>
                    <p className="text-slate-500 text-sm mt-2 leading-relaxed">Download your complete product catalog for manual price updates.</p>
                  </div>
                  <button onClick={() => downloadFile(exportSupabaseProductsCSV(products), "products_only.csv", "text/csv")} className="w-full flex items-center justify-center gap-3 bg-slate-100 hover:bg-slate-200 text-slate-700 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all">
                    <Download size={20} /> Download CSV
                  </button>
               </div>
            </div>
         </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Party, Product, SpecialRate, Invoice, User } from '../types';
import { Database, AlertTriangle, CheckCircle, RefreshCw, Terminal, ExternalLink, Copy, Download, Info, ShieldAlert, PlayCircle, Users, Package } from 'lucide-react';
import { Cloud } from '../services/cloud';
import { exportSupabasePartiesCSV, exportSupabaseProductsCSV, exportSupabaseRatesCSV } from '../services/csv';

interface Props {
  parties: Party[];
  products: Product[];
  specialRates: SpecialRate[];
  invoices: Invoice[];
  refreshData: () => void;
  onUrlChange?: (url: string) => void;
  onForcePush?: () => void;
}

export const DataManager: React.FC<Props> = ({ parties, products, specialRates, invoices, onForcePush }) => {
  const [activeTab, setActiveTab] = useState<'sync' | 'setup' | 'backup'>('sync');
  const [statusMsg, setStatusMsg] = useState<{msg: string, type: 'success' | 'error'} | null>(null);
  const [connectionStatus, setConnectionStatus] = useState<'checking' | 'connected' | 'error'>('checking');

  useEffect(() => {
    checkSupabaseConnection();
  }, []);

  const checkSupabaseConnection = async () => {
    setConnectionStatus('checking');
    const result = await Cloud.testConnection();
    if (result.success) {
      setConnectionStatus('connected');
    } else {
      setConnectionStatus('error');
    }
  };

  const schemaSql = `-- ==========================================
-- STEP 1: CREATE TABLES (RUN THIS FIRST)
-- ==========================================

BEGIN;

CREATE TABLE IF NOT EXISTS parties (
    id TEXT PRIMARY KEY, 
    name TEXT NOT NULL, 
    code TEXT, 
    address TEXT, 
    city TEXT, 
    phone TEXT, 
    "gstNumber" TEXT, 
    "aadharNumber" TEXT, 
    "panNumber" TEXT, 
    email TEXT
);

CREATE TABLE IF NOT EXISTS products (
    id TEXT PRIMARY KEY, 
    name TEXT NOT NULL, 
    code TEXT, 
    "standardRate" NUMERIC, 
    unit TEXT, 
    hsn TEXT, 
    "gstPercent" NUMERIC, 
    "qtyPerCase" NUMERIC
);

CREATE TABLE IF NOT EXISTS special_rates (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, 
    "partyId" TEXT REFERENCES parties(id) ON DELETE CASCADE, 
    "productId" TEXT REFERENCES products(id) ON DELETE CASCADE, 
    rate NUMERIC, 
    UNIQUE("partyId", "productId")
);

CREATE TABLE IF NOT EXISTS invoices (
    id TEXT PRIMARY KEY, 
    "invoiceNumber" TEXT, 
    "partyId" TEXT, 
    "partyName" TEXT, 
    date DATE, 
    items JSONB, 
    "subTotal" NUMERIC, 
    "taxAmount" NUMERIC, 
    "globalDiscount" NUMERIC, 
    "grandTotal" NUMERIC, 
    "vehicleNumber" TEXT, 
    "poNumber" TEXT, 
    "partyAddress" TEXT, 
    "partyGst" TEXT, 
    "partyPan" TEXT, 
    "partyAadhar" TEXT, 
    "partyPhone" TEXT
);

CREATE TABLE IF NOT EXISTS app_users (
    username TEXT PRIMARY KEY, 
    password TEXT, 
    role TEXT
);

-- FIX IDENTITY COLUMN
ALTER TABLE special_rates ALTER COLUMN id SET GENERATED BY DEFAULT;

COMMIT;`;

  const copyToClipboard = (text: string, msg: string) => {
    navigator.clipboard.writeText(text);
    setStatusMsg({ msg, type: 'success' });
    setTimeout(() => setStatusMsg(null), 2000);
  };

  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const generateSqlBackup = () => {
    // SECURITY FIX: Filter out rates for parties or products that no longer exist
    const validPartyIds = new Set(parties.map(p => p.id));
    const validProductIds = new Set(products.map(p => p.id));

    const filteredRates = specialRates.filter(r => 
      validPartyIds.has(r.partyId) && validProductIds.has(r.productId)
    );

    let sql = `-- ==========================================\n`;
    sql += `-- GREENZAR MASTER RESTORE SCRIPT\n`;
    sql += `-- Generated on: ${new Date().toLocaleString()}\n`;
    sql += `-- THIS SCRIPT IS SELF-CLEANING AND PREVENTS ERROR 23503\n`;
    sql += `-- ==========================================\n\n`;

    sql += `BEGIN;\n\n`;

    sql += `-- 1. CLEAR OLD DATA IN CORRECT ORDER\n`;
    sql += `TRUNCATE TABLE special_rates, invoices, parties, products CASCADE;\n\n`;

    sql += `-- 2. INSERT PARTIES\n`;
    sql += parties.map(p => `INSERT INTO parties (id, name, code, address, city, phone, "gstNumber", "aadharNumber", "panNumber", email) VALUES ('${p.id}', '${p.name.replace(/'/g, "''")}', '${p.code || ''}', '${(p.address || '').replace(/'/g, "''")}', '${(p.city || '').replace(/'/g, "''")}', '${p.phone || ''}', '${p.gstNumber || ''}', '${p.aadharNumber || ''}', '${p.panNumber || ''}', '${p.email || ''}');`).join('\n') + '\n\n';

    sql += `-- 3. INSERT PRODUCTS\n`;
    sql += products.map(p => `INSERT INTO products (id, name, code, "standardRate", unit, hsn, "gstPercent", "qtyPerCase") VALUES ('${p.id}', '${p.name.replace(/'/g, "''")}', '${p.code || ''}', ${p.standardRate}, '${p.unit}', '${p.hsn || ''}', ${p.gstPercent || 0}, ${p.qtyPerCase || 1});`).join('\n') + '\n\n';

    sql += `-- 4. INSERT SPECIAL RATES (ONLY VALID ONES)\n`;
    sql += filteredRates.map(r => `INSERT INTO special_rates ("partyId", "productId", rate) VALUES ('${r.partyId}', '${r.productId}', ${r.rate});`).join('\n') + '\n\n';

    sql += `COMMIT;\n`;

    downloadFile(sql, `greenzar_full_fix_${new Date().toISOString().split('T')[0]}.sql`, 'text/sql');
    setStatusMsg({ msg: "Safe Restore SQL Downloaded", type: 'success' });
  };

  return (
    <div className="p-6 max-w-5xl mx-auto pb-20">
      <div className="mb-8 border-b border-slate-200 pb-6 flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2 tracking-tight">
            <Database className="text-sky-600" /> Data Management
          </h2>
          <p className="text-slate-500 text-sm">Control database structure and fix sync errors.</p>
        </div>
        <div className="flex bg-slate-100 p-1 rounded-2xl shadow-inner">
           <button onClick={() => setActiveTab('sync')} className={`px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'sync' ? 'bg-white text-sky-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>1. Fix Errors</button>
           <button onClick={() => setActiveTab('setup')} className={`px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'setup' ? 'bg-white text-sky-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>2. Setup DB</button>
           <button onClick={() => setActiveTab('backup')} className={`px-5 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'backup' ? 'bg-white text-sky-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>3. Backup SQL</button>
        </div>
      </div>

      {statusMsg && (
        <div className={`fixed top-6 right-6 z-[200] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-right-5 duration-300 ${statusMsg.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-500 text-white'}`}>
          <CheckCircle size={20} />
          <span className="font-black text-sm uppercase tracking-wider">{statusMsg.msg}</span>
        </div>
      )}

      {activeTab === 'sync' && (
        <div className="space-y-6 animate-in fade-in duration-300">
           {/* TROUBLESHOOTER BOX FOR ERROR 23503 */}
           <div className="bg-red-50 border-2 border-red-200 rounded-[2rem] p-8 shadow-sm">
              <div className="flex items-start gap-6">
                 <div className="bg-red-100 text-red-600 p-4 rounded-2xl shrink-0">
                    <ShieldAlert size={40} />
                 </div>
                 <div>
                    <h3 className="text-xl font-black text-red-900 uppercase tracking-tight mb-2">Fixing "ERROR: 23503" (Foreign Key)</h3>
                    <p className="text-sm text-red-800 mb-6 leading-relaxed">
                       This error happens when you have a <b>Rate</b> for a <b>Customer</b> that was deleted. Supabase blocks the save because the customer ID is missing.
                    </p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                       <div className="flex gap-3 items-center text-red-900 font-bold text-xs">
                          <CheckCircle size={16} className="text-red-600" /> Go to "Backup SQL" tab
                       </div>
                       <div className="flex gap-3 items-center text-red-900 font-bold text-xs">
                          <CheckCircle size={16} className="text-red-600" /> Click "Download Safe Backup"
                       </div>
                       <div className="flex gap-3 items-center text-red-900 font-bold text-xs">
                          <CheckCircle size={16} className="text-red-600" /> Copy EVERYTHING from that file
                       </div>
                       <div className="flex gap-3 items-center text-red-900 font-bold text-xs">
                          <CheckCircle size={16} className="text-red-600" /> Paste into SQL Editor and Run
                       </div>
                    </div>
                    <button onClick={() => setActiveTab('backup')} className="bg-red-600 hover:bg-red-700 text-white px-8 py-3 rounded-xl font-black text-xs uppercase tracking-widest shadow-xl transition-all">
                       Fix My Database Now
                    </button>
                 </div>
              </div>
           </div>

