  const [status, setStatus] = useState<{msg: string, type: 'success' | 'error'} | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);

  const schemaSql = `-- RUN THIS IN SUPABASE SQL EDITOR TO FIX TABLES
BEGIN;
TRUNCATE TABLE special_rates, invoices, parties, products CASCADE;

CREATE TABLE IF NOT EXISTS parties (id TEXT PRIMARY KEY, name TEXT NOT NULL, code TEXT, address TEXT, city TEXT, phone TEXT, "gstNumber" TEXT, "aadharNumber" TEXT, "panNumber" TEXT, email TEXT);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, name TEXT NOT NULL, code TEXT, "standardRate" NUMERIC, unit TEXT, hsn TEXT, "gstPercent" NUMERIC, "qtyPerCase" NUMERIC);
CREATE TABLE IF NOT EXISTS special_rates (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "partyId" TEXT REFERENCES parties(id) ON DELETE CASCADE, "productId" TEXT REFERENCES products(id) ON DELETE CASCADE, rate NUMERIC, UNIQUE("partyId", "productId"));
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, "invoiceNumber" TEXT, "partyId" TEXT, "partyName" TEXT, date DATE, items JSONB, "subTotal" NUMERIC, "taxAmount" NUMERIC, "globalDiscount" NUMERIC, "grandTotal" NUMERIC, "vehicleNumber" TEXT, "poNumber" TEXT, "partyAddress" TEXT, "partyGst" TEXT, "partyPan" TEXT, "partyAadhar" TEXT, "partyPhone" TEXT);
CREATE TABLE IF NOT EXISTS app_users (username TEXT PRIMARY KEY, password TEXT, role TEXT);

COMMIT;`;

  const handleFixAndSync = async () => {
    setIsSyncing(true);
    setStatus({ msg: 'Cleaning data and syncing...', type: 'success' });
    try {
      await Cloud.syncMasterData(parties, products, specialRates, []);
      setStatus({ msg: 'System Repaired & Synced Successfully!', type: 'success' });
    } catch (err: any) {
      setStatus({ msg: err.message || 'Sync failed', type: 'error' });
    } finally {
      setIsSyncing(false);
      setTimeout(() => setStatus(null), 5000);
    }
  };

  const copySql = () => {
    navigator.clipboard.writeText(schemaSql);
    setStatus({ msg: 'SQL Script Copied!', type: 'success' });
    setTimeout(() => setStatus(null), 2000);
  };

  return (
    <div className="p-8 max-w-4xl mx-auto">
      <div className="mb-10 text-center">
        <h2 className="text-3xl font-black text-slate-800 uppercase tracking-tight flex items-center justify-center gap-3">
          <Database className="text-sky-600" size={32} /> System Health & Sync
        </h2>
        <p className="text-slate-500 mt-2">Manage your cloud database and resolve Foreign Key errors.</p>
      </div>

      {status && (
        <div className={`mb-8 p-4 rounded-2xl flex items-center gap-3 animate-in fade-in slide-in-from-top-4 duration-300 ${status.type === 'success' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 'bg-red-50 text-red-700 border border-red-100'}`}>
          {status.type === 'success' ? <CheckCircle size={20} /> : <AlertTriangle size={20} />}
          <span className="font-bold text-sm">{status.msg}</span>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* Sync Card */}
        <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm flex flex-col items-center text-center">
          <div className="bg-sky-50 text-sky-600 p-5 rounded-3xl mb-6">
            <ShieldCheck size={40} />
          </div>
          <h3 className="text-xl font-black text-slate-800 mb-2 uppercase">Smart Repair Sync</h3>
          <p className="text-sm text-slate-500 mb-8">Automatically removes orphaned rates and forces a clean sync to Supabase. Fixes Error 23503.</p>
          <button 
            onClick={handleFixAndSync}
            disabled={isSyncing}
            className="w-full bg-sky-600 hover:bg-sky-700 disabled:bg-slate-300 text-white py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3"
          >
            {isSyncing ? <RefreshCw size={18} className="animate-spin" /> : <RefreshCw size={18} />}
            Repair & Push Now
          </button>
        </div>

        {/* SQL Card */}
        <div className="bg-slate-900 p-8 rounded-[2rem] shadow-2xl flex flex-col items-center text-center text-white">
          <div className="bg-white/10 text-sky-400 p-5 rounded-3xl mb-6">
            <Terminal size={40} />
          </div>
          <h3 className="text-xl font-black mb-2 uppercase">Database Setup</h3>
          <p className="text-sm text-slate-400 mb-8">Run the setup script in Supabase to ensure your tables are built correctly with proper relationships.</p>
          <button 
            onClick={copySql}
            className="w-full bg-white text-slate-900 py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3"
          >
            <Copy size={18} />
            Copy Setup SQL
          </button>
        </div>
      </div>

      <div className="mt-12 bg-amber-50 border border-amber-200 p-6 rounded-[2rem] flex items-start gap-4">
