                                <button onClick={() => handleShareInvoice(inv)} className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all" title="Share"><Share2 size={18}/></button>
                                <button onClick={(e) => handlePrintOptions(e, inv)} className="p-2.5 text-slate-400 hover:text-sky-600 hover:bg-sky-50 rounded-lg transition-all" title="More Options"><Printer size={18}/></button>
