        {currentView === 'parties' && <div className="h-full overflow-y-auto"><PartyManager parties={parties} setParties={setParties} /></div>}
        {currentView === 'products' && <div className="h-full overflow-y-auto"><ProductManager products={products} setProducts={setProducts} /></div>}
        {currentView === 'rates' && <RateManager parties={parties} products={products} specialRates={specialRates} setSpecialRates={setSpecialRates} />}
        {currentView === 'users' && <div className="h-full overflow-y-auto"><UserManager users={validUsers} setUsers={setValidUsers} /></div>}
        {currentView === 'data' && <div className="h-full overflow-y-auto"><DataManager parties={parties} products={products} specialRates={specialRates} invoices={invoices} refreshData={loadLocalData} onForcePush={async () => { setSyncStatus('syncing'); await Cloud.syncMasterData(parties, products, specialRates, validUsers); setSyncStatus('synced'); setTimeout(() => setSyncStatus('idle'), 2000); alert("Data Uploaded."); }} /></div>}
        {currentView === 'logs' && <div className="h-full overflow-y-auto"><InvoiceLogs invoices={invoices} /></div>}
        {currentView === 'ranking' && <div className="h-full overflow-y-auto"><Ranking invoices={invoices} parties={parties} /></div>}
        {currentView === 'statement' && <div className="h-full overflow-y-auto"><PartyStatement invoices={invoices} parties={parties} /></div>}
      </div>

