                <button onClick={() => setViewInvoice(null)} className="text-white px-6 py-2 border border-white/20 hover:bg-white/10 rounded-xl transition-all"><X size={20}/></button>
             </div>
          </div>
          <div className="bg-white mx-auto shadow-2xl print-only-container">
            <InvoiceTemplate invoice={viewInvoice} parties={parties} />
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Users, Package, DollarSign, FileText, History, Menu, X, Database, CheckCircle, RefreshCw, Loader2, LayoutDashboard, Printer, LogOut, User as UserIcon, Edit3, Download, MoreHorizontal, FileDown, Search, Trophy, ClipboardList, Share2, ScrollText } from 'lucide-react';
