                   <tbody className="divide-y divide-slate-100">
                      {invoices.filter(i => i.partyName.toLowerCase().includes(invoiceSearch.toLowerCase()) || i.invoiceNumber.toLowerCase().includes(invoiceSearch.toLowerCase())).map(inv => (
                        <tr key={inv.id} className="hover:bg-slate-50/80 transition-colors">
