                                <button onClick={() => handleEditInvoice(inv)} className="p-2.5 text-slate-400 hover:text-orange-600 hover:bg-orange-50 rounded-lg transition-all" title="Edit"><Edit3 size={18}/></button>
                                <button onClick={() => setPdfInvoice(prepareInvoiceForView(inv))} className="p-2.5 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-all" title="Download PDF"><Download size={18}/></button>
                                <button onClick={() => handleShareInvoice(inv)} className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all" title="Share"><Share2 size={18}/></button>
                                <button onClick={(e) => handlePrintOptions(e, inv)} className="p-2.5 text-slate-400 hover:text-sky-600 hover:bg-sky-50 rounded-lg transition-all" title="More Options"><Printer size={18}/></button>
                              </div>
                           </td>
                        </tr>
                      ))}
                      {invoices.length === 0 && (
                        <tr><td colSpan={5} className="p-12 text-center text-slate-400">No invoices found.</td></tr>
                      )}
                   </tbody>
                </table>
             </div>
          </div>
        )}
        {currentView === 'parties' && <div className="h-full overflow-y-auto"><PartyManager parties={parties} setParties={setParties} /></div>}
        {currentView === 'products' && <div className="h-full overflow-y-auto"><ProductManager products={products} setProducts={setProducts} /></div>}
        {currentView === 'rates' && <RateManager parties={parties} products={products} specialRates={specialRates} setSpecialRates={setSpecialRates} />}
        {currentView === 'users' && <div className="h-full overflow-y-auto"><UserManager users={validUsers} setUsers={setValidUsers} /></div>}
        {currentView === 'data' && <div className="h-full overflow-y-auto"><DataManager parties={parties} products={products} specialRates={specialRates} invoices={invoices} refreshData={loadLocalData} onForcePush={async () => { setSyncStatus('syncing'); await Cloud.syncMasterData(parties, products, specialRates, validUsers); setSyncStatus('synced'); setTimeout(() => setSyncStatus('idle'), 2000); alert("Data Uploaded."); }} /></div>}
        {currentView === 'logs' && <div className="h-full overflow-y-auto"><InvoiceLogs invoices={invoices} /></div>}
        {currentView === 'ranking' && <div className="h-full overflow-y-auto"><Ranking invoices={invoices} parties={parties} /></div>}
        {currentView === 'statement' && <div className="h-full overflow-y-auto"><PartyStatement invoices={invoices} parties={parties} /></div>}
      </div>

      {/* Print View Modal */}
      {viewInvoice && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex flex-col p-8 no-print overflow-y-auto">
          <div className="flex justify-between items-center mb-6 max-w-[210mm] mx-auto w-full">
             <h2 className="text-white text-xl font-bold">Invoice Preview</h2>
             <div className="flex gap-4">
                <button onClick={() => window.print()} className="bg-sky-600 hover:bg-sky-500 text-white px-8 py-2 rounded-xl font-bold flex items-center gap-2 shadow-xl"><Printer size={18}/> Print Now</button>
                <button onClick={() => setViewInvoice(null)} className="text-white px-6 py-2 border border-white/20 hover:bg-white/10 rounded-xl transition-all"><X size={20}/></button>
             </div>
          </div>
          <div className="bg-white mx-auto shadow-2xl print-only-container">
            <InvoiceTemplate invoice={viewInvoice} parties={parties} />
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export interface Party {
  id: string;        // A: Serial No (Internal UUID)
  name: string;      // B: Name
  code?: string;     // New: Auto-generated Serial/Short Code (e.g. C-001)
  address: string;   // C: Address
  city: string;      // D: City (New)
  phone: string;     // E: Phone
  gstNumber: string; // F: GST (New)
  aadharNumber: string;// G: Aadhar (New)
  panNumber: string; // H: PAN (New)
  email?: string;    // kept as optional internal field
}

export interface Product {
  id: string;
  name: string;
  code: string;
  standardRate: number;
  unitWeight: number; // New: Weight in KG per unit
  unit: string;
  hsn?: string;
  gstPercent?: number;
  qtyPerCase?: number;
}

// The core mapping: Party + Product = Specific Rate
export interface SpecialRate {
  partyId: string;
  productId: string;
  rate: number;
}

export interface InvoiceItem {
  id: string;
  productId: string;
  productName: string;
  quantity: number;
  rate: number; // This is now the GROSS (Inclusive) Rate
  baseRate: number; // New: Rate before Tax
  total: number; // Total Inclusive Amount (Qty * Rate)
  totalWeight: number; // New: Calculated weight for this line (qty * unitWeight)
  hsn?: string;
  gstPercent?: number;
}

export interface Invoice {
  id: string;
  invoiceNumber: string;
  partyId: string;
  partyName: string; 
  date: string;
  items: InvoiceItem[];
  subTotal: number;
  taxPercent: number;
  taxAmount: number;
  globalDiscount: number; // New: Discount on total invoice
  grandTotal: number;
  // New fields for the PDF format
  vehicleNumber?: string;
  poNumber?: string; // Reference No
  // Snapshot fields for Sheet Export "A to Z"
  partyAddress?: string;
  partyGst?: string;
  partyPan?: string;    // New Snapshot
  partyAadhar?: string; // New Snapshot
  partyPhone?: string;  // New Snapshot
}

export interface User {
  username: string;
  password: string;
  role?: string;
}

