import React, { useState, useEffect, useRef } from 'react';
import { Party, Product, SpecialRate, Invoice, InvoiceItem } from '../types';
import { ShoppingBag, User, Plus, Trash2, Save, Scan, Zap, FileText, CloudLightning, Loader2, Printer, X, CreditCard, Box, MapPin, Phone, Calculator, ChevronDown, ChevronUp, Edit3, Copy, Download, FileSpreadsheet, Search, Tag, Sparkles, Info, ArrowUpCircle, Weight } from 'lucide-react';
import { Store } from '../services/store';
import { Cloud } from '../services/cloud';
import { InvoiceTemplate } from './InvoiceTemplate';

interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (rates: SpecialRate[]) => void; 
  onInvoiceSaved: () => void;
  initialData?: Invoice | null; 
}

const VEHICLE_OPTIONS = ["WB894170", "WB25K1322", "WB25K2982", "WB25L6365", "WB25K1326", "WB25K1341", "WB47J7275", "WB35H3960"];

const getTodayString = () => {
  const d = new Date();
  return d.toISOString().split('T')[0];
};

export const Billing: React.FC<Props> = ({ parties, setParties, products, specialRates, setSpecialRates, onInvoiceSaved, initialData }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string>('');
  const [items, setItems] = useState<InvoiceItem[]>([]);
  const [invoiceDate, setInvoiceDate] = useState(getTodayString());
  const [customInvoiceNo, setCustomInvoiceNo] = useState('');
  const [refNo, setRefNo] = useState(''); 
  const [globalDiscount, setGlobalDiscount] = useState<number>(0);
  const [isSaving, setIsSaving] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [lastInvoice, setLastInvoice] = useState<Invoice | null>(null);
  const [vehicleNo, setVehicleNo] = useState('');
  const [currentProductId, setCurrentProductId] = useState('');
  const [productSearch, setProductSearch] = useState(''); 
  const [currentQty, setCurrentQty] = useState(0);
  const [currentRate, setCurrentRate] = useState(0); 
  const [rateType, setRateType] = useState<'standard' | 'special' | 'manual'>('standard');

  const partyInputRef = useRef<HTMLInputElement>(null);
  const productInputRef = useRef<HTMLInputElement>(null);
  const qtyInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (initialData) {
      setSelectedPartyId(initialData.partyId);
      setItems(initialData.items);
      setInvoiceDate(initialData.date);
      setCustomInvoiceNo(initialData.invoiceNumber);
      setVehicleNo(initialData.vehicleNumber || '');
      setRefNo(initialData.poNumber || '');
      setGlobalDiscount(initialData.globalDiscount || 0);
    }
  }, [initialData]);

  const addItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentProductId || currentQty <= 0) return;
    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    const gstPercent = product.gstPercent || 0;
    const inclusiveRate = currentRate;
    const baseRate = inclusiveRate / (1 + (gstPercent / 100));
    const grossTotal = currentQty * inclusiveRate; 
    const totalWeight = currentQty * (product.unitWeight || 0);

    const newItem: InvoiceItem = {
      id: crypto.randomUUID(),
      productId: product.id,
      productName: product.name,
      quantity: currentQty,
      rate: inclusiveRate,
      baseRate: baseRate,  
      total: grossTotal,   
      totalWeight: totalWeight,
      hsn: product.hsn,
      gstPercent: gstPercent
    };

    setItems([...items, newItem]);
    setProductSearch('');
    setCurrentProductId('');
    setCurrentQty(0); 
    setCurrentRate(0);
    setRateType('standard');
    productInputRef.current?.focus();
  };

  const handleSaveInvoice = async () => {
    if (!selectedPartyId || items.length === 0) return;
    setIsSaving(true);

    const party = parties.find(p => p.id === selectedPartyId);
    const subTotal = items.reduce((sum, item) => sum + item.total, 0);
    const taxAmount = items.reduce((sum, item) => {
       const taxable = item.total / (1 + (item.gstPercent || 0)/100);
       return sum + (item.total - taxable);
    }, 0);

    const newInvoice: Invoice = {
      id: initialData ? initialData.id : crypto.randomUUID(), 
      invoiceNumber: customInvoiceNo,
      partyId: selectedPartyId,
      partyName: party?.name || 'Unknown Party',
      date: invoiceDate,
      items: items,
      subTotal: subTotal,
      taxPercent: 0,
      taxAmount: taxAmount,
      globalDiscount: globalDiscount,
      grandTotal: Math.round(subTotal - globalDiscount),
      vehicleNumber: vehicleNo,
      poNumber: refNo,
      partyAddress: party ? [party.address, party.city].filter(Boolean).join(', ') : '',
      partyGst: party?.gstNumber || '',
      partyPhone: party?.phone || ''
    };

    try {
        if (initialData) Store.updateInvoice(newInvoice);
        else Store.saveInvoice(newInvoice);

        setLastInvoice(newInvoice);
        setIsPreviewOpen(true); 
        onInvoiceSaved(); 
        setItems([]);
        setSelectedPartyId('');
    } catch (error) {
        alert("Error saving invoice.");
    } finally {
        setIsSaving(false);
    }
  };

  // Weight Calculation for summary
  const totalWeightKg = items.reduce((sum, item) => sum + (item.totalWeight || 0), 0);
  const formattedWeight = (kg: number) => {
    const mt = Math.floor(kg / 1000);
    const remKg = Math.round(kg % 1000);
    return mt > 0 ? `${mt} MT ${remKg} KG` : `${remKg} KG`;
  };

  return (
    <div className="flex h-full flex-col md:flex-row bg-slate-50">
      <div className="flex-1 flex flex-col h-full overflow-hidden border-r border-slate-200">
        <div className="px-6 py-4 bg-white border-b border-slate-200 flex justify-between items-center shadow-sm">
           <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2"><FileText size={20} className="text-sky-600" /> Billing</h2>
           <button onClick={handleSaveInvoice} disabled={isSaving || !selectedPartyId || items.length === 0} className="bg-slate-900 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-lg">
             <Save size={18} /> Save Invoice
           </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6">
           <div className="bg-white p-5 rounded-xl border border-slate-200">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Select Party</label>
              <select value={selectedPartyId} onChange={(e) => setSelectedPartyId(e.target.value)} className="w-full mt-1 p-2 border rounded-lg outline-none">
                 <option value="">Choose Party...</option>
                 {parties.map(p => <option key={p.id} value={p.id}>{p.name} ({p.code})</option>)}
              </select>
           </div>

           <div className="bg-sky-50/50 p-4 rounded-xl border border-sky-100 flex flex-col md:flex-row gap-4 items-end">
              <div className="flex-1 w-full">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Product</label>
                <select value={currentProductId} onChange={(e) => {
                  const pid = e.target.value;
                  setCurrentProductId(pid);
                  const p = products.find(prod => prod.id === pid);
                  if (p) {
                    setCurrentRate(p.standardRate);
                    // Check special rates
                    const special = specialRates.find(r => r.partyId === selectedPartyId && r.productId === pid);
                    if (special) {
                      setCurrentRate(special.rate);
                      setRateType('special');
                    } else {
                      setRateType('standard');
                    }
                  }
                }} className="w-full p-2 border rounded-lg mt-1 outline-none">
                  <option value="">Select Item...</option>
                  {products.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                </select>
              </div>
              <div className="w-24">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Qty</label>
                <input ref={qtyInputRef} type="number" value={currentQty || ''} onChange={e => setCurrentQty(parseFloat(e.target.value) || 0)} className="w-full p-2 border rounded-lg mt-1 text-center font-bold" />
              </div>
              <div className="w-32">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Rate</label>
