export const Ranking: React.FC<Props> = ({ invoices, parties }) => {
  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1).toISOString().split('T')[0];
  const lastDay = today.toISOString().split('T')[0];

  const [startDate, setStartDate] = useState(firstDay);
  const [endDate, setEndDate] = useState(lastDay);
  const [sortBy, setSortBy] = useState<'amount' | 'count' | 'weight'>('amount');
  const [searchTerm, setSearchTerm] = useState('');

  const topParties = useMemo(() => {
    const agg: Record<string, { partyId: string, partyName: string, partyCode: string, total: number, count: number, totalWeight: number }> = {};

    invoices.forEach(inv => {
      if (inv.date >= startDate && inv.date <= endDate) {
        const totalAmount = Number(inv.grandTotal) || 0;
        const weight = (inv.items || []).reduce((s, i) => s + (i.totalWeight || 0), 0);

        if (!agg[inv.partyId]) {
          const p = parties.find(pa => pa.id === inv.partyId);
          agg[inv.partyId] = { 
             partyId: inv.partyId, 
             partyName: inv.partyName || 'Unknown', 
             partyCode: p?.code || '-',
             total: 0, 
             count: 0,
             totalWeight: 0
          };
        }
        agg[inv.partyId].total += totalAmount;
        agg[inv.partyId].count += 1;
        agg[inv.partyId].totalWeight += weight;
      }
    });

    return Object.values(agg).sort((a, b) => {
        if (sortBy === 'amount') return b.total - a.total;
        if (sortBy === 'weight') return b.totalWeight - a.totalWeight;
        return b.count - a.count;
    });
  }, [invoices, startDate, endDate, sortBy, parties]);

  const displayedParties = useMemo(() => {
      if (!searchTerm) return topParties;
      return topParties.filter(p => p.partyName.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [topParties, searchTerm]);

  const formatWeight = (kg: number) => {
    const mt = Math.floor(kg / 1000);
    const remKg = Math.round(kg % 1000);
    if (mt > 0) return `${mt} MT ${remKg} KG`;
    return `${remKg} KG`;
  };

  return (
    <div className="p-6 max-w-6xl mx-auto">
       <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2"><Trophy className="text-yellow-500" /> Sales & Weight Performance</h2>
          <p className="text-slate-500">Summary of billing totals and total tonnage per party.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <div className="bg-white p-4 rounded-xl border flex flex-col justify-center">
            <label className="text-[10px] font-bold text-slate-400 uppercase mb-1">From</label>
            <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-2 border rounded-lg text-sm" />
        </div>
        <div className="bg-white p-4 rounded-xl border flex flex-col justify-center">
            <label className="text-[10px] font-bold text-slate-400 uppercase mb-1">To</label>
            <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-2 border rounded-lg text-sm" />
        </div>
        <div className="bg-white p-4 rounded-xl border flex flex-col justify-center">
            <label className="text-[10px] font-bold text-slate-400 uppercase mb-1">Sort By</label>
            <div className="flex gap-1 bg-slate-50 p-1 rounded-lg">
               <button onClick={() => setSortBy('amount')} className={`flex-1 py-1 text-[10px] font-bold rounded ${sortBy === 'amount' ? 'bg-white shadow text-sky-700' : 'text-slate-500'}`}>AMOUNT</button>
               <button onClick={() => setSortBy('weight')} className={`flex-1 py-1 text-[10px] font-bold rounded ${sortBy === 'weight' ? 'bg-white shadow text-sky-700' : 'text-slate-500'}`}>WEIGHT</button>
               <button onClick={() => setSortBy('count')} className={`flex-1 py-1 text-[10px] font-bold rounded ${sortBy === 'count' ? 'bg-white shadow text-sky-700' : 'text-slate-500'}`}>COUNT</button>
            </div>
        </div>
        <div className="bg-sky-600 p-4 rounded-xl text-white flex flex-col justify-center shadow-lg">
            <span className="text-[10px] font-bold uppercase opacity-80">Period Volume</span>
            <div className="text-xl font-black">{formatWeight(displayedParties.reduce((s, p) => s + p.totalWeight, 0))}</div>
