      </div>

      <div className="bg-white rounded-xl shadow-lg border border-slate-100 overflow-hidden">
         <table className="w-full text-left">
            <thead className="bg-slate-50 border-b text-xs font-bold text-slate-500 uppercase">
               <tr>
                 <th className="px-6 py-4 text-center">Rank</th>
                 <th className="px-6 py-4">Party Name</th>
                 <th className="px-6 py-4 text-center">Party Code</th>
                 <th className="px-6 py-4 text-center">Invoices</th>
                 <th className="px-6 py-4 text-center">Total Weight</th>
