        {currentView === 'more' && <div className="h-full overflow-y-auto"><MoreMenu invoices={invoices} parties={parties} products={products} /></div>}
      </div>

      {/* Print View Modal */}
      {viewInvoice && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex flex-col p-8 no-print overflow-y-auto">
          <div className="flex justify-between items-center mb-6 max-w-[210mm] mx-auto w-full">
