             <div className="flex gap-4">
                <button onClick={() => window.print()} className="bg-sky-600 hover:bg-sky-500 text-white px-8 py-2 rounded-xl font-bold flex items-center gap-2 shadow-xl"><Printer size={18}/> Print Now</button>
                <button onClick={() => setViewInvoice(null)} className="text-white px-6 py-2 border border-white/20 hover:bg-white/10 rounded-xl transition-all"><X size={20}/></button>
