interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
}

export const PartyManager: React.FC<Props> = ({ parties, setParties }) => {
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<Party>>({});
  const [searchTerm, setSearchTerm] = useState('');

  // Get invoices to calculate weight per party
  const invoices = useMemo(() => Store.getInvoices(), []);

  const calculatePartyWeight = (partyId: string) => {
    const partyInvoices = invoices.filter(inv => inv.partyId === partyId);
    const totalKg = partyInvoices.reduce((sum, inv) => {
      return sum + (inv.items || []).reduce((s, i) => s + (i.totalWeight || 0), 0);
    }, 0);

    const mt = Math.floor(totalKg / 1000);
    const remKg = Math.round(totalKg % 1000);
    return mt > 0 ? `${mt} MT ${remKg} KG` : `${remKg} KG`;
  };

  const generateSmartCode = (name: string, excludeId?: string) => {
    if (!name || name.trim().length === 0) return '';
    const cleanName = name.trim().toUpperCase();
    const prefix = `${cleanName.charAt(0)}${cleanName.charAt(cleanName.length - 1)}`.replace(/[^A-Z0-9]/g, 'X'); 
    const existingCodes = parties.filter(p => p.id !== excludeId && p.code && p.code.startsWith(prefix)).map(p => p.code!);
    let maxNum = 0;
    existingCodes.forEach(code => {
        const numPart = parseInt(code.substring(prefix.length));
        if (!isNaN(numPart) && numPart > maxNum) maxNum = numPart;
    });
    return `${prefix}${String(maxNum + 1).padStart(2, '0')}`;
  };

  const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const newName = e.target.value;
      if (!editingId) {
          const autoCode = generateSmartCode(newName);
          setFormData(prev => ({ ...prev, name: newName, code: autoCode }));
      } else {
          setFormData(prev => ({ ...prev, name: newName }));
      }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;
    let finalCode = formData.code || generateSmartCode(formData.name, editingId || undefined);

    if (editingId) {
      setParties(parties.map(p => p.id === editingId ? { ...p, ...formData, code: finalCode } as Party : p));
    } else {
      const newParty: Party = {
        id: crypto.randomUUID(),
        name: formData.name!,
        code: finalCode!,
        phone: formData.phone || '',
        address: formData.address || '',
        city: formData.city || '',
        gstNumber: formData.gstNumber || '',
        aadharNumber: formData.aadharNumber || '',
        panNumber: formData.panNumber || '',
        email: formData.email || '',
      };
      setParties([...parties, newParty]);
    }
    closeForm();
  };

  const filteredParties = parties.filter(p => {
    const term = searchTerm.toLowerCase();
    return (p.name?.toLowerCase().includes(term)) || (p.code?.toLowerCase().includes(term)) || (p.city?.toLowerCase().includes(term));
  });

  const openEdit = (party: Party) => {
    setFormData(party);
    setEditingId(party.id);
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setFormData({});
    setEditingId(null);
    setIsFormOpen(false);
  };

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 font-serif">Parties & Code Section</h2>
          <p className="text-slate-500">Manage customers and view total calculated weight.</p>
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
             <input type="text" placeholder="Search..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 border rounded-lg outline-none bg-white shadow-sm" />
          </div>
          <button onClick={() => setIsFormOpen(true)} className="bg-sky-600 hover:bg-sky-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 font-medium">
            <Plus size={18} /> Add Party
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border overflow-hidden overflow-x-auto">
        <table className="w-full text-left border-collapse min-w-[1000px]">
          <thead>
            <tr className="bg-slate-50 border-b">
              <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider">Party Code</th>
              <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider">Name</th>
              <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider">Total Weight (Sales)</th>
              <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider">Contact</th>
              <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredParties.map((party) => (
              <tr key={party.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4">
                    <span className="bg-slate-900 text-white font-mono font-bold px-3 py-1 rounded text-xs">
                        {party.code || '-'}
                    </span>
                </td>
                <td className="px-6 py-4">
                  <div className="font-bold text-slate-800 uppercase">{party.name}</div>
                  <div className="text-[10px] text-slate-400">{party.city}</div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center gap-2 text-sky-700 font-black text-sm bg-sky-50 px-3 py-1.5 rounded-lg border border-sky-100 w-fit">
                    <Weight size={14} />
                    {calculatePartyWeight(party.id)}
                  </div>
                </td>
                <td className="px-6 py-4 text-slate-600 font-mono text-sm">
                  {party.phone || '-'}
                </td>
                <td className="px-6 py-4 text-right">
                    <button onClick={() => openEdit(party)} className="p-2 text-slate-400 hover:text-sky-600 hover:bg-sky-50 rounded-full"><Edit2 size={16} /></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isFormOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-xl p-6 w-full max-w-2xl overflow-y-auto max-h-[90vh]">
            <h3 className="text-xl font-bold mb-4">{editingId ? 'Edit Party' : 'New Party'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                    <div className="col-span-2 md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Party Name</label>
                        <input className="w-full border rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-sky-500" value={formData.name || ''} onChange={handleNameChange} required />
                    </div>
                    <div className="col-span-2 md:col-span-1">
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Party Code</label>
                        <input className="w-full border rounded-lg px-3 py-2 outline-none bg-slate-50 font-mono font-bold" value={formData.code || ''} onChange={e => setFormData({...formData, code: e.target.value})} />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Phone</label>
                        <input className="w-full border rounded-lg px-3 py-2 outline-none" value={formData.phone || ''} onChange={e => setFormData({...formData, phone: e.target.value})} />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">City</label>
                        <input className="w-full border rounded-lg px-3 py-2 outline-none" value={formData.city || ''} onChange={e => setFormData({...formData, city: e.target.value})} />
                    </div>
                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Address</label>
                        <textarea className="w-full border rounded-lg px-3 py-2 outline-none" value={formData.address || ''} onChange={e => setFormData({...formData, address: e.target.value})} rows={2} />
                    </div>
                </div>
                <div className="flex justify-end gap-3 mt-6">
                    <button type="button" onClick={closeForm} className="text-slate-500 px-4 py-2">Cancel</button>
                    <button type="submit" className="bg-sky-600 text-white px-6 py-2 rounded-lg font-bold">Save Party</button>
                </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

