interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
}

export const PartyManager: React.FC<Props> = ({ parties, setParties }) => {
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<Party>>({});
  const [searchTerm, setSearchTerm] = useState('');

  // Fetch invoices once to calculate weights
  const invoices = useMemo(() => Store.getInvoices(), []);

  const calculateTotalWeight = (partyId: string) => {
    const partyInvoices = invoices.filter(inv => inv.partyId === partyId);
    const totalKg = partyInvoices.reduce((sum, inv) => {
      return sum + (inv.items || []).reduce((s, item) => s + (item.totalWeight || 0), 0);
    }, 0);

    const mt = Math.floor(totalKg / 1000);
    const remKg = Math.round(totalKg % 1000);
    return mt > 0 ? `${mt} MT ${remKg} KG` : `${remKg} KG`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;
    if (editingId) {
      setParties(parties.map(p => p.id === editingId ? { ...p, ...formData } as Party : p));
    } else {
      setParties([...parties, { ...formData, id: crypto.randomUUID() } as Party]);
    }
    closeForm();
  };

  const closeForm = () => {
    setFormData({});
    setEditingId(null);
    setIsFormOpen(false);
  };

  const filteredParties = parties.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    (p.code && p.code.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Parties & Code Section</h2>
          <p className="text-slate-500">Party details and lifetime purchase weight.</p>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          <input type="text" placeholder="Search party..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="px-4 py-2 border rounded-lg outline-none focus:ring-2 focus:ring-sky-500 w-full md:w-64 bg-white" />
          <button onClick={() => setIsFormOpen(true)} className="bg-sky-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 font-bold"><Plus size={18} /> Add Party</button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border overflow-hidden overflow-x-auto">
        <table className="w-full text-left min-w-[900px]">
          <thead>
            <tr className="bg-slate-50 border-b">
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Party Code</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Name</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Total Weight (Sales)</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Phone</th>
              <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredParties.map(party => (
              <tr key={party.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4"><span className="bg-slate-900 text-white font-mono font-bold px-2 py-1 rounded text-xs">{party.code || '-'}</span></td>
                <td className="px-6 py-4 font-bold text-slate-800 uppercase">{party.name}</td>
                <td className="px-6 py-4">
                    <div className="flex items-center gap-2 text-sky-700 font-black text-sm bg-sky-50 px-3 py-1.5 rounded-lg border border-sky-100 w-fit">
                        <Weight size={14} />
                        {calculateTotalWeight(party.id)}
                    </div>
                </td>
                <td className="px-6 py-4 font-mono text-slate-600">{party.phone || '-'}</td>
                <td className="px-6 py-4 text-right">
                    <button onClick={() => { setFormData(party); setEditingId(party.id); setIsFormOpen(true); }} className="text-slate-400 hover:text-sky-600 p-2"><Edit2 size={16} /></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {isFormOpen && (
        <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white p-6 rounded-xl shadow-xl w-full max-w-lg">
             <h3 className="text-xl font-bold mb-4">{editingId ? 'Edit Party' : 'Add Party'}</h3>
             <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                    <div className="col-span-2">
                        <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Name</label>
                        <input className="w-full border rounded-lg px-3 py-2" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} required />
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-slate-400 uppercase mb-1">Code</label>
                        <input className="w-full border rounded-lg px-3 py-2 font-mono" value={formData.code || ''} onChange={e => setFormData({...formData, code: e.target.value})} />
