          <div className="relative">
            <input ref={partyInputRef} type="text" value={partySearch} onChange={e => { setPartySearch(e.target.value); setShowPartySuggestions(true); }} placeholder="Search party..." className="w-full px-4 py-2.5 border rounded-lg font-bold text-slate-800" />
            {showPartySuggestions && filteredParties.length > 0 && (
              <div className="absolute z-50 w-full bg-white border rounded-lg shadow-xl mt-1 max-h-40 overflow-y-auto">
                {filteredParties.map(p => <div key={p.id} onClick={() => selectParty(p)} className="px-4 py-2 hover:bg-sky-50 cursor-pointer font-bold">{p.name}</div>)}
              </div>
            )}
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl border shadow-sm grid grid-cols-2 md:grid-cols-4 gap-4">
           <div>
             <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Invoice No</label>
             <input type="text" value={customInvoiceNo} onChange={e => setCustomInvoiceNo(e.target.value)} className="w-full border rounded-lg px-3 py-2 font-mono font-bold" />
           </div>
           <div>
             <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Date</label>
             <input type="date" value={invoiceDate} onChange={e => setInvoiceDate(e.target.value)} className="w-full border rounded-lg px-3 py-2 font-bold" />
           </div>
           <div>
             <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Vehicle No</label>
             <input type="text" value={vehicleNo} onChange={e => setVehicleNo(e.target.value.toUpperCase())} className="w-full border rounded-lg px-3 py-2 uppercase font-bold" />
           </div>
        </div>

        <div className="bg-sky-50 p-4 rounded-xl border border-sky-100 flex gap-4 items-end">
           <div className="flex-1 relative">
             <label className="text-[10px] font-bold text-sky-600 uppercase block mb-1">Product</label>
             <input ref={productInputRef} type="text" value={productSearch} onChange={e => { setProductSearch(e.target.value); setShowProductSuggestions(true); }} placeholder="Type product..." className="w-full border rounded-lg px-3 py-2.5 font-bold" />
             {showProductSuggestions && filteredProducts.length > 0 && (
               <div className="absolute z-50 w-full bg-white border rounded-lg shadow-xl mt-1">
                 {filteredProducts.map(p => <div key={p.id} onClick={() => { setProductSearch(p.name); setCurrentProductId(p.id); setShowProductSuggestions(false); qtyInputRef.current?.focus(); }} className="px-4 py-2 hover:bg-sky-50 cursor-pointer font-bold">{p.name}</div>)}
               </div>
             )}
           </div>
           <div className="w-24">
             <label className="text-[10px] font-bold text-sky-600 uppercase block mb-1">Qty</label>
             <input ref={qtyInputRef} type="number" value={currentQty || ''} onChange={e => setCurrentQty(parseFloat(e.target.value) || 0)} className="w-full border rounded-lg px-3 py-2.5 font-bold text-center" />
           </div>
           <div className="w-32">
             <label className="text-[10px] font-bold text-sky-600 uppercase block mb-1">Rate</label>
             <input type="number" value={currentRate} onChange={e => { setCurrentRate(parseFloat(e.target.value) || 0); setRateType('manual'); }} className="w-full border rounded-lg px-3 py-2.5 font-bold text-center" />
           </div>
           <button onClick={addItem} className="bg-sky-600 text-white p-3 rounded-lg"><Plus /></button>
        </div>

        <div className="bg-white rounded-xl border shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b">
              <tr className="text-[10px] font-bold text-slate-400 uppercase">
                <th className="px-4 py-3">Item</th>
                <th className="px-4 py-3 text-center">Qty</th>
                <th className="px-4 py-3 text-right">Rate</th>
                <th className="px-4 py-3 text-right">Total</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {items.map(item => (
                <tr key={item.id}>
                  <td className="px-4 py-3 font-bold text-slate-800">{item.productName}</td>
                  <td className="px-4 py-3 text-center font-bold">{item.quantity}</td>
                  <td className="px-4 py-3 text-right font-mono text-slate-600">{item.rate.toFixed(2)}</td>
                  <td className="px-4 py-3 text-right font-black">₹{item.total.toFixed(2)}</td>
                  <td className="px-4 py-3 text-center"><button onClick={() => setItems(items.filter(i => i.id !== item.id))} className="text-red-400"><Trash2 size={16}/></button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="flex justify-end gap-6 p-6 bg-white border rounded-xl shadow-sm">
           <div className="text-right">
             <div className="text-[10px] font-bold text-slate-400 uppercase">Sub Total</div>
             <div className="text-xl font-bold text-slate-800">₹{items.reduce((s,i) => s + i.total, 0).toFixed(2)}</div>
           </div>
           <div className="text-right border-l pl-6">
             <div className="text-[10px] font-bold text-sky-600 uppercase">Grand Total</div>
             <div className="text-3xl font-black text-slate-900">₹{Math.round(items.reduce((s,i) => s + i.total, 0) - globalDiscount).toLocaleString('en-IN')}</div>
           </div>
        </div>

        <div className="flex justify-center">
            <button onClick={handleSaveInvoice} className="bg-slate-900 text-white px-12 py-4 rounded-xl font-black text-lg flex items-center gap-3 hover:scale-[1.02] transition-transform shadow-xl">
               <Save size={24} /> SAVE & PRINT INVOICE
            </button>
        </div>
      </div>

      {isPreviewOpen && lastInvoice && (
        <div className="fixed inset-0 z-[200] bg-slate-900/90 backdrop-blur flex flex-col p-4 overflow-y-auto no-print">
            <div className="flex justify-between items-center mb-4 max-w-[210mm] mx-auto w-full text-white">
                <h2 className="text-xl font-bold">Invoice Preview</h2>
                <div className="flex gap-4">
                    <button onClick={() => window.print()} className="bg-sky-600 px-6 py-2 rounded-lg font-bold">Print</button>
                    <button onClick={() => setIsPreviewOpen(false)} className="bg-white/10 px-4 py-2 rounded-lg"><X /></button>
                </div>
            </div>
            <div className="bg-white mx-auto shadow-2xl print-area">
                <InvoiceTemplate invoice={lastInvoice} parties={parties} />
            </div>
            <style>{`
                @media print {
                  body * { visibility: hidden; }
                  .print-area, .print-area * { visibility: visible; }
                  .print-area { position: absolute; left: 0; top: 0; width: 100%; box-shadow: none; }
                }
            `}</style>
        </div>
      )}
    </div>
  );
};

