interface Props {
  products: Product[];
  setProducts: (p: Product[]) => void;
}

export const ProductManager: React.FC<Props> = ({ products, setProducts }) => {
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<Partial<Product>>({});
  const [searchTerm, setSearchTerm] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || formData.standardRate === undefined) return;

    let updatedProducts = [...products];

    if (editingId) {
      updatedProducts = products.map(p => p.id === editingId ? { ...p, ...formData } as Product : p);
    } else {
      const newProduct: Product = {
        id: crypto.randomUUID(),
        name: formData.name!,
        code: formData.code || 'N/A',
        standardRate: Number(formData.standardRate),
        unitWeight: Number(formData.unitWeight) || 0,
        unit: formData.unit || 'pcs',
        hsn: formData.hsn || '',
        gstPercent: Number(formData.gstPercent) || 0,
        qtyPerCase: Number(formData.qtyPerCase) || 1
      };
      updatedProducts.push(newProduct);
    }

    setProducts(updatedProducts);
    closeForm();
  };

  const openEdit = (product: Product) => {
    setFormData(product);
    setEditingId(product.id);
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setFormData({});
    setEditingId(null);
    setIsFormOpen(false);
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.code.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="p-6 max-w-6xl mx-auto">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Products & Inventory</h2>
          <p className="text-slate-500">Manage item rates and physical weight specs.</p>
        </div>

        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
             <input 
               type="text" 
               placeholder="Search products..." 
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
               className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-sky-500 outline-none bg-white text-slate-900 shadow-sm"
             />
          </div>

          <button 
            onClick={() => setIsFormOpen(true)}
            className="bg-sky-600 hover:bg-sky-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition-colors font-medium whitespace-nowrap"
          >
            <Plus size={18} /> Add Product
          </button>
        </div>
      </div>

      {isFormOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-xl p-6 w-full max-w-lg animate-in fade-in zoom-in duration-200 overflow-y-auto max-h-[90vh]">
            <h3 className="text-xl font-bold mb-4 text-slate-800">{editingId ? 'Edit Product' : 'New Product'}</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="bg-slate-50 p-3 rounded-lg space-y-3">
                <h4 className="text-xs font-bold text-slate-400 uppercase">Product Specs</h4>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Product Name *</label>
                  <input className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none bg-white" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} required />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Standard Rate (₹)</label>
                    <input type="number" step="0.01" className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none" value={formData.standardRate || ''} onChange={e => setFormData({...formData, standardRate: parseFloat(e.target.value)})} required />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Unit Weight (KG)</label>
                    <input type="number" step="0.001" className="w-full border border-sky-200 rounded-lg px-3 py-2 outline-none bg-sky-50 font-bold text-sky-700" value={formData.unitWeight || ''} onChange={e => setFormData({...formData, unitWeight: parseFloat(e.target.value)})} placeholder="e.g. 0.500" />
                  </div>
                </div>
              </div>

              <div className="bg-blue-50/50 p-3 rounded-lg space-y-3 border border-blue-100">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">HSN Code</label>
                    <input className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none" value={formData.hsn || ''} onChange={e => setFormData({...formData, hsn: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">GST (%)</label>
                    <input type="number" className="w-full border border-slate-300 rounded-lg px-3 py-2 outline-none" value={formData.gstPercent || ''} onChange={e => setFormData({...formData, gstPercent: parseFloat(e.target.value)})} />
                  </div>
                </div>
              </div>

              <div className="flex justify-end gap-3 mt-6">
                <button type="button" onClick={closeForm} className="text-slate-500 px-4 py-2">Cancel</button>
                <button type="submit" className="bg-sky-600 text-white px-6 py-2 rounded-lg font-medium">Save Product</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200 text-xs font-bold text-slate-600 uppercase">
              <th className="px-6 py-4">Product Info</th>
              <th className="px-6 py-4 text-center">Unit Weight</th>
              <th className="px-6 py-4 text-right">Standard Rate</th>
              <th className="px-6 py-4 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredProducts.map(product => (
              <tr key={product.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4">
                  <div className="font-semibold text-slate-800">{product.name}</div>
                  <div className="text-xs text-slate-400 font-mono">{product.code}</div>
                </td>
                <td className="px-6 py-4 text-center">
                  <span className="bg-sky-100 text-sky-700 px-3 py-1 rounded-full text-xs font-black">
                    {product.unitWeight || 0} KG
                  </span>
                </td>
                <td className="px-6 py-4 text-right font-mono font-bold text-slate-700">
                  ₹{(product.standardRate || 0).toFixed(2)}
                </td>
                <td className="px-6 py-4 text-right">
                  <button onClick={() => openEdit(product)} className="text-slate-400 hover:text-sky-600 p-2"><Edit2 size={16} /></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Party, Product, SpecialRate, Invoice, InvoiceItem } from '../types';
import { ShoppingCart, User, Plus, Trash2, Save, Scan, Zap, FileText, CloudLightning, Loader2, Printer, X, CreditCard, Box, MapPin, Phone, Calculator, ChevronDown, ChevronUp, Edit3, Copy, Download, FileSpreadsheet, Search, Tag, Sparkles, Info, ArrowUpCircle } from 'lucide-react';
import { Store } from '../services/store';
import { Cloud } from '../services/cloud';
import { InvoiceTemplate } from './InvoiceTemplate';

interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (rates: SpecialRate[]) => void; 
  onInvoiceSaved: () => void;
  initialData?: Invoice | null; 
}

const getTodayString = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

export const Billing: React.FC<Props> = ({ parties, setParties, products, specialRates, setSpecialRates, onInvoiceSaved, initialData }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string>('');
  const [items, setItems] = useState<InvoiceItem[]>([]);
  const [invoiceDate, setInvoiceDate] = useState(getTodayString());
  const [customInvoiceNo, setCustomInvoiceNo] = useState('');
  const [refNo, setRefNo] = useState(''); 
  const [globalDiscount, setGlobalDiscount] = useState<number>(0);
  const [isSaving, setIsSaving] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [lastInvoice, setLastInvoice] = useState<Invoice | null>(null);
  const [partySearch, setPartySearch] = useState('');
  const [showPartySuggestions, setShowPartySuggestions] = useState(false);
  const [vehicleNo, setVehicleNo] = useState('');
  const [productSearch, setProductSearch] = useState(''); 
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const [currentProductId, setCurrentProductId] = useState('');
  const [currentQty, setCurrentQty] = useState(0);
  const [currentRate, setCurrentRate] = useState(0);
  const [rateType, setRateType] = useState<'standard' | 'special' | 'manual'>('standard');

  const partyInputRef = useRef<HTMLInputElement>(null);
  const productInputRef = useRef<HTMLInputElement>(null);
  const qtyInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (initialData) {
      setSelectedPartyId(initialData.partyId);
      const p = parties.find(party => party.id === initialData.partyId);
      setPartySearch(p?.name || initialData.partyName);
      setItems(initialData.items);
      setInvoiceDate(initialData.date);
      setCustomInvoiceNo(initialData.invoiceNumber);
      setVehicleNo(initialData.vehicleNumber || '');
      setGlobalDiscount(initialData.globalDiscount || 0);
    }
  }, [initialData, parties]);

  const addItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentProductId || currentQty <= 0) return;
    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    const inclusiveRate = currentRate;
    const gstPercent = product.gstPercent || 0;
    const baseRate = inclusiveRate / (1 + gstPercent / 100);

    const newItem: InvoiceItem = {
      id: crypto.randomUUID(),
      productId: product.id,
      productName: product.name,
      quantity: currentQty,
      rate: inclusiveRate,
      baseRate: baseRate,
      total: currentQty * inclusiveRate,
      totalWeight: currentQty * (product.unitWeight || 0), // Calculate weight for this line
      hsn: product.hsn,
      gstPercent: gstPercent
    };

    setItems([...items, newItem]);
    setProductSearch('');
    setCurrentProductId('');
    setCurrentQty(0);
    setCurrentRate(0);
    productInputRef.current?.focus();
  };

  const handleSaveInvoice = async () => {
    if (!selectedPartyId || items.length === 0) return;
    setIsSaving(true);
    const party = parties.find(p => p.id === selectedPartyId);
    const subTotal = items.reduce((sum, item) => sum + item.total, 0);

    const newInvoice: Invoice = {
      id: initialData ? initialData.id : crypto.randomUUID(),
      invoiceNumber: customInvoiceNo,
      partyId: selectedPartyId,
      partyName: party?.name || 'Unknown',
      date: invoiceDate,
      items: items,
      subTotal: subTotal,
      taxPercent: 0,
      taxAmount: 0, 
      globalDiscount: globalDiscount,
      grandTotal: Math.round(subTotal - globalDiscount),
      vehicleNumber: vehicleNo,
      poNumber: refNo,
      partyAddress: party?.address || '',
      partyGst: party?.gstNumber || '',
      partyPhone: party?.phone || ''
    };

    if (initialData) Store.updateInvoice(newInvoice);
    else Store.saveInvoice(newInvoice);

    setLastInvoice(newInvoice);
    setIsPreviewOpen(true);
    onInvoiceSaved();
    setIsSaving(false);
  };

  useEffect(() => {
    if (currentProductId) {
      const prod = products.find(p => p.id === currentProductId);
      if (prod) {
        const special = specialRates.find(r => r.partyId === selectedPartyId && r.productId === currentProductId);
        setCurrentRate(special ? special.rate : prod.standardRate);
        setRateType(special ? 'special' : 'standard');
      }
    }
  }, [currentProductId, selectedPartyId, products, specialRates]);

  const filteredParties = parties.filter(p => p.name.toLowerCase().includes(partySearch.toLowerCase()));
  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(productSearch.toLowerCase()));

  return (
    <div className="flex h-full bg-slate-50">
      <div className="flex-1 flex flex-col p-6 overflow-y-auto space-y-6">
        <div className="bg-white p-6 rounded-xl border shadow-sm">
          <label className="text-xs font-bold text-slate-400 uppercase block mb-2">Party Selection</label>
          <div className="relative">
            <input ref={partyInputRef} type="text" value={partySearch} onChange={e => { setPartySearch(e.target.value); setShowPartySuggestions(true); }} placeholder="Search party..." className="w-full px-4 py-2.5 border rounded-lg font-bold text-slate-800" />
            {showPartySuggestions && filteredParties.length > 0 && (
              <div className="absolute z-50 w-full bg-white border rounded-lg shadow-xl mt-1 max-h-40 overflow-y-auto">
                {filteredParties.map(p => <div key={p.id} onClick={() => { setSelectedPartyId(p.id); setPartySearch(p.name); setShowPartySuggestions(false); }} className="px-4 py-2 hover:bg-sky-50 cursor-pointer font-bold">{p.name}</div>)}
              </div>
            )}
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl border shadow-sm grid grid-cols-2 md:grid-cols-4 gap-4">
           <div>
             <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Invoice No</label>
             <input type="text" value={customInvoiceNo} onChange={e => setCustomInvoiceNo(e.target.value)} className="w-full border rounded-lg px-3 py-2 font-mono font-bold" />
           </div>
           <div>
             <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Date</label>
             <input type="date" value={invoiceDate} onChange={e => setInvoiceDate(e.target.value)} className="w-full border rounded-lg px-3 py-2 font-bold" />
           </div>
           <div>
             <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Vehicle No</label>
             <input type="text" value={vehicleNo} onChange={e => setVehicleNo(e.target.value.toUpperCase())} className="w-full border rounded-lg px-3 py-2 uppercase font-bold" />
           </div>
        </div>

        <div className="bg-sky-50 p-4 rounded-xl border border-sky-100 flex gap-4 items-end">
           <div className="flex-1 relative">
             <label className="text-[10px] font-bold text-sky-600 uppercase block mb-1">Product</label>
             <input ref={productInputRef} type="text" value={productSearch} onChange={e => { setProductSearch(e.target.value); setShowProductSuggestions(true); }} placeholder="Type product..." className="w-full border rounded-lg px-3 py-2.5 font-bold" />
             {showProductSuggestions && filteredProducts.length > 0 && (
               <div className="absolute z-50 w-full bg-white border rounded-lg shadow-xl mt-1">
                 {filteredProducts.map(p => <div key={p.id} onClick={() => { setProductSearch(p.name); setCurrentProductId(p.id); setShowProductSuggestions(false); qtyInputRef.current?.focus(); }} className="px-4 py-2 hover:bg-sky-50 cursor-pointer font-bold">{p.name}</div>)}
               </div>
             )}
           </div>
           <div className="w-24">
             <label className="text-[10px] font-bold text-sky-600 uppercase block mb-1">Qty</label>
             <input ref={qtyInputRef} type="number" value={currentQty || ''} onChange={e => setCurrentQty(parseFloat(e.target.value) || 0)} className="w-full border rounded-lg px-3 py-2.5 font-bold text-center" />
           </div>
           <div className="w-32">
             <label className="text-[10px] font-bold text-sky-600 uppercase block mb-1">Rate</label>
             <input type="number" value={currentRate} onChange={e => { setCurrentRate(parseFloat(e.target.value) || 0); setRateType('manual'); }} className="w-full border rounded-lg px-3 py-2.5 font-bold text-center" />
           </div>
           <button onClick={addItem} className="bg-sky-600 text-white p-3 rounded-lg"><Plus /></button>
        </div>

        <div className="bg-white rounded-xl border shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b">
              <tr className="text-[10px] font-bold text-slate-400 uppercase">
                <th className="px-4 py-3">Item</th>
                <th className="px-4 py-3 text-center">Qty</th>
                <th className="px-4 py-3 text-center">Weight</th>
                <th className="px-4 py-3 text-right">Rate</th>
                <th className="px-4 py-3 text-right">Total</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
