            <Plus size={18} /> Add Party
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border overflow-hidden overflow-x-auto">
        <table className="w-full text-left border-collapse min-w-[1000px]">
          <thead>
            <tr className="bg-slate-50 border-b">
              <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider">Party Code</th>
              <th className="px-6 py-4 font-bold text-slate-600 text-xs uppercase tracking-wider">Name</th>
