const numberToWords = (num: number): string => {
  const a = ['','One ','Two ','Three ','Four ','Five ','Six ','Seven ','Eight ','Nine ','Ten ','Eleven ','Twelve ','Thirteen ','Fourteen ','Fifteen ','Sixteen ','Seventeen ','Eighteen ','Nineteen '];
  const b = ['', '', 'Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];

  const convert = (n: number): string => {
    if (n === 0) return '';
    if (n < 20) return a[n];
    if (n < 100) return b[Math.floor(n / 10)] + (n % 10 !== 0 ? ' ' + a[n % 10] : '');
    if (n < 1000) return a[Math.floor(n / 100)] + 'Hundred ' + convert(n % 100);
    if (n < 100000) return convert(Math.floor(n / 1000)) + 'Thousand ' + convert(n % 1000);
    if (n < 10000000) return convert(Math.floor(n / 100000)) + 'Lakh ' + convert(n % 100000);
    return convert(Math.floor(n / 10000000)) + 'Crore ' + convert(n % 10000000);
  };

  const numInt = Math.floor(num || 0);
  if (numInt === 0) return 'Zero Rupees Only';
  return `Rupees ${convert(numInt)}Only`; 
};

// Helper for weight formatting in invoice
const formatWeight = (kg: number) => {
  const mt = Math.floor(kg / 1000);
  const remKg = Math.round(kg % 1000);
  if (mt > 0) {
    return `${mt} MT ${remKg} KG`;
  }
  return `${remKg.toFixed(2)} KG`;
};

