                               <button onClick={(e) => handlePrintOptions(e, inv)} className="text-slate-400 hover:text-sky-600 p-2 hover:bg-sky-50 rounded-lg transition-all" title="Print Options">
                                 <Printer size={16} />
                               </button>
                               <button onClick={() => handleDownloadSingleInvoice(inv)} className="text-slate-400 hover:text-emerald-600 p-2 hover:bg-emerald-50 rounded-lg transition-all" title="Download CSV">
                                 <Download size={16} />
                               </button>
                             </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
             </div>
          </div>
        )}

        {currentView === 'data' && (
          <div className="h-full overflow-y-auto">
            <DataManager parties={parties} products={products} specialRates={specialRates} invoices={invoices} refreshData={loadLocalData} onForcePush={handleForcePush} />
          </div>
        )}
      </div>
    </div>
  );
};

