export const Cloud = {
  getScriptUrl: () => 'SUPABASE_ENABLED', 

  clearAllData: async () => {
    console.warn("Wipe command blocked by security policy.");
    return true;
  },

  // --- SYNC METHODS (UPSERT) ---
  syncInvoice: async (invoice: Invoice) => {
    const { error } = await supabase
      .from('invoices')
      .upsert({
        id: invoice.id,
        invoiceNumber: invoice.invoiceNumber,
        partyId: invoice.partyId,
        partyName: invoice.partyName,
        date: invoice.date,
        items: invoice.items, 
        subTotal: invoice.subTotal,
        taxAmount: invoice.taxAmount,
        globalDiscount: invoice.globalDiscount,
        grandTotal: invoice.grandTotal,
        vehicleNumber: invoice.vehicleNumber,
        poNumber: invoice.poNumber,
        partyAddress: invoice.partyAddress,
        partyGst: invoice.partyGst,
        partyPan: invoice.partyPan,
        partyAadhar: invoice.partyAadhar,
        partyPhone: invoice.partyPhone
      });

    if (error) {
      console.error('Error syncing invoice:', error);
      return { success: false, error: error.message };
    }
    return { success: true };
  },

  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
    try {
      if (parties.length > 0) {
        await supabase.from('parties').upsert(parties);
      }

      if (products.length > 0) {
        // SQL schema uses 'standardRate', mapping local 'unitWeight' is skipped if not in SQL
        const productsToSync = products.map(({ ...p }) => ({
            id: p.id,
            name: p.name,
            code: p.code,
            standardRate: p.standardRate,
            unit: p.unit,
            hsn: p.hsn,
            gstPercent: p.gstPercent,
            qtyPerCase: p.qtyPerCase
        }));
        await supabase.from('products').upsert(productsToSync);
      }

      if (users.length > 0) {
        await supabase.from('app_users').upsert(users);
      }

      // Special Rates: Handling quoted column names partyId and productId
      if (rates.length >= 0) {
        const { error: deleteError } = await supabase.from('special_rates').delete().neq('rate', -1);
        if (!deleteError && rates.length > 0) {
            const ratesToSync = rates.map(r => ({
                partyId: r.partyId,
                productId: r.productId,
                rate: r.rate
            }));
            await supabase.from('special_rates').insert(ratesToSync);
        }
      }

      return { success: true };
    } catch (e: any) {
      console.error("Master Sync Error", e);
      return { success: false, error: e.message };
    }
  },

  // --- FETCH METHODS ---
  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES' | 'INVOICES' | 'USERS'): Promise<any[]> => {
    try {
      const tableMap: Record<string, string> = {
        'PARTIES': 'parties',
        'PRODUCTS': 'products',
        'RATES': 'special_rates',
        'INVOICES': 'invoices',
        'USERS': 'app_users'
      };

      const table = tableMap[type];
      if (!table) return [];

      let query = supabase.from(table).select('*');

      if (type === 'PARTIES' || type === 'PRODUCTS') {
        query = query.order('name', { ascending: true });
      } else if (type === 'INVOICES') {
        query = query.order('created_at', { ascending: false });
      }

      const { data, error } = await query;
      if (error) throw error;

      if (type === 'INVOICES') {
        return (data || []).map((inv: any) => ({
          ...inv,
          items: typeof inv.items === 'string' ? JSON.parse(inv.items) : (inv.items || []),
          subTotal: Number(inv.subTotal) || 0,
          taxAmount: Number(inv.taxAmount) || 0,
          globalDiscount: Number(inv.globalDiscount) || 0,
          grandTotal: Number(inv.grandTotal) || 0,
          taxPercent: Number(inv.taxPercent) || 0,
        }));
      }

      if (type === 'RATES') {
          // Normalize quoted columns to standard JS property names
          return (data || []).map(r => ({ 
              partyId: r.partyId, 
              productId: r.productId, 
              rate: Number(r.rate) 
          }));
      }

      if (type === 'PRODUCTS') {
          return (data || []).map(p => ({ 
              ...p, 
              standardRate: Number(p.standardRate),
              gstPercent: Number(p.gstPercent || 0),
              qtyPerCase: Number(p.qtyPerCase || 1)
          }));
      }

      return data || [];
    } catch (e) {
      console.error(`Fetch error for ${type}:`, e);
      return [];
    }
  },

  fetchUsers: async (): Promise<User[]> => {
    return Cloud.fetchData('USERS');
  },

  fetchInvoices: async (): Promise<Invoice[]> => {
    return Cloud.fetchData('INVOICES');
  },

  testConnection: async () => {
    try {
      const { error } = await supabase.from('parties').select('id').limit(1);
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (e: any) {
      return { success: false, error: e.message || "Unknown Connection Error" };
    }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Party, Product, SpecialRate, Invoice, InvoiceItem } from '../types';
import { ShoppingCart, User, Plus, Trash2, Save, Scan, Zap, FileText, CloudLightning, Loader2, Printer, X, CreditCard, Box, MapPin, Phone, Calculator, ChevronDown, ChevronUp, Edit3, Copy, Download, FileSpreadsheet, Search, Tag, Sparkles, Info, ArrowUpCircle } from 'lucide-react';
