interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (rates: SpecialRate[]) => void; 
  onInvoiceSaved: () => void;
  initialData?: Invoice | null; 
}

const getTodayString = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

export const Billing: React.FC<Props> = ({ parties, setParties, products, specialRates, setSpecialRates, onInvoiceSaved, initialData }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string>('');
  const [items, setItems] = useState<InvoiceItem[]>([]);
  const [invoiceDate, setInvoiceDate] = useState(getTodayString());
  const [customInvoiceNo, setCustomInvoiceNo] = useState('');
  const [refNo, setRefNo] = useState(''); 
  const [globalDiscount, setGlobalDiscount] = useState<number>(0);
  const [isSaving, setIsSaving] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [lastInvoice, setLastInvoice] = useState<Invoice | null>(null);
  const [partySearch, setPartySearch] = useState('');
  const [showPartySuggestions, setShowPartySuggestions] = useState(false);
  const [vehicleNo, setVehicleNo] = useState('');
  const [productSearch, setProductSearch] = useState(''); 
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const [currentProductId, setCurrentProductId] = useState('');
  const [currentQty, setCurrentQty] = useState(0);
  const [currentRate, setCurrentRate] = useState(0);
  const [rateType, setRateType] = useState<'standard' | 'special' | 'manual'>('standard');

  const partyInputRef = useRef<HTMLInputElement>(null);
  const productInputRef = useRef<HTMLInputElement>(null);
  const qtyInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (initialData) {
      setSelectedPartyId(initialData.partyId);
      const p = parties.find(party => party.id === initialData.partyId);
      setPartySearch(p?.name || initialData.partyName);
      setItems(initialData.items);
      setInvoiceDate(initialData.date);
      setCustomInvoiceNo(initialData.invoiceNumber);
      setVehicleNo(initialData.vehicleNumber || '');
      setGlobalDiscount(initialData.globalDiscount || 0);
    }
  }, [initialData, parties]);

  const addItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentProductId || currentQty <= 0) return;
    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    const inclusiveRate = currentRate;
    const gstPercent = product.gstPercent || 0;
    const baseRate = inclusiveRate / (1 + gstPercent / 100);

    const newItem: InvoiceItem = {
      id: crypto.randomUUID(),
      productId: product.id,
      productName: product.name,
      quantity: currentQty,
      rate: inclusiveRate,
      baseRate: baseRate,
      total: currentQty * inclusiveRate,
      totalWeight: currentQty * (product.unitWeight || 0), 
      hsn: product.hsn,
      gstPercent: gstPercent
    };

    setItems([...items, newItem]);
    setProductSearch('');
    setCurrentProductId('');
    setCurrentQty(0);
    setCurrentRate(0);
    productInputRef.current?.focus();
  };

  const handleSaveInvoice = async () => {
    if (!selectedPartyId || items.length === 0) return;
    setIsSaving(true);
    const party = parties.find(p => p.id === selectedPartyId);
    const subTotal = items.reduce((sum, item) => sum + item.total, 0);

    const newInvoice: Invoice = {
      id: initialData ? initialData.id : crypto.randomUUID(),
      invoiceNumber: customInvoiceNo,
      partyId: selectedPartyId,
      partyName: party?.name || 'Unknown',
      date: invoiceDate,
      items: items,
      subTotal: subTotal,
      taxPercent: 0,
      taxAmount: 0, 
      globalDiscount: globalDiscount,
      grandTotal: Math.round(subTotal - globalDiscount),
      vehicleNumber: vehicleNo,
      poNumber: refNo,
      partyAddress: party?.address || '',
      partyGst: party?.gstNumber || '',
      partyPhone: party?.phone || ''
    };

    if (initialData) Store.updateInvoice(newInvoice);
    else Store.saveInvoice(newInvoice);

    setLastInvoice(newInvoice);
    setIsPreviewOpen(true);
    onInvoiceSaved();
    setIsSaving(false);
  };

  // Fix: Ensure rate updates when party or product changes
  useEffect(() => {
    if (currentProductId) {
      const prod = products.find(p => p.id === currentProductId);
      if (prod) {
        const special = specialRates.find(r => r.partyId === selectedPartyId && r.productId === currentProductId);
        setCurrentRate(special ? special.rate : (prod.standardRate || 0));
        setRateType(special ? 'special' : 'standard');
      }
    }
  }, [currentProductId, selectedPartyId, products, specialRates]);

  const filteredParties = parties.filter(p => p.name.toLowerCase().includes(partySearch.toLowerCase()));
  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(productSearch.toLowerCase()));

  return (
    <div className="flex h-full bg-slate-50">
      <div className="flex-1 flex flex-col p-6 overflow-y-auto space-y-6">
        <div className="bg-white p-6 rounded-xl border shadow-sm">
          <label className="text-xs font-bold text-slate-400 uppercase block mb-2">Party Selection</label>
          <div className="relative">
            <input 
              ref={partyInputRef} 
              type="text" 
              value={partySearch} 
              onChange={e => { setPartySearch(e.target.value); setShowPartySuggestions(true); }} 
              onFocus={() => setShowPartySuggestions(true)}
              placeholder="Search party..." 
              className="w-full px-4 py-2.5 border rounded-lg font-bold text-slate-800" 
            />
            {showPartySuggestions && filteredParties.length > 0 && (
              <div className="absolute z-50 w-full bg-white border rounded-lg shadow-xl mt-1 max-h-40 overflow-y-auto">
                {filteredParties.map(p => (
                  <div 
                    key={p.id} 
                    onClick={() => { 
                      setSelectedPartyId(p.id); 
                      setPartySearch(p.name); 
                      setShowPartySuggestions(false); 
                      productInputRef.current?.focus();
                    }} 
                    className="px-4 py-2 hover:bg-sky-50 cursor-pointer font-bold"
                  >
                    {p.name} <span className="text-[10px] text-slate-400 ml-2">{p.code}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl border shadow-sm grid grid-cols-2 md:grid-cols-4 gap-4">
           <div>
             <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Invoice No</label>
             <input type="text" value={customInvoiceNo} onChange={e => setCustomInvoiceNo(e.target.value)} className="w-full border rounded-lg px-3 py-2 font-mono font-bold" />
           </div>
           <div>
             <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Date</label>
             <input type="date" value={invoiceDate} onChange={e => setInvoiceDate(e.target.value)} className="w-full border rounded-lg px-3 py-2 font-bold" />
           </div>
           <div>
             <label className="text-[10px] font-bold text-slate-400 uppercase block mb-1">Vehicle No</label>
             <input type="text" value={vehicleNo} onChange={e => setVehicleNo(e.target.value.toUpperCase())} className="w-full border rounded-lg px-3 py-2 uppercase font-bold" />
           </div>
        </div>

        <div className="bg-sky-50 p-4 rounded-xl border border-sky-100 flex gap-4 items-end">
           <div className="flex-1 relative">
             <label className="text-[10px] font-bold text-sky-600 uppercase block mb-1">Product</label>
             <input 
              ref={productInputRef} 
              type="text" 
              value={productSearch} 
              onChange={e => { setProductSearch(e.target.value); setShowProductSuggestions(true); }} 
              onFocus={() => setShowProductSuggestions(true)}
              placeholder="Type product..." 
              className="w-full border rounded-lg px-3 py-2.5 font-bold" 
             />
             {showProductSuggestions && filteredProducts.length > 0 && (
               <div className="absolute z-50 w-full bg-white border rounded-lg shadow-xl mt-1 max-h-48 overflow-y-auto">
                 {filteredProducts.map(p => (
                   <div 
                    key={p.id} 
                    onClick={() => { 
                      setProductSearch(p.name); 
                      setCurrentProductId(p.id); 
                      setShowProductSuggestions(false); 
                      qtyInputRef.current?.focus(); 
                    }} 
                    className="px-4 py-2 hover:bg-sky-50 cursor-pointer font-bold"
                   >
                     {p.name} <span className="text-[10px] text-slate-400 ml-2">₹{p.standardRate}</span>
                   </div>
                 ))}
               </div>
             )}
           </div>
           <div className="w-24">
             <label className="text-[10px] font-bold text-sky-600 uppercase block mb-1">Qty</label>
             <input ref={qtyInputRef} type="number" value={currentQty || ''} onChange={e => setCurrentQty(parseFloat(e.target.value) || 0)} className="w-full border rounded-lg px-3 py-2.5 font-bold text-center" />
           </div>
           <div className="w-32">
             <label className="text-[10px] font-bold text-sky-600 uppercase block mb-1">Rate {rateType === 'special' && '⭐'}</label>
