    }
    return { success: true };
  },

  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
    try {
      if (parties.length > 0) {
        await supabase.from('parties').upsert(parties);
      }

      if (products.length > 0) {
        const productsToSync = products.map(p => ({
            id: p.id,
            name: p.name,
            code: p.code,
            standardRate: p.standardRate,
            unit: p.unit,
            hsn: p.hsn,
            gstPercent: p.gstPercent,
            qtyPerCase: p.qtyPerCase
        }));
        await supabase.from('products').upsert(productsToSync);
      }

      if (users.length > 0) {
        await supabase.from('app_users').upsert(users);
      }

      if (rates.length >= 0) {
        const { error: deleteError } = await supabase.from('special_rates').delete().neq('rate', -1);
        if (!deleteError && rates.length > 0) {
            const ratesToSync = rates.map(r => ({
                partyId: r.partyId,
                productId: r.productId,
                rate: r.rate
            }));
            await supabase.from('special_rates').insert(ratesToSync);
        }
      }
      return { success: true };
    } catch (e: any) {
      console.error("Master Sync Error", e);
      return { success: false, error: e.message };
    }
  },

  // --- OPTIMIZED FETCH METHODS ---
  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES' | 'INVOICES' | 'USERS'): Promise<any[]> => {
    try {
      const tableMap: Record<string, { table: string, cols: string }> = {
        'PARTIES': { table: 'parties', cols: 'id, name, code, address, city, phone, gstNumber, aadharNumber, panNumber' },
        'PRODUCTS': { table: 'products', cols: 'id, name, code, standardRate, unit, hsn, gstPercent, qtyPerCase' },
        'RATES': { table: 'special_rates', cols: 'partyId, productId, rate' },
        'INVOICES': { table: 'invoices', cols: 'id, invoiceNumber, partyId, partyName, date, items, subTotal, taxAmount, globalDiscount, grandTotal, vehicleNumber, poNumber, created_at' },
        'USERS': { table: 'app_users', cols: 'username, password, role' }
      };

      const config = tableMap[type];
      if (!config) return [];

      let query = supabase.from(config.table).select(config.cols);

      if (type === 'PARTIES' || type === 'PRODUCTS') {
        query = query.order('name', { ascending: true });
      } else if (type === 'INVOICES') {
        // Limit to 50 most recent for performance
        query = query.order('created_at', { ascending: false }).limit(50);
      }

      const { data, error } = await query;
      if (error) throw error;

      if (type === 'INVOICES') {
        return (data || []).map((inv: any) => ({
          ...inv,
          items: typeof inv.items === 'string' ? JSON.parse(inv.items) : (inv.items || []),
          subTotal: Number(inv.subTotal) || 0,
          taxAmount: Number(inv.taxAmount) || 0,
          globalDiscount: Number(inv.globalDiscount) || 0,
          grandTotal: Number(inv.grandTotal) || 0
        }));
      }

      if (type === 'RATES') {
          return (data || []).map(r => ({ 
              partyId: r.partyId, 
              productId: r.productId, 
              rate: Number(r.rate) 
          }));
      }

      if (type === 'PRODUCTS') {
          return (data || []).map(p => ({ 
              ...p, 
              standardRate: Number(p.standardRate),
              gstPercent: Number(p.gstPercent || 0),
              qtyPerCase: Number(p.qtyPerCase || 1)
          }));
      }

      return data || [];
    } catch (e) {
      console.error(`Fetch error for ${type}:`, e);
      return [];
    }
  },

  fetchUsers: async (): Promise<User[]> => {
    return Cloud.fetchData('USERS');
  },

  fetchInvoices: async (): Promise<Invoice[]> => {
    return Cloud.fetchData('INVOICES');
  },

  testConnection: async () => {
    try {
      const { error } = await supabase.from('parties').select('id').limit(1);
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (e: any) {
      return { success: false, error: e.message || "Unknown Connection Error" };
    }
  }
};

