declare global {
  interface Window {
    html2pdf: any;
  }
}

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  const [validUsers, setValidUsers] = useState<User[]>(() => Store.getUsers());
  const [parties, setParties] = useState<Party[]>(() => Store.getParties());
  const [products, setProducts] = useState<Product[]>(() => Store.getProducts());
  const [specialRates, setSpecialRates] = useState<SpecialRate[]>(() => Store.getRates());
  const [invoices, setInvoices] = useState<Invoice[]>(() => Store.getInvoices());

  const [currentView, setCurrentView] = useState<ViewState>('billing');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [viewInvoice, setViewInvoice] = useState<Invoice | null>(null);
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

  const [invoiceSearch, setInvoiceSearch] = useState('');
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);

  const [contextMenu, setContextMenu] = useState<{ visible: boolean; x: number; y: number; invoice: Invoice | null }>({
    visible: false,
    x: 0,
    y: 0,
    invoice: null,
  });

  const [pdfInvoice, setPdfInvoice] = useState<Invoice | null>(null);
  const pdfContainerRef = useRef<HTMLDivElement>(null);

  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'pulling'>('idle');

  const isFirstLoad = useRef(true);
  const hasPendingChanges = useRef(false);
  const isRemoteUpdate = useRef(false);
  const lastPushTime = useRef(0); 
  const isFetching = useRef(false);
  const masterDataFetched = useRef(false);

  const calculateInvWeight = (inv: Invoice) => {
    return (inv.items || []).reduce((sum, item) => sum + (item.totalWeight || 0), 0);
  };

  const formatWeight = (kg: number) => {
    const mt = Math.floor(kg / 1000);
    const remKg = Math.round(kg % 1000);
    return mt > 0 ? `${mt} MT ${remKg} KG` : `${remKg} KG`;
  };

  const loadLocalData = () => {
    setParties(Store.getParties());
    setProducts(Store.getProducts());
    setSpecialRates(Store.getRates());
    setInvoices(Store.getInvoices());
    setValidUsers(Store.getUsers());
  };

  useEffect(() => {
    const handleClick = () => setContextMenu({ ...contextMenu, visible: false });
    window.addEventListener('click', handleClick);
    return () => window.removeEventListener('click', handleClick);
  }, [contextMenu]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('gfb_user');
    if (sessionUser) {
      setIsAuthenticated(true);
    }
    handleCloudPull(true); // Initial fetch including master data
  }, []);

  // AUTO-SYNC PUSH (Debounced)
  useEffect(() => {
    Store.saveParties(parties);
    Store.saveProducts(products);
    Store.saveRates(specialRates);
    Store.saveUsers(validUsers);

    if (isFirstLoad.current) {
      isFirstLoad.current = false;
      return;
    }

    if (isRemoteUpdate.current) {
       isRemoteUpdate.current = false; 
       return; 
    }

    hasPendingChanges.current = true;

    setSyncStatus('syncing');
    const handler = setTimeout(async () => {
        try {
          const result = await Cloud.syncMasterData(parties, products, specialRates, validUsers);
          if (result.success) {
            lastPushTime.current = Date.now();
            setSyncStatus('synced');
            hasPendingChanges.current = false;
            setTimeout(() => setSyncStatus('idle'), 2000);
          } else {
            setSyncStatus('idle');
          }
        } catch (e) {
          console.error("Auto-sync failed", e);
          setSyncStatus('idle');
          hasPendingChanges.current = false; 
        }
    }, 5000); // 5s debounce for local changes

    return () => clearTimeout(handler);
  }, [parties, products, specialRates, validUsers]);

  const handleCloudPull = useCallback(async (includeMasterData = false) => {
      // Logic guards to prevent unnecessary requests
      if (isFetching.current || hasPendingChanges.current || document.visibilityState === 'hidden') return;
      if (!includeMasterData && Date.now() - lastPushTime.current < 30000) return; // 30s minimum wait

      try {
        isFetching.current = true;
        setSyncStatus('pulling');

        // Conditional fetches to save requests
        const fetches = [Cloud.fetchInvoices()];
        if (includeMasterData || !masterDataFetched.current) {
            fetches.push(Cloud.fetchData('PARTIES'), Cloud.fetchData('PRODUCTS'), Cloud.fetchData('RATES'), Cloud.fetchUsers());
        }

        const [cloudInvoices, cloudParties, cloudProducts, cloudRates, cloudUsers] = await Promise.all(fetches);

        let updateData = false;

        // Invoice update
        if (cloudInvoices && cloudInvoices.length > 0 && cloudInvoices.length !== invoices.length) {
            setInvoices(cloudInvoices);
            Store.saveInvoices(cloudInvoices);
        }

        // Master Data updates (only if fetched)
        if (cloudParties) {
            if (cloudParties.length > 0 && JSON.stringify(cloudParties) !== JSON.stringify(parties)) { setParties(cloudParties); updateData = true; }
            if (cloudProducts.length > 0 && JSON.stringify(cloudProducts) !== JSON.stringify(products)) { setProducts(cloudProducts); updateData = true; }
            if (cloudRates.length > 0 && JSON.stringify(cloudRates) !== JSON.stringify(specialRates)) { setSpecialRates(cloudRates); updateData = true; }
            if (cloudUsers.length > 0 && JSON.stringify(cloudUsers) !== JSON.stringify(validUsers)) { setValidUsers(cloudUsers); updateData = true; }
            masterDataFetched.current = true;
        }

        if (updateData) isRemoteUpdate.current = true;
        setSyncStatus('idle');

      } catch (e) {
        console.error("Cloud Pull Error", e);
        setSyncStatus('idle');
      } finally {
        isFetching.current = false;
      }
  }, [parties, products, specialRates, invoices, validUsers]);

  // STRICT POLLING: 60 seconds interval, only when visible
  useEffect(() => {
    const interval = setInterval(() => handleCloudPull(false), 60000); 
    const handleVisibility = () => { if (document.visibilityState === 'visible') handleCloudPull(false); };
    document.addEventListener('visibilitychange', handleVisibility);
    return () => {
        clearInterval(interval);
        document.removeEventListener('visibilitychange', handleVisibility);
    };
  }, [handleCloudPull]);

  const refreshInvoices = () => {
    setInvoices(Store.getInvoices());
  };

  const handleEditInvoice = (invoice: Invoice) => {
    setEditingInvoice(invoice);
    setCurrentView('billing');
  };

  const handleLogin = (user: User) => {
    setIsAuthenticated(true);
    sessionStorage.setItem('gfb_user', JSON.stringify(user));
  };

  const confirmLogout = () => {
    setIsAuthenticated(false);
    sessionStorage.removeItem('gfb_user');
    setShowLogoutConfirm(false);
  };

  const filteredInvoices = invoices.filter(inv => {
    if (!inv) return false;
    const term = invoiceSearch.toLowerCase();
    const invNo = inv.invoiceNumber ? inv.invoiceNumber.toLowerCase() : '';
    const pName = inv.partyName ? inv.partyName.toLowerCase() : '';
    const vNo = inv.vehicleNumber ? inv.vehicleNumber.toLowerCase() : '';
    return invNo.includes(term) || pName.includes(term) || vNo.includes(term);
  });

  if (!isAuthenticated) {
    return <Login onLogin={handleLogin} validUsers={validUsers} />;
  }

  const NavItem = ({ view, icon: Icon, label }: { view: ViewState; icon: any; label: string }) => (
    <button
      onClick={() => {
        setCurrentView(view);
        setEditingInvoice(null);
        setIsMobileMenuOpen(false);
      }}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium mb-1 ${
        currentView === view 
          ? 'bg-sky-100 text-sky-800 shadow-sm ring-1 ring-sky-200' 
          : 'text-slate-500 hover:bg-slate-50 hover:text-sky-600'
      }`}
    >
      <Icon size={18} strokeWidth={2} />
      <span>{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900">

      {showLogoutConfirm && (
        <div className="fixed inset-0 z-[1000] bg-black/50 flex items-center justify-center p-4 backdrop-blur-sm animate-in fade-in duration-200">
           <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-sm scale-100">
              <div className="flex items-center gap-3 mb-4 text-red-600">
                 <div className="p-3 bg-red-100 rounded-full"><LogOut size={24} /></div>
                 <h3 className="text-lg font-bold text-slate-800">Confirm Logout</h3>
              </div>
              <p className="text-slate-600 mb-6 text-sm font-medium">Are you sure you want to end your session?</p>
              <div className="flex justify-end gap-3">
                 <button onClick={() => setShowLogoutConfirm(false)} className="px-4 py-2 text-slate-600 font-bold hover:bg-slate-100 rounded-lg">Cancel</button>
                 <button onClick={confirmLogout} className="px-4 py-2 bg-red-600 text-white font-bold rounded-lg hover:bg-red-700">Yes, Logout</button>
              </div>
           </div>
        </div>
      )}

      {contextMenu.visible && (
        <div className="fixed z-[999] bg-white border border-slate-200 shadow-xl rounded-lg py-1 w-40 animate-in fade-in zoom-in-95 duration-100 origin-top-left"
          style={{ top: contextMenu.y, left: Math.min(contextMenu.x, window.innerWidth - 170) }}>
          <button onClick={() => { setViewInvoice(contextMenu.invoice); setContextMenu({ ...contextMenu, visible: false }); }} className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-sky-50 flex items-center gap-2">
            <Printer size={14} /> Print
          </button>
        </div>
      )}

      <div className="fixed bottom-6 right-6 z-50 animate-in slide-in-from-bottom-5">
        <div className="bg-white rounded-xl shadow-lg border border-slate-100 p-3 pr-4 flex items-center gap-3 min-w-[180px]">
          {syncStatus === 'syncing' || syncStatus === 'pulling' ? (
            <RefreshCw className="text-orange-500 animate-spin" size={20} />
          ) : (
            <CheckCircle className="text-emerald-500" size={20} />
          )}
          <div className="flex-1">
            <div className={`font-bold text-xs ${syncStatus === 'syncing' || syncStatus === 'pulling' ? 'text-orange-600' : 'text-slate-700'}`}>
              {syncStatus === 'syncing' ? 'Syncing...' : syncStatus === 'pulling' ? 'Updating...' : 'Connected'}
            </div>
          </div>
          <button onClick={() => handleCloudPull(true)} className="p-1.5 hover:bg-slate-50 rounded-full text-slate-400">
            <RefreshCw size={14} className={syncStatus === 'pulling' ? 'animate-spin' : ''} />
          </button>
        </div>
      </div>

      <div className="md:hidden fixed top-0 w-full bg-white z-50 border-b border-slate-200 px-4 py-3 flex justify-between items-center shadow-sm no-print">
        <div className="font-bold text-sky-700 text-lg flex items-center gap-2">
            <LayoutDashboard size={20} /> GREENZAR
        </div>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
          {isMobileMenuOpen ? <X /> : <Menu />}
        </button>
      </div>

      <div className={`fixed md:static inset-y-0 left-0 w-64 bg-white border-r border-slate-200 transform transition-transform duration-300 z-[60] shadow-xl md:shadow-none no-print flex flex-col ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0`}>
        <div className="p-6"><h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">GREENZAR</h1></div>
        <nav className="px-4 py-2 flex-1 overflow-y-auto">
          <NavItem view="billing" icon={FileText} label="Create Invoice" />
          <NavItem view="history" icon={History} label="History" />
          <NavItem view="logs" icon={ClipboardList} label="All Logs" />
          <NavItem view="statement" icon={ScrollText} label="Party Statement" />
          <NavItem view="ranking" icon={Trophy} label="Ranking" />
          <NavItem view="parties" icon={Users} label="Parties" />
          <NavItem view="products" icon={Package} label="Products" />
          <NavItem view="rates" icon={DollarSign} label="Price Lists" />
          <NavItem view="users" icon={UserIcon} label="Users" />
          <NavItem view="data" icon={Database} label="Data & Sync" />
        </nav>
        <div className="p-4 border-t border-slate-100">
           <button onClick={() => setShowLogoutConfirm(true)} className="w-full flex items-center justify-center gap-2 text-xs font-bold text-slate-500 hover:text-red-600 p-2 rounded-lg">
             <LogOut size={14} /> Logout
           </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col h-full overflow-hidden pt-14 md:pt-0 bg-slate-50/50">
        {currentView === 'billing' && <Billing parties={parties} setParties={setParties} products={products} specialRates={specialRates} setSpecialRates={setSpecialRates} onInvoiceSaved={() => { refreshInvoices(); setEditingInvoice(null); }} initialData={editingInvoice} />}
        {currentView === 'history' && (
          <div className="h-full overflow-y-auto p-8">
            <div className="max-w-7xl mx-auto">
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-slate-800">Invoice History (Last 50)</h2>
                <div className="relative w-64">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input type="text" placeholder="Search..." value={invoiceSearch} onChange={(e) => setInvoiceSearch(e.target.value)} className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-sky-500 outline-none" />
                </div>
              </div>
              <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                <table className="w-full text-left">
                  <thead className="bg-slate-50 border-b">
                    <tr className="text-xs font-bold text-slate-500 uppercase">
                      <th className="px-4 py-4">Invoice #</th>
                      <th className="px-4 py-4">Date</th>
                      <th className="px-4 py-4">Party</th>
                      <th className="px-4 py-4 text-center">Weight</th>
                      <th className="px-4 py-4 text-right">Total</th>
                      <th className="px-4 py-4 no-print"></th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {filteredInvoices.map(inv => (
                      <tr key={inv.id} className="hover:bg-sky-50 transition-colors">
                        <td className="px-4 py-4 font-mono text-xs font-bold">{inv.invoiceNumber}</td>
                        <td className="px-4 py-4 text-xs">{inv.date.split('-').reverse().join('-')}</td>
                        <td className="px-4 py-4 text-xs font-medium">{inv.partyName}</td>
                        <td className="px-4 py-4 text-center">
                           <span className="text-[10px] font-black text-sky-700 bg-sky-50 px-2 py-0.5 rounded">
                              {formatWeight(calculateInvWeight(inv))}
                           </span>
                        </td>
                        <td className="px-4 py-4 text-right text-sm font-bold">₹{(inv.grandTotal || 0).toLocaleString('en-IN')}</td>
                        <td className="px-4 py-4 text-right no-print">
                           <button onClick={() => handleEditInvoice(inv)} className="text-slate-400 hover:text-orange-600 p-2"><Edit3 size={16} /></button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}
        {currentView === 'parties' && <PartyManager parties={parties} setParties={setParties} />}
        {currentView === 'products' && <ProductManager products={products} setProducts={setProducts} />}
        {currentView === 'rates' && <RateManager parties={parties} products={products} specialRates={specialRates} setSpecialRates={setSpecialRates} />}
        {currentView === 'users' && <UserManager users={validUsers} setUsers={setValidUsers} />}
        {currentView === 'logs' && <InvoiceLogs invoices={invoices} parties={parties} />}
        {currentView === 'ranking' && <Ranking invoices={invoices} parties={parties} />}
        {currentView === 'statement' && <PartyStatement invoices={invoices} parties={parties} />}
        {currentView === 'data' && <DataManager parties={parties} products={products} invoices={invoices} specialRates={specialRates} refreshData={loadLocalData} onForcePush={() => handleCloudPull(true)} />}
      </div>
    </div>
  );
};

export default App;

