                        <td className="px-4 py-4 text-right text-sm font-bold">₹{(inv.grandTotal || 0).toLocaleString('en-IN')}</td>
                        <td className="px-4 py-4 text-right no-print">
                           <button onClick={() => handleEditInvoice(inv)} className="text-slate-400 hover:text-orange-600 p-2"><Edit3 size={16} /></button>
