Here is the SQL code you need to run in your Supabase SQL Editor to set up the database tables correctly for the Greenzar billing system. 

This schema matches the exact table names (`app_users`, `special_rates`, etc.) and columns used in the application.

```sql
-- 1. Parties Table
CREATE TABLE IF NOT EXISTS parties (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    code TEXT,
    address TEXT,
    city TEXT,
    phone TEXT,
    "gstNumber" TEXT,
    "aadharNumber" TEXT,
    "panNumber" TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 2. Products Table
CREATE TABLE IF NOT EXISTS products (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    code TEXT,
    "standardRate" NUMERIC DEFAULT 0,
    unit TEXT DEFAULT 'pcs',
    hsn TEXT,
    "gstPercent" NUMERIC DEFAULT 0,
    "qtyPerCase" NUMERIC DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 3. Special Rates Table (Party-specific pricing)
CREATE TABLE IF NOT EXISTS special_rates (
    "partyId" UUID REFERENCES parties(id) ON DELETE CASCADE,
    "productId" UUID REFERENCES products(id) ON DELETE CASCADE,
    rate NUMERIC NOT NULL,
    PRIMARY KEY ("partyId", "productId")
);

-- 4. Invoices Table
CREATE TABLE IF NOT EXISTS invoices (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "invoiceNumber" TEXT NOT NULL,
    "partyId" UUID,
    "partyName" TEXT,
    date DATE NOT NULL,
    items JSONB NOT NULL DEFAULT '[]'::jsonb,
    "subTotal" NUMERIC DEFAULT 0,
    "taxAmount" NUMERIC DEFAULT 0,
    "globalDiscount" NUMERIC DEFAULT 0,
    "grandTotal" NUMERIC DEFAULT 0,
    "vehicleNumber" TEXT,
    "poNumber" TEXT,
    "partyAddress" TEXT,
    "partyGst" TEXT,
    "partyPan" TEXT,
    "partyAadhar" TEXT,
    "partyPhone" TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 5. Users Table
CREATE TABLE IF NOT EXISTS app_users (
    username TEXT PRIMARY KEY,
    password TEXT NOT NULL,
    role TEXT DEFAULT 'user',
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 6. Insert Default Admin User
INSERT INTO app_users (username, password, role) 
VALUES ('riyaz', '6211', 'admin')
ON CONFLICT (username) DO NOTHING;

-- Enable Row Level Security (RLS) - Optional but recommended
-- For development, you can disable RLS or add broad policies
ALTER TABLE parties ENABLE ROW LEVEL SECURITY;
ALTER TABLE products ENABLE ROW LEVEL SECURITY;
ALTER TABLE special_rates ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE app_users ENABLE ROW LEVEL SECURITY;

-- Create broad access policies for the 'anon' role used in the app
CREATE POLICY "Allow anon select" ON parties FOR SELECT USING (true);
CREATE POLICY "Allow anon insert" ON parties FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow anon update" ON parties FOR UPDATE USING (true);

CREATE POLICY "Allow anon select" ON products FOR SELECT USING (true);
CREATE POLICY "Allow anon insert" ON products FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow anon update" ON products FOR UPDATE USING (true);

CREATE POLICY "Allow anon select" ON special_rates FOR SELECT USING (true);
CREATE POLICY "Allow anon insert" ON special_rates FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow anon delete" ON special_rates FOR DELETE USING (true);

CREATE POLICY "Allow anon select" ON invoices FOR SELECT USING (true);
CREATE POLICY "Allow anon insert" ON invoices FOR INSERT WITH CHECK (true);

CREATE POLICY "Allow anon select" ON app_users FOR SELECT USING (true);
CREATE POLICY "Allow anon insert" ON app_users FOR INSERT WITH CHECK (true);
```

### Steps to set this up:
1. Go to your **Supabase Dashboard**.
2. Click on **SQL Editor** in the left sidebar.
3. Click **New Query**.
4. Paste the code above into the editor.
5. Click **Run**.

Once you run this, your "Connected" status in the app will turn green, and you'll be able to save parties, products, and invoices directly to your cloud database.

