import { supabase } from './supabase';

export const Cloud = {
  getScriptUrl: () => 'SUPABASE_ENABLED', 

  clearAllData: async () => {
    console.warn("Wipe command blocked by security policy.");
    return true;
  },

  // --- SYNC METHODS (UPSERT) ---
  syncInvoice: async (invoice: Invoice) => {
    const { error } = await supabase
      .from('invoices')
      .upsert({
        id: invoice.id,
        invoiceNumber: invoice.invoiceNumber,
        partyId: invoice.partyId,
        partyName: invoice.partyName,
        date: invoice.date,
        items: invoice.items, // jsonb in SQL
        subTotal: invoice.subTotal,
        taxAmount: invoice.taxAmount,
        globalDiscount: invoice.globalDiscount,
        grandTotal: invoice.grandTotal,
        vehicleNumber: invoice.vehicleNumber,
        poNumber: invoice.poNumber,
        partyAddress: invoice.partyAddress,
        partyGst: invoice.partyGst,
        partyPan: invoice.partyPan,
        partyAadhar: invoice.partyAadhar,
        partyPhone: invoice.partyPhone
      });

    if (error) {
      console.error('Error syncing invoice:', error);
      return { success: false, error: error.message };
    }
    return { success: true };
  },

  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
    try {
      if (parties.length > 0) {
        await supabase.from('parties').upsert(parties);
      }

      if (products.length > 0) {
        const productsToSync = products.map(p => ({
            id: p.id,
            name: p.name,
            code: p.code,
            standardRate: p.standardRate,
            unit: p.unit,
            hsn: p.hsn,
            gstPercent: p.gstPercent,
            qtyPerCase: p.qtyPerCase
        }));
        await supabase.from('products').upsert(productsToSync);
      }

      if (users.length > 0) {
        await supabase.from('app_users').upsert(users);
      }

      if (rates.length >= 0) {
        // Quoted identifiers for case-sensitive columns from SQL schema
        const { error: deleteError } = await supabase.from('special_rates').delete().neq('rate', -1);
        if (!deleteError && rates.length > 0) {
            const ratesToSync = rates.map(r => ({
                partyId: r.partyId,
                productId: r.productId,
                rate: r.rate
            }));
            await supabase.from('special_rates').insert(ratesToSync);
        }
      }
      return { success: true };
    } catch (e: any) {
      console.error("Master Sync Error", e);
      return { success: false, error: e.message };
    }
  },

  // --- OPTIMIZED FETCH METHODS ---
  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES' | 'INVOICES' | 'USERS'): Promise<any[]> => {
    try {
      const tableMap: Record<string, { table: string, cols: string }> = {
        'PARTIES': { table: 'parties', cols: 'id, name, code, address, city, phone, gstNumber, aadharNumber, panNumber, email' },
        'PRODUCTS': { table: 'products', cols: 'id, name, code, "standardRate", unit, hsn, "gstPercent", "qtyPerCase"' },
        'RATES': { table: 'special_rates', cols: '"partyId", "productId", rate' },
        'INVOICES': { table: 'invoices', cols: 'id, "invoiceNumber", "partyId", "partyName", date, items, "subTotal", "taxAmount", "globalDiscount", "grandTotal", "vehicleNumber", "poNumber", "partyAddress", "partyGst", "partyPan", "partyAadhar", "partyPhone", created_at' },
        'USERS': { table: 'app_users', cols: 'username, password, role' }
      };

      const config = tableMap[type];
      if (!config) return [];

      let query = supabase.from(config.table).select(config.cols);

      if (type === 'PARTIES' || type === 'PRODUCTS') {
        query = query.order('name', { ascending: true });
      } else if (type === 'INVOICES') {
        query = query.order('created_at', { ascending: false }).limit(50);
      }

      const { data, error } = await query;
      if (error) throw error;

      if (type === 'INVOICES') {
        return (data as any[] || []).map((inv: any) => ({
          ...inv,
          items: typeof inv.items === 'string' ? JSON.parse(inv.items) : (inv.items || []),
          subTotal: Number(inv.subTotal) || 0,
          taxAmount: Number(inv.taxAmount) || 0,
          globalDiscount: Number(inv.globalDiscount) || 0,
          grandTotal: Number(inv.grandTotal) || 0
        }));
      }

      if (type === 'RATES') {
          return (data as any[] || []).map(r => ({ 
              partyId: r.partyId, 
              productId: r.productId, 
              rate: Number(r.rate) 
          }));
      }

      if (type === 'PRODUCTS') {
          return (data as any[] || []).map(p => ({ 
              ...p, 
              standardRate: Number(p.standardRate),
              gstPercent: Number(p.gstPercent || 0),
              qtyPerCase: Number(p.qtyPerCase || 1)
          }));
      }

      return data || [];
    } catch (e) {
      console.error(`Fetch error for ${type}:`, e);
      return [];
    }
  },

  fetchUsers: async (): Promise<User[]> => {
    return Cloud.fetchData('USERS');
  },

  fetchInvoices: async (): Promise<Invoice[]> => {
    return Cloud.fetchData('INVOICES');
  },

  testConnection: async () => {
    try {
      const { error } = await supabase.from('parties').select('id').limit(1);
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (e: any) {
      return { success: false, error: e.message || "Unknown Connection Error" };
    }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Party, Product, SpecialRate, Invoice, InvoiceItem } from '../types';
import { ShoppingCart, User, Plus, Trash2, Save, Scan, Zap, FileText, CloudLightning, Loader2, Printer, X, CreditCard, Box, MapPin, Phone, Calculator, ChevronDown, ChevronUp, Edit3, Copy, Download, FileSpreadsheet, Search, Tag, Sparkles, Info, ArrowUpCircle } from 'lucide-react';
import { Store } from '../services/store';
import { Cloud } from '../services/cloud';
import { InvoiceTemplate } from './InvoiceTemplate';

interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (rates: SpecialRate[]) => void; 
  onInvoiceSaved: () => void;
  initialData?: Invoice | null; 
}

const getTodayString = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

export const Billing: React.FC<Props> = ({ parties, setParties, products, specialRates, setSpecialRates, onInvoiceSaved, initialData }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string>('');
  const [items, setItems] = useState<InvoiceItem[]>([]);
  const [invoiceDate, setInvoiceDate] = useState(getTodayString());
  const [customInvoiceNo, setCustomInvoiceNo] = useState('');
  const [globalDiscount, setGlobalDiscount] = useState<number>(0);
  const [isSaving, setIsSaving] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [lastInvoice, setLastInvoice] = useState<Invoice | null>(null);

  const [partySearch, setPartySearch] = useState('');
  const [showPartySuggestions, setShowPartySuggestions] = useState(false);
  const [productSearch, setProductSearch] = useState(''); 
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);

  const [currentProductId, setCurrentProductId] = useState('');
  const [currentQty, setCurrentQty] = useState(0);
  const [currentRate, setCurrentRate] = useState(0);
  const [rateType, setRateType] = useState<'standard' | 'special' | 'manual'>('standard');
  const [vehicleNo, setVehicleNo] = useState('');

  const partyInputRef = useRef<HTMLInputElement>(null);
  const productInputRef = useRef<HTMLInputElement>(null);
  const qtyInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (initialData) {
      setSelectedPartyId(initialData.partyId);
      const p = parties.find(party => party.id === initialData.partyId);
      setPartySearch(p?.name || initialData.partyName);
      setItems(initialData.items);
      setInvoiceDate(initialData.date);
      setCustomInvoiceNo(initialData.invoiceNumber);
      setVehicleNo(initialData.vehicleNumber || '');
      setGlobalDiscount(initialData.globalDiscount || 0);
    }
  }, [initialData, parties]);

  // Pricing Engine: Triggered when product or party changes
  useEffect(() => {
    if (currentProductId) {
      const product = products.find(p => p.id === currentProductId);
      if (product) {
        // Find if this specific party has a special rate for this product
        const special = specialRates.find(r => r.partyId === selectedPartyId && r.productId === currentProductId);
        if (special) {
          setCurrentRate(special.rate);
          setRateType('special');
        } else {
          setCurrentRate(product.standardRate || 0);
          setRateType('standard');
        }
      }
    }
  }, [currentProductId, selectedPartyId, products, specialRates]);

  const addItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentProductId || currentQty <= 0) return;
    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    const gstPercent = product.gstPercent || 0;
    const inclusiveRate = currentRate;
    const baseRate = inclusiveRate / (1 + (gstPercent / 100));

    const newItem: InvoiceItem = {
      id: crypto.randomUUID(),
      productId: product.id,
      productName: product.name,
      quantity: currentQty,
      rate: inclusiveRate,
      baseRate: baseRate,
      total: currentQty * inclusiveRate,
      hsn: product.hsn,
      gstPercent: gstPercent
    };

    setItems([...items, newItem]);
    setProductSearch('');
    setCurrentProductId('');
    setCurrentQty(0);
    setCurrentRate(0);
    productInputRef.current?.focus();
  };

  const handleSaveInvoice = async () => {
    if (!selectedPartyId || items.length === 0) return;
    setIsSaving(true);
    const party = parties.find(p => p.id === selectedPartyId);
    const subTotal = items.reduce((sum, item) => sum + item.total, 0);

    const newInvoice: Invoice = {
      id: initialData ? initialData.id : crypto.randomUUID(),
      invoiceNumber: customInvoiceNo,
      partyId: selectedPartyId,
      partyName: party?.name || 'Unknown',
      date: invoiceDate,
      items: items,
      subTotal: subTotal,
      taxPercent: 0,
      taxAmount: 0, 
      globalDiscount: globalDiscount,
      grandTotal: Math.round(subTotal - globalDiscount),
      vehicleNumber: vehicleNo,
      partyAddress: party?.address || '',
      partyGst: party?.gstNumber || '',
      partyPhone: party?.phone || ''
    };

    if (initialData) Store.updateInvoice(newInvoice);
    else Store.saveInvoice(newInvoice);

    setLastInvoice(newInvoice);
    setIsPreviewOpen(true);
    onInvoiceSaved();
    setIsSaving(false);
  };

  const filteredParties = parties.filter(p => p.name.toLowerCase().includes(partySearch.toLowerCase()));
  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(productSearch.toLowerCase()));

  return (
    <div className="flex flex-col h-full bg-slate-50 overflow-hidden">
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        <div className="bg-white p-4 rounded-xl border shadow-sm">
          <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Customer Selection</label>
          <div className="relative">
            <input 
              ref={partyInputRef} 
              type="text" 
              value={partySearch} 
              onChange={e => { setPartySearch(e.target.value); setShowPartySuggestions(true); }} 
              onFocus={() => setShowPartySuggestions(true)}
              placeholder="Search party..." 
              className="w-full px-3 py-2 border rounded-lg font-bold" 
            />
            {showPartySuggestions && filteredParties.length > 0 && (
              <div className="absolute z-50 w-full bg-white border rounded-lg shadow-xl mt-1 max-h-40 overflow-y-auto">
                {filteredParties.map(p => (
                  <div key={p.id} onClick={() => { setSelectedPartyId(p.id); setPartySearch(p.name); setShowPartySuggestions(false); }} className="px-4 py-2 hover:bg-sky-50 cursor-pointer font-bold">
                    {p.name} <span className="text-[10px] text-slate-400 ml-2">{p.code}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="bg-white p-4 rounded-xl border shadow-sm grid grid-cols-2 gap-4">
           <div>
             <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Date</label>
             <input type="date" value={invoiceDate} onChange={e => setInvoiceDate(e.target.value)} className="w-full border rounded-lg px-3 py-2 font-bold" />
           </div>
           <div>
             <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Invoice #</label>
             <input type="text" value={customInvoiceNo} onChange={e => setCustomInvoiceNo(e.target.value)} className="w-full border rounded-lg px-3 py-2 font-bold" />
           </div>
        </div>

        <div className="bg-sky-50 p-4 rounded-xl border border-sky-100 space-y-3">
           <div className="relative">
             <label className="text-[10px] font-bold text-sky-600 uppercase mb-1 block">Add Product</label>
             <input 
              ref={productInputRef} 
              type="text" 
              value={productSearch} 
              onChange={e => { setProductSearch(e.target.value); setShowProductSuggestions(true); }} 
              onFocus={() => setShowProductSuggestions(true)}
              placeholder="Search product..." 
              className="w-full border rounded-lg px-3 py-2 font-bold" 
             />
             {showProductSuggestions && filteredProducts.length > 0 && (
               <div className="absolute z-50 w-full bg-white border rounded-lg shadow-xl mt-1 max-h-40 overflow-y-auto">
                 {filteredProducts.map(p => (
                   <div key={p.id} onClick={() => { setProductSearch(p.name); setCurrentProductId(p.id); setShowProductSuggestions(false); qtyInputRef.current?.focus(); }} className="px-4 py-2 hover:bg-sky-50 cursor-pointer font-bold">
                     {p.name}
                   </div>
                 ))}
               </div>
             )}
           </div>
           <div className="flex gap-4">
             <div className="flex-1">
               <label className="text-[10px] font-bold text-sky-600 uppercase mb-1 block">Qty</label>
               <input ref={qtyInputRef} type="number" value={currentQty || ''} onChange={e => setCurrentQty(parseFloat(e.target.value) || 0)} className="w-full border rounded-lg px-3 py-2 font-bold" />
             </div>
             <div className="flex-1">
               <label className="text-[10px] font-bold text-sky-600 uppercase mb-1 block">Rate {rateType === 'special' && '⭐'}</label>
               <input type="number" value={currentRate} onChange={e => { setCurrentRate(parseFloat(e.target.value) || 0); setRateType('manual'); }} className={`w-full border rounded-lg px-3 py-2 font-bold ${rateType === 'special' ? 'bg-amber-50 border-amber-300 text-amber-900' : ''}`} />
             </div>
             <button onClick={addItem} className="bg-sky-600 text-white px-4 mt-5 rounded-lg font-bold hover:bg-sky-700 transition-colors"><Plus /></button>
           </div>
        </div>

        <div className="bg-white rounded-xl border shadow-sm overflow-hidden overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b">
              <tr className="text-[10px] font-bold text-slate-400 uppercase">
                <th className="px-4 py-2">Item</th>
                <th className="px-4 py-2 text-center">Qty</th>
                <th className="px-4 py-2 text-right">Rate</th>
                <th className="px-4 py-2 text-right">Total</th>
                <th className="px-4 py-2"></th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {items.map(item => (
                <tr key={item.id}>
                  <td className="px-4 py-2 font-bold text-slate-800">{item.productName}</td>
                  <td className="px-4 py-2 text-center font-bold">{item.quantity}</td>
                  <td className="px-4 py-2 text-right font-bold">₹{item.rate.toFixed(2)}</td>
                  <td className="px-4 py-2 text-right font-bold text-sky-700">₹{item.total.toFixed(2)}</td>
                  <td className="px-4 py-2 text-center">
                    <button onClick={() => setItems(items.filter(i => i.id !== item.id))} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="bg-white border-t p-4 flex justify-between items-center shadow-2xl">
        <div className="text-right flex-1 pr-4">
          <div className="text-[10px] font-bold text-slate-400 uppercase">Grand Total</div>
          <div className="text-2xl font-black text-slate-900">₹{items.reduce((sum, item) => sum + item.total, 0).toFixed(2)}</div>
        </div>
        <button 
          onClick={handleSaveInvoice} 
          disabled={!selectedPartyId || items.length === 0 || isSaving}
          className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:scale-105 transition-all disabled:opacity-50"
        >
          {isSaving ? <Loader2 className="animate-spin" /> : <Save />}
          Save Invoice
        </button>
      </div>

      {isPreviewOpen && lastInvoice && (
        <div className="fixed inset-0 z-50 bg-black/50 flex flex-col p-4 overflow-y-auto no-print">
            <div className="flex justify-end mb-4"><button onClick={() => setIsPreviewOpen(false)} className="bg-white p-2 rounded-full"><X /></button></div>
            <div className="bg-white mx-auto shadow-2xl"><InvoiceTemplate invoice={lastInvoice} parties={parties} /></div>
        </div>
      )}
    </div>
  );
};

