interface Props {
  parties: Party[];
  setParties: (p: Party[]) => void;
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (rates: SpecialRate[]) => void; 
  onInvoiceSaved: () => void;
  initialData?: Invoice | null; 
}

const VEHICLE_OPTIONS = [
  "WB894170", "WB25K1322", "WB25K2982", "WB25L6365", 
  "WB25K1326", "WB25K1341", "WB47J7275", "WB35H3960"
];

const getTodayString = () => {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

export const Billing: React.FC<Props> = ({ parties, setParties, products, specialRates, setSpecialRates, onInvoiceSaved, initialData }) => {
  const [selectedPartyId, setSelectedPartyId] = useState<string>('');
  const [items, setItems] = useState<InvoiceItem[]>([]);
  const [invoiceDate, setInvoiceDate] = useState(getTodayString());
  const [customInvoiceNo, setCustomInvoiceNo] = useState('');
  const [refNo, setRefNo] = useState(''); 
  const [globalDiscount, setGlobalDiscount] = useState<number>(0);
  const [isSaving, setIsSaving] = useState(false);
  const [isPartyModalOpen, setIsPartyModalOpen] = useState(false);
  const [isPreviewOpen, setIsPreviewOpen] = useState(false);
  const [lastInvoice, setLastInvoice] = useState<Invoice | null>(null);
  const [newPartyName, setNewPartyName] = useState('');
  const [newPartyPhone, setNewPartyPhone] = useState(''); 
  const [showActiveRates, setShowActiveRates] = useState(false);
  const [partySearch, setPartySearch] = useState('');
  const [showPartySuggestions, setShowPartySuggestions] = useState(false);
  const [partyHighlightIndex, setPartyHighlightIndex] = useState(0);
  const [vehicleNo, setVehicleNo] = useState('');
  const [showVehicleSuggestions, setShowVehicleSuggestions] = useState(false);
  const [vehicleHighlightIndex, setVehicleHighlightIndex] = useState(0);
  const [currentProductId, setCurrentProductId] = useState('');
  const [productSearch, setProductSearch] = useState(''); 
  const [showProductSuggestions, setShowProductSuggestions] = useState(false);
  const [productHighlightIndex, setProductHighlightIndex] = useState(0);
  const [currentQty, setCurrentQty] = useState(0);
  const [currentRate, setCurrentRate] = useState(0); 
  const [stdRate, setStdRate] = useState(0);
  const [rateType, setRateType] = useState<'standard' | 'special' | 'manual'>('standard');

  const partyInputRef = useRef<HTMLInputElement>(null);
  const invoiceNoInputRef = useRef<HTMLInputElement>(null);
  const vehicleInputRef = useRef<HTMLInputElement>(null);
  const productInputRef = useRef<HTMLInputElement>(null);
  const qtyInputRef = useRef<HTMLInputElement>(null);
  const addBtnRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (isPreviewOpen && lastInvoice) {
      const timer = setTimeout(() => {
        window.print();
      }, 1500); 
      return () => clearTimeout(timer);
    }
  }, [isPreviewOpen, lastInvoice]);

  useEffect(() => {
    if (initialData) {
      setSelectedPartyId(initialData.partyId);
      const p = parties.find(party => party.id === initialData.partyId);
      setPartySearch(p ? p.name : initialData.partyName);
      setItems(initialData.items || []);
      setInvoiceDate(initialData.date);
      setCustomInvoiceNo(initialData.invoiceNumber);
      setVehicleNo(initialData.vehicleNumber || '');
      setRefNo(initialData.poNumber || '');
      setGlobalDiscount(initialData.globalDiscount || 0);
    }
  }, [initialData, parties]);

  useEffect(() => {
    const totalQty = items.reduce((sum, item) => sum + item.quantity, 0);
    setRefNo(totalQty > 0 ? totalQty.toString() : '');
  }, [items]);

  // --- PRICING ENGINE ---
  useEffect(() => {
    if (!currentProductId) {
      setStdRate(0);
      setCurrentRate(0);
      setRateType('standard');
      return;
    }

    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    const standard = product.standardRate || 0;
    setStdRate(standard);

    // Prioritize special rate for the selected party
    if (selectedPartyId) {
      const special = specialRates.find(r => r.partyId === selectedPartyId && r.productId === currentProductId);
      if (special && special.rate > 0) {
        setCurrentRate(special.rate);
        setRateType('special');
        return;
      }
    }

    setCurrentRate(standard);
    setRateType('standard');
  }, [currentProductId, selectedPartyId, products, specialRates]);

  const filteredParties = parties.filter(p => 
      p.name.toLowerCase().includes(partySearch.toLowerCase()) ||
      (p.code && p.code.toLowerCase().includes(partySearch.toLowerCase()))
  );

  const filteredVehicles = VEHICLE_OPTIONS.filter(v => 
    v.toLowerCase().includes(vehicleNo.toLowerCase())
  );

  const filteredProducts = products.filter(p => {
      const term = productSearch.toLowerCase();
      return p.name.toLowerCase().includes(term) || p.code.toLowerCase().includes(term);
  }).sort((a, b) => {
    if (!selectedPartyId) return 0;
    const hasA = specialRates.some(r => r.partyId === selectedPartyId && r.productId === a.id);
    const hasB = specialRates.some(r => r.partyId === selectedPartyId && r.productId === b.id);
    return hasA && !hasB ? -1 : !hasA && hasB ? 1 : 0;
  });

  const selectParty = (p: Party) => {
      setSelectedPartyId(p.id);
      setPartySearch(p.name);
      setShowPartySuggestions(false);
      invoiceNoInputRef.current?.focus();
  };

  const selectProduct = (p: Product) => {
    setProductSearch(p.name);
    setCurrentProductId(p.id);
    setShowProductSuggestions(false);
    setTimeout(() => qtyInputRef.current?.focus(), 50);
  };

  const addItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentProductId || currentQty <= 0) return;
    const product = products.find(p => p.id === currentProductId);
    if (!product) return;

    const gstPercent = product.gstPercent || 0;
    const inclusiveRate = currentRate;
    const baseRate = inclusiveRate / (1 + (gstPercent / 100));
    const grossTotal = currentQty * inclusiveRate; 

    const newItem: InvoiceItem = {
      id: crypto.randomUUID(),
      productId: product.id,
      productName: product.name,
      quantity: currentQty,
      rate: inclusiveRate,
      baseRate: baseRate,  
      total: grossTotal,   
      hsn: product.hsn,
      gstPercent: gstPercent
    };

    setItems([...items, newItem]);
    setProductSearch('');
    setCurrentProductId('');
    setCurrentQty(0);
    productInputRef.current?.focus();
  };

  const removeItem = (id: string) => setItems(items.filter(item => item.id !== id));

  const handleSaveInvoice = async () => {
    if (!selectedPartyId || items.length === 0) return;
    setIsSaving(true);

    const party = parties.find(p => p.id === selectedPartyId);
    const subTotal = items.reduce((sum, item) => sum + item.total, 0);
    const taxAmount = items.reduce((sum, item) => sum + (item.total - (item.total / (1 + (item.gstPercent || 0)/100))), 0);
    const grandTotal = Math.round(subTotal - globalDiscount);

    const newInvoice: Invoice = {
      id: initialData ? initialData.id : crypto.randomUUID(), 
      invoiceNumber: customInvoiceNo,
      partyId: selectedPartyId,
      partyName: party?.name || 'Unknown Party',
      date: invoiceDate,
      items: items,
      subTotal: subTotal,
      taxPercent: 0,
      taxAmount: taxAmount,
      globalDiscount: globalDiscount,
      grandTotal: grandTotal,
      vehicleNumber: vehicleNo,
      poNumber: refNo,
      partyAddress: party ? `${party.address}, ${party.city}` : '',
      partyGst: party?.gstNumber || '',
      partyPhone: party?.phone || ''
    };

    try {
        if (initialData) Store.updateInvoice(newInvoice);
        else Store.saveInvoice(newInvoice);

        await Cloud.syncInvoice(newInvoice);
        setLastInvoice(newInvoice);
        setIsPreviewOpen(true);
        onInvoiceSaved();
        setItems([]);
    } catch (error) {
        console.error("Save failed", error);
    } finally {
        setIsSaving(false);
    }
  };

  return (
    <div className="flex h-full flex-col md:flex-row bg-slate-50">
      <div className="flex-1 flex flex-col h-full overflow-hidden border-r border-slate-200">
        <div className="px-6 py-4 bg-white border-b border-slate-200 flex justify-between items-center shadow-sm">
           <div>
             <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
               <FileText size={20} className="text-sky-600" /> {initialData ? 'Edit Invoice' : 'New Invoice'}
             </h2>
             <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">{invoiceDate}</div>
           </div>
           <button 
             onClick={handleSaveInvoice}
             disabled={isSaving || !selectedPartyId || items.length === 0}
             className="bg-slate-900 hover:bg-slate-800 disabled:opacity-50 text-white px-6 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-lg transition-all"
           >
             {isSaving ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
             <span>Save Invoice</span>
           </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6">
           <div className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2 block">Customer Selection</label>
              <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    ref={partyInputRef}
                    type="text" 
                    value={partySearch}
                    onChange={(e) => { setPartySearch(e.target.value); setSelectedPartyId(''); setShowPartySuggestions(true); }}
                    onFocus={() => setShowPartySuggestions(true)}
                    placeholder="Search customer name or code..."
                    className="w-full pl-10 pr-4 py-3 border border-slate-300 rounded-xl focus:ring-2 focus:ring-sky-500 outline-none text-sm font-bold bg-slate-50"
                  />
                  {showPartySuggestions && filteredParties.length > 0 && (
                    <div className="absolute z-20 w-full mt-1 bg-white border border-slate-200 rounded-xl shadow-xl max-h-60 overflow-y-auto">
                        {filteredParties.map((p, idx) => (
                          <div key={p.id} className="px-4 py-3 text-sm cursor-pointer hover:bg-sky-50 border-b border-slate-50 last:border-0" onMouseDown={() => selectParty(p)}>
                            <div className="font-bold text-slate-800">{p.name} <span className="text-xs text-slate-400 ml-2">{p.code}</span></div>
                            <div className="text-[10px] text-slate-400 uppercase font-bold">{p.city}</div>
                          </div>
                        ))}
                    </div>
                  )}
              </div>
           </div>

           <div className={`p-5 rounded-2xl border transition-all ${rateType === 'special' ? 'bg-emerald-50 border-emerald-200' : 'bg-white border-slate-200 shadow-sm'}`}>
               <div className="flex justify-between items-center mb-4">
                 <label className={`text-[10px] font-bold uppercase ${rateType === 'special' ? 'text-emerald-700' : 'text-slate-400'}`}>Items & Pricing</label>
