import { Invoice, Party, Product, SpecialRate, User } from '../types';
import { supabase } from './supabase';

export const Cloud = {
  getScriptUrl: () => 'SUPABASE_ENABLED', 

  clearAllData: async () => {
    console.warn("Wipe command blocked by security policy.");
    return true;
  },

  // --- SYNC METHODS ---
  syncInvoice: async (invoice: Invoice) => {
    try {
      const { error } = await supabase
        .from('invoices')
        .upsert({
          id: invoice.id,
          invoiceNumber: invoice.invoiceNumber,
          partyId: invoice.partyId,
          partyName: invoice.partyName,
          date: invoice.date,
          items: invoice.items, 
          subTotal: invoice.subTotal,
          taxAmount: invoice.taxAmount,
          globalDiscount: invoice.globalDiscount,
          grandTotal: invoice.grandTotal,
          vehicleNumber: invoice.vehicleNumber,
          poNumber: invoice.poNumber,
          partyAddress: invoice.partyAddress,
          partyGst: invoice.partyGst,
          partyPan: invoice.partyPan,
          partyAadhar: invoice.partyAadhar,
          partyPhone: invoice.partyPhone
        });

      if (error) throw error;
      return { success: true };
    } catch (e: any) {
      console.error('Invoice sync error:', e);
      return { success: false, error: e.message };
    }
  },

  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
    try {
      // 1. Sync Parties
      if (parties.length > 0) {
        const { error: pError } = await supabase.from('parties').upsert(parties);
        if (pError) {
            console.error("Party Sync Error:", pError);
            throw new Error(`Parties: ${pError.message}`);
        }
      }

      // 2. Sync Products
      if (products.length > 0) {
        const { error: prodError } = await supabase.from('products').upsert(products);
        if (prodError) {
            console.error("Product Sync Error:", prodError);
            throw new Error(`Products: ${prodError.message}`);
        }
      }

      // 3. Sync Users
      if (users.length > 0) {
        const { error: uError } = await supabase.from('app_users').upsert(users);
        if (uError) throw uError;
      }

      // 4. Sync Rates (Pricing for different persons)
      if (rates.length >= 0) {
        // Clear old rates to ensure clean pricing update
        await supabase.from('special_rates').delete().neq('rate', -1);

        if (rates.length > 0) {
            const formattedRates = rates.map(r => ({
                partyId: r.partyId,
                productId: r.productId,
                rate: r.rate
            }));
            const { error: rateError } = await supabase.from('special_rates').insert(formattedRates);
            if (rateError) {
                console.error("Rate Sync Error:", rateError);
                throw new Error(`Special Rates: ${rateError.message}`);
            }
        }
      }
      return { success: true };
    } catch (e: any) {
      console.error("Master Sync Exception:", e);
      return { success: false, error: e.message };
    }
  },

  // --- FETCH METHODS ---
  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES' | 'INVOICES' | 'USERS'): Promise<any[]> => {
    try {
      const tableMap: Record<string, string> = {
        'PARTIES': 'parties',
        'PRODUCTS': 'products',
        'RATES': 'special_rates',
        'INVOICES': 'invoices',
        'USERS': 'app_users'
      };

      const table = tableMap[type];
      if (!table) return [];

      let query = supabase.from(table).select('*');

      if (type === 'PARTIES' || type === 'PRODUCTS') {
        query = query.order('name', { ascending: true });
      } else if (type === 'INVOICES') {
        query = query.order('created_at', { ascending: false }).limit(100);
      }

      const { data, error } = await query;
      if (error) throw error;

      return data || [];
    } catch (e: any) {
      console.error(`Fetch error for ${type}:`, e);
      return [];
    }
  },

  fetchUsers: async (): Promise<User[]> => Cloud.fetchData('USERS'),

  fetchInvoices: async (): Promise<Invoice[]> => {
      const data = await Cloud.fetchData('INVOICES');
      return data.map(inv => ({
          ...inv,
          items: typeof inv.items === 'string' ? JSON.parse(inv.items) : (inv.items || []),
          subTotal: Number(inv.subTotal) || 0,
          taxAmount: Number(inv.taxAmount) || 0,
          globalDiscount: Number(inv.globalDiscount) || 0,
          grandTotal: Number(inv.grandTotal) || 0
      }));
  },

  testConnection: async () => {
    try {
      // Test if table exists by selecting one item
      const { error } = await supabase.from('products').select('id').limit(1);
      if (error) {
          console.error("Connection test failed:", error);
          return { success: false, error: error.message };
      }
      return { success: true };
    } catch (e: any) {
      return { success: false, error: e.message || "Connection failed" };
    }
  }
};

import React, { useState, useEffect } from 'react';
import { Party, Product, SpecialRate, Invoice } from '../types';
import { Database, AlertTriangle, CheckCircle, CloudLightning, ArrowUpCircle, RefreshCw, XCircle, Info, Server, ShieldCheck, Loader2 } from 'lucide-react';
import { Cloud } from '../services/cloud';

interface Props {
  parties: Party[];
  products: Product[];
  specialRates: SpecialRate[];
  invoices: Invoice[];
  refreshData: () => void;
  onUrlChange?: (url: string) => void;
  onForcePush?: () => void;
}

export const DataManager: React.FC<Props> = ({ parties, products, onForcePush }) => {
  const [connectionStatus, setConnectionStatus] = useState<'checking' | 'connected' | 'error'>('checking');
  const [connectionError, setConnectionError] = useState('');
  const [isPushing, setIsPushing] = useState(false);
  const [pushStatus, setPushStatus] = useState<{msg: string, type: 'success' | 'error' | 'idle'}>({msg: '', type: 'idle'});

  useEffect(() => {
    checkSupabaseConnection();
  }, []);

  const checkSupabaseConnection = async () => {
    setConnectionStatus('checking');
    const result = await Cloud.testConnection();
    if (result.success) {
      setConnectionStatus('connected');
      setConnectionError('');
    } else {
      setConnectionStatus('error');
      setConnectionError(result.error || 'Unknown Connection Error');
    }
  };

  const handlePush = async () => {
    if (!onForcePush) return;
    setIsPushing(true);
    setPushStatus({msg: 'Uploading items to new database...', type: 'idle'});

    try {
        // We use the sync logic inside cloud.syncMasterData directly here for more control
        const result = await Cloud.syncMasterData(parties, products, [], []);
        if (result.success) {
            setPushStatus({msg: 'Success! All items added to your new database.', type: 'success'});
        } else {
            setPushStatus({msg: `Upload Failed: ${result.error}`, type: 'error'});
        }
    } catch (e: any) {
        setPushStatus({msg: `Error: ${e.message}`, type: 'error'});
    } finally {
        setIsPushing(false);
    }
  };

  return (
    <div className="p-6 max-w-4xl mx-auto pb-20">
      <div className="mb-8 border-b border-slate-200 pb-6">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <Database className="text-sky-600" /> Data Management
        </h2>
        <p className="text-slate-500">
          Sync your local items with the new Supabase database.
        </p>
      </div>

      <div className="bg-white border border-slate-200 shadow-xl rounded-2xl p-6 mb-8">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <CloudLightning className="text-sky-500" /> Database Connection
            </h3>
            <button 
                onClick={checkSupabaseConnection} 
                className="text-xs font-bold text-sky-600 hover:text-sky-800 flex items-center gap-1 bg-sky-50 px-3 py-1.5 rounded-lg transition-colors"
            >
                <RefreshCw size={12} className={connectionStatus === 'checking' ? 'animate-spin' : ''} />
                Test Now
            </button>
          </div>

          <div className="space-y-4">
             {connectionStatus === 'checking' && (
                <div className="flex items-center gap-4 bg-slate-50 p-5 rounded-xl border border-slate-200 animate-pulse">
                    <RefreshCw className="text-slate-400 animate-spin" size={24} />
                    <div>
                        <h4 className="font-bold text-slate-700">Verifying Connection...</h4>
                        <p className="text-xs text-slate-500">Checking credentials with the new database project.</p>
                    </div>
                </div>
             )}

             {connectionStatus === 'connected' && (
                <div className="flex items-center gap-4 bg-emerald-50 p-5 rounded-xl border border-emerald-200">
                    <ShieldCheck className="text-emerald-600" size={28} />
                    <div>
                        <h4 className="font-bold text-emerald-900">Connected Successfully</h4>
                        <p className="text-xs text-emerald-700">Database is reachable and ready for data transfer.</p>
                    </div>
                </div>
             )}

             {connectionStatus === 'error' && (
                <div className="space-y-4">
                    <div className="flex items-center gap-4 bg-red-50 p-5 rounded-xl border border-red-200">
                        <XCircle className="text-red-600" size={28} />
                        <div>
                            <h4 className="font-bold text-red-900">Database Connection Error</h4>
                            <p className="text-xs text-red-700 mb-2">Check if your tables exist in the Supabase Dashboard.</p>
                            <p className="text-[10px] font-mono bg-red-100/50 p-2 rounded text-red-800 break-all border border-red-100">{connectionError}</p>
                        </div>
                    </div>
                </div>
             )}
          </div>
      </div>

      <div className="bg-slate-900 rounded-2xl p-8 text-white shadow-2xl relative overflow-hidden">
          <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full blur-2xl -mr-10 -mt-10"></div>

          <div className="relative z-10">
              <h3 className="text-xl font-bold mb-2 flex items-center gap-2">
                  <ArrowUpCircle className="text-sky-400" /> Transfer Local Data
              </h3>
              <p className="text-slate-400 text-sm mb-6 max-w-lg">
                  Since your new database is empty, click the button below to upload your current local parties, products, and prices to the cloud.
              </p>

              <div className="flex flex-col md:flex-row items-center gap-4 mb-6">
                  <button 
                    onClick={handlePush} 
                    disabled={connectionStatus !== 'connected' || isPushing}
                    className="w-full md:w-auto px-8 py-3 bg-sky-500 hover:bg-sky-400 disabled:bg-slate-700 disabled:cursor-not-allowed text-slate-900 font-black rounded-xl shadow-lg transition-all flex justify-center items-center gap-2"
                  >
                      {isPushing ? <Loader2 className="animate-spin" size={20} /> : <ArrowUpCircle size={20} />}
                      {isPushing ? 'Uploading...' : 'Upload Data Now'}
                  </button>

                  <div className="flex items-center gap-6">
                      <div className="text-center">
                          <div className="text-[10px] uppercase font-bold text-slate-500">Parties</div>
                          <div className="text-lg font-bold">{parties.length}</div>
                      </div>
                      <div className="h-8 w-px bg-white/10"></div>
                      <div className="text-center">
                          <div className="text-[10px] uppercase font-bold text-slate-500">Products</div>
                          <div className="text-lg font-bold">{products.length}</div>
                      </div>
                  </div>
              </div>

              {pushStatus.type !== 'idle' && (
                  <div className={`p-4 rounded-xl border flex items-center gap-3 animate-in slide-in-from-top-2 ${pushStatus.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/50 text-emerald-400' : 'bg-red-500/10 border-red-500/50 text-red-400'}`}>
                      {pushStatus.type === 'success' ? <CheckCircle size={18} /> : <AlertTriangle size={18} />}
                      <span className="text-sm font-bold">{pushStatus.msg}</span>
                  </div>
              )}
          </div>
      </div>

      <div className="mt-8 bg-amber-50 border border-amber-200 p-6 rounded-2xl flex gap-4 shadow-sm">
          <Info className="text-amber-600 shrink-0" size={24} />
          <div className="text-sm text-amber-900 space-y-2">
              <p className="font-bold uppercase tracking-wider">Common Sync Issues:</p>
              <ul className="list-disc ml-4 space-y-1 text-xs">
                  <li><b>ID Mismatch:</b> If your products have custom IDs like "p10", the database table must be created with ID as <b>TEXT</b>, not UUID.</li>
                  <li><b>RLS Policy:</b> If you see "Permission Denied", go to Supabase Dashboard and <b>Disable RLS</b> on your tables temporarily.</li>
                  <li><b>Empty Project:</b> If you just changed the database, you <u>must</u> run the SQL script in your Supabase SQL Editor first.</li>
              </ul>
          </div>
      </div>
    </div>
  );
};

