  const [specialRates, setSpecialRates] = useState<SpecialRate[]>(() => Store.getRates());
  const [invoices, setInvoices] = useState<Invoice[]>(() => Store.getInvoices());

  const [currentView, setCurrentView] = useState<ViewState>('billing');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [viewInvoice, setViewInvoice] = useState<Invoice | null>(null);
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

  const [invoiceSearch, setInvoiceSearch] = useState('');
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);

  const [contextMenu, setContextMenu] = useState<{ visible: boolean; x: number; y: number; invoice: Invoice | null }>({
    visible: false,
    x: 0,
    y: 0,
    invoice: null,
  });

  const [pdfInvoice, setPdfInvoice] = useState<Invoice | null>(null);
  const pdfContainerRef = useRef<HTMLDivElement>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'pulling'>('idle');

  const isFirstLoad = useRef(true);
  const isDirty = useRef(false); // Only sync if local changes were made
  const isRemoteUpdate = useRef(false);
  const lastSyncedHash = useRef(''); // To prevent redundant network calls
  const isWiping = useRef(false);

  // Helper to generate a simple hash of master data
  const getDataHash = useCallback(() => {
    return JSON.stringify({ parties, products, specialRates, validUsers });
  }, [parties, products, specialRates, validUsers]);

  // --- MIGRATION / WIPE LOGIC ---
  useEffect(() => {
     const WIPE_KEY = 'greenzar_server_wiped_v3_1';
     const hasWiped = localStorage.getItem(WIPE_KEY);

     if (!hasWiped) {
         isWiping.current = true;
         setSyncStatus('syncing');
         Cloud.clearAllData().then(() => {
             localStorage.setItem(WIPE_KEY, 'true');
             isWiping.current = false;
             setSyncStatus('idle');
             window.location.reload();
         }).catch(() => {
             isWiping.current = false;
             setSyncStatus('idle');
         });
     }
  }, []);

  const loadLocalData = () => {
    setParties(Store.getParties());
    setProducts(Store.getProducts());
    setSpecialRates(Store.getRates());
    setInvoices(Store.getInvoices());
    setValidUsers(Store.getUsers());
  };

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('gfb_user');
    if (sessionUser) setIsAuthenticated(true);
    if (!isWiping.current) handleCloudPull();
  }, []);

  // --- MASTER DATA SETTERS WITH DIRTY FLAG ---
  const updateParties = (newParties: Party[]) => {
      setParties(newParties);
      isDirty.current = true;
  };
  const updateProducts = (newProducts: Product[]) => {
      setProducts(newProducts);
      isDirty.current = true;
  };
  const updateRates = (newRates: SpecialRate[]) => {
      setSpecialRates(newRates);
      isDirty.current = true;
  };
  const updateUsers = (newUsers: User[]) => {
      setValidUsers(newUsers);
      isDirty.current = true;
  };

  // --- AUTO-PUSH LOGIC ---
  useEffect(() => {
    if (isWiping.current) return;

    // Save to local storage immediately
    Store.saveParties(parties);
    Store.saveProducts(products);
    Store.saveRates(specialRates);
    Store.saveUsers(validUsers);

    if (isFirstLoad.current) {
      lastSyncedHash.current = getDataHash();
      isFirstLoad.current = false;
      return;
    }

    // Don't push if the update came from the cloud
    if (isRemoteUpdate.current) {
       isRemoteUpdate.current = false; 
       lastSyncedHash.current = getDataHash();
       return; 
    }

    // Debounce the sync to avoid "every second" requests
    const handler = setTimeout(async () => {
       const currentHash = getDataHash();

       // Only sync if data is actually different and marked as dirty
       if (isDirty.current && currentHash !== lastSyncedHash.current) {
         setSyncStatus('syncing');
         try {
           const result = await Cloud.syncMasterData(parties, products, specialRates, validUsers);
           if (result.success) {
               lastSyncedHash.current = currentHash;
               isDirty.current = false;
               setSyncStatus('synced');
               setTimeout(() => setSyncStatus('idle'), 2000);
           } else {
               setSyncStatus('idle');
           }
         } catch (e) {
           console.error("Auto-sync failed", e);
           setSyncStatus('idle');
         }
       }
    }, 5000); // 5 second debounce for efficiency

    return () => clearTimeout(handler);
  }, [parties, products, specialRates, validUsers, getDataHash]);

  const handleCloudPull = useCallback(async () => {
      // Don't pull if we are currently syncing or have local unsaved changes
      if (syncStatus === 'syncing' || syncStatus === 'pulling' || isDirty.current || isWiping.current) return;

      try {
        setSyncStatus('pulling');
        const [cloudParties, cloudProducts, cloudRates, cloudInvoices, cloudUsers] = await Promise.all([
           Cloud.fetchData('PARTIES'),
           Cloud.fetchData('PRODUCTS'),
           Cloud.fetchData('RATES'),
           Cloud.fetchInvoices(),
           Cloud.fetchUsers()
        ]);

        if (isDirty.current) {
           setSyncStatus('idle');
           return;
        }

        let hasRemoteChanges = false;

        if (JSON.stringify(cloudParties) !== JSON.stringify(parties)) {
             setParties(cloudParties);
             hasRemoteChanges = true;
        }
        if (JSON.stringify(cloudProducts) !== JSON.stringify(products)) {
             setProducts(cloudProducts);
             hasRemoteChanges = true;
        }
        if (JSON.stringify(cloudRates) !== JSON.stringify(specialRates)) {
             setSpecialRates(cloudRates);
             hasRemoteChanges = true;
        }
        if (cloudInvoices.length !== invoices.length) {
             setInvoices(cloudInvoices);
             Store.saveInvoices(cloudInvoices);
        }
        if (cloudUsers.length > 0 && JSON.stringify(cloudUsers) !== JSON.stringify(validUsers)) {
            setValidUsers(cloudUsers);
            Store.saveUsers(cloudUsers);
        }

        if (hasRemoteChanges) {
            isRemoteUpdate.current = true;
        }

        setSyncStatus('idle');
      } catch (e) {
        setSyncStatus('idle');
      }
  }, [parties, products, specialRates, invoices, validUsers, syncStatus]);

  useEffect(() => {
    const interval = setInterval(handleCloudPull, 30000); // Pull every 30 seconds
    return () => clearInterval(interval);
  }, [handleCloudPull]);

  // ... Rest of the component logic (handleEdit, handlePrint, etc.)

  if (!isAuthenticated) return <Login onLogin={(u) => { setIsAuthenticated(true); sessionStorage.setItem('gfb_user', JSON.stringify(u)); }} validUsers={validUsers} />;

  const NavItem = ({ view, icon: Icon, label }: { view: ViewState; icon: any; label: string }) => (
    <button
      onClick={() => { setCurrentView(view); setEditingInvoice(null); setIsMobileMenuOpen(false); }}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium mb-1 ${
        currentView === view ? 'bg-sky-100 text-sky-800 shadow-sm ring-1 ring-sky-200' : 'text-slate-500 hover:bg-slate-50 hover:text-sky-600'
      }`}
    >
      <Icon size={18} strokeWidth={2} />
      <span>{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900">
      {/* Sidebar and Navigation components same as before but using the new update functions */}
      {/* ... [Sidebar Code] ... */}
      <div className={`fixed md:static inset-y-0 left-0 w-64 bg-white border-r border-slate-200 transform transition-transform duration-300 z-[60] shadow-xl md:shadow-none no-print flex flex-col ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0`}>
        <div className="p-6">
          <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2 tracking-tight">
            <div className="w-8 h-8 bg-sky-600 rounded-lg flex items-center justify-center text-white text-lg font-bold shadow-lg shadow-sky-200">G</div>
            GREENZAR
          </h1>
        </div>
        <nav className="px-4 py-2 flex-1 overflow-y-auto">
          <div className="mb-2 px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Operations</div>
          <NavItem view="billing" icon={FileText} label="Create Invoice" />
          <NavItem view="history" icon={History} label="History" />
          <div className="mt-6 mb-2 px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Database</div>
          <NavItem view="parties" icon={Users} label="Parties" />
          <NavItem view="products" icon={Package} label="Products" />
          <NavItem view="rates" icon={DollarSign} label="Price Lists" />
          <div className="mt-6 mb-2 px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Configuration</div>
          <NavItem view="users" icon={UserIcon} label="Users" />
          <NavItem view="data" icon={Database} label="Data & Sync" />
        </nav>
        <div className="p-4 border-t border-slate-100 bg-slate-50/50">
           <button onClick={() => setShowLogoutConfirm(true)} className="w-full flex items-center justify-center gap-2 text-xs font-bold text-slate-500 hover:text-red-600 hover:bg-red-50 p-2 rounded-lg transition-colors">
             <LogOut size={14} /> Logout
           </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col h-full overflow-hidden pt-14 md:pt-0 bg-slate-50/50">
        {currentView === 'billing' && (
          <Billing 
            parties={parties} setParties={updateParties}
            products={products} specialRates={specialRates} setSpecialRates={updateRates}
            onInvoiceSaved={() => { setInvoices(Store.getInvoices()); setEditingInvoice(null); }}
            initialData={editingInvoice}
          />
        )}
        {currentView === 'parties' && <div className="h-full overflow-y-auto"><PartyManager parties={parties} setParties={updateParties} /></div>}
        {currentView === 'products' && <div className="h-full overflow-y-auto"><ProductManager products={products} setProducts={updateProducts} /></div>}
        {currentView === 'rates' && <RateManager parties={parties} products={products} specialRates={specialRates} setSpecialRates={updateRates} />}
        {currentView === 'users' && <div className="h-full overflow-y-auto"><UserManager users={validUsers} setUsers={updateUsers} /></div>}
        {currentView === 'data' && <div className="h-full overflow-y-auto"><DataManager parties={parties} products={products} specialRates={specialRates} invoices={invoices} refreshData={loadLocalData} onForcePush={() => { isDirty.current = true; lastSyncedHash.current = ''; }} /></div>}
        {/* Other views same as original code... */}
        {currentView === 'history' && <div className="h-full overflow-y-auto p-4 md:p-8">
            {/* Same history rendering code as original */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <h2 className="text-2xl font-bold text-slate-800 tracking-tight">Invoice History</h2>
                <div className="flex gap-2">
                    <button onClick={handleCloudPull} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-sky-700 bg-white border border-slate-200 rounded-lg shadow-sm hover:bg-slate-50">
                        <RefreshCw size={16} className={syncStatus === 'pulling' ? 'animate-spin' : ''} /> Refresh
                    </button>
                </div>
            </div>
            {/* ... [Table rendering from original history view] ... */}
        </div>}
      </div>

