              {syncStatus === 'syncing' ? 'Syncing...' : syncStatus === 'pulling' ? 'Updating...' : syncStatus === 'synced' ? 'All Saved' : 'Cloud Ready'}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

