        const result = await Cloud.syncMasterData(parties, products, specialRates, []);
        if (result.success) {
            setPushStatus({msg: 'All data (Parties, Products & Rates) uploaded successfully!', type: 'success'});
            if (onForcePush) onForcePush();
        } else {
            setPushStatus({msg: `Upload Failed: ${result.error}`, type: 'error'});
