  const [parties, setParties] = useState<Party[]>(() => Store.getParties());
  const [products, setProducts] = useState<Product[]>(() => Store.getProducts());
  const [specialRates, setSpecialRates] = useState<SpecialRate[]>(() => Store.getRates());
  const [invoices, setInvoices] = useState<Invoice[]>(() => Store.getInvoices());

  const [currentView, setCurrentView] = useState<ViewState>('billing');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [viewInvoice, setViewInvoice] = useState<Invoice | null>(null);
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);
  const [invoiceSearch, setInvoiceSearch] = useState('');
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'pulling'>('idle');

  const [contextMenu, setContextMenu] = useState<{ visible: boolean; x: number; y: number; invoice: Invoice | null }>({
    visible: false, x: 0, y: 0, invoice: null,
  });

  const [pdfInvoice, setPdfInvoice] = useState<Invoice | null>(null);
  const pdfContainerRef = useRef<HTMLDivElement>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  const isFirstLoad = useRef(true);
  const isDirty = useRef(false);
  const isRemoteUpdate = useRef(false);
  const lastSyncedHash = useRef('');
  const isWiping = useRef(false);

  const getDataHash = useCallback(() => {
    return JSON.stringify({ parties, products, specialRates, validUsers });
  }, [parties, products, specialRates, validUsers]);

  useEffect(() => {
    const WIPE_KEY = 'greenzar_server_wiped_v3_2'; // Updated version for stable sync
    if (!localStorage.getItem(WIPE_KEY)) {
        isWiping.current = true;
        setSyncStatus('syncing');
        Cloud.clearAllData().then(() => {
            localStorage.setItem(WIPE_KEY, 'true');
            isWiping.current = false;
            window.location.reload();
        });
    }
  }, []);

  const loadLocalData = () => {
    setParties(Store.getParties());
    setProducts(Store.getProducts());
    setSpecialRates(Store.getRates());
    setInvoices(Store.getInvoices());
    setValidUsers(Store.getUsers());
  };

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('gfb_user');
    if (sessionUser) setIsAuthenticated(true);
    if (!isWiping.current) handleCloudPull();
  }, []);

  const updateParties = (newParties: Party[]) => { setParties(newParties); isDirty.current = true; };
  const updateProducts = (newProducts: Product[]) => { setProducts(newProducts); isDirty.current = true; };
  const updateRates = (newRates: SpecialRate[]) => { setSpecialRates(newRates); isDirty.current = true; };
  const updateUsers = (newUsers: User[]) => { setValidUsers(newUsers); isDirty.current = true; };

  useEffect(() => {
    if (isWiping.current) return;
    Store.saveParties(parties);
    Store.saveProducts(products);
    Store.saveRates(specialRates);
    Store.saveUsers(validUsers);

    if (isFirstLoad.current) { lastSyncedHash.current = getDataHash(); isFirstLoad.current = false; return; }
    if (isRemoteUpdate.current) { isRemoteUpdate.current = false; lastSyncedHash.current = getDataHash(); return; }

    const handler = setTimeout(async () => {
       const currentHash = getDataHash();
       if (isDirty.current && currentHash !== lastSyncedHash.current) {
         setSyncStatus('syncing');
         try {
           const result = await Cloud.syncMasterData(parties, products, specialRates, validUsers);
           if (result.success) {
               lastSyncedHash.current = currentHash;
               isDirty.current = false;
               setSyncStatus('synced');
               setTimeout(() => setSyncStatus('idle'), 2000);
           }
         } catch (e) { setSyncStatus('idle'); }
       }
    }, 4000); 
    return () => clearTimeout(handler);
  }, [parties, products, specialRates, validUsers, getDataHash]);

  const handleCloudPull = useCallback(async () => {
      if (syncStatus === 'syncing' || syncStatus === 'pulling' || isDirty.current || isWiping.current) return;
      try {
        setSyncStatus('pulling');
        const [cloudParties, cloudProducts, cloudRates, cloudInvoices, cloudUsers] = await Promise.all([
           Cloud.fetchData('PARTIES'), Cloud.fetchData('PRODUCTS'), Cloud.fetchData('RATES'), Cloud.fetchInvoices(), Cloud.fetchUsers()
        ]);
        if (isDirty.current) { setSyncStatus('idle'); return; }

        let remoteChanged = false;
        if (JSON.stringify(cloudParties) !== JSON.stringify(parties)) { setParties(cloudParties); remoteChanged = true; }
        if (JSON.stringify(cloudProducts) !== JSON.stringify(products)) { setProducts(cloudProducts); remoteChanged = true; }
        if (JSON.stringify(cloudRates) !== JSON.stringify(specialRates)) { setSpecialRates(cloudRates); remoteChanged = true; }
        if (cloudInvoices.length !== invoices.length) { setInvoices(cloudInvoices); Store.saveInvoices(cloudInvoices); }
        if (cloudUsers.length > 0 && JSON.stringify(cloudUsers) !== JSON.stringify(validUsers)) { setValidUsers(cloudUsers); Store.saveUsers(cloudUsers); }

        if (remoteChanged) isRemoteUpdate.current = true;
        setSyncStatus('idle');
      } catch (e) { setSyncStatus('idle'); }
  }, [parties, products, specialRates, invoices, validUsers, syncStatus]);

  useEffect(() => {
    const interval = setInterval(handleCloudPull, 45000); // Efficient polling
    return () => clearInterval(interval);
  }, [handleCloudPull]);

  const handleEditInvoice = (invoice: Invoice) => { setEditingInvoice(invoice); setCurrentView('billing'); };
  const handlePrintOptions = (e: React.MouseEvent, invoice: Invoice) => {
    e.preventDefault(); e.stopPropagation();
