                        <th className="px-4 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider text-right whitespace-nowrap">Total</th>
                        <th className="px-4 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider text-right whitespace-nowrap no-print">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 print:divide-slate-200">
                      {filteredInvoices.map(inv => (
                        <tr key={inv.id} className="hover:bg-sky-50/50 transition-colors print:hover:bg-transparent">
                          <td className="px-4 py-4 font-mono text-xs text-slate-600 font-bold whitespace-nowrap">{inv.invoiceNumber}</td>
                          <td className="px-4 py-4 text-xs text-slate-600 whitespace-nowrap">{inv.date}</td>
                          <td className="px-4 py-4 text-xs font-medium text-slate-800 whitespace-nowrap max-w-[150px] truncate" title={inv.partyName || 'Unknown'}>{inv.partyName || 'Unknown Party'}</td>
                          <td className="px-4 py-4 text-xs text-slate-500 whitespace-nowrap">{inv.vehicleNumber || '-'}</td>
                          <td className="px-4 py-4 text-xs text-slate-500 text-center whitespace-nowrap">{inv.poNumber || '-'}</td>
                          <td className="px-4 py-4 text-xs text-slate-500 text-center whitespace-nowrap">{(inv.items || []).length}</td>
                          <td className="px-4 py-4 text-xs text-slate-500 text-right whitespace-nowrap">₹{(inv.taxAmount || 0).toFixed(2)}</td>
                          <td className="px-4 py-4 text-xs text-red-400 text-right whitespace-nowrap">{(inv.globalDiscount || 0) > 0 ? `₹${inv.globalDiscount}` : '-'}</td>
                          <td className="px-4 py-4 text-right text-sm font-bold text-slate-700 whitespace-nowrap">₹{(inv.grandTotal || 0).toFixed(2)}</td>
                          <td className="px-4 py-4 text-right whitespace-nowrap no-print">
                             <div className="flex justify-end gap-1">
                               <button 
                                onClick={() => handleEditInvoice(inv)}
                                className="text-slate-400 hover:text-orange-600 p-2 hover:bg-orange-50 rounded-lg transition-all"
                                title="Edit Invoice"
                                >
                                 <Edit3 size={16} />
                               </button>
                               <button 
                                onClick={(e) => handlePrintOptions(e, inv)}
                                className="text-slate-400 hover:text-sky-600 p-2 hover:bg-sky-50 rounded-lg transition-all"
                                title="Print / Download Options"
                               >
                                 <Printer size={16} />
                               </button>
                               <button 
                                onClick={() => handleDownloadSingleInvoice(inv)}
                                className="text-slate-400 hover:text-emerald-600 p-2 hover:bg-emerald-50 rounded-lg transition-all"
                                title="Download CSV"
                               >
                                 <Download size={16} />
                               </button>
                             </div>
                          </td>
                        </tr>
                      ))}
                      {filteredInvoices.length === 0 && (
                        <tr>
                          <td colSpan={10} className="px-6 py-12 text-center text-slate-400">
                             {invoiceSearch ? 'No invoices match your search.' : 'No invoices generated yet.'}
                          </td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
             </div>
          </div>
        )}

        {currentView === 'data' && (
          <div className="h-full overflow-y-auto">
            <DataManager 
              parties={parties}
              products={products}
              specialRates={specialRates}
              invoices={invoices}
              refreshData={loadLocalData}
              onForcePush={handleForcePush}
            />
          </div>
        )}

      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Users, Package, DollarSign, FileText, History, Menu, X, Database, CheckCircle, RefreshCw, Loader2, LayoutDashboard, Printer, LogOut, User as UserIcon, Edit3, Download, MoreHorizontal, FileDown, Search, Trophy, ClipboardList, ScrollText } from 'lucide-react';
import { PartyManager } from './components/PartyManager';
import { ProductManager } from './components/ProductManager';
import { RateManager } from './components/RateManager';
import { Billing } from './components/Billing';
import { DataManager } from './components/DataManager';
import { UserManager } from './components/UserManager';
import { MoreMenu } from './components/MoreMenu';
import { InvoiceLogs } from './components/InvoiceLogs';
import { Ranking } from './components/Ranking';
import { PartyStatement } from './components/PartyStatement';
import { Login } from './components/Login';
import { Store } from './services/store';
import { Cloud } from './services/cloud';
import { Party, Product, SpecialRate, Invoice, ViewState, User } from './types';
import { InvoiceTemplate } from './components/InvoiceTemplate';
import { exportInvoicesToCSV } from './services/csv';

declare global {
  interface Window {
    html2pdf: any;
  }
}

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  const [validUsers, setValidUsers] = useState<User[]>(() => Store.getUsers());
  const [parties, setParties] = useState<Party[]>(() => Store.getParties());
  const [products, setProducts] = useState<Product[]>(() => Store.getProducts());
  const [specialRates, setSpecialRates] = useState<SpecialRate[]>(() => Store.getRates());
  const [invoices, setInvoices] = useState<Invoice[]>(() => Store.getInvoices());

  const [currentView, setCurrentView] = useState<ViewState>('billing');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [viewInvoice, setViewInvoice] = useState<Invoice | null>(null);
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

  const [invoiceSearch, setInvoiceSearch] = useState('');
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);

  const [contextMenu, setContextMenu] = useState<{ visible: boolean; x: number; y: number; invoice: Invoice | null }>({
    visible: false,
    x: 0,
    y: 0,
    invoice: null,
  });

  const [pdfInvoice, setPdfInvoice] = useState<Invoice | null>(null);
  const pdfContainerRef = useRef<HTMLDivElement>(null);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'pulling'>('idle');
  const [cloudUrl] = useState(() => Cloud.getScriptUrl()); 

  const isFirstLoad = useRef(true);
  const hasPendingChanges = useRef(false);
  const isRemoteUpdate = useRef(false);
  const lastPushTime = useRef(0); 
  const isWiping = useRef(false);

  // --- ONE-TIME DATA PULL ---
  const handleCloudPull = useCallback(async () => {
      // Prevent multiple simultaneous pulls
      if (syncStatus === 'syncing' || syncStatus === 'pulling' || isWiping.current) return;

      try {
        setSyncStatus('pulling');

        const [cloudParties, cloudProducts, cloudRates, cloudInvoices, cloudUsers] = await Promise.all([
           Cloud.fetchData('PARTIES'),
           Cloud.fetchData('PRODUCTS'),
           Cloud.fetchData('RATES'),
           Cloud.fetchInvoices(),
           Cloud.fetchUsers()
        ]);

        // Only update if we haven't started typing local changes in the meantime
        if (hasPendingChanges.current) {
           setSyncStatus('idle');
           return;
        }

        let updateData = false;
        if (JSON.stringify(cloudParties) !== JSON.stringify(parties)) { setParties(cloudParties); updateData = true; }
        if (JSON.stringify(cloudProducts) !== JSON.stringify(products)) { setProducts(cloudProducts); updateData = true; }
        if (JSON.stringify(cloudRates) !== JSON.stringify(specialRates)) { setSpecialRates(cloudRates); updateData = true; }

        if (cloudInvoices.length !== invoices.length) {
             setInvoices(cloudInvoices);
             Store.saveInvoices(cloudInvoices);
        }

        if (cloudUsers.length > 0 && JSON.stringify(cloudUsers) !== JSON.stringify(validUsers)) {
            setValidUsers(cloudUsers);
            Store.saveUsers(cloudUsers);
        }

        if (updateData) isRemoteUpdate.current = true;
        setSyncStatus('idle');

      } catch (e) {
        console.error("Supabase Pull Error", e);
        setSyncStatus('idle');
      }
  }, [parties, products, specialRates, invoices, validUsers, syncStatus]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('gfb_user');
    if (sessionUser) setIsAuthenticated(true);

    // Initial data load only
    handleCloudPull();
  }, []);

  // --- AUTO-PUSH ON CHANGE (NO BACKGROUND INTERVAL) ---
  useEffect(() => {
    if (isWiping.current) return;

    Store.saveParties(parties);
    Store.saveProducts(products);
    Store.saveRates(specialRates);
    Store.saveUsers(validUsers);

    if (isFirstLoad.current) {
      isFirstLoad.current = false;
      return;
    }

    // Don't push back what we just pulled from the server
    if (isRemoteUpdate.current) {
       isRemoteUpdate.current = false; 
       return; 
    }

    hasPendingChanges.current = true;

    if (cloudUrl) {
      setSyncStatus('syncing');

      // Debounce: Wait 5 seconds after last change before pushing
      const handler = setTimeout(async () => {
         try {
           await Cloud.syncMasterData(parties, products, specialRates, validUsers);
           lastPushTime.current = Date.now();
           setSyncStatus('synced');
           hasPendingChanges.current = false;
           setTimeout(() => setSyncStatus('idle'), 2000);
         } catch (e) {
           console.error("Auto-sync failed", e);
           setSyncStatus('idle');
           hasPendingChanges.current = false; 
         }
      }, 5000); 

      return () => clearTimeout(handler);
    } else {
       hasPendingChanges.current = false;
    }
  }, [parties, products, specialRates, validUsers, cloudUrl]);

  // Rest of the component logic remains identical...
  const handleForcePush = async () => {
      setSyncStatus('syncing');
      try {
          await Cloud.syncMasterData(parties, products, specialRates, validUsers);
          setSyncStatus('synced');
          hasPendingChanges.current = false;
          setTimeout(() => setSyncStatus('idle'), 2000);
          alert("Data uploaded to Supabase.");
      } catch(e) {
          setSyncStatus('idle');
          alert("Upload failed.");
      }
  };

  const handleEditInvoice = (invoice: Invoice) => {
    setEditingInvoice(invoice);
    setCurrentView('billing');
  };

  if (!isAuthenticated) return <Login onLogin={(u) => { setIsAuthenticated(true); sessionStorage.setItem('gfb_user', JSON.stringify(u)); }} validUsers={validUsers} />;

  const NavItem = ({ view, icon: Icon, label }: { view: ViewState; icon: any; label: string }) => (
    <button
      onClick={() => { setCurrentView(view); setEditingInvoice(null); setIsMobileMenuOpen(false); }}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-medium mb-1 ${
        currentView === view ? 'bg-sky-100 text-sky-800 shadow-sm ring-1 ring-sky-200' : 'text-slate-500 hover:bg-slate-50 hover:text-sky-600'
      }`}
    >
      <Icon size={18} strokeWidth={2} />
      <span>{label}</span>
    </button>
  );

  return (
    <div className="flex h-screen bg-slate-50 font-sans text-slate-900">
      {/* Sidebar UI */}
      <div className={`fixed md:static inset-y-0 left-0 w-64 bg-white border-r border-slate-200 transform transition-transform duration-300 z-[60] shadow-xl md:shadow-none no-print flex flex-col ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0`}>
        <div className="p-6">
          <h1 className="text-xl font-bold text-slate-800 flex items-center gap-2">
            <div className="w-8 h-8 bg-sky-600 rounded-lg flex items-center justify-center text-white text-lg font-bold">G</div>
            GREENZAR
          </h1>
        </div>
        <nav className="px-4 py-2 flex-1 overflow-y-auto">
          <div className="mb-2 px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Operations</div>
          <NavItem view="billing" icon={FileText} label="Create Invoice" />
          <NavItem view="history" icon={History} label="History" />
          <div className="mt-6 mb-2 px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Reports</div>
          <NavItem view="logs" icon={ClipboardList} label="All Logs" />
          <NavItem view="statement" icon={ScrollText} label="Party Statement" />
          <NavItem view="ranking" icon={Trophy} label="Ranking" />
          <div className="mt-6 mb-2 px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Database</div>
          <NavItem view="parties" icon={Users} label="Parties" />
          <NavItem view="products" icon={Package} label="Products" />
          <NavItem view="rates" icon={DollarSign} label="Price Lists" />
          <div className="mt-6 mb-2 px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Configuration</div>
          <NavItem view="users" icon={UserIcon} label="Users" />
          <NavItem view="data" icon={Database} label="Data & Sync" />
        </nav>
        <div className="p-4 border-t border-slate-100 bg-slate-50/50">
           <button onClick={() => setShowLogoutConfirm(true)} className="w-full flex items-center justify-center gap-2 text-xs font-bold text-slate-500 hover:text-red-600 hover:bg-red-50 p-2 rounded-lg transition-colors">
             <LogOut size={14} /> Logout
           </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col h-full overflow-hidden pt-14 md:pt-0 bg-slate-50/50">
        {/* Main View Router */}
        {currentView === 'billing' && <Billing parties={parties} setParties={setParties} products={products} specialRates={specialRates} setSpecialRates={setSpecialRates} onInvoiceSaved={() => { setInvoices(Store.getInvoices()); setEditingInvoice(null); }} initialData={editingInvoice} />}
        {currentView === 'history' && (
            <div className="p-6 h-full overflow-y-auto">
                <div className="flex justify-between items-center mb-6">
                    <h2 className="text-2xl font-bold">Invoice History</h2>
                    <div className="flex gap-2">
                         <div className="relative">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                            <input type="text" placeholder="Search..." value={invoiceSearch} onChange={e => setInvoiceSearch(e.target.value)} className="pl-9 pr-3 py-2 border rounded-lg outline-none w-64" />
                         </div>
                         <button onClick={handleCloudPull} className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-sky-700 bg-white border border-slate-200 rounded-lg shadow-sm hover:bg-slate-50">
                            <RefreshCw size={16} className={syncStatus === 'pulling' ? 'animate-spin' : ''} /> Refresh
                         </button>
                    </div>
                </div>
                <div className="bg-white rounded-xl shadow border overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-slate-50 text-xs font-bold text-slate-500 uppercase border-b">
                            <tr>
                                <th className="px-6 py-4">Invoice #</th>
                                <th className="px-6 py-4">Date</th>
                                <th className="px-6 py-4">Party</th>
                                <th className="px-6 py-4 text-right">Amount</th>
                                <th className="px-6 py-4 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {invoices.filter(i => i.invoiceNumber.includes(invoiceSearch) || i.partyName.toLowerCase().includes(invoiceSearch.toLowerCase())).map(inv => (
                                <tr key={inv.id} className="hover:bg-slate-50 transition-colors">
                                    <td className="px-6 py-4 font-mono font-bold text-slate-600">{inv.invoiceNumber}</td>
                                    <td className="px-6 py-4 text-sm">{inv.date}</td>
                                    <td className="px-6 py-4 font-medium">{inv.partyName}</td>
                                    <td className="px-6 py-4 text-right font-black">₹{inv.grandTotal}</td>
                                    <td className="px-6 py-4 text-right">
                                        <div className="flex justify-end gap-2">
                                            <button onClick={() => handleEditInvoice(inv)} className="p-2 text-slate-400 hover:text-sky-600"><Edit3 size={16}/></button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        )}
        {currentView === 'parties' && <PartyManager parties={parties} setParties={setParties} />}
        {currentView === 'products' && <ProductManager products={products} setProducts={setProducts} />}
        {currentView === 'rates' && <RateManager parties={parties} products={products} specialRates={specialRates} setSpecialRates={setSpecialRates} />}
        {currentView === 'logs' && <InvoiceLogs invoices={invoices} parties={parties} />}
        {currentView === 'ranking' && <Ranking invoices={invoices} parties={parties} />}
        {currentView === 'statement' && <PartyStatement invoices={invoices} parties={parties} />}
        {currentView === 'users' && <UserManager users={validUsers} setUsers={setValidUsers} />}
        {currentView === 'data' && <DataManager parties={parties} products={products} specialRates={specialRates} invoices={invoices} refreshData={loadLocalData} onForcePush={handleForcePush} />}
      </div>

      {/* Manual Sync Status / Trigger */}
      <div className="fixed bottom-6 right-6 z-50">
        <div className="bg-white rounded-xl shadow-lg border border-slate-100 p-3 flex items-center gap-3">
          {syncStatus === 'syncing' || syncStatus === 'pulling' ? <RefreshCw className="text-orange-500 animate-spin" size={20} /> : <CheckCircle className="text-emerald-500" size={20} />}
          <div className="font-bold text-xs text-slate-700">
            {syncStatus === 'syncing' ? 'Syncing...' : syncStatus === 'pulling' ? 'Updating...' : 'Online'}
          </div>
          <button onClick={handleCloudPull} className="p-1.5 hover:bg-slate-50 rounded-full text-slate-400" title="Manual Sync">
             <RefreshCw size={14} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default App;

