import { Invoice, Party, Product, SpecialRate, User } from '../types';
import { supabase } from './supabase';

export const Cloud = {
  // Flag to indicate we are using Supabase
  getScriptUrl: () => 'SUPABASE_ENABLED', 
  setScriptUrl: (url: string) => {}, 

  // --- CLEAN DATA ---
  clearAllData: async () => {
    // Targeted clean-up to avoid heavy global deletes
    await supabase.from('special_rates').delete().neq('rate', -1);
    return true;
  },

  // --- SYNC METHODS ---

  syncInvoice: async (invoice: Invoice) => {
    const { error } = await supabase
      .from('invoices')
      .upsert({
        id: invoice.id,
        invoiceNumber: invoice.invoiceNumber,
        partyId: invoice.partyId,
        partyName: invoice.partyName,
        date: invoice.date,
        items: invoice.items, 
        subTotal: invoice.subTotal,
        taxAmount: invoice.taxAmount,
        globalDiscount: invoice.globalDiscount,
        grandTotal: invoice.grandTotal,
        vehicleNumber: invoice.vehicleNumber,
        poNumber: invoice.poNumber,
        partyAddress: invoice.partyAddress,
        partyGst: invoice.partyGst,
        partyPan: invoice.partyPan,
        partyAadhar: invoice.partyAadhar,
        partyPhone: invoice.partyPhone
      });

    if (error) {
      console.error('Error syncing invoice:', error);
      return { success: false, error: error.message };
    }
    return { success: true };
  },

  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
    // 1. Sync Parties (Small chunks)
    if (parties.length > 0) {
      await supabase.from('parties').upsert(parties);
    }

    // 2. Sync Products (Small chunks)
    if (products.length > 0) {
      await supabase.from('products').upsert(products);
    }

    // 3. Sync Users
    if (users.length > 0) {
      await supabase.from('app_users').upsert(users);
    }

    // 4. Sync Rates (Optimized Batched Upsert)
    if (rates.length > 0) {
        const batchSize = 200;
        for (let i = 0; i < rates.length; i += batchSize) {
            const batch = rates.slice(i, i + batchSize);
            const { error } = await supabase.from('special_rates').upsert(batch);
            if (error) console.error(`Error syncing rate batch ${i}:`, error);
        }
    }
  },

  // --- FETCH METHODS (Maxed at 10,000 for large lists) ---

  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES' | 'INVOICES' | 'USERS'): Promise<any> => {
    const FETCH_LIMIT = 10000;

    if (type === 'PARTIES') {
      const { data, error } = await supabase.from('parties').select('*').order('name', { ascending: true }).limit(FETCH_LIMIT);
      if (error) throw error;
      return data;
    }
    if (type === 'PRODUCTS') {
      const { data, error } = await supabase.from('products').select('*').order('name', { ascending: true }).limit(FETCH_LIMIT);
      if (error) throw error;
      return data;
    }
    if (type === 'RATES') {
      const { data, error } = await supabase.from('special_rates').select('*').limit(FETCH_LIMIT);
      if (error) throw error;
      return data;
    }
    return [];
  },

  fetchUsers: async (): Promise<User[]> => {
    const { data, error } = await supabase.from('app_users').select('*').limit(100);
    if (error) throw error;
    return data as User[];
  },

  fetchInvoices: async (): Promise<Invoice[]> => {
    const { data, error } = await supabase.from('invoices').select('*').order('date', { ascending: false }).limit(5000);
    if (error) throw error;

    return data.map((inv: any) => ({
      ...inv,
      items: typeof inv.items === 'string' ? JSON.parse(inv.items) : (inv.items || []),
      subTotal: Number(inv.subTotal) || 0,
      taxAmount: Number(inv.taxAmount) || 0,
      globalDiscount: Number(inv.globalDiscount) || 0,
      grandTotal: Number(inv.grandTotal) || 0,
    })) as Invoice[];
  },

  testConnection: async () => {
    try {
      const { error } = await supabase.from('parties').select('id').limit(1);
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (e: any) {
      return { success: false, error: e.message || "Connection Error" };
    }
  }
};

import React, { useState, useEffect } from 'react';
import { Party, Product, SpecialRate } from '../types';
import { Search, Check, CloudLightning, Grid, LayoutList, ArrowLeft, Save, AlignLeft, Tag } from 'lucide-react';

interface Props {
  parties: Party[];
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (r: SpecialRate[]) => void;
}

export const RateManager: React.FC<Props> = ({ parties, products, specialRates, setSpecialRates }) => {
  const [viewMode, setViewMode] = useState<'detail' | 'matrix' | 'summary'>('summary');
  const [selectedPartyId, setSelectedPartyId] = useState<string | null>(null);
  const [filterText, setFilterText] = useState('');
  const [partySearch, setPartySearch] = useState('');
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'pending'>('saved');
  const [matrixMap, setMatrixMap] = useState<Record<string, number>>({});

  useEffect(() => {
    const map: Record<string, number> = {};
    specialRates.forEach(r => {
      map[`${r.partyId}_${r.productId}`] = r.rate;
    });
    setMatrixMap(map);
  }, [specialRates]);

  const handleManualSave = () => {
    setSaveStatus('saving');

    const newRates: SpecialRate[] = [];
    Object.entries(matrixMap).forEach(([key, val]) => {
        const [pId, prodId] = key.split('_');
        const rateVal = val as number;
        if (rateVal > 0) {
            newRates.push({ partyId: pId, productId: prodId, rate: rateVal });
        }
    });

    setSpecialRates(newRates);
    setTimeout(() => setSaveStatus('saved'), 1000);
  };

  const handleRateChange = (partyId: string, productId: string, val: string) => {
    setSaveStatus('pending');
    const num = parseFloat(val);
    const key = `${partyId}_${productId}`;
    setMatrixMap(prev => {
        const next = { ...prev };
        if (!isNaN(num) && val !== '') next[key] = num;
        else delete next[key];
        return next;
    });
  };

  const filteredParties = parties.filter(p => 
    p.name.toLowerCase().includes(partySearch.toLowerCase()) ||
    (p.code && p.code.toLowerCase().includes(partySearch.toLowerCase()))
  );

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(filterText.toLowerCase()) || 
    p.code.toLowerCase().includes(filterText.toLowerCase())
  );

  return (
    <div className="flex flex-col h-[calc(100vh-64px)] overflow-hidden bg-slate-50">

      <div className="bg-white border-b border-slate-200 px-6 py-3 flex flex-col md:flex-row justify-between items-center shadow-sm z-20 gap-4">
         <div className="flex items-center gap-4 w-full md:w-auto overflow-x-auto pb-1 md:pb-0">
             <div className="flex bg-slate-100 p-1 rounded-lg border border-slate-200 shrink-0">
                <button 
                  onClick={() => setViewMode('summary')}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${viewMode === 'summary' ? 'bg-white text-sky-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  title="Show all rates for a person in one row"
                >
                    <AlignLeft size={16} /> Summary
                </button>
                <button 
                  onClick={() => setViewMode('matrix')}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${viewMode === 'matrix' ? 'bg-white text-sky-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <Grid size={16} /> Grid
                </button>
                <button 
                  onClick={() => setViewMode('detail')}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold transition-all ${viewMode === 'detail' ? 'bg-white text-sky-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <LayoutList size={16} /> Edit Single
                </button>
             </div>

             <div className={`hidden md:flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-bold uppercase tracking-wider transition-all shrink-0 ${
                saveStatus === 'saved' ? 'text-slate-400' : 'text-orange-500 bg-orange-50'
             }`}>
                {saveStatus === 'saved' ? <Check size={14}/> : <CloudLightning size={14} className={saveStatus === 'saving' ? 'animate-pulse' : ''} />}
                {saveStatus === 'saved' ? 'Synced' : saveStatus === 'saving' ? 'Saving...' : 'Unsaved Changes'}
             </div>
