};

import React, { useState, useEffect, useMemo } from 'react';
import { Party, Product, SpecialRate } from '../types';
import { Search, Check, CloudLightning, Grid, LayoutList, ArrowLeft, Save, AlignLeft, Table, ChevronRight, ChevronLeft, Filter } from 'lucide-react';

interface Props {
  parties: Party[];
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (r: SpecialRate[]) => void;
}

export const RateManager: React.FC<Props> = ({ parties, products, specialRates, setSpecialRates }) => {
  // We prioritize the 'Matrix' (Master Sheet) view as requested for "One Row" management
  const [viewMode, setViewMode] = useState<'sheet' | 'individual'>('sheet');
  const [partySearch, setPartySearch] = useState('');
  const [productSearch, setProductSearch] = useState('');
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'pending'>('saved');

  // Local state for the grid to make editing fast
  const [gridData, setGridData] = useState<Record<string, number>>({});

  // Sync incoming special rates to our local grid map
  useEffect(() => {
    const map: Record<string, number> = {};
    specialRates.forEach(r => {
      map[`${r.partyId}_${r.productId}`] = r.rate;
    });
    setGridData(map);
  }, [specialRates]);

  const handleManualSave = () => {
    setSaveStatus('saving');

    const newRatesList: SpecialRate[] = [];
    Object.entries(gridData).forEach(([key, val]) => {
        const [pId, prodId] = key.split('_');
        const rateVal = val as number;
        if (rateVal > 0) {
            newRatesList.push({ partyId: pId, productId: prodId, rate: rateVal });
        }
    });

    setSpecialRates(newRatesList);
    setTimeout(() => setSaveStatus('saved'), 800);
  };

  const handleCellChange = (partyId: string, productId: string, val: string) => {
    setSaveStatus('pending');
    const num = parseFloat(val);
    const key = `${partyId}_${productId}`;

    setGridData(prev => {
        const next = { ...prev };
        if (!isNaN(num) && val !== '') next[key] = num;
        else delete next[key];
        return next;
    });
  };

  // Memoized filters for performance
  const filteredParties = useMemo(() => parties.filter(p => 
    p.name.toLowerCase().includes(partySearch.toLowerCase()) ||
    (p.code && p.code.toLowerCase().includes(partySearch.toLowerCase()))
  ), [parties, partySearch]);

  const filteredProducts = useMemo(() => products.filter(p => 
    p.name.toLowerCase().includes(productSearch.toLowerCase()) || 
    p.code.toLowerCase().includes(productSearch.toLowerCase())
  ), [products, productSearch]);

  return (
    <div className="flex flex-col h-[calc(100vh-64px)] overflow-hidden bg-white">

      {/* HEADER CONTROLS */}
      <div className="bg-slate-900 text-white px-6 py-3 flex flex-col md:flex-row justify-between items-center z-30 gap-4">
         <div className="flex items-center gap-6">
             <div className="flex items-center gap-2">
                <div className="p-2 bg-sky-500 rounded-lg">
                    <Table size={20} className="text-white" />
                </div>
                <div>
                    <h2 className="text-sm font-black uppercase tracking-widest leading-none">Master Rate Sheet</h2>
                    <p className="text-[10px] text-sky-300 font-bold mt-1">One Row Per Person • {filteredProducts.length} Products</p>
                </div>
             </div>

             <div className="flex bg-slate-800 p-1 rounded-lg border border-slate-700">
                <button 
                  onClick={() => setViewMode('sheet')}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-[10px] font-black uppercase transition-all ${viewMode === 'sheet' ? 'bg-sky-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-200'}`}
                >
                    <Grid size={14} /> Full Sheet
                </button>
                <button 
                  onClick={() => setViewMode('individual')}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-[10px] font-black uppercase transition-all ${viewMode === 'individual' ? 'bg-sky-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-200'}`}
                >
                    <LayoutList size={14} /> Individual
                </button>
             </div>
         </div>

         <div className="flex items-center gap-4 w-full md:w-auto">
             {/* SEARCH FILTERS */}
             <div className="flex gap-2 flex-1 md:flex-none">
                <div className="relative">
                    <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-500" size={12} />
                    <input 
                        type="text" 
                        placeholder="Search Party..."
                        value={partySearch}
                        onChange={e => setPartySearch(e.target.value)}
                        className="bg-slate-800 border-none text-white text-xs px-8 py-2 rounded-lg w-32 md:w-48 focus:ring-2 focus:ring-sky-500 outline-none"
                    />
                </div>
                <div className="relative">
                    <Filter className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-500" size={12} />
                    <input 
                        type="text" 
                        placeholder="Filter Products..."
                        value={productSearch}
                        onChange={e => setProductSearch(e.target.value)}
                        className="bg-slate-800 border-none text-white text-xs px-8 py-2 rounded-lg w-32 md:w-48 focus:ring-2 focus:ring-sky-500 outline-none"
                    />
                </div>
             </div>

             {/* SAVE BUTTON */}
             <div className="flex items-center gap-3 border-l border-slate-700 pl-4">
                 <div className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-tighter ${saveStatus === 'saved' ? 'text-slate-500' : 'text-orange-400'}`}>
                    {saveStatus === 'saved' ? <Check size={12}/> : <CloudLightning size={12} className="animate-pulse" />}
                    {saveStatus === 'saved' ? 'Synced' : 'Unsaved'}
                 </div>
                 {saveStatus === 'pending' && (
                    <button 
                        onClick={handleManualSave}
                        className="bg-emerald-500 hover:bg-emerald-600 text-white px-4 py-2 rounded-lg text-[10px] font-black uppercase shadow-lg shadow-emerald-900/20 flex items-center gap-2 animate-bounce"
                    >
                        <Save size={14} /> Save All
                    </button>
                 )}
             </div>
         </div>
      </div>

      <div className="flex-1 overflow-hidden">
         {viewMode === 'sheet' ? (
            <div className="h-full overflow-auto relative">
                {/* DENSE SPREADSHEET TABLE */}
                <table className="w-max border-separate border-spacing-0 min-w-full">
                    <thead className="sticky top-0 z-20">
                        <tr>
                            {/* Sticky Top-Left Corner */}
                            <th className="sticky left-0 top-0 z-30 bg-slate-100 border-r border-b border-slate-300 px-4 py-3 min-w-[220px] text-left">
