export const Cloud = {
  getScriptUrl: () => 'SUPABASE_ENABLED', 
  setScriptUrl: (url: string) => {}, 

  clearAllData: async () => {
    await supabase.from('special_rates').delete().neq('party_id', '00000000-0000-0000-0000-000000000000');
    return true;
  },

  syncInvoice: async (invoice: Invoice) => {
    const { error } = await supabase
      .from('invoices')
      .upsert({
        id: invoice.id,
        invoiceNumber: invoice.invoiceNumber,
        partyId: invoice.partyId,
        partyName: invoice.partyName,
        date: invoice.date,
        items: invoice.items, 
        subTotal: invoice.subTotal,
        taxAmount: invoice.taxAmount,
        globalDiscount: invoice.globalDiscount,
        grandTotal: invoice.grandTotal,
        vehicleNumber: invoice.vehicleNumber,
        poNumber: invoice.poNumber,
        partyAddress: invoice.partyAddress,
        partyGst: invoice.partyGst,
        partyPan: invoice.partyPan,
        partyAadhar: invoice.partyAadhar,
        partyPhone: invoice.partyPhone
      });

    if (error) {
      console.error('Error syncing invoice:', error);
      return { success: false, error: error.message };
    }
    return { success: true };
  },

  /**
   * Syncs rates into ONE ROW per party in the database.
   */
  syncSinglePartyRates: async (partyId: string, rates: SpecialRate[]) => {
    const partyRates = rates.filter(r => r.partyId === partyId);
    const rateMap: Record<string, number> = {};
    partyRates.forEach(r => {
      rateMap[r.productId] = r.rate;
    });

    const { error } = await supabase
      .from('special_rates')
      .upsert({
        party_id: partyId,
        rates: rateMap,
        updated_at: new Date().toISOString()
      });

    if (error) console.error("Error syncing single party row:", error);
  },

  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
    if (parties.length > 0) await supabase.from('parties').upsert(parties);
    if (products.length > 0) await supabase.from('products').upsert(products);
    if (users.length > 0) await supabase.from('app_users').upsert(users);

    // Group rates by Party for "One Row Per Person" database storage
    const consolidatedRows: any[] = [];
    parties.forEach(party => {
        const partyRates = rates.filter(r => r.partyId === party.id);
        if (partyRates.length > 0) {
            const rateMap: Record<string, number> = {};
            partyRates.forEach(pr => {
                rateMap[pr.productId] = pr.rate;
            });
            consolidatedRows.push({
                party_id: party.id,
                rates: rateMap,
                updated_at: new Date().toISOString()
            });
        }
    });

    if (consolidatedRows.length > 0) {
        const { error } = await supabase.from('special_rates').upsert(consolidatedRows);
        if (error) console.error("Batch rate sync error:", error);
    }
  },

  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES' | 'INVOICES' | 'USERS'): Promise<any> => {
    const FETCH_LIMIT = 10000;

    if (type === 'PARTIES') {
      const { data, error } = await supabase.from('parties').select('*').order('name', { ascending: true }).limit(FETCH_LIMIT);
      if (error) throw error;
      return data;
    }
    if (type === 'PRODUCTS') {
      const { data, error } = await supabase.from('products').select('*').order('name', { ascending: true }).limit(FETCH_LIMIT);
      if (error) throw error;
      return data;
    }
    if (type === 'RATES') {
      const { data, error } = await supabase.from('special_rates').select('*');
      if (error) throw error;

      const flatRates: SpecialRate[] = [];
      data.forEach((row: any) => {
          const partyId = row.party_id;
          const ratesMap = row.rates || {};
          Object.entries(ratesMap).forEach(([prodId, price]) => {
              flatRates.push({
                  partyId: partyId,
                  productId: prodId,
                  rate: Number(price)
              });
          });
      });
      return flatRates;
    }
    return [];
  },

  fetchUsers: async (): Promise<User[]> => {
    const { data, error } = await supabase.from('app_users').select('*').limit(100);
    if (error) throw error;
    return data as User[];
  },

  fetchInvoices: async (): Promise<Invoice[]> => {
    const { data, error } = await supabase.from('invoices').select('*').order('date', { ascending: false }).limit(2000);
    if (error) throw error;

    return data.map((inv: any) => ({
      ...inv,
      items: typeof inv.items === 'string' ? JSON.parse(inv.items) : (inv.items || []),
      subTotal: Number(inv.subTotal) || 0,
      taxAmount: Number(inv.taxAmount) || 0,
      globalDiscount: Number(inv.globalDiscount) || 0,
      grandTotal: Number(inv.grandTotal) || 0,
    })) as Invoice[];
  },

  testConnection: async () => {
    try {
      const { error } = await supabase.from('parties').select('id').limit(1);
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (e: any) {
      return { success: false, error: e.message || "Connection Error" };
    }
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { Party, Product, SpecialRate } from '../types';
import { Cloud } from '../services/cloud';
import { Search, Check, CloudLightning, Grid, LayoutList, Save, AlignLeft, Table, ChevronRight, ChevronLeft, Filter, UserCheck } from 'lucide-react';

interface Props {
  parties: Party[];
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (r: SpecialRate[]) => void;
}

export const RateManager: React.FC<Props> = ({ parties, products, specialRates, setSpecialRates }) => {
  const [viewMode, setViewMode] = useState<'sheet' | 'individual'>('sheet');
  const [partySearch, setPartySearch] = useState('');
  const [productSearch, setProductSearch] = useState('');
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'pending'>('saved');

  const [gridData, setGridData] = useState<Record<string, number>>({});

  useEffect(() => {
    const map: Record<string, number> = {};
    specialRates.forEach(r => {
      map[`${r.partyId}_${r.productId}`] = r.rate;
    });
    setGridData(map);
  }, [specialRates]);

  const handleManualSave = async () => {
    setSaveStatus('saving');

    const newRatesList: SpecialRate[] = [];
    Object.entries(gridData).forEach(([key, val]) => {
        const [pId, prodId] = key.split('_');
        const rateVal = val as number;
        if (rateVal > 0) {
            newRatesList.push({ partyId: pId, productId: prodId, rate: rateVal });
        }
    });

    // Update Local Store
    setSpecialRates(newRatesList);

    // Push to Cloud with consolidated "One Row Per Person" structure
    try {
        await Cloud.syncMasterData(parties, products, newRatesList, []);
        setSaveStatus('saved');
    } catch (error) {
        console.error("Sync failed:", error);
        setSaveStatus('pending');
    }
  };

  const saveSingleRow = async (partyId: string) => {
      const rowRates: SpecialRate[] = [];
      products.forEach(prod => {
          const val = gridData[`${partyId}_${prod.id}`];
          if (val > 0) {
              rowRates.push({ partyId, productId: prod.id, rate: val });
          }
      });

      // We update the master list locally first
      const otherRates = specialRates.filter(r => r.partyId !== partyId);
      setSpecialRates([...otherRates, ...rowRates]);

      // Sync specific person row to Supabase
      await Cloud.syncSinglePartyRates(partyId, rowRates);
      alert("Rates for this person saved to database as one row.");
  };

  const handleCellChange = (partyId: string, productId: string, val: string) => {
    setSaveStatus('pending');
    const num = parseFloat(val);
    const key = `${partyId}_${productId}`;

    setGridData(prev => {
        const next = { ...prev };
        if (!isNaN(num) && val !== '' && num > 0) next[key] = num;
        else delete next[key];
        return next;
    });
  };

  const filteredParties = useMemo(() => parties.filter(p => 
    p.name.toLowerCase().includes(partySearch.toLowerCase()) ||
    (p.code && p.code.toLowerCase().includes(partySearch.toLowerCase()))
  ), [parties, partySearch]);

  const filteredProducts = useMemo(() => products.filter(p => 
    p.name.toLowerCase().includes(productSearch.toLowerCase()) || 
    p.code.toLowerCase().includes(productSearch.toLowerCase())
  ), [products, productSearch]);

  return (
    <div className="flex flex-col h-[calc(100vh-64px)] overflow-hidden bg-white">

      <div className="bg-slate-900 text-white px-6 py-3 flex flex-col md:flex-row justify-between items-center z-30 gap-4">
         <div className="flex items-center gap-6">
             <div className="flex items-center gap-2">
                <div className="p-2 bg-emerald-500 rounded-lg">
                    <Table size={20} className="text-white" />
                </div>
                <div>
                    <h2 className="text-sm font-black uppercase tracking-widest leading-none">Price Matrix</h2>
                    <p className="text-[10px] text-emerald-300 font-bold mt-1 tracking-tight">Database: One Row Per Person</p>
                </div>
             </div>

             <div className="flex bg-slate-800 p-1 rounded-lg border border-slate-700">
                <button 
                  onClick={() => setViewMode('sheet')}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-[10px] font-black uppercase transition-all ${viewMode === 'sheet' ? 'bg-sky-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-200'}`}
                >
                    <Grid size={14} /> Full Sheet
                </button>
                <button 
                  onClick={() => setViewMode('individual')}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-[10px] font-black uppercase transition-all ${viewMode === 'individual' ? 'bg-sky-600 text-white shadow-lg' : 'text-slate-400 hover:text-slate-200'}`}
                >
                    <LayoutList size={14} /> Individual
                </button>
             </div>
         </div>

         <div className="flex items-center gap-4 w-full md:w-auto">
             <div className="flex gap-2 flex-1 md:flex-none">
                <div className="relative">
                    <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-500" size={12} />
                    <input 
                        type="text" 
                        placeholder="Search Party..."
                        value={partySearch}
                        onChange={e => setPartySearch(e.target.value)}
                        className="bg-slate-800 border-none text-white text-xs px-8 py-2 rounded-lg w-32 md:w-48 focus:ring-2 focus:ring-sky-500 outline-none"
                    />
                </div>
                <div className="relative">
                    <Filter className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-500" size={12} />
                    <input 
                        type="text" 
                        placeholder="Filter Products..."
                        value={productSearch}
                        onChange={e => setProductSearch(e.target.value)}
                        className="bg-slate-800 border-none text-white text-xs px-8 py-2 rounded-lg w-32 md:w-48 focus:ring-2 focus:ring-sky-500 outline-none"
                    />
                </div>
             </div>

             <div className="flex items-center gap-3 border-l border-slate-700 pl-4">
                 <div className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-tighter ${saveStatus === 'saved' ? 'text-slate-500' : 'text-orange-400'}`}>
                    {saveStatus === 'saved' ? <Check size={12}/> : <CloudLightning size={12} className="animate-pulse" />}
                    {saveStatus === 'saved' ? 'Synced' : 'Unsaved'}
                 </div>
                 {saveStatus === 'pending' && (
                    <button 
                        onClick={handleManualSave}
                        className="bg-sky-500 hover:bg-sky-600 text-white px-4 py-2 rounded-lg text-[10px] font-black uppercase shadow-lg shadow-sky-900/20 flex items-center gap-2"
                    >
                        <Save size={14} /> Save All
                    </button>
                 )}
             </div>
         </div>
      </div>

      <div className="flex-1 overflow-hidden">
         {viewMode === 'sheet' ? (
            <div className="h-full overflow-auto relative bg-slate-50">
                <table className="w-max border-separate border-spacing-0 min-w-full">
                    <thead className="sticky top-0 z-20">
                        <tr>
                            <th className="sticky left-0 top-0 z-30 bg-slate-100 border-r border-b border-slate-300 px-4 py-3 min-w-[260px] text-left shadow-sm">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                                    <AlignLeft size={12}/> Person / Party Name
                                </div>
                            </th>

                            {filteredProducts.map(prod => (
                                <th key={prod.id} className="bg-white border-b border-r border-slate-200 px-2 py-3 min-w-[120px] text-center align-bottom">
                                    <div className="text-[9px] font-bold text-slate-400 uppercase leading-tight mb-1 truncate w-24 mx-auto" title={prod.name}>
                                        {prod.name}
                                    </div>
                                    <div className="text-[10px] font-mono text-slate-400">
                                        ₹{prod.standardRate}
                                    </div>
                                </th>
                            ))}
                        </tr>
                    </thead>

                    <tbody>
                        {filteredParties.map(party => (
                            <tr key={party.id} className="group hover:bg-sky-50 transition-colors">
                                <td className="sticky left-0 z-10 bg-white group-hover:bg-sky-50 border-r border-b border-slate-200 px-4 py-2 shadow-sm">
                                    <div className="flex justify-between items-center">
                                        <div className="max-w-[160px]">
                                            <div className="font-black text-slate-800 text-xs truncate" title={party.name}>
                                                {party.name}
                                            </div>
                                            <div className="text-[9px] text-slate-400 font-bold uppercase flex items-center gap-1 mt-0.5">
                                                {party.code && <span className="bg-slate-100 px-1 rounded text-slate-500">{party.code}</span>}
                                                {party.city || 'No City'}
                                            </div>
                                        </div>
                                        <button 
                                            onClick={() => saveSingleRow(party.id)}
                                            className="opacity-0 group-hover:opacity-100 transition-opacity bg-emerald-500 text-white p-1.5 rounded-lg hover:bg-emerald-600 shadow-sm"
                                            title="Save only this person's rates"
                                        >
                                            <UserCheck size={14} />
                                        </button>
                                    </div>
                                </td>

                                {filteredProducts.map(prod => {
                                    const rateKey = `${party.id}_${prod.id}`;
                                    const val = gridData[rateKey];

                                    return (
                                        <td 
                                            key={prod.id} 
                                            className={`border-r border-b border-slate-100 p-0 text-center transition-colors ${val ? 'bg-emerald-50/50' : 'bg-transparent'}`}
                                        >
                                            <input 
                                                type="number"
                                                className={`w-full text-center py-4 text-xs font-black outline-none bg-transparent hover:bg-white focus:bg-white focus:ring-1 focus:ring-sky-500 transition-all ${
                                                    val ? 'text-emerald-700' : 'text-slate-300'
                                                }`}
                                                value={val ?? ''}
                                                placeholder="-"
                                                onChange={(e) => handleCellChange(party.id, prod.id, e.target.value)}
                                            />
                                        </td>
                                    );
                                })}
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
         ) : (
            <div className="flex h-full bg-slate-50">
                <div className="w-72 bg-white border-r border-slate-200 flex flex-col h-full overflow-hidden shrink-0">
                   <div className="overflow-y-auto flex-1">
                      {filteredParties.map(p => (
                        <button 
                          key={p.id}
                          className="w-full text-left px-5 py-4 border-b border-slate-100 hover:bg-slate-50 transition-all flex items-center justify-between group"
                        >
                            <div>
                                <div className="font-bold text-slate-800 text-sm">{p.name}</div>
                                <div className="text-[10px] font-bold text-slate-400 uppercase">{p.code || 'NO CODE'}</div>
                            </div>
                            <ChevronRight size={16} className="text-slate-300 group-hover:text-sky-500" />
                        </button>
                      ))}
                   </div>
                </div>

                <div className="flex-1 flex flex-col items-center justify-center p-12 text-slate-400 italic">
                    <AlignLeft size={48} className="mb-4 opacity-10" />
                    <p>Select a person from the left to manage their product rates individually.</p>
                </div>
            </div>
         )}
      </div>

      <div className="bg-slate-50 border-t border-slate-200 px-6 py-2 flex justify-between items-center text-[9px] font-bold text-slate-400 uppercase tracking-widest">
         <div className="flex gap-4">
            <div className="flex items-center gap-1.5">
                <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                Special Rate
            </div>
            <div className="flex items-center gap-1.5">
                <div className="w-2 h-2 rounded-full bg-slate-200"></div>
                Standard Rate
            </div>
         </div>
         <div className="flex items-center gap-2">
            <ChevronLeft size={10}/> Scroll sideways for products <ChevronRight size={10}/>
         </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Party, Product, SpecialRate } from '../types';
import { Cloud } from '../services/cloud';
import { 
  Search, Check, CloudLightning, Grid, LayoutList, Save, 
  AlignLeft, Table, ChevronRight, Filter, UserCheck, 
  Package, Tag, Copy, ArrowRight, Loader2, Sparkles, User
} from 'lucide-react';

interface Props {
  parties: Party[];
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (r: SpecialRate[]) => void;
}

export const RateManager: React.FC<Props> = ({ parties, products, specialRates, setSpecialRates }) => {
  const [viewMode, setViewMode] = useState<'sheet' | 'individual'>('individual');
  const [selectedPartyId, setSelectedPartyId] = useState<string | null>(null);
  const [partySearch, setPartySearch] = useState('');
  const [productSearch, setProductSearch] = useState('');
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'pending'>('saved');
  const [isCloning, setIsCloning] = useState(false);

  // Local temporary data store for the UI grid
  const [gridData, setGridData] = useState<Record<string, number>>({});

  useEffect(() => {
    const map: Record<string, number> = {};
    specialRates.forEach(r => {
      map[`${r.partyId}_${r.productId}`] = r.rate;
    });
    setGridData(map);
  }, [specialRates]);

  // Set first party by default if in individual mode
  useEffect(() => {
    if (viewMode === 'individual' && !selectedPartyId && parties.length > 0) {
      setSelectedPartyId(parties[0].id);
    }
  }, [viewMode, parties]);

  const handleManualSave = async () => {
    setSaveStatus('saving');

    const newRatesList: SpecialRate[] = [];
    Object.entries(gridData).forEach(([key, val]) => {
        const [pId, prodId] = key.split('_');
        const rateVal = val as number;
        if (rateVal > 0) {
            newRatesList.push({ partyId: pId, productId: prodId, rate: rateVal });
        }
    });

    setSpecialRates(newRatesList);

    try {
        await Cloud.syncMasterData(parties, products, newRatesList, []);
        setSaveStatus('saved');
    } catch (error) {
        console.error("Sync failed:", error);
        setSaveStatus('pending');
    }
  };

  const saveCurrentPerson = async () => {
      if (!selectedPartyId) return;
      setSaveStatus('saving');

      const rowRates: SpecialRate[] = [];
      products.forEach(prod => {
          const val = gridData[`${selectedPartyId}_${prod.id}`];
          if (val > 0) {
              rowRates.push({ partyId: selectedPartyId, productId: prod.id, rate: val });
          }
      });

      const otherRates = specialRates.filter(r => r.partyId !== selectedPartyId);
      const updatedAll = [...otherRates, ...rowRates];
      setSpecialRates(updatedAll);

      try {
          await Cloud.syncSinglePartyRates(selectedPartyId, rowRates);
          setSaveStatus('saved');
      } catch (e) {
          setSaveStatus('pending');
      }
  };

  const copyRatesFrom = (sourcePartyId: string) => {
    if (!selectedPartyId) return;

    setGridData(prev => {
      const next = { ...prev };
      products.forEach(prod => {
        const sourceVal = prev[`${sourcePartyId}_${prod.id}`];
        const currentKey = `${selectedPartyId}_${prod.id}`;
        if (sourceVal) {
          next[currentKey] = sourceVal;
        } else {
          delete next[currentKey];
        }
      });
      return next;
    });

    setSaveStatus('pending');
    setIsCloning(false);
  };

  const handleCellChange = (partyId: string, productId: string, val: string) => {
    setSaveStatus('pending');
    const num = parseFloat(val);
    const key = `${partyId}_${productId}`;

    setGridData(prev => {
        const next = { ...prev };
        if (!isNaN(num) && val !== '' && num > 0) next[key] = num;
        else delete next[key];
        return next;
    });
  };

  const filteredParties = useMemo(() => parties.filter(p => 
    p.name.toLowerCase().includes(partySearch.toLowerCase()) ||
    (p.code && p.code.toLowerCase().includes(partySearch.toLowerCase()))
  ), [parties, partySearch]);

  const filteredProducts = useMemo(() => products.filter(p => 
    p.name.toLowerCase().includes(productSearch.toLowerCase()) || 
    p.code.toLowerCase().includes(productSearch.toLowerCase())
  ), [products, productSearch]);

  const selectedParty = parties.find(p => p.id === selectedPartyId);

  return (
    <div className="flex flex-col h-full overflow-hidden bg-slate-50">

      {/* PROFESSIONAL TOP NAV */}
      <div className="bg-white border-b border-slate-200 px-6 py-4 flex flex-col md:flex-row justify-between items-center z-30 gap-4 shadow-sm">
         <div className="flex items-center gap-6">
             <div className="flex items-center gap-3">
                <div className="p-2.5 bg-slate-900 rounded-xl shadow-lg shadow-slate-200">
                    <Table size={20} className="text-white" />
                </div>
                <div>
                    <h2 className="text-lg font-black text-slate-800 tracking-tight leading-none uppercase">Master Price List</h2>
                    <p className="text-[10px] text-slate-400 font-bold mt-1 tracking-widest uppercase flex items-center gap-1">
                       <CloudLightning size={10} className="text-sky-500" /> Database: One Row Per Person
                    </p>
                </div>
             </div>

             <div className="flex bg-slate-100 p-1 rounded-xl border border-slate-200">
                <button 
                  onClick={() => setViewMode('individual')}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold uppercase transition-all ${viewMode === 'individual' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    <LayoutList size={16} /> Individual
                </button>
                <button 
                  onClick={() => setViewMode('sheet')}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold uppercase transition-all ${viewMode === 'sheet' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                >
                    <Grid size={16} /> Full Sheet
                </button>
             </div>
         </div>

         <div className="flex items-center gap-3">
             <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-tighter transition-colors ${saveStatus === 'saved' ? 'bg-slate-100 text-slate-500' : 'bg-orange-100 text-orange-600'}`}>
                {saveStatus === 'saved' ? <Check size={12}/> : <Loader2 size={12} className="animate-spin" />}
                {saveStatus === 'saved' ? 'All Synced' : 'Unsaved Changes'}
             </div>

             {saveStatus === 'pending' && (
                <button 
                    onClick={handleManualSave}
                    className="bg-slate-900 hover:bg-black text-white px-5 py-2.5 rounded-xl text-xs font-bold flex items-center gap-2 shadow-xl shadow-slate-200 active:scale-95 transition-all"
                >
                    <Save size={16} /> Save Master Changes
                </button>
             )}
         </div>
      </div>

      {/* WORKSPACE AREA */}
      <div className="flex-1 flex overflow-hidden">

         {viewMode === 'individual' ? (
           <div className="flex flex-1 overflow-hidden">
              {/* LEFT SIDEBAR: PARTY LIST */}
              <div className="w-80 bg-white border-r border-slate-200 flex flex-col h-full overflow-hidden shrink-0">
