import React, { useState, useEffect, useMemo } from 'react';
import { Party, Product, SpecialRate } from '../types';
import { Cloud } from '../services/cloud';
import { 
  Search, Check, Grid, LayoutList, Save, 
  ChevronRight, Filter, Loader2, CheckCircle2,
  RefreshCcw
} from 'lucide-react';

interface Props {
  parties: Party[];
  products: Product[];
  specialRates: SpecialRate[];
  setSpecialRates: (r: SpecialRate[]) => void;
}

export const RateManager: React.FC<Props> = ({ parties, products, specialRates, setSpecialRates }) => {
  const [viewMode, setViewMode] = useState<'sheet' | 'detail'>('detail');
  const [selectedPartyId, setSelectedPartyId] = useState<string | null>(null);
  const [partySearch, setPartySearch] = useState('');
  const [productSearch, setProductSearch] = useState('');
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'pending'>('saved');

  // Local temporary data store for the UI grid
  const [gridData, setGridData] = useState<Record<string, number>>({});

  useEffect(() => {
    const map: Record<string, number> = {};
    specialRates.forEach(r => {
      map[`${r.partyId}_${r.productId}`] = r.rate;
    });
    setGridData(map);
  }, [specialRates]);

  // Set first party by default if none selected
  useEffect(() => {
    if (!selectedPartyId && parties.length > 0) {
      setSelectedPartyId(parties[0].id);
    }
  }, [parties, selectedPartyId]);

  const handleManualSave = async () => {
    setSaveStatus('saving');

    const newRatesList: SpecialRate[] = [];
    Object.entries(gridData).forEach(([key, val]) => {
        const [pId, prodId] = key.split('_');
        const rateVal = val as number;
        if (rateVal > 0) {
            newRatesList.push({ partyId: pId, productId: prodId, rate: rateVal });
        }
    });

    setSpecialRates(newRatesList);

    try {
        await Cloud.syncMasterData(parties, products, newRatesList, []);
        setSaveStatus('saved');
    } catch (error) {
        console.error("Sync failed:", error);
        setSaveStatus('pending');
    }
  };

  const handleCellChange = (partyId: string, productId: string, val: string) => {
    setSaveStatus('pending');
    const num = parseFloat(val);
    const key = `${partyId}_${productId}`;

    setGridData(prev => {
        const next = { ...prev };
        if (!isNaN(num) && val !== '' && num >= 0) next[key] = num;
        else delete next[key];
        return next;
    });
  };

  const filteredParties = useMemo(() => parties.filter(p => 
    p.name.toLowerCase().includes(partySearch.toLowerCase()) ||
    (p.code && p.code.toLowerCase().includes(partySearch.toLowerCase()))
  ), [parties, partySearch]);

  const filteredProducts = useMemo(() => products.filter(p => 
    p.name.toLowerCase().includes(productSearch.toLowerCase()) || 
    p.code.toLowerCase().includes(productSearch.toLowerCase())
  ), [products, productSearch]);

  const selectedParty = parties.find(p => p.id === selectedPartyId);

  return (
    <div className="flex flex-col h-full bg-white overflow-hidden">

      {/* TOP NAVBAR */}
      <div className="h-16 border-b border-slate-200 flex items-center justify-between px-6 shrink-0 bg-white z-10">
        <div className="flex items-center gap-2">
          <div className="flex p-1 bg-slate-100 rounded-lg border border-slate-200 shadow-sm">
            <button 
              onClick={() => setViewMode('sheet')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-md text-[11px] font-bold transition-all ${viewMode === 'sheet' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              <Grid size={14} /> Grid Matrix
            </button>
            <button 
              onClick={() => setViewMode('detail')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-md text-[11px] font-bold transition-all ${viewMode === 'detail' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              <LayoutList size={14} /> Detail View
            </button>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {saveStatus === 'saved' ? (
            <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50 px-3 py-1.5 rounded-full border border-slate-100">
              <Check size={12} className="text-emerald-500" /> ALL CHANGES SAVED
            </div>
          ) : (
            <button 
              onClick={handleManualSave}
              className="flex items-center gap-2 bg-sky-600 hover:bg-sky-700 text-white text-[10px] font-bold uppercase tracking-widest px-4 py-2 rounded-full transition-all shadow-md shadow-sky-100"
            >
              {saveStatus === 'saving' ? <Loader2 size={12} className="animate-spin" /> : <Save size={12} />}
              Save Changes
            </button>
          )}
        </div>

        <div className="relative w-64">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
          <input 
            type="text" 
            placeholder="Search items..."
            value={productSearch}
            onChange={(e) => setProductSearch(e.target.value)}
            className="w-full pl-9 pr-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs outline-none focus:ring-1 focus:ring-sky-500"
          />
        </div>
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* LEFT PARTY SIDEBAR */}
        <div className="w-[300px] border-r border-slate-200 flex flex-col h-full bg-white">
          <div className="p-4 border-b border-slate-100">
            <div className="relative">
              <input 
                type="text" 
                placeholder="Search Party..."
                value={partySearch}
                onChange={e => setPartySearch(e.target.value)}
                className="w-full px-3 py-2 border border-sky-400 rounded-lg text-sm font-medium focus:ring-0 outline-none placeholder:text-slate-400"
              />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto">
            {filteredParties.map(p => (
              <button 
                key={p.id}
                onClick={() => setSelectedPartyId(p.id)}
                className={`w-full text-left px-6 py-4 transition-all flex flex-col border-b border-slate-50 relative ${selectedPartyId === p.id ? 'bg-white' : 'hover:bg-slate-50'}`}
              >
                {selectedPartyId === p.id && <div className="absolute left-0 top-0 bottom-0 w-1 bg-sky-600"></div>}
                <div className={`text-xs font-bold uppercase tracking-tight ${selectedPartyId === p.id ? 'text-sky-700' : 'text-slate-700'}`}>
                  {p.name}
                </div>
                <div className="text-[10px] text-slate-400 font-medium mt-1 uppercase tracking-wider">
                  {p.code || 'No Code'}
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* MAIN CONTENT AREA */}
        <div className="flex-1 overflow-y-auto bg-white">
          {viewMode === 'detail' ? (
            <div className="p-0">
              <table className="w-full border-collapse">
                <thead className="sticky top-0 bg-white z-10">
                  <tr className="border-b border-slate-100">
                    <th className="px-10 py-4 text-left text-[10px] font-bold text-slate-400 uppercase tracking-widest w-1/2">Product</th>
                    <th className="px-6 py-4 text-center text-[10px] font-bold text-slate-400 uppercase tracking-widest w-1/4">Std Rate</th>
                    <th className="px-6 py-4 text-center text-[10px] font-bold text-slate-400 uppercase tracking-widest w-1/4">Your Rate</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {filteredProducts.map(prod => {
                    const rateKey = `${selectedPartyId}_${prod.id}`;
                    const val = gridData[rateKey];

                    return (
                      <tr key={prod.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-10 py-5">
                          <div className="font-bold text-slate-700 text-sm">{prod.name}</div>
                          <div className="text-[10px] text-slate-400 font-bold uppercase mt-1">{prod.code || 'N/A'}</div>
                        </td>
                        <td className="px-6 py-5 text-center text-sm font-medium text-slate-400">
                          {prod.standardRate}
                        </td>
                        <td className="px-6 py-5 flex justify-center">
                          <input 
                            type="number" 
                            value={val ?? ''}
                            placeholder={prod.standardRate.toString()}
                            onChange={(e) => handleCellChange(selectedPartyId!, prod.id, e.target.value)}
                            className="w-24 px-3 py-2 border border-sky-300 rounded-md text-sm font-bold text-sky-700 text-center focus:ring-2 focus:ring-sky-100 outline-none shadow-sm"
                          />
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="p-4 text-slate-400 text-sm font-medium italic flex items-center justify-center h-full">
              Full grid matrix mode - Coming soon
            </div>
          )}
        </div>
      </div>

      {/* FOOTER STATUS BAR */}
      <div className="h-10 border-t border-slate-100 px-6 flex items-center justify-end bg-slate-50 shrink-0">
        <div className="flex items-center gap-2 bg-white px-3 py-1 rounded-lg border border-slate-200 shadow-sm">
          <CheckCircle2 size={14} className="text-emerald-500" />
          <span className="text-[10px] font-bold text-slate-600 uppercase tracking-wider">Connected</span>
          <RefreshCcw size={12} className="text-slate-300" />
        </div>
      </div>
    </div>
  );
};

