  const [viewInvoice, setViewInvoice] = useState<Invoice | null>(null);
  const [editingInvoice, setEditingInvoice] = useState<Invoice | null>(null);

  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'pulling'>('idle');
  const [cloudUrl] = useState(() => Cloud.getScriptUrl()); 

  const isFirstLoad = useRef(true);
  const hasPendingChanges = useRef(false);
  const isRemoteUpdate = useRef(false);
  const lastPushTime = useRef(0); 

  const handleCloudPull = useCallback(async () => {
      if (syncStatus === 'syncing' || syncStatus === 'pulling' || hasPendingChanges.current) return;
      try {
        setSyncStatus('pulling');
        const [cloudParties, cloudProducts, cloudRates, cloudInvoices, cloudUsers] = await Promise.all([
           Cloud.fetchData('PARTIES'),
           Cloud.fetchData('PRODUCTS'),
           Cloud.fetchData('RATES'),
           Cloud.fetchInvoices(),
           Cloud.fetchUsers()
        ]);
        setParties(cloudParties);
        setProducts(cloudProducts);
        setSpecialRates(cloudRates);
        setInvoices(cloudInvoices);
        setValidUsers(cloudUsers);
        setSyncStatus('idle');
      } catch (e) {
        setSyncStatus('idle');
      }
  }, [syncStatus]);

  useEffect(() => {
    const sessionUser = sessionStorage.getItem('gfb_user');
    if (sessionUser) setIsAuthenticated(true);
    handleCloudPull();
  }, []);

  const handleForcePush = async () => {
      setSyncStatus('syncing');
      try {
          await Cloud.syncMasterData(parties, products, specialRates, validUsers);
          setSyncStatus('synced');
          setTimeout(() => setSyncStatus('idle'), 2000);
      } catch(e) {
          setSyncStatus('idle');
      }
  };

  const NavItem = ({ view, icon: Icon, label }: { view: ViewState; icon: any; label: string }) => (
    <button
      onClick={() => {
        setCurrentView(view);
        setEditingInvoice(null);
        setIsMobileMenuOpen(false);
      }}
      className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all font-semibold mb-1 ${
        currentView === view 
          ? 'bg-sky-100 text-sky-800 shadow-sm' 
          : 'text-slate-500 hover:bg-slate-50 hover:text-sky-600'
      }`}
    >
      <Icon size={18} />
      <span className="text-sm">{label}</span>
    </button>
  );

  if (!isAuthenticated) {
    return <Login onLogin={(user) => { setIsAuthenticated(true); sessionStorage.setItem('gfb_user', JSON.stringify(user)); }} validUsers={validUsers} />;
  }

  return (
    <div className="flex h-screen bg-white font-sans text-slate-900">

      {/* Sidebar */}
      <div className={`fixed md:static inset-y-0 left-0 w-64 bg-white border-r border-slate-200 transform transition-transform duration-300 z-[60] no-print flex flex-col ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0`}>
        <div className="p-6">
          <div className="flex items-center gap-2 mb-1">
            <div className="w-8 h-8 bg-sky-600 rounded-lg flex items-center justify-center text-white text-lg font-bold">G</div>
            <h1 className="text-xl font-black text-slate-800 tracking-tight">GREENZAR</h1>
          </div>
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest pl-10">Food & Beverage</p>
        </div>

        <nav className="px-4 py-2 flex-1 overflow-y-auto">
          <NavItem view="billing" icon={Edit3} label="Create Invoice" />
          <NavItem view="history" icon={History} label="History" />
          <NavItem view="ranking" icon={Trophy} label="Ranking" />
          <NavItem view="logs" icon={ClipboardList} label="All Logs" />

          <div className="mt-8 mb-2 px-4 text-[10px] font-bold text-slate-300 uppercase tracking-widest">Database</div>
          <NavItem view="parties" icon={Users} label="Parties" />
          <NavItem view="products" icon={Package} label="Products" />
          <NavItem view="rates" icon={DollarSign} label="Price Lists" />

          <div className="mt-8 mb-2 px-4 text-[10px] font-bold text-slate-300 uppercase tracking-widest">Configuration</div>
          <NavItem view="users" icon={UserIcon} label="Users" />
          <NavItem view="data" icon={Database} label="Data & Sync" />
          <NavItem view="more" icon={MoreHorizontal} label="More" />
        </nav>

        <div className="p-4 border-t border-slate-50">
           <button onClick={() => setIsAuthenticated(false)} className="w-full flex items-center justify-center gap-2 text-xs font-bold text-slate-400 hover:text-red-600 p-2 transition-colors">
             <LogOut size={14} /> Logout
           </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col h-full overflow-hidden bg-white">
        {currentView === 'billing' && <Billing parties={parties} setParties={setParties} products={products} specialRates={specialRates} setSpecialRates={setSpecialRates} onInvoiceSaved={() => { setInvoices(Store.getInvoices()); }} initialData={editingInvoice} />}
        {currentView === 'parties' && <PartyManager parties={parties} setParties={setParties} />}
        {currentView === 'products' && <ProductManager products={products} setProducts={setProducts} />}
        {currentView === 'rates' && <RateManager parties={parties} products={products} specialRates={specialRates} setSpecialRates={setSpecialRates} />}
        {currentView === 'users' && <UserManager users={validUsers} setUsers={setValidUsers} />}
        {currentView === 'logs' && <InvoiceLogs invoices={invoices} parties={parties} />}
        {currentView === 'ranking' && <Ranking invoices={invoices} parties={parties} />}
        {currentView === 'statement' && <PartyStatement invoices={invoices} parties={parties} />}
        {currentView === 'data' && <DataManager parties={parties} products={products} specialRates={specialRates} invoices={invoices} refreshData={handleCloudPull} onForcePush={handleForcePush} />}
      </div>
    </div>
  );
};

