  const [formData, setFormData] = useState<Partial<Product>>({});
  const [searchTerm, setSearchTerm] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || formData.standardRate === undefined) return;

    let updatedProducts = [...products];

    if (editingId) {
      updatedProducts = products.map(p => p.id === editingId ? { ...p, ...formData } as Product : p);
    } else {
      const newProduct: Product = {
        id: crypto.randomUUID(),
        name: formData.name!,
        code: formData.code || 'N/A',
        standardRate: Number(formData.standardRate),
        unit: formData.unit || 'Unit',
        hsn: formData.hsn || '',
        gstPercent: Number(formData.gstPercent) || 0,
        qtyPerCase: Number(formData.qtyPerCase) || 1,
        weight: Number(formData.weight) || 0
      };
      updatedProducts.push(newProduct);
    }

    setProducts(updatedProducts);
    closeForm();
  };

  const openEdit = (product: Product) => {
    setFormData(product);
    setEditingId(product.id);
    setIsFormOpen(true);
  };

