              />
            </div>
          </div>
          <div className="flex-1 overflow-y-auto custom-scrollbar">
            {filteredParties.map(p => (
              <button 
                key={p.id}
                onClick={() => setSelectedPartyId(p.id)}
                className={`w-full text-left px-8 py-5 transition-all flex flex-col border-b border-slate-50 relative ${selectedPartyId === p.id ? 'bg-white' : 'hover:bg-slate-50'}`}
              >
                {selectedPartyId === p.id && <div className="absolute left-0 top-0 bottom-0 w-1.5 bg-[#0088cc]"></div>}
                <div className={`text-sm font-bold uppercase tracking-tight transition-colors ${selectedPartyId === p.id ? 'text-[#0088cc]' : 'text-slate-700'}`}>
                  {p.name}
                </div>
                <div className="text-[10px] text-slate-400 font-bold mt-1 uppercase tracking-widest">
                  {p.code || 'NO-CODE'}
