            {filteredParties.length === 0 && (
                <div className="p-8 text-center text-slate-400 text-xs font-medium">No parties found</div>
            )}
          </div>
        </div>

        {/* RIGHT AREA: PRODUCT LISTING */}
        <div className="flex-1 overflow-y-auto bg-white custom-scrollbar relative">
          {viewMode === 'detail' ? (
            <div className="p-0 min-w-max">
              <table className="w-full border-collapse">
                <thead className="sticky top-0 bg-white z-10 border-b border-slate-200">
                  <tr className="bg-slate-50/50">
                    <th className="px-10 py-5 text-left text-[11px] font-bold text-slate-400 uppercase tracking-widest w-[40%] bg-white">PRODUCT & HSN</th>
                    <th className="px-6 py-5 text-center text-[11px] font-bold text-slate-400 uppercase tracking-widest w-[15%] bg-white">WEIGHT</th>
                    <th className="px-6 py-5 text-center text-[11px] font-bold text-slate-400 uppercase tracking-widest w-[15%] bg-white">STD RATE</th>
                    <th className="px-6 py-5 text-center text-[11px] font-bold text-slate-400 uppercase tracking-widest w-[30%] bg-white">YOUR RATE</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {filteredProducts.map(prod => {
                    const rateKey = `${selectedPartyId}_${prod.id}`;
                    const val = gridData[rateKey];

                    return (
                      <tr key={prod.id} className="hover:bg-[#f0f9ff] transition-colors group">
                        <td className="px-10 py-6">
                          <div className="font-bold text-slate-800 text-[13px] leading-tight group-hover:text-[#0088cc] transition-colors uppercase">{prod.name}</div>
                          <div className="flex items-center gap-3 mt-1.5">
                             <div className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">SKU: {prod.code || 'N/A'}</div>
                             <div className="w-1 h-1 rounded-full bg-slate-200"></div>
                             <div className="text-[10px] text-[#0088cc] font-bold uppercase tracking-tighter">HSN: {prod.hsn || '2201'}</div>
                          </div>
                        </td>
                        <td className="px-6 py-6 text-center">
                           <div className="inline-flex items-center gap-1.5 px-2.5 py-1 bg-slate-50 rounded-lg border border-slate-100">
                             <Weight size={12} className="text-[#0088cc]" />
                             <span className="text-xs font-bold text-slate-600">{(prod.weight || 0).toFixed(2)} KG</span>
                           </div>
                        </td>
                        <td className="px-6 py-6 text-center text-sm font-medium text-slate-400 font-mono">
                          ₹{prod.standardRate.toFixed(2)}
                        </td>
                        <td className="px-6 py-6 flex justify-center">
                          <div className="relative">
                            <input 
                                type="number" 
                                value={val ?? ''}
                                placeholder={prod.standardRate.toString()}
                                onChange={(e) => handleCellChange(selectedPartyId!, prod.id, e.target.value)}
                                className="w-28 px-4 py-2.5 border border-[#0088cc] rounded-lg text-sm font-black text-[#0088cc] text-center focus:ring-4 focus:ring-sky-100 outline-none shadow-sm transition-all placeholder:text-slate-200"
                            />
