      </div>

      {/* FOOTER STATUS BAR */}
      <div className="h-10 border-t border-slate-100 px-6 flex items-center justify-between bg-slate-50 shrink-0">
        <div className="flex items-center gap-6">
            <div className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">
               Listing {filteredProducts.length} Products
            </div>
            {selectedParty && (
              <div className="text-[9px] font-bold text-[#0088cc] uppercase tracking-widest flex items-center gap-2">
