        <div className="flex items-center gap-3 bg-white px-3 py-1 rounded-full border border-slate-200 shadow-sm">
          <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>
          <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest">Server Connection Stable</span>
          <RefreshCcw size={12} onClick={() => window.location.reload()} className="text-slate-300 cursor-pointer hover:text-[#0088cc] transition-colors" />
