import { Invoice, Party, Product, SpecialRate, User } from '../types';
import { supabase } from './supabase';

export const Cloud = {
  getScriptUrl: () => 'SUPABASE_ENABLED', 
  setScriptUrl: (url: string) => {}, 

  clearAllData: async () => {
    await supabase.from('special_rates').delete().neq('party_id', '00000000-0000-0000-0000-000000000000');
    return true;
  },

  syncInvoice: async (invoice: Invoice) => {
    const { error } = await supabase
      .from('invoices')
      .upsert({
        id: invoice.id,
        invoiceNumber: invoice.invoiceNumber,
        partyId: invoice.partyId,
        partyName: invoice.partyName,
        date: invoice.date,
        items: invoice.items, 
        subTotal: invoice.subTotal,
        taxAmount: invoice.taxAmount,
        globalDiscount: invoice.globalDiscount,
        grandTotal: invoice.grandTotal,
        totalWeight: invoice.totalWeight, // Syncing the weight to cloud
        vehicleNumber: invoice.vehicleNumber,
        poNumber: invoice.poNumber,
        partyAddress: invoice.partyAddress,
        partyGst: invoice.partyGst,
        partyPan: invoice.partyPan,
        partyAadhar: invoice.partyAadhar,
        partyPhone: invoice.partyPhone
      });

    if (error) {
      console.error('Error syncing invoice:', error);
      return { success: false, error: error.message };
    }
    return { success: true };
  },

  syncSinglePartyRates: async (partyId: string, rates: SpecialRate[]) => {
    const partyRates = rates.filter(r => r.partyId === partyId);
    const rateMap: Record<string, number> = {};
    partyRates.forEach(r => {
      rateMap[r.productId] = r.rate;
    });

    const { error } = await supabase
      .from('special_rates')
      .upsert({
        party_id: partyId,
        rates: rateMap,
        updated_at: new Date().toISOString()
      });

    if (error) console.error("Error syncing single party row:", error);
  },

  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
    if (parties.length > 0) await supabase.from('parties').upsert(parties);
    if (products.length > 0) await supabase.from('products').upsert(products);
    if (users.length > 0) await supabase.from('app_users').upsert(users);

    const consolidatedRows: any[] = [];
    parties.forEach(party => {
        const partyRates = rates.filter(r => r.partyId === party.id);
        if (partyRates.length > 0) {
            const rateMap: Record<string, number> = {};
            partyRates.forEach(pr => {
                rateMap[pr.productId] = pr.rate;
            });
            consolidatedRows.push({
                party_id: party.id,
                rates: rateMap,
                updated_at: new Date().toISOString()
            });
        }
    });

    if (consolidatedRows.length > 0) {
        const { error } = await supabase.from('special_rates').upsert(consolidatedRows);
        if (error) console.error("Batch rate sync error:", error);
    }
  },

  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES' | 'INVOICES' | 'USERS'): Promise<any> => {
    const FETCH_LIMIT = 10000;

    if (type === 'PARTIES') {
      const { data, error } = await supabase.from('parties').select('*').order('name', { ascending: true }).limit(FETCH_LIMIT);
      if (error) throw error;
      return data;
    }
    if (type === 'PRODUCTS') {
      const { data, error } = await supabase.from('products').select('*').order('name', { ascending: true }).limit(FETCH_LIMIT);
      if (error) throw error;
      return data;
    }
    if (type === 'RATES') {
      const { data, error } = await supabase.from('special_rates').select('*');
      if (error) throw error;

      const flatRates: SpecialRate[] = [];
      data.forEach((row: any) => {
          const partyId = row.party_id;
          const ratesMap = row.rates || {};
          Object.entries(ratesMap).forEach(([prodId, price]) => {
              flatRates.push({
                  partyId: partyId,
                  productId: prodId,
                  rate: Number(price)
              });
          });
      });
      return flatRates;
    }
    return [];
  },

  fetchUsers: async (): Promise<User[]> => {
    const { data, error } = await supabase.from('app_users').select('*').limit(100);
    if (error) throw error;
    return data as User[];
  },

  fetchInvoices: async (): Promise<Invoice[]> => {
    const { data, error } = await supabase.from('invoices').select('*').order('date', { ascending: false }).limit(2000);
    if (error) throw error;

    return data.map((inv: any) => ({
      ...inv,
      items: typeof inv.items === 'string' ? JSON.parse(inv.items) : (inv.items || []),
      subTotal: Number(inv.subTotal) || 0,
      taxAmount: Number(inv.taxAmount) || 0,
      globalDiscount: Number(inv.globalDiscount) || 0,
      grandTotal: Number(inv.grandTotal) || 0,
      totalWeight: Number(inv.totalWeight) || 0
    })) as Invoice[];
  },

  testConnection: async () => {
    try {
      const { error } = await supabase.from('parties').select('id').limit(1);
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (e: any) {
      return { success: false, error: e.message || "Connection Error" };
    }
  }
};

