export const Store = {
  resetToSeedData: () => {
    localStorage.setItem(KEYS.PARTIES, JSON.stringify([]));
    localStorage.setItem(KEYS.PRODUCTS, JSON.stringify(SEED_PRODUCTS));
    localStorage.setItem(KEYS.RATES, JSON.stringify([]));
    localStorage.setItem(KEYS.INVOICES, JSON.stringify([]));
    localStorage.setItem(KEYS.VERSION, CURRENT_DB_VERSION);
    window.location.reload();
  },

  getParties: (): Party[] => {
    const data = localStorage.getItem(KEYS.PARTIES);
    if (!data || data === 'null') return []; 
    try { return JSON.parse(data); } catch { return []; }
  },
  saveParties: (parties: Party[]) => localStorage.setItem(KEYS.PARTIES, JSON.stringify(parties)),

  getProducts: (): Product[] => {
    const data = localStorage.getItem(KEYS.PRODUCTS);
    if (!data || data === 'null') return SEED_PRODUCTS;
    try { return JSON.parse(data); } catch { return SEED_PRODUCTS; }
  },
  saveProducts: (products: Product[]) => localStorage.setItem(KEYS.PRODUCTS, JSON.stringify(products)),

  getRates: (): SpecialRate[] => {
    const data = localStorage.getItem(KEYS.RATES);
    if (!data || data === 'null') return [];
    try { return JSON.parse(data); } catch { return []; }
  },
  saveRates: (rates: SpecialRate[]) => localStorage.setItem(KEYS.RATES, JSON.stringify(rates)),

  getInvoices: (): Invoice[] => {
    const data = localStorage.getItem(KEYS.INVOICES);
    if (!data || data === 'null') return [];
    try {
        const parsed = JSON.parse(data);
        if (!Array.isArray(parsed)) return [];
        return parsed.map((inv: any) => ({
            ...inv,
            totalWeight: Number(inv.totalWeight) || 0
        }));
    } catch (e) {
        return [];
    }
  },
  saveInvoice: (invoice: Invoice) => {
    const invoices = Store.getInvoices();
    invoices.unshift(invoice);
    localStorage.setItem(KEYS.INVOICES, JSON.stringify(invoices));
  },
  saveInvoices: (invoices: Invoice[]) => {
    localStorage.setItem(KEYS.INVOICES, JSON.stringify(invoices));
  },
  getUsers: (): User[] => {
    const data = localStorage.getItem(KEYS.USERS);
    try { return data ? JSON.parse(data) : SEED_USERS; } catch { return SEED_USERS; }
  },
  saveUsers: (users: User[]) => localStorage.setItem(KEYS.USERS, JSON.stringify(users)),
};

import React, { useState, useMemo } from 'react';
import { Product } from '../types';
import { Plus, Edit2, Package, Search, X, Weight, Info, Scale, List, FileText } from 'lucide-react';

interface Props {
  products: Product[];
  setProducts: (p: Product[]) => void;
}

export const ProductManager: React.FC<Props> = ({ products, setProducts }) => {
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'standard' | 'weight-list'>('standard');

  const [formData, setFormData] = useState<Partial<Product>>({});
  const [searchTerm, setSearchTerm] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || formData.standardRate === undefined) return;

    let updatedProducts = [...products];
    if (editingId) {
      updatedProducts = products.map(p => p.id === editingId ? { ...p, ...formData } as Product : p);
    } else {
      const newProduct: Product = {
        id: crypto.randomUUID(),
        name: formData.name!,
        code: formData.code || 'N/A',
        standardRate: Number(formData.standardRate),
        unit: formData.unit || 'Unit',
        hsn: formData.hsn || '',
        gstPercent: Number(formData.gstPercent) || 0,
        qtyPerCase: Number(formData.qtyPerCase) || 1,
        weight: Number(formData.weight) || 0
      };
      updatedProducts.push(newProduct);
    }
    setProducts(updatedProducts);
    closeForm();
  };

  const openEdit = (product: Product) => {
    setFormData(product);
    setEditingId(product.id);
    setIsFormOpen(true);
  };

  const closeForm = () => {
    setFormData({});
    setEditingId(null);
    setIsFormOpen(false);
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (p.code && p.code.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const totalInventoryWeight = useMemo(() => {
    return filteredProducts.reduce((sum, p) => sum + (p.weight || 0), 0);
  }, [filteredProducts]);

  return (
    <div className="p-6 max-w-7xl mx-auto h-full flex flex-col bg-white">
