import { Invoice, Party, Product, SpecialRate, User } from '../types';
import { supabase } from './supabase';

export const Cloud = {
  getScriptUrl: () => 'SUPABASE_ENABLED', 

  clearAllData: async () => {
    console.warn("Wipe command blocked by security policy.");
    return true;
  },

  // --- SYNC METHODS (UPSERT) ---

  syncInvoice: async (invoice: Invoice) => {
    const { error } = await supabase
      .from('invoices')
      .upsert({
        id: invoice.id,
        invoiceNumber: invoice.invoiceNumber,
        partyId: invoice.partyId,
        partyName: invoice.partyName,
        date: invoice.date,
        items: invoice.items,
        subTotal: invoice.subTotal,
        taxAmount: invoice.taxAmount,
        globalDiscount: invoice.globalDiscount,
        grandTotal: invoice.grandTotal,
        totalWeight: invoice.totalWeight,
        vehicleNumber: invoice.vehicleNumber,
        poNumber: invoice.poNumber,
        partyAddress: invoice.partyAddress,
        partyGst: invoice.partyGst,
        partyPan: invoice.partyPan,
        partyAadhar: invoice.partyAadhar,
        partyPhone: invoice.partyPhone
      });

    if (error) {
      console.error('Error syncing invoice:', error);
      return { success: false, error: error.message };
    }
    return { success: true };
  },

  syncMasterData: async (parties: Party[], products: Product[], rates: SpecialRate[], users: User[]) => {
    // 1. Sync Parties (Map camelCase to snake_case)
    if (parties.length > 0) {
      const dbParties = parties.map(p => ({
        id: p.id,
        name: p.name,
        code: p.code,
        address: p.address,
        city: p.city,
        phone: p.phone,
        gst_number: p.gstNumber,
        aadhar_number: p.aadharNumber,
        pan_number: p.panNumber,
        email: p.email
      }));
      await supabase.from('parties').upsert(dbParties);
    }

    // 2. Sync Products (Map camelCase to snake_case)
    if (products.length > 0) {
      const dbProducts = products.map(p => ({
        id: p.id,
        name: p.name,
        code: p.code,
        standard_rate: p.standardRate,
        unit: p.unit,
        hsn: p.hsn,
        gst_percent: p.gstPercent,
        qty_per_case: p.qtyPerCase,
        weight: p.weight
      }));
      await supabase.from('products').upsert(dbProducts);
    }

    // 3. Sync Users
    if (users.length > 0) {
      await supabase.from('app_users').upsert(users);
    }

    // 4. Sync Rates (Store in JSONB format per SQL schema)
    const partyRateMap: Record<string, Record<string, number>> = {};
    rates.forEach(r => {
      if (!partyRateMap[r.partyId]) partyRateMap[r.partyId] = {};
      partyRateMap[r.partyId][r.productId] = r.rate;
    });

    const dbRates = Object.entries(partyRateMap).map(([partyId, ratesJson]) => ({
      party_id: partyId,
      rates: ratesJson
    }));

    if (dbRates.length > 0) {
      await supabase.from('special_rates').upsert(dbRates);
    }
  },

  // --- FETCH METHODS ---

  fetchData: async (type: 'PRODUCTS' | 'RATES' | 'PARTIES' | 'INVOICES' | 'USERS'): Promise<any> => {
    if (type === 'PARTIES') {
      const { data, error } = await supabase.from('parties').select('*');
      if (error) throw error;
      return (data || []).map(p => ({
        id: p.id,
        name: p.name,
        code: p.code,
        address: p.address,
        city: p.city,
        phone: p.phone,
        gstNumber: p.gst_number,
        aadharNumber: p.aadhar_number,
        panNumber: p.pan_number,
        email: p.email
      }));
    }
    if (type === 'PRODUCTS') {
      const { data, error } = await supabase.from('products').select('*');
      if (error) throw error;
      return (data || []).map(p => ({
        id: p.id,
        name: p.name,
        code: p.code,
        standardRate: Number(p.standard_rate),
        unit: p.unit,
        hsn: p.hsn,
        gstPercent: Number(p.gst_percent),
        qtyPerCase: p.qty_per_case,
        weight: Number(p.weight)
      }));
    }
    if (type === 'RATES') {
      const { data, error } = await supabase.from('special_rates').select('*');
      if (error) throw error;

      const flatRates: SpecialRate[] = [];
      (data || []).forEach(row => {
        if (row.rates && typeof row.rates === 'object') {
          Object.entries(row.rates).forEach(([prodId, rate]) => {
            flatRates.push({
              partyId: row.party_id,
              productId: prodId,
              rate: Number(rate)
            });
          });
        }
      });
      return flatRates;
    }
    return [];
  },

  fetchUsers: async (): Promise<User[]> => {
    const { data, error } = await supabase.from('app_users').select('*');
    if (error) throw error;
    return data as User[];
  },

  fetchInvoices: async (): Promise<Invoice[]> => {
    const { data, error } = await supabase.from('invoices').select('*').order('created_at', { ascending: false });
    if (error) throw error;

    return (data || []).map((inv: any) => ({
      id: inv.id,
      invoiceNumber: inv.invoiceNumber || '',
      partyId: inv.partyId,
      partyName: inv.partyName || 'Unknown',
      date: inv.date,
      items: Array.isArray(inv.items) ? inv.items : [],
      subTotal: Number(inv.subTotal) || 0,
      taxAmount: Number(inv.taxAmount) || 0,
      globalDiscount: Number(inv.globalDiscount) || 0,
      grandTotal: Number(inv.grandTotal) || 0,
      totalWeight: Number(inv.totalWeight) || 0,
      vehicleNumber: inv.vehicleNumber || '',
      poNumber: inv.poNumber || '',
      partyAddress: inv.partyAddress || '',
      partyGst: inv.partyGst || '',
      partyPan: inv.partyPan || '',
      partyAadhar: inv.partyAadhar || '',
      partyPhone: inv.partyPhone || ''
    })) as Invoice[];
  },

  testConnection: async () => {
    try {
      const { error } = await supabase.from('parties').select('id').limit(1);
      if (error) return { success: false, error: error.message };
      return { success: true };
    } catch (e: any) {
      return { success: false, error: e.message || "Unknown Connection Error" };
    }
  }
};

