            <p className="max-w-[220px] leading-tight">{party ? `${party.address}${party.city ? ', ' + party.city : ''}` : (invoice.partyAddress || '-')}</p>
          </div>
          <div className="grid grid-cols-[50px_1fr] text-[10px] font-bold uppercase leading-tight">
            <span className="text-slate-400">GSTIN</span>
            <span className="text-[#1a202c] font-mono">{party?.gstNumber || invoice.partyGst || 'NO'}</span>
            <span className="text-slate-400">Pan</span>
            <span className="text-[#1a202c] font-mono">{party?.panNumber || invoice.partyPan || '---'}</span>
            <span className="text-slate-400">Aadhar</span>
            <span className="text-[#1a202c] font-mono">{party?.aadharNumber || invoice.partyAadhar || '-'}</span>
          </div>
        </div>
        <div>
          <h3 className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1.5">Ship To</h3>
          <p className="text-[12px] font-black text-[#1a202c] uppercase leading-tight mb-1">{party?.name || invoice.partyName}</p>
          <div className="text-[10px] text-slate-600 space-y-0.5 uppercase">
            <p>Ph : {party?.phone || invoice.partyPhone || '-'}</p>
            <p className="max-w-[220px] leading-tight">{party ? `${party.address}${party.city ? ', ' + party.city : ''}` : (invoice.partyAddress || '-')}</p>
          </div>
        </div>
      </div>

      {/* PRODUCT TABLE - COMPACT FONT & PADDING */}
      <table className="w-full text-right border-collapse mb-6 invoice-table">
        <thead>
          <tr className="text-slate-400 font-bold uppercase">
            <th className="py-2 text-left pl-1 w-6">#</th>
            <th className="py-2 text-left">Item Description</th>
            <th className="py-2 text-center w-14">HSN</th>
            <th className="py-2 text-center w-10">GST</th>
            <th className="py-2 text-center w-10">Qty</th>
            <th className="py-2 w-16">Rate</th>
            <th className="py-2 w-16">Taxable</th>
            <th className="py-2 w-14">CGST</th>
            <th className="py-2 w-14">SGST</th>
            <th className="py-2 pr-1 w-20">Total</th>
          </tr>
        </thead>
        <tbody className="font-bold text-[#1a202c]">
          {(invoice.items || []).map((item, idx) => {
            const gstP = item.gstPercent || 0;
            const taxableItem = item.total / (1 + gstP / 100);
            const totalItemTax = item.total - taxableItem;
            const rateVal = taxableItem / item.quantity;

            return (
              <tr key={idx}>
                <td className="py-1.5 text-left pl-1 text-slate-400">{idx + 1}</td>
                <td className="py-1.5 text-left uppercase text-[10px]">{item.productName}</td>
                <td className="py-1.5 text-center font-mono">{item.hsn || '2201'}</td>
                <td className="py-1.5 text-center">{gstP}%</td>
                <td className="py-1.5 text-center">{item.quantity}</td>
                <td className="py-1.5">{rateVal.toFixed(2)}</td>
                <td className="py-1.5">{taxableItem.toFixed(2)}</td>
                <td className="py-1.5">{(totalItemTax / 2).toFixed(2)}</td>
                <td className="py-1.5">{(totalItemTax / 2).toFixed(2)}</td>
                <td className="py-1.5 pr-1">{item.total.toFixed(2)}</td>
              </tr>
            );
          })}
        </tbody>
      </table>

      {/* BOTTOM SUMMARY SECTION */}
      <div className="flex justify-between items-start print-break-inside-avoid">
        {/* BANK DETAILS */}
        <div className="w-[45%] border border-slate-100 p-3 rounded-sm">
          <h4 className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-2">Bank Details</h4>
          <div className="space-y-1 text-[9px] font-bold uppercase">
            <div className="flex justify-between border-b border-slate-50 pb-0.5">
              <span className="text-slate-400">Account Name</span>
              <span className="text-[#1a202c]">Greenzar Food And Beverage</span>
            </div>
            <div className="flex justify-between border-b border-slate-50 pb-0.5">
              <span className="text-slate-400">Bank Name</span>
              <span className="text-[#1a202c]">UCO BANK</span>
            </div>
            <div className="flex justify-between border-b border-slate-50 pb-0.5">
              <span className="text-slate-400">Branch</span>
              <span className="text-[#1a202c]">BADU BR.</span>
            </div>
            <div className="flex justify-between border-b border-slate-50 pb-0.5">
              <span className="text-slate-400">A/C No</span>
              <span className="text-[#1a202c] font-mono">06710510011188</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-400">IFSC</span>
              <span className="text-[#1a202c] font-mono">UCBA0000671</span>
            </div>
          </div>
        </div>

        {/* CALCULATION SUMMARY */}
        <div className="w-[48%] space-y-1.5">
          <div className="flex justify-between text-[11px] font-bold">
            <span className="text-slate-400 uppercase">Taxable Amount</span>
            <span className="text-[#1a202c]">₹{taxableAmount.toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-[11px] font-bold">
            <span className="text-slate-400 uppercase">Add: CGST</span>
            <span className="text-[#1a202c]">₹{cgstAmount.toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-[11px] font-bold">
            <span className="text-slate-400 uppercase">Add: SGST</span>
            <span className="text-[#1a202c]">₹{sgstAmount.toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-[11px] font-bold">
            <span className="text-slate-400 uppercase">Round Off / Adj.</span>
            <span className="text-[#1a202c] font-mono">{roundOff >= 0 ? '+' : ''}{roundOff.toFixed(2)}</span>
          </div>

          <div className="border-t border-slate-200 mt-2 pt-2 flex justify-between items-center">
            <span className="text-[14px] font-black uppercase tracking-tighter">Grand Total</span>
            <span className="text-[20px] font-black">₹{grandTotal.toLocaleString('en-IN')}.00</span>
          </div>

          <div className="text-right mt-2">
            <div className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Amount in Words</div>
            <div className="text-[12px] font-bold italic text-[#1a202c] leading-tight">{numberToWords(grandTotal)}</div>
          </div>
        </div>
      </div>

      {/* FOOTER - SIGNATORY & TERMS */}
      <div className="mt-10 flex justify-between items-end">
        <div className="text-[8px] text-slate-400 space-y-0.5 font-bold max-w-[300px]">
          <p><span className="text-slate-500 uppercase">Terms:</span> 1. Goods once sold will not be taken back.</p>
          <p>2. Interest @ 18% p.a. charged if payment delayed.</p>
          <p>3. Complete payment within 30 days of the billing date.</p>
        </div>
        <div className="text-right">
          <div className="text-[10px] font-bold text-[#1a202c] uppercase mb-0.5">Authorized Signatory</div>
          <div className="text-[8px] text-slate-400 uppercase font-bold">For Greenzar Food and Beverage</div>
        </div>
      </div>

      <div className="absolute bottom-4 left-0 right-0 text-center text-[8px] font-bold text-slate-200 no-print">
        This Invoice Is Generated Using GREENZAR F & B Official Billing Software.
      </div>
    </div>
  );
};
